package com.petbattles;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(PetBattlesConfig.GROUP)
public interface PetBattlesConfig extends Config
{
	String GROUP = "petbattles";

	/**
	 * Developer mode. Enable it with {@code -Dpetbattles.dev=true} when running the client from
	 * source (e.g. {@code ./gradlew run -Dpetbattles.dev=true}). It is never set in the plugin-hub
	 * build, so every dev affordance below is inert and invisible in production — the testing
	 * toggles are intentionally NOT {@code @ConfigItem}s, so they never appear in the config panel
	 * and there is no branch to maintain. See docs/plans/roadmap.md §S.
	 */
	boolean DEV = Boolean.getBoolean("petbattles.dev");

	@ConfigItem(
		keyName = "battleSpeed",
		name = "Battle speed",
		description = "Game ticks between battle messages (lower = faster battles)",
		position = 1
	)
	@Range(min = 1, max = 5)
	default int battleSpeed()
	{
		return 1;
	}

	@ConfigItem(
		keyName = "autoAdvanceBattleText",
		name = "Auto-advance battle text",
		description = "Advance battle messages on a timer instead of waiting for a click or Space on each line",
		position = 2
	)
	default boolean autoAdvanceBattleText()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showXpMessages",
		name = "Pet XP chat messages",
		description = "Announce pet XP gains and level-ups in the chat box",
		position = 3
	)
	default boolean showXpMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "battleSoundEffects",
		name = "Battle sound effects",
		description = "Play a matching in-game sound when a pet uses a move in battle",
		position = 4
	)
	default boolean battleSoundEffects()
	{
		return true;
	}

	@ConfigItem(
		keyName = "battleSoundVolume",
		name = "Battle sound volume",
		description = "Volume of the battle sound effects, independent of the in-game sound slider",
		position = 5
	)
	@Range(min = 0, max = 100)
	@Units(Units.PERCENT)
	default int battleSoundVolume()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "showHubOverlay",
		name = "Show hub overlay",
		description = "Draw the pet hub over the game screen. With this off the side panel is the way in,"
			+ " and its tabs light up when a trainer or quest NPC is nearby",
		position = 6
	)
	default boolean showHubOverlay()
	{
		return true;
	}

	// --- Developer-only affordances (gated on DEV; NOT config items) ---
	// These are STATIC on purpose: RuneLite proxies the Config interface and returns null for any
	// instance method that lacks @ConfigItem, so an instance `default` here would NPE at runtime.
	// As statics they bypass the proxy entirely and read only the DEV flag (plus, for the graduated
	// knobs, extra -D properties), so a hub build can never show or enable them. Call as
	// PetBattlesConfig.devXxx().

	/**
	 * Adds per-card "Unlock (dev)" buttons and the "Reset progression (dev)" button so a developer
	 * can build teams with unowned pets. Dev-only.
	 */
	static boolean devSelectLockedPets()
	{
		return DEV;
	}

	/**
	 * Lets a developer fight any trainer from the panel without meeting them in-world first. Dev-only.
	 */
	static boolean devRemoteBattles()
	{
		return DEV;
	}

	/**
	 * Treat every pet as owned, for testing without the collection log. Off unless the developer
	 * additionally passes {@code -Dpetbattles.unlockAll=true}. Dev-only.
	 */
	static boolean devUnlockAll()
	{
		return DEV && Boolean.getBoolean("petbattles.unlockAll");
	}

	/**
	 * Use the full, unscaled OSRS experience table instead of the 20x-faster default pacing. Off
	 * unless the developer passes {@code -Dpetbattles.fullXpCurve=true}. Dev-only.
	 */
	static boolean devFullXpCurve()
	{
		return DEV && Boolean.getBoolean("petbattles.fullXpCurve");
	}

	/**
	 * Multiply battle XP rewards so pets level quickly in testing. Set with
	 * {@code -Dpetbattles.xpMult=<n>} (clamped to at least 1). Dev-only; always 1 in production.
	 */
	static int devXpMultiplier()
	{
		return DEV ? Math.max(1, Integer.getInteger("petbattles.xpMult", 1)) : 1;
	}

	/**
	 * Log the battle event sequence at debug level to diagnose animation/sequencing. Off unless the
	 * developer passes {@code -Dpetbattles.trace=true}. Dev-only.
	 */
	static boolean devBattleTrace()
	{
		return DEV && Boolean.getBoolean("petbattles.trace");
	}
}

package com.petbattles;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.api.coords.WorldPoint;
import com.petbattles.bank.AtBankTracker;
import com.petbattles.battle.BattleInputHandler;
import com.petbattles.battle.BattleKeyListener;
import com.petbattles.battle.BattleSession;
import com.petbattles.collection.CollectionLogSync;
import com.petbattles.data.ContentLoader;
import com.petbattles.data.PetDatabase;
import com.petbattles.easteregg.EasterEggTracker;
import com.petbattles.engine.Leveling;
import com.petbattles.engine.TrainerDef;
import com.petbattles.item.Item;
import com.petbattles.follower.FollowerTracker;
import com.petbattles.follower.HeldItemTracker;
import com.petbattles.npc.NearTrainerTracker;
import com.petbattles.persist.RosterManager;
import com.petbattles.persist.RosterStore;
import com.petbattles.quest.QuestDialogSession;
import com.petbattles.quest.QuestManager;
import com.petbattles.ui.BattleOverlay;
import com.petbattles.ui.HubActions;
import com.petbattles.ui.HubInputHandler;
import com.petbattles.ui.ChatheadAnchors;
import com.petbattles.ui.HubKeyListener;
import com.petbattles.ui.HubOverlay;
import com.petbattles.ui.HubPanel;
import com.petbattles.ui.HubView;
import com.petbattles.ui.ItemSprites;
import com.petbattles.ui.PetBattlesPanel;
import com.petbattles.ui.PetChatheads;
import com.petbattles.ui.Portraits;
import com.petbattles.ui.QuestDialogInputHandler;
import com.petbattles.ui.QuestDialogOverlay;
import com.petbattles.ui.RestOverlay;
import com.petbattles.ui.Sprites;
import com.petbattles.xp.KillXpTracker;
import net.runelite.client.eventbus.EventBus;

@Slf4j
@PluginDescriptor(
	name = "Pet Battles",
	description = "Turn-based battles between your collection log pets",
	tags = {"pets", "minigame", "fun", "battle"}
)
public class PetBattlesPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private PetBattlesConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private Gson gson;

	@Inject
	private Sprites sprites;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private WorldMapPointManager worldMapPointManager;

	@Inject
	private TooltipManager tooltipManager;

	// "Locate" pins currently on the world map (one per known trainer location). Replaced on each
	// Locate and cleared on shutdown. A trainer like Man has many, so this is a list.
	private final java.util.List<WorldMapPoint> locatePins = new java.util.ArrayList<>();
	private BufferedImage mapPinImage;

	private PetDatabase db;
	private RosterManager roster;
	private PetBattlesPanel panel;
	private NavigationButton navButton;
	private BattleSession session;
	private BattleOverlay overlay;
	private RestOverlay restOverlay;
	private HubOverlay hubOverlay;
	// Whether the hub overlay is currently registered (PetBattlesConfig.showHubOverlay). Read from the
	// AWT thread by the input handler's bounds supplier, written on the client thread.
	private volatile boolean hubOverlayShown;
	private QuestDialogSession questDialog;
	private QuestDialogOverlay questDialogOverlay;
	private QuestDialogInputHandler questDialogInputHandler;
	private HubInputHandler hubInputHandler;
	private HubKeyListener hubKeyListener;
	private BattleInputHandler inputHandler;
	private BattleKeyListener keyListener;
	private AtBankTracker atBankTracker;
	private NearTrainerTracker nearTrainerTracker;
	private QuestManager questManager;
	private CollectionLogSync collectionLogSync;
	private FollowerTracker followerTracker;
	private HeldItemTracker heldItemTracker;
	private KillXpTracker killXpTracker;
	private EasterEggTracker easterEggTracker;

	@Override
	protected void startUp() throws Exception
	{
		db = PetDatabase.load(new ContentLoader(gson));
		Leveling.setFullCurve(PetBattlesConfig.devFullXpCurve());
		roster = new RosterManager(db, new RosterStore(configManager, gson));
		atBankTracker = new AtBankTracker(client, () ->
		{
			if (panel != null)
			{
				panel.refresh();
			}
		});
		roster.setTeamEditGate(atBankTracker::isAtBank);
		questManager = new QuestManager(db, roster);
		nearTrainerTracker = new NearTrainerTracker(client, db, this::onNearTrainersChanged);
		restOverlay = new RestOverlay();
		// The quest dialog frame: the one surface quest conversations play on, from a chapter's first
		// line through to the payoff a battle earns. It owns the live cursor, so the hub surfaces are
		// only a log of where the player has got to. The battle-active gate reads the session field
		// below, which is assigned right after this.
		questDialog = new QuestDialogSession(db, roster, questManager,
			nearTrainerTracker::getNearTrainerIds, () -> session != null && session.isActive());
		session = new BattleSession(client, db, roster, questManager, questDialog, config, () ->
		{
			if (panel != null)
			{
				panel.refresh();
			}
		});
		overlay = new BattleOverlay(session, db, sprites, new PetChatheads(),
			new ChatheadAnchors(gson), new ItemSprites());
		inputHandler = new BattleInputHandler(session, overlay, clientThread);
		keyListener = new BattleKeyListener(client, session, clientThread);

		questDialogOverlay = new QuestDialogOverlay(questDialog, new Portraits());
		questDialogInputHandler = new QuestDialogInputHandler(questDialogOverlay, questDialog,
			clientThread, this::startTrainerBattle);

		// Floating hub: the HubView drawn by a movable RuneLite overlay.
		hubOverlay = new HubOverlay(db, roster, questManager, sprites, new Portraits(), session,
			atBankTracker::isAtBank, nearTrainerTracker::getNearTrainerIds, tooltipManager);
		HubActions hubActions = new HubActions(hubOverlay.getView(), db, roster,
			this::startTrainerBattle, this::locateTrainer, this::examineItem, restOverlay::play);
		// A hidden overlay keeps the bounds of its last frame, so the hit test has to go with it —
		// otherwise clicks in a dead corner of the screen would still be swallowed by the hub.
		HubOverlay hub = hubOverlay;
		hubInputHandler = new HubInputHandler(hubOverlay.getView(), hubActions,
			() -> hubOverlayShown ? hub.getBounds() : null, roster, session, clientThread);
		hubKeyListener = new HubKeyListener(hubOverlay.getView(), session, clientThread);

		// Docked hub: the same HubView, embedded in the side panel as a Swing component. Its dispatch
		// runs on the EDT, so the client-touching Locate/Examine callbacks are marshalled to the
		// client thread here (Fight already marshals internally).
		HubView panelView = new HubView(db, roster, questManager, sprites, new Portraits(), session,
			atBankTracker::isAtBank, nearTrainerTracker::getNearTrainerIds, tooltipManager,
			PluginPanel.PANEL_WIDTH, true);
		HubActions panelActions = new HubActions(panelView, db, roster, this::startTrainerBattle,
			id -> clientThread.invokeLater(() -> locateTrainer(id)),
			id -> clientThread.invokeLater(() -> examineItem(id)), restOverlay::play);
		panel = new PetBattlesPanel(new HubPanel(panelView, panelActions, roster, session));
		overlayManager.add(overlay);
		overlayManager.add(restOverlay);
		// The hub is the plugin's one always-on fixture, so it's the one overlay the player can turn
		// off; the quest, rest and battle overlays only appear because something happened.
		setHubOverlayShown(config.showHubOverlay());
		overlayManager.add(questDialogOverlay);
		mouseManager.registerMouseListener(inputHandler);
		mouseManager.registerMouseListener(questDialogInputHandler);
		mouseManager.registerMouseListener(hubInputHandler);
		mouseManager.registerMouseWheelListener(hubInputHandler);
		keyManager.registerKeyListener(keyListener);
		keyManager.registerKeyListener(hubKeyListener);

		Runnable refreshPanel = () -> panel.refresh();
		collectionLogSync = new CollectionLogSync(client, db, roster, refreshPanel);
		followerTracker = new FollowerTracker(client, db, roster, refreshPanel);
		heldItemTracker = new HeldItemTracker(client, db, roster, refreshPanel);
		killXpTracker = new KillXpTracker(client, db, roster, followerTracker, config, refreshPanel);
		easterEggTracker = new EasterEggTracker(client, db, roster, followerTracker, refreshPanel);
		eventBus.register(atBankTracker);
		eventBus.register(nearTrainerTracker);
		eventBus.register(collectionLogSync);
		eventBus.register(followerTracker);
		eventBus.register(heldItemTracker);
		eventBus.register(killXpTracker);
		eventBus.register(easterEggTracker);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/petbattles/icons/panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Pet Battles")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		// Handle plugin being enabled while already logged in
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			roster.load();
			clientThread.invokeLater(followerTracker::refresh);
			panel.refresh();
		}
		log.debug("Pet Battles started with {} species, {} moves, {} trainers (dev mode: {})",
			db.allSpecies().size(), db.allMoves().size(), db.allTrainers().size(), PetBattlesConfig.DEV);
	}

	@Override
	protected void shutDown() throws Exception
	{
		clientToolbar.removeNavigation(navButton);
		clearLocatePins();
		mapPinImage = null;
		if (collectionLogSync != null)
		{
			eventBus.unregister(atBankTracker);
			eventBus.unregister(nearTrainerTracker);
			eventBus.unregister(collectionLogSync);
			eventBus.unregister(followerTracker);
			eventBus.unregister(heldItemTracker);
			eventBus.unregister(killXpTracker);
			eventBus.unregister(easterEggTracker);
		}
		if (overlay != null)
		{
			overlayManager.remove(overlay);
		}
		if (restOverlay != null)
		{
			overlayManager.remove(restOverlay);
		}
		if (hubOverlay != null)
		{
			overlayManager.remove(hubOverlay);
			hubOverlayShown = false;
		}
		if (questDialogOverlay != null)
		{
			overlayManager.remove(questDialogOverlay);
		}
		if (questDialogInputHandler != null)
		{
			mouseManager.unregisterMouseListener(questDialogInputHandler);
		}
		if (hubInputHandler != null)
		{
			mouseManager.unregisterMouseListener(hubInputHandler);
			mouseManager.unregisterMouseWheelListener(hubInputHandler);
		}
		if (inputHandler != null)
		{
			mouseManager.unregisterMouseListener(inputHandler);
		}
		if (keyListener != null)
		{
			keyManager.unregisterKeyListener(keyListener);
		}
		if (hubKeyListener != null)
		{
			keyManager.unregisterKeyListener(hubKeyListener);
		}
		if (session != null)
		{
			session.close();
		}
		if (roster != null)
		{
			roster.unload();
		}
		navButton = null;
		panel = null;
		roster = null;
		db = null;
		session = null;
		overlay = null;
		restOverlay = null;
		hubOverlay = null;
		questDialog = null;
		questDialogOverlay = null;
		questDialogInputHandler = null;
		hubInputHandler = null;
		hubKeyListener = null;
		inputHandler = null;
		keyListener = null;
		atBankTracker = null;
		nearTrainerTracker = null;
		collectionLogSync = null;
		followerTracker = null;
		heldItemTracker = null;
		killXpTracker = null;
		easterEggTracker = null;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		session.tick();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGGED_IN)
		{
			if (!roster.isLoaded())
			{
				roster.load();
				clientThread.invokeLater(followerTracker::refresh);
			}
			panel.refresh();
		}
		else if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING)
		{
			if (e.getGameState() == GameState.LOGIN_SCREEN)
			{
				roster.unload();
				easterEggTracker.resetBaselines();
				// Conversation cursors are per-login: the next account gets its own chapter intros.
				questDialog.reset();
			}
			panel.refresh();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (PetBattlesConfig.GROUP.equals(e.getGroup()))
		{
			Leveling.setFullCurve(PetBattlesConfig.devFullXpCurve());
			setHubOverlayShown(config.showHubOverlay());
			panel.refresh();
		}
	}

	/**
	 * Show or hide the floating hub, live. Tracked with a flag rather than asked of the
	 * {@link OverlayManager} so a repeated call can't register the overlay twice, and so the input
	 * handler's hit test can be switched off with it — a removed overlay keeps its last bounds.
	 */
	private void setHubOverlayShown(boolean shown)
	{
		if (hubOverlay == null || shown == hubOverlayShown)
		{
			return;
		}
		hubOverlayShown = shown;
		if (shown)
		{
			overlayManager.add(hubOverlay);
		}
		else
		{
			overlayManager.remove(hubOverlay);
			// Nothing is listening for the hub's search box any more; leaving it focused would eat
			// keystrokes meant for the game.
			hubOverlay.getView().blurSearch();
		}
	}

	/**
	 * The set of nearby trainers changed: refresh the panel so a quest chapter's conversation appears
	 * (or its Challenge unlocks) once the player reaches the relevant NPC. Runs on the client thread.
	 */
	private void onNearTrainersChanged()
	{
		if (panel != null)
		{
			panel.refresh();
		}
	}

	private void startTrainerBattle(String trainerId)
	{
		clientThread.invokeLater(() ->
		{
			if (session.isActive() && session.getPhase() != BattleSession.Phase.ENDED)
			{
				return;
			}
			session.close();
			if (!session.startTrainerBattle(trainerId))
			{
				log.debug("Could not start battle vs {}", trainerId);
				// Most likely cause: empty or fully-fainted team
				String reason = roster.getTeam().isEmpty()
					? "Add a pet to your team first."
					: !roster.teamCanFight()
					? "Your team is knocked out — rest your pets at a bank first."
					: "Could not start the battle.";
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"Pet Battles: " + reason, null);
			}
		});
	}

	/**
	 * Drop a "Locate" pin on the world map at every known location of this trainer and centre the
	 * map on the one nearest the player. Pins persist so the player sees them when they open the
	 * map; the next Locate replaces them. No-op for trainers with no known location. Runs on the
	 * client thread (dispatched from the hub input handler).
	 */
	private void locateTrainer(String trainerId)
	{
		TrainerDef trainer = db.trainer(trainerId);
		if (trainer == null || trainer.getLocations().isEmpty())
		{
			return;
		}
		clearLocatePins();
		if (mapPinImage == null)
		{
			mapPinImage = buildMapPin();
		}
		WorldPoint me = client.getLocalPlayer() != null ? client.getLocalPlayer().getWorldLocation() : null;
		WorldPoint nearest = null;
		int nearestDist = Integer.MAX_VALUE;
		for (TrainerDef.Location loc : trainer.getLocations())
		{
			WorldPoint wp = new WorldPoint(loc.getX(), loc.getY(), loc.getPlane());
			WorldMapPoint pin = new WorldMapPoint(wp, mapPinImage);
			pin.setName(trainer.getName());
			pin.setTarget(wp);
			pin.setJumpOnClick(true);
			pin.setSnapToEdge(true);
			worldMapPointManager.add(pin);
			locatePins.add(pin);
			int dist = me != null && me.getPlane() == wp.getPlane() ? me.distanceTo(wp) : Integer.MAX_VALUE;
			if (nearest == null || dist < nearestDist)
			{
				nearest = wp;
				nearestDist = dist;
			}
		}
		// getWorldMap() is null until the map widget has initialised; the pins still register, and
		// centring is a best-effort nicety, so just skip it when unavailable.
		if (client.getWorldMap() != null)
		{
			client.getWorldMap().setWorldMapPositionTarget(nearest);
		}
		int count = trainer.getLocations().size();
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
			"<col=ff7700>Pet Battles:</col> " + trainer.getName() + " marked on your world map"
				+ (count > 1 ? " (" + count + " locations)." : "."), null);
	}

	private void clearLocatePins()
	{
		for (WorldMapPoint pin : locatePins)
		{
			worldMapPointManager.remove(pin);
		}
		locatePins.clear();
	}

	/**
	 * Print a held item's examine text to the chatbox, like a RuneScape item examine. Dispatched
	 * from the hub's Items grid on the client thread, so it may touch the client directly.
	 *
	 * <p>An unearned item prints nothing at all — not even its name. The grid only offers items the
	 * player owns, so this is defence in depth against a stale button naming a reward the player
	 * hasn't found.
	 */
	private void examineItem(String itemId)
	{
		Item item = Item.byId(itemId);
		if (item == null || !roster.ownsItem(item))
		{
			return;
		}
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
			"<col=ff7700>" + item.getName() + ":</col> " + item.getDescription(), null);
	}

	/**
	 * The world-map marker. The bare paw icon washes out against the tan map, so it's composited
	 * onto a bright, dark-outlined disc and the paw is redrawn as a solid dark silhouette on top —
	 * high-contrast at any map zoom regardless of the source icon's own colours.
	 */
	private BufferedImage buildMapPin()
	{
		BufferedImage paw = ImageUtil.loadImageResource(getClass(), "/com/petbattles/icons/panel_icon.png");
		int size = 28;
		BufferedImage pin = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = pin.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		int inset = 3;
		int d = size - inset * 2;
		g.setColor(new Color(240, 170, 40));
		g.fillOval(inset, inset, d, d);
		g.setColor(new Color(25, 20, 10));
		g.setStroke(new BasicStroke(2.5f));
		g.drawOval(inset, inset, d, d);
		if (paw != null)
		{
			BufferedImage silhouette = ImageUtil.recolorImage(paw, new Color(25, 20, 10));
			int inner = d - 6;
			g.drawImage(silhouette, (size - inner) / 2, (size - inner) / 2, inner, inner, null);
		}
		g.dispose();
		return pin;
	}

	public PetDatabase getDb()
	{
		return db;
	}

	public RosterManager getRoster()
	{
		return roster;
	}

	@Provides
	PetBattlesConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PetBattlesConfig.class);
	}
}

package com.petbattles.bank;

import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.eventbus.Subscribe;

/**
 * Shared "is the player at a bank?" check: true while the bank interface is open or a
 * banker NPC is within a few tiles. Gates team composition changes and pet resting.
 * Bankers are tracked from spawn events (no scene scans); proximity is re-evaluated
 * once per game tick against that small set.
 */
public class AtBankTracker
{
	private static final int BANK_RADIUS_TILES = 10;

	private final Client client;
	private final Runnable onChanged;
	private final Set<NPC> bankers = new HashSet<>();
	private boolean bankInterfaceOpen;
	// Read from the Swing EDT by the panel; written on the client thread
	private volatile boolean atBank;

	public AtBankTracker(Client client, Runnable onChanged)
	{
		this.client = client;
		this.onChanged = onChanged;
	}

	public boolean isAtBank()
	{
		return atBank;
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned e)
	{
		if (isBanker(e.getNpc()))
		{
			bankers.add(e.getNpc());
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned e)
	{
		bankers.remove(e.getNpc());
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded e)
	{
		if (e.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankInterfaceOpen = true;
			update();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed e)
	{
		if (e.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankInterfaceOpen = false;
			update();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOADING || e.getGameState() == GameState.LOGIN_SCREEN
			|| e.getGameState() == GameState.HOPPING)
		{
			bankers.clear();
			bankInterfaceOpen = false;
			update();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		update();
	}

	private void update()
	{
		boolean now = bankInterfaceOpen || bankerNearby();
		if (now != atBank)
		{
			atBank = now;
			onChanged.run();
		}
	}

	private boolean bankerNearby()
	{
		if (bankers.isEmpty() || client.getLocalPlayer() == null)
		{
			return false;
		}
		WorldPoint me = client.getLocalPlayer().getWorldLocation();
		for (NPC banker : bankers)
		{
			WorldPoint p = banker.getWorldLocation();
			if (p != null && me.distanceTo(p) <= BANK_RADIUS_TILES)
			{
				return true;
			}
		}
		return false;
	}

	private static boolean isBanker(NPC npc)
	{
		NPCComposition comp = npc.getComposition();
		if (comp == null || comp.getActions() == null)
		{
			return false;
		}
		for (String action : comp.getActions())
		{
			if ("Bank".equalsIgnoreCase(action))
			{
				return true;
			}
		}
		return false;
	}
}

package com.petbattles.battle;

import com.petbattles.ui.BattleOverlay;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.MouseAdapter;

/**
 * Routes canvas clicks to the battle overlay's buttons. Mouse events arrive on the
 * AWT thread; session mutations are marshalled onto the client thread. Clicks on
 * overlay buttons are consumed so they don't leak into the game world.
 */
public class BattleInputHandler extends MouseAdapter
{
	private final BattleSession session;
	private final BattleOverlay overlay;
	private final ClientThread clientThread;

	public BattleInputHandler(BattleSession session, BattleOverlay overlay, ClientThread clientThread)
	{
		this.session = session;
		this.overlay = overlay;
		this.clientThread = clientThread;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		// Alt+click is overlay repositioning — let the overlay system have it
		if (!session.isActive() || e.getButton() != MouseEvent.BUTTON1 || e.isAltDown())
		{
			return e;
		}
		Rectangle bounds = overlay.getBounds();
		if (bounds == null || !bounds.contains(e.getPoint()))
		{
			return e;
		}
		Point local = new Point(e.getX() - bounds.x, e.getY() - bounds.y);
		for (BattleOverlay.Button button : overlay.getButtons())
		{
			if (button.rect.contains(local))
			{
				String action = button.action;
				clientThread.invokeLater(() -> dispatch(action));
				e.consume();
				return e;
			}
		}
		// Clicking anywhere on the battle window advances the text in manual mode
		if (session.getPhase() == BattleSession.Phase.ANIMATING && session.isManualAdvance())
		{
			clientThread.invokeLater(session::advance);
		}
		// Swallow clicks anywhere on the battle window so they don't hit the game world
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		if (!session.isActive())
		{
			return e;
		}
		Rectangle bounds = overlay.getBounds();
		if (bounds != null && bounds.contains(e.getPoint()))
		{
			overlay.setHoverPoint(new Point(e.getX() - bounds.x, e.getY() - bounds.y));
		}
		else
		{
			overlay.setHoverPoint(null);
		}
		return e;
	}

	private void dispatch(String action)
	{
		if (action.startsWith("move:"))
		{
			session.submitMove(Integer.parseInt(action.substring(5)));
		}
		else if (action.startsWith("forceswitch:"))
		{
			session.submitForcedSwitch(Integer.parseInt(action.substring(12)));
		}
		else if (action.startsWith("switch:"))
		{
			overlay.setSwapMenuOpen(false);
			session.submitSwitch(Integer.parseInt(action.substring(7)));
		}
		else if (action.startsWith("freeswitch:"))
		{
			session.submitFreeSwitch(Integer.parseInt(action.substring(11)));
		}
		else if ("freeswitchcancel".equals(action))
		{
			session.declineFreeSwitch();
		}
		else if ("swapmenu".equals(action))
		{
			overlay.setSwapMenuOpen(true);
		}
		else if ("swapcancel".equals(action))
		{
			overlay.setSwapMenuOpen(false);
		}
		else if (action.startsWith("learn:"))
		{
			session.submitLearnChoice(Integer.parseInt(action.substring(6)));
		}
		else if ("learnskip".equals(action))
		{
			session.submitLearnChoice(-1);
		}
		else if ("flee".equals(action))
		{
			session.submitFlee();
		}
		else if ("close".equals(action))
		{
			session.close();
		}
	}
}

package com.petbattles.battle;

import java.awt.event.KeyEvent;
import net.runelite.api.Client;
import net.runelite.api.VarClientStr;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.KeyListener;

/**
 * Consumes Space to advance battle text while a battle is on-screen in
 * manual-advance mode. We only react to real keypresses — never generate them.
 */
public class BattleKeyListener implements KeyListener
{
	private final Client client;
	private final BattleSession session;
	private final ClientThread clientThread;

	public BattleKeyListener(Client client, BattleSession session, ClientThread clientThread)
	{
		this.client = client;
		this.session = session;
		this.clientThread = clientThread;
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (e.getKeyCode() != KeyEvent.VK_SPACE)
		{
			return;
		}
		if (!session.isActive() || !session.isManualAdvance()
			|| session.getPhase() != BattleSession.Phase.ANIMATING)
		{
			return;
		}
		// Don't steal Space from a chat message the player is typing
		String typed = client.getVarcStrValue(VarClientStr.CHATBOX_TYPED_TEXT);
		if (typed != null && !typed.isEmpty())
		{
			return;
		}
		e.consume();
		clientThread.invokeLater(session::advance);
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
	}
}

package com.petbattles.battle;

import com.petbattles.PetBattlesConfig;
import com.petbattles.data.PetDatabase;
import com.petbattles.engine.BattleAction;
import com.petbattles.engine.BattleEngine;
import com.petbattles.engine.BattleEvent;
import com.petbattles.engine.BattlePet;
import com.petbattles.engine.BattleState;
import com.petbattles.engine.ItemEffect;
import com.petbattles.engine.LearnsetEntry;
import com.petbattles.engine.Leveling;
import com.petbattles.engine.MoveDef;
import com.petbattles.engine.PetInstance;
import com.petbattles.engine.SpeciesDef;
import com.petbattles.engine.TrainerDef;
import com.petbattles.engine.TypeChart;
import com.petbattles.engine.controller.AiController;
import com.petbattles.engine.controller.OpponentController;
import com.petbattles.item.EquipItemDef;
import com.petbattles.persist.RosterManager;
import com.petbattles.quest.QuestDialogSession;
import com.petbattles.quest.QuestManager;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;

/**
 * Client-side battle orchestration: builds teams, paces engine events out on game
 * ticks for the overlay, collects player input, and awards XP at the end.
 * All methods are called on the client thread (game ticks and consumed mouse input).
 */
@Slf4j
public class BattleSession
{
	public enum Phase
	{
		IDLE,
		ANIMATING,
		AWAITING_INPUT,
		// Player's active pet fainted mid-turn; they must pick a replacement to continue
		FORCED_SWITCH,
		// The enemy just sent in a replacement after a KO; the player is offered one optional,
		// cost-free swap before their next turn (declining keeps the current pet).
		FREE_SWITCH,
		// A pet levelled into a new move with a full moveset; player must forget one or skip
		LEARN_MOVE,
		ENDED
	}

	// The DAMAGE/HEALED HP bar drains over this window of the event's 0->1 progress, so the
	// hit-splat pops first (0 -> HP_DRAIN_START) and the bar then animates to the new value.
	private static final float HP_DRAIN_START = 0.15f;
	private static final float HP_DRAIN_END = 0.55f;

	/**
	 * One row of the post-battle summary: a pet that fought, its ending state and rewards.
	 */
	public static final class SummaryEntry
	{
		private final String name;
		private final int displayItemId;
		private final boolean fought;
		private final int level;
		private final int currentHp;
		private final int maxHp;
		private final boolean fainted;
		private final long xpGained;
		private final int levelsGained;
		private final List<String> learnedMoves;

		SummaryEntry(String name, int displayItemId, boolean fought, int level, int currentHp, int maxHp,
			boolean fainted, long xpGained, int levelsGained, List<String> learnedMoves)
		{
			this.name = name;
			this.displayItemId = displayItemId;
			this.fought = fought;
			this.level = level;
			this.currentHp = currentHp;
			this.maxHp = maxHp;
			this.fainted = fainted;
			this.xpGained = xpGained;
			this.levelsGained = levelsGained;
			this.learnedMoves = learnedMoves;
		}

		public String getName()
		{
			return name;
		}

		/** Item id of the pet's icon at its current growth stage, for the summary slot. */
		public int getDisplayItemId()
		{
			return displayItemId;
		}

		/** Whether this pet actually took the field (and so earned XP), vs. sat benched. */
		public boolean isFought()
		{
			return fought;
		}

		public int getLevel()
		{
			return level;
		}

		public int getCurrentHp()
		{
			return currentHp;
		}

		public int getMaxHp()
		{
			return maxHp;
		}

		public boolean isFainted()
		{
			return fainted;
		}

		public long getXpGained()
		{
			return xpGained;
		}

		public int getLevelsGained()
		{
			return levelsGained;
		}

		public List<String> getLearnedMoves()
		{
			return learnedMoves;
		}
	}

	private final Client client;
	private final PetDatabase db;
	private final RosterManager roster;
	private final QuestManager questManager;
	// Where a cleared chapter's payoff conversation goes: the quest dialog frame holds it until this
	// battle window is gone (learn prompts and the level-up summary included), then plays it.
	private final QuestDialogSession questDialog;
	private final PetBattlesConfig config;
	private final BattleEngine engine;
	private final BattleSoundManager sound;
	private final Runnable onRosterChanged;

	private Phase phase = Phase.IDLE;
	private BattleState state;
	private OpponentController enemyController;
	private TrainerDef trainer;
	private Random rng;
	private final Deque<BattleEvent> pendingEvents = new ArrayDeque<>();
	// Per-pet results for the end-of-battle summary screen, built when the battle ends.
	private final List<SummaryEntry> summary = new ArrayList<>();
	// XP/levels/moves accrued per participating pet across the battle (keyed by species id).
	private final Map<String, Progress> progress = new HashMap<>();
	// Full-moveset learns awaiting the player's forget-or-skip choice, oldest first.
	private final Deque<PendingLearn> pendingLearns = new ArrayDeque<>();
	private int tickCounter;
	private boolean finalized;
	// Set true while an enemy replacement is surfaced after a KO; if the player still has a
	// benched pet to switch to, the queue drains into FREE_SWITCH to offer one cost-free swap.
	private boolean freeSwitchOffer;
	private BattleEvent currentEvent;
	private MoveDef currentMove;
	private long eventStartMs;

	// --- presentation state: what the overlay draws, lagged behind the resolved model ---
	// Displayed HP per pet (by identity): the value currently at rest on screen. Damage/heal
	// events animate this toward the model value while their line is shown (see displayHp).
	private final Map<BattlePet, Float> shownHp = new IdentityHashMap<>();
	// Pets whose FAINTED line has already been surfaced, so the overlay may settle them to a
	// faint ghost. A pet is NOT settled here until its faint line plays — that keeps the
	// collapse from firing during the attacker's earlier MOVE_USED/DAMAGE lines.
	private final Set<BattlePet> faintShown = Collections.newSetFromMap(new IdentityHashMap<>());
	// The pet whose HP the current event is animating (or null), with its from/to endpoints.
	private BattlePet hpAnimPet;
	private float hpAnimFrom;
	private float hpAnimTo;
	// Player pets that have taken the field against the CURRENT enemy — the KO's XP is split
	// evenly among them (shared experience). Reset each time a new enemy is sent out.
	// LinkedHashSet gives identity semantics (BattlePet has no equals override) + stable order.
	private final Set<BattlePet> enemyParticipants = new LinkedHashSet<>();

	public BattleSession(Client client, PetDatabase db, RosterManager roster, QuestManager questManager,
		QuestDialogSession questDialog, PetBattlesConfig config, Runnable onRosterChanged)
	{
		this.client = client;
		this.db = db;
		this.roster = roster;
		this.questManager = questManager;
		this.questDialog = questDialog;
		this.config = config;
		this.engine = new BattleEngine(db.getTypeChart());
		this.sound = new BattleSoundManager(client, config);
		this.onRosterChanged = onRosterChanged;
	}

	/**
	 * Start a battle against the given trainer using the player's current team.
	 * Returns false (with no state change) if a battle is running or the team is empty.
	 */
	public boolean startTrainerBattle(String trainerId)
	{
		if (phase != Phase.IDLE && phase != Phase.ENDED)
		{
			return false;
		}
		TrainerDef def = db.trainer(trainerId);
		if (def == null || roster.getTeam().isEmpty())
		{
			return false;
		}

		List<BattlePet> playerTeam = new ArrayList<>();
		for (String speciesId : roster.getTeam())
		{
			BattlePet pet = buildPlayerPet(speciesId);
			if (pet != null)
			{
				playerTeam.add(pet);
			}
		}
		if (playerTeam.isEmpty())
		{
			return false;
		}

		List<BattlePet> enemyTeam = new ArrayList<>();
		for (TrainerDef.PartyEntry entry : def.getParty())
		{
			SpeciesDef species = db.species(entry.getSpecies());
			enemyTeam.add(new BattlePet(species, species.nameAt(entry.getLevel()), entry.getLevel(),
				enemyMoves(species, entry.getLevel())));
		}

		trainer = def;
		enemyController = new AiController(def.getDifficulty(), db.getTypeChart());
		rng = new Random();
		pendingEvents.clear();
		summary.clear();
		pendingLearns.clear();
		progress.clear();
		shownHp.clear();
		faintShown.clear();
		enemyParticipants.clear();
		hpAnimPet = null;
		// Seed each pet's displayed HP with its starting HP so the first hit animates from full.
		for (BattlePet bp : playerTeam)
		{
			shownHp.put(bp, (float) bp.getCurrentHp());
		}
		for (BattlePet bp : enemyTeam)
		{
			shownHp.put(bp, (float) bp.getCurrentHp());
		}
		// Snapshot starting levels so the summary can show levels gained across the fight.
		for (BattlePet bp : playerTeam)
		{
			PetInstance inst = roster.getPet(bp.getSpecies().getId());
			progress.put(bp.getSpecies().getId(), new Progress(inst != null ? inst.getLevel() : bp.getLevel()));
		}
		finalized = false;
		tickCounter = 0;

		List<BattleEvent> events = new ArrayList<>();
		events.add(BattleEvent.of(BattleEvent.Type.PET_SENT_OUT, -1,
			def.getName() + " wants to battle!"));
		state = engine.start(playerTeam, enemyTeam, events);
		pendingEvents.addAll(events);
		roster.recordBattleFought();
		beginAnimating();
		return true;
	}

	private BattlePet buildPlayerPet(String speciesId)
	{
		SpeciesDef species = db.species(speciesId);
		PetInstance instance = roster.getOrCreatePet(speciesId);
		if (species == null || instance == null || instance.isFainted())
		{
			// Fainted pets are benched until rested at a bank
			return null;
		}
		List<MoveDef> moves = new ArrayList<>();
		for (String moveId : instance.getEquippedMoves())
		{
			MoveDef move = db.move(moveId);
			if (move != null)
			{
				moves.add(move);
			}
		}
		String variantId = instance.getActiveVariantId();
		if (moves.isEmpty())
		{
			// Fallback: level-1 learnset move so a pet is never unarmed
			for (String moveId : species.movesKnownFor(variantId, 1))
			{
				MoveDef move = db.move(moveId);
				if (move != null)
				{
					moves.add(move);
					break;
				}
			}
		}
		String name = instance.getNickname() != null ? instance.getNickname()
			: species.nameFor(variantId, instance.getLevel());
		BattlePet battler = new BattlePet(species, name, instance.getLevel(), moves,
			instance.getCurrentHp(), variantId, heldEffect(instance.getHeldItemId()));
		battler.setCosmetics(instance.getHeadItemId(), instance.getFaceItemId());
		return battler;
	}

	/**
	 * The passive stat modifier for a pet's equipped held item, or null if it holds nothing, the id
	 * is unknown, or the item is a cosmetic (no combat effect).
	 */
	private ItemEffect heldEffect(String heldItemId)
	{
		if (heldItemId == null)
		{
			return null;
		}
		EquipItemDef item = db.equipItem(heldItemId);
		return item == null ? null : item.getEffect();
	}

	private List<MoveDef> enemyMoves(SpeciesDef species, int level)
	{
		List<MoveDef> moves = new ArrayList<>();
		for (String moveId : species.movesKnownAt(level))
		{
			MoveDef move = db.move(moveId);
			if (move != null)
			{
				moves.add(move);
			}
			if (moves.size() >= PetInstance.MAX_EQUIPPED_MOVES)
			{
				break;
			}
		}
		return moves;
	}

	/**
	 * Advance pacing by one game tick. In manual-advance mode (the default) this only
	 * surfaces the first line after a submit; every further line waits for advance().
	 */
	public void tick()
	{
		if (phase != Phase.ANIMATING)
		{
			return;
		}
		if (isManualAdvance())
		{
			if (currentEvent == null)
			{
				advanceEvent();
			}
			return;
		}
		if (++tickCounter < config.battleSpeed())
		{
			return;
		}
		// Per-event dwell: hold impactful events (level-ups, flying projectiles)
		// until their animation has fully played out
		if (getAnimationProgress() < 1f)
		{
			tickCounter = config.battleSpeed();
			return;
		}
		tickCounter = 0;
		advanceEvent();
	}

	/**
	 * Player clicked / pressed Space to show the next battle line (manual-advance mode).
	 */
	public void advance()
	{
		if (phase != Phase.ANIMATING || !isManualAdvance())
		{
			return;
		}
		advanceEvent();
	}

	public boolean isManualAdvance()
	{
		return !config.autoAdvanceBattleText();
	}

	/**
	 * Enter ANIMATING after queuing events. In manual mode the first line shows
	 * immediately instead of waiting a game tick.
	 */
	private void beginAnimating()
	{
		phase = Phase.ANIMATING;
		tickCounter = 0;
		currentEvent = null;
		// Cleared each batch; re-set only if this batch surfaces an enemy on-faint replacement.
		freeSwitchOffer = false;
		if (isManualAdvance())
		{
			advanceEvent();
		}
	}

	/**
	 * Show the next event, or hand over control / finish once the queue drains.
	 */
	private void advanceEvent()
	{
		// Leaving the previous line: rest its HP animation at the value it reached.
		commitHpAnimation();
		BattleEvent event = pendingEvents.poll();
		if (event == null && state.isOver() && !finalized)
		{
			finalizeBattle();
			event = pendingEvents.poll();
		}
		if (event != null)
		{
			if (event.getType() == BattleEvent.Type.FAINTED && event.getSide() == BattleState.ENEMY)
			{
				// An enemy just went down: reward the active pet now and queue its level-up /
				// move-learning lines to play right after this faint line.
				awardFaintXp();
			}
			currentEvent = event;
			eventStartMs = System.currentTimeMillis();
			if (event.getType() == BattleEvent.Type.MOVE_USED)
			{
				// Remembered through the following DAMAGE/STATUS events for tinting
				currentMove = event.getMove();
			}
			// One cue per surfaced line: the move's sound on MOVE_USED, a whiff on MISSED.
			sound.play(event, currentMove);
			if (event.isDeferredSwitch())
			{
				// Apply the enemy's on-faint swap now, so the fainted pet was shown through
				// its faint animation and the replacement appears exactly on this line
				state.setActive(event.getSide(), event.getValue());
				// The enemy just sent in a fresh pet after a KO — flag an optional free swap for
				// the player, honoured at the drain below if they still have a benched pet.
				if (event.getSide() == BattleState.ENEMY)
				{
					freeSwitchOffer = true;
				}
			}
			// Shared-XP bookkeeping: a fresh enemy resets the participant pool; whoever the
			// player has on the field (now, and as they swap) joins the pool for this enemy.
			if (event.getType() == BattleEvent.Type.PET_SENT_OUT && event.getSide() == BattleState.ENEMY)
			{
				enemyParticipants.clear();
			}
			BattlePet activePlayer = state.active(BattleState.PLAYER);
			if (activePlayer != null)
			{
				enemyParticipants.add(activePlayer);
			}
			// Damage/heal lines animate the affected pet's HP bar as they play.
			beginHpAnimation(event);
			// The faint only "reveals" (settles to a ghost) once its own line is shown, never
			// during the earlier attack/damage lines that read the already-resolved model.
			if (event.getType() == BattleEvent.Type.FAINTED)
			{
				BattlePet fainter = state.active(event.getSide());
				if (fainter != null)
				{
					faintShown.add(fainter);
				}
			}
			if (PetBattlesConfig.devBattleTrace())
			{
				log.debug("[battle] event {} side={} phase={} queue={} : {}",
					event.getType(), event.getSide(), phase, pendingEvents.size(), event.getText());
			}
			return;
		}
		currentEvent = null;
		// A full-moveset learn pauses everything until the player forgets a move or skips.
		if (!pendingLearns.isEmpty())
		{
			phase = Phase.LEARN_MOVE;
			return;
		}
		if (state.isOver())
		{
			enterEnded();
			return;
		}
		if (state.awaitingForcedSwitch())
		{
			phase = Phase.FORCED_SWITCH;
			return;
		}
		// The enemy sent in a replacement this batch and the player still has a bench pet: offer
		// one cost-free swap before their next turn. Otherwise it's a normal command turn.
		if (freeSwitchOffer && hasBenchTarget())
		{
			freeSwitchOffer = false;
			phase = Phase.FREE_SWITCH;
			return;
		}
		phase = Phase.AWAITING_INPUT;
	}

	/**
	 * Whether the player has a benched pet (not active, not fainted) they could switch to.
	 */
	private boolean hasBenchTarget()
	{
		List<BattlePet> team = state.team(BattleState.PLAYER);
		int active = state.activeIndex(BattleState.PLAYER);
		for (int i = 0; i < team.size(); i++)
		{
			if (i != active && !team.get(i).isFainted())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Player picked a move (index into the active pet's move list).
	 */
	public void submitMove(int moveIndex)
	{
		if (phase != Phase.AWAITING_INPUT)
		{
			return;
		}
		BattlePet active = state.active(BattleState.PLAYER);
		if (moveIndex < 0 || moveIndex >= active.getMoves().size())
		{
			return;
		}
		BattleAction enemyAction = enemyController.chooseAction(state, BattleState.ENEMY, rng);
		pendingEvents.addAll(engine.resolveTurn(state, BattleAction.move(moveIndex), enemyAction, rng));
		beginAnimating();
	}

	/**
	 * Player swaps the active pet for the bench pet at the given team index.
	 * Consumes the turn; the enemy still acts.
	 */
	public void submitSwitch(int teamIndex)
	{
		if (phase != Phase.AWAITING_INPUT)
		{
			return;
		}
		BattleAction enemyAction = enemyController.chooseAction(state, BattleState.ENEMY, rng);
		pendingEvents.addAll(engine.resolveTurn(state, BattleAction.switchTo(teamIndex), enemyAction, rng));
		beginAnimating();
	}

	/**
	 * Player picked a replacement after their active pet fainted mid-turn. Unlike a
	 * voluntary switch this doesn't run a full turn — the incoming pet just takes over,
	 * and the next real turn is the player's to command.
	 */
	public void submitForcedSwitch(int teamIndex)
	{
		if (phase != Phase.FORCED_SWITCH)
		{
			return;
		}
		pendingEvents.addAll(engine.resolveForcedSwitch(state, teamIndex));
		beginAnimating();
	}

	/**
	 * Player accepted the post-KO free swap: the incoming pet takes over at no turn cost, then
	 * play resumes on the player's next command turn. Ignored unless a free swap is being offered.
	 */
	public void submitFreeSwitch(int teamIndex)
	{
		if (phase != Phase.FREE_SWITCH)
		{
			return;
		}
		pendingEvents.addAll(engine.resolveOptionalSwitch(state, teamIndex));
		beginAnimating();
	}

	/**
	 * Player declined the post-KO free swap and keeps their current pet: straight to their turn.
	 */
	public void declineFreeSwitch()
	{
		if (phase != Phase.FREE_SWITCH)
		{
			return;
		}
		freeSwitchOffer = false;
		phase = Phase.AWAITING_INPUT;
	}

	public void submitFlee()
	{
		if (phase != Phase.AWAITING_INPUT)
		{
			return;
		}
		BattleAction enemyAction = enemyController.chooseAction(state, BattleState.ENEMY, rng);
		pendingEvents.addAll(engine.resolveTurn(state, BattleAction.flee(), enemyAction, rng));
		beginAnimating();
	}

	/**
	 * Dismiss the finished battle (or forfeit-close a stuck one from the panel).
	 */
	public void close()
	{
		// Forfeit-closing mid-battle still persists the damage taken so far
		if (state != null && !finalized && phase != Phase.IDLE)
		{
			persistTeamHp();
			roster.petChanged();
			onRosterChanged.run();
		}
		phase = Phase.IDLE;
		state = null;
		trainer = null;
		pendingEvents.clear();
		summary.clear();
		pendingLearns.clear();
		progress.clear();
		shownHp.clear();
		faintShown.clear();
		enemyParticipants.clear();
		hpAnimPet = null;
		currentEvent = null;
		currentMove = null;
		// A pending payoff conversation is deliberately left alone: closing this window is what
		// releases it to the quest dialog frame.
	}

	/**
	 * Award XP for the enemy pet that just fainted, split evenly among every player pet that
	 * took the field against it (shared experience), and queue each earner's XP / level-up /
	 * move-learned lines to play right after the faint line. Full-moveset learns are pushed onto
	 * {@link #pendingLearns} for an in-battle forget-or-skip prompt. Called per enemy faint, so
	 * rewards land per-faint rather than in a lump.
	 */
	private void awardFaintXp()
	{
		BattlePet fallen = state.active(BattleState.ENEMY);
		if (fallen == null)
		{
			return;
		}
		// The pets that were out against this enemy share its reward; fall back to the active
		// pet if (defensively) the pool is somehow empty.
		List<BattlePet> earners = new ArrayList<>(enemyParticipants);
		if (earners.isEmpty())
		{
			BattlePet active = state.active(BattleState.PLAYER);
			if (active != null)
			{
				earners.add(active);
			}
		}
		// Re-fights taper toward half rate, 10% per previous win (Leveling.repeatFactor). The win
		// count is only bumped at battle end, so every faint in this fight pays the same rate.
		int priorWins = roster.trainerWins(trainer.getId());
		// Dev XP boost multiplies rewards so abilities/growth stages are quick to reach in testing
		int mult = Math.max(1, PetBattlesConfig.devXpMultiplier());
		// Split evenly across everyone who was on the field, so a shared KO dilutes each share.
		int share = Math.max(1, earners.size());

		List<BattleEvent> inject = new ArrayList<>();
		boolean anyAward = false;
		for (BattlePet earner : earners)
		{
			String speciesId = earner.getSpecies().getId();
			PetInstance pet = roster.getPet(speciesId);
			SpeciesDef species = db.species(speciesId);
			if (pet == null || species == null || pet.getLevel() >= Leveling.MAX_LEVEL)
			{
				continue;
			}
			int oldLevel = pet.getLevel();
			Progress p = progress.computeIfAbsent(speciesId, k -> new Progress(oldLevel));
			long xp = Math.max(1,
				Leveling.battleWinXp(fallen.getLevel(), pet.getLevel(), priorWins) * mult / share);
			// Cap the per-battle jump relative to the level this pet entered the battle at, so a
			// single win can't rocket a low-level pet up the compressed early curve (feedback #3).
			xp = Leveling.capBattleXp(pet.getXp(), xp, p.startLevel);
			if (xp <= 0)
			{
				// Already hit the per-battle level cap on an earlier faint this fight.
				continue;
			}
			int gained = pet.addXp(xp);
			p.xp += xp;
			anyAward = true;
			if (PetBattlesConfig.devBattleTrace())
			{
				log.debug("[battle] {} shares KO of {} (Lv{}): +{} xp (1/{}), level {}->{}",
					displayName(pet, species), fallen.getDisplayName(), fallen.getLevel(), xp, share,
					oldLevel, pet.getLevel());
			}
			inject.add(BattleEvent.value(BattleEvent.Type.XP_GAINED, BattleState.PLAYER, (int) xp,
				displayName(pet, species) + " gained " + xp + " XP!"));
			if (gained > 0)
			{
				int newLevel = pet.getLevel();
				// Grow the on-field battler too, so its level/HP/stats/sprite match the roster
				// for the rest of this fight (the info card was showing the start-of-battle level).
				int hpGain = earner.growTo(newLevel);
				if (hpGain > 0)
				{
					// Keep the displayed HP in step with the level-up heal so the bar doesn't lag.
					shownHp.merge(earner, (float) hpGain, Float::sum);
				}
				inject.add(BattleEvent.value(BattleEvent.Type.LEVEL_UP, BattleState.PLAYER, newLevel,
					displayName(pet, species) + " grew to level " + newLevel + "!"));
				learnMovesForLevelUp(pet, species, oldLevel, newLevel, p, inject);
			}
		}
		if (anyAward)
		{
			roster.petChanged();
		}
		// Push in front of the queue, preserving order, so they follow the faint line just shown.
		for (int i = inject.size() - 1; i >= 0; i--)
		{
			pendingEvents.addFirst(inject.get(i));
		}
	}

	/**
	 * Equip every newly reached learnset move that fits; queue the rest ({@link PendingLearn})
	 * for the player to resolve. Auto-equipped moves get a MOVE_LEARNED line and land on the
	 * summary; deferred ones are announced only once the player chooses.
	 */
	private void learnMovesForLevelUp(PetInstance pet, SpeciesDef species, int oldLevel, int newLevel,
		Progress p, List<BattleEvent> inject)
	{
		for (LearnsetEntry entry : species.getLearnset())
		{
			if (entry.getLevel() <= oldLevel || entry.getLevel() > newLevel)
			{
				continue;
			}
			MoveDef move = db.move(entry.getMove());
			if (move == null || pet.getEquippedMoves().contains(entry.getMove()))
			{
				continue;
			}
			if (pet.getEquippedMoves().size() < PetInstance.MAX_EQUIPPED_MOVES)
			{
				pet.equipMove(entry.getMove());
				p.learned.add(move.getName());
				inject.add(BattleEvent.of(BattleEvent.Type.MOVE_LEARNED, BattleState.PLAYER,
					displayName(pet, species) + " learned " + move.getName() + "!"));
				if (PetBattlesConfig.devBattleTrace())
				{
					log.debug("[battle] {} auto-learned {} (free slot)", displayName(pet, species), move.getName());
				}
			}
			else
			{
				pendingLearns.add(new PendingLearn(pet, species, move));
				if (PetBattlesConfig.devBattleTrace())
				{
					log.debug("[battle] {} defers {} (full moveset) -> pendingLearns", displayName(pet, species), move.getName());
				}
			}
		}
		// Make any auto-equipped move usable for the rest of THIS battle, not just the next one.
		syncBattleMoves(pet);
	}

	/**
	 * Re-sync a player pet's in-battle moveset from its (just-updated) persistent instance, so a
	 * move learned or forgotten mid-battle takes effect immediately for the current fight.
	 */
	private void syncBattleMoves(PetInstance pet)
	{
		if (state == null)
		{
			return;
		}
		for (BattlePet bp : state.team(BattleState.PLAYER))
		{
			if (!bp.getSpecies().getId().equals(pet.getSpeciesId()))
			{
				continue;
			}
			List<MoveDef> moves = new ArrayList<>();
			for (String moveId : pet.getEquippedMoves())
			{
				MoveDef m = db.move(moveId);
				if (m != null)
				{
					moves.add(m);
				}
			}
			bp.setMoves(moves);
			if (PetBattlesConfig.devBattleTrace())
			{
				log.debug("[battle] resynced {} in-battle moves -> {}", bp.getDisplayName(), pet.getEquippedMoves());
			}
			return;
		}
	}

	/**
	 * The player picked a move to forget (index into the current moveset) or skipped
	 * ({@code moveIndex < 0}) the pending learn. Resolves one queued learn, then either shows
	 * the next one or resumes the battle.
	 */
	public void submitLearnChoice(int moveIndex)
	{
		if (phase != Phase.LEARN_MOVE)
		{
			return;
		}
		PendingLearn pl = pendingLearns.poll();
		if (pl != null)
		{
			List<String> equipped = pl.pet.getEquippedMoves();
			if (!equipped.contains(pl.newMove.getId()))
			{
				if (equipped.size() < PetInstance.MAX_EQUIPPED_MOVES)
				{
					// A slot opened up (an earlier skip/forget in this batch): just learn it.
					pl.pet.equipMove(pl.newMove.getId());
					recordLearned(pl);
				}
				else if (moveIndex >= 0 && moveIndex < equipped.size())
				{
					String forgotten = equipped.get(moveIndex);
					pl.pet.unequipMove(forgotten);
					pl.pet.equipMove(pl.newMove.getId());
					recordLearned(pl);
					if (PetBattlesConfig.devBattleTrace())
					{
						log.debug("[battle] {} forgot {} to learn {}", displayName(pl.pet, pl.species),
							forgotten, pl.newMove.getName());
					}
				}
				// moveIndex < 0 => player declined; learn nothing.
			}
			// Reflect the swap in the active battler's moveset for the rest of this fight.
			syncBattleMoves(pl.pet);
			roster.petChanged();
			onRosterChanged.run();
		}
		if (!pendingLearns.isEmpty())
		{
			return; // stay in LEARN_MOVE for the next queued move
		}
		if (state.isOver())
		{
			enterEnded();
		}
		else
		{
			phase = state.awaitingForcedSwitch() ? Phase.FORCED_SWITCH : Phase.AWAITING_INPUT;
		}
	}

	private void recordLearned(PendingLearn pl)
	{
		Progress p = progress.get(pl.pet.getSpeciesId());
		if (p != null)
		{
			p.learned.add(pl.newMove.getName());
		}
	}

	/**
	 * Finish the battle once the last event drains: persist HP, record the trainer win, save.
	 * XP was already awarded per faint, so nothing is rewarded here.
	 */
	private void finalizeBattle()
	{
		finalized = true;
		// Battle damage survives the fight: heal at a bank to restore it
		persistTeamHp();
		if (state.getPhase() == BattleState.Phase.PLAYER_WON)
		{
			// The win count must be read before recordTrainerDefeated bumps it, so this win is paid
			// at the rate its own prior-win count earned.
			awardCoins(roster.trainerWins(trainer.getId()));
			roster.recordTrainerDefeated(trainer.getId());
			grantQuestRewards();
		}
		roster.petChanged();
		onRosterChanged.run();
	}

	/**
	 * Grant the battle-win coin reward: a single flat per-battle amount (not shared per pet like XP)
	 * scaled by the trainer's combined team level, tapering on repeat wins. Coins land in the player's
	 * wallet; a plugin system line reports the earning (never player chat), per AGENTS chat rules.
	 */
	private void awardCoins(int priorWins)
	{
		int totalEnemyLevels = 0;
		for (TrainerDef.PartyEntry entry : trainer.getParty())
		{
			totalEnemyLevels += entry.getLevel();
		}
		long coins = Leveling.battleWinCoins(totalEnemyLevels, priorWins);
		if (coins <= 0)
		{
			return;
		}
		long balance = roster.addCoins(coins);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
			"<col=ff7700>Pet Battles:</col> You earned <col=ffff00>" + coins + "</col> coins. "
				+ "(Wallet: <col=ffff00>" + balance + "</col>)", null);
	}

	/**
	 * Story-quest progress tied to beating this trainer: {@link QuestManager#onTrainerDefeated(String)}
	 * advances the matching chapter and grants its reward. On a hit we hand the chapter's payoff
	 * conversation to the quest dialog frame — the one surface quest talking happens on — and log a
	 * plugin system line for the reward (never player chat), per AGENTS chat rules.
	 */
	private void grantQuestRewards()
	{
		QuestManager.DefeatResult story = questManager.onTrainerDefeated(trainer.getId());
		if (story != null)
		{
			questDialog.play(story.getConversation());
			announceStoryReward(story);
		}
	}

	/**
	 * Report a story chapter's reward (item and/or coins) as a plugin system line — never player chat.
	 */
	private void announceStoryReward(QuestManager.DefeatResult story)
	{
		StringBuilder msg = new StringBuilder("<col=ff7700>Pet Battles:</col>");
		String itemName = story.getRewardItemName();
		if (itemName != null)
		{
			msg.append(" You received the <col=ffffff>").append(itemName).append("</col>!");
		}
		if (story.getRewardCoins() > 0)
		{
			msg.append(" You earned <col=ffff00>").append(story.getRewardCoins()).append("</col> coins.");
		}
		if (itemName != null || story.getRewardCoins() > 0)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", msg.toString(), null);
		}
	}

	/**
	 * Build the post-battle summary (every pet on the battle team gets a slot) and show it.
	 * Called once all queued move-learn prompts are resolved, so learned moves are reflected.
	 */
	private void enterEnded()
	{
		summary.clear();
		List<BattlePet> battled = state.team(BattleState.PLAYER);
		for (int i = 0; i < battled.size(); i++)
		{
			BattlePet bp = battled.get(i);
			PetInstance pet = roster.getPet(bp.getSpecies().getId());
			SpeciesDef species = db.species(bp.getSpecies().getId());
			if (pet == null || species == null)
			{
				continue;
			}
			boolean fought = state.hasFought(BattleState.PLAYER, i);
			Progress p = progress.get(bp.getSpecies().getId());
			long xp = p != null ? p.xp : 0;
			int startLevel = p != null ? p.startLevel : pet.getLevel();
			List<String> learned = p != null ? p.learned : new ArrayList<>();
			summary.add(new SummaryEntry(displayName(pet, species),
				species.itemIdFor(pet.getActiveVariantId(), pet.getLevel()), fought,
				pet.getLevel(), bp.getCurrentHp(), bp.getMaxHp(), bp.isFainted(), xp,
				pet.getLevel() - startLevel, learned));
		}
		phase = Phase.ENDED;
	}

	/**
	 * Write each battled pet's ending HP back to its persistent instance. Full HP is
	 * stored as null ("fully rested") so untouched pets never look injured.
	 * Callers are responsible for the save/refresh (petChanged + onRosterChanged).
	 */
	private void persistTeamHp()
	{
		for (BattlePet battlePet : state.team(BattleState.PLAYER))
		{
			PetInstance instance = roster.getPet(battlePet.getSpecies().getId());
			if (instance == null)
			{
				continue;
			}
			instance.setCurrentHp(battlePet.getCurrentHp() >= battlePet.getMaxHp()
				? null : battlePet.getCurrentHp());
		}
	}

	private static String displayName(PetInstance pet, SpeciesDef species)
	{
		return pet.getNickname() != null ? pet.getNickname()
			: species.nameFor(pet.getActiveVariantId(), pet.getLevel());
	}

	// --- accessors for the overlay ---

	public Phase getPhase()
	{
		return phase;
	}

	public boolean isActive()
	{
		return phase != Phase.IDLE;
	}

	public boolean isAwaitingInput()
	{
		return phase == Phase.AWAITING_INPUT;
	}

	/**
	 * The move-learning choice currently awaiting the player during {@link Phase#LEARN_MOVE},
	 * or null. Reads the pet's live moveset so it always reflects earlier choices in the batch.
	 */
	public LearnPrompt getLearnPrompt()
	{
		PendingLearn pl = pendingLearns.peek();
		if (pl == null)
		{
			return null;
		}
		List<MoveDef> current = new ArrayList<>();
		for (String moveId : pl.pet.getEquippedMoves())
		{
			MoveDef m = db.move(moveId);
			if (m != null)
			{
				current.add(m);
			}
		}
		return new LearnPrompt(displayName(pl.pet, pl.species), pl.newMove, current);
	}

	public BattleState getState()
	{
		return state;
	}

	public TrainerDef getTrainer()
	{
		return trainer;
	}

	/**
	 * Type chart for UI match-up hints (e.g. the swap menu).
	 */
	public TypeChart getTypeChart()
	{
		return engine.getTypeChart();
	}

	/**
	 * Per-pet results for the end-of-battle summary screen (only pets that fought).
	 */
	public List<SummaryEntry> getSummary()
	{
		return Collections.unmodifiableList(summary);
	}

	/**
	 * The event currently on display (drives the dialog box and animations), or null.
	 */
	public BattleEvent getCurrentEvent()
	{
		return currentEvent;
	}

	/**
	 * The move behind the most recent MOVE_USED event, for effect tinting.
	 */
	public MoveDef getCurrentMove()
	{
		return currentMove;
	}

	/**
	 * 0.0 → 1.0 progress of the current event's animation, smooth against wall-clock
	 * time so overlay motion isn't stepped by game ticks.
	 */
	public float getAnimationProgress()
	{
		if (currentEvent == null)
		{
			return 1f;
		}
		long elapsed = System.currentTimeMillis() - eventStartMs;
		return Math.min(1f, elapsed / (float) animationDurationMs(currentEvent.getType()));
	}

	/**
	 * Per-event-type animation dwell so impactful moments get time to read.
	 */
	private static int animationDurationMs(BattleEvent.Type type)
	{
		switch (type)
		{
			case MOVE_USED:
				return 500;
			case DAMAGE:
				return 650;
			case MISSED:
				return 500;
			case LEVEL_UP:
				return 1500;
			case HEALED:
				return 700;
			case FAINTED:
				return 900;
			default:
				return 400;
		}
	}

	/**
	 * Rest the in-flight HP animation at its target, so the bar stays put once its line ends.
	 */
	private void commitHpAnimation()
	{
		if (hpAnimPet != null)
		{
			shownHp.put(hpAnimPet, hpAnimTo);
			hpAnimPet = null;
		}
	}

	/**
	 * If {@code event} changes a pet's HP (damage, status chip, heal), start animating that
	 * pet's displayed HP from where it rests now by the event's OWN delta. Crucially the target
	 * is derived from {@code event.getValue()}, not the live model: the engine resolves the whole
	 * turn up front, so the model already holds the end-of-turn HP. Using the per-event delta lets
	 * each of a pet's several changes in one turn (e.g. a hit then its burn/poison tick) animate
	 * its own step in order. {@code shownHp} tracks the displayed value, so deltas accumulate.
	 */
	private void beginHpAnimation(BattleEvent event)
	{
		BattlePet affected;
		int delta;
		switch (event.getType())
		{
			case DAMAGE:
			case STATUS_TICK:
				affected = event.getSide() >= 0 ? state.active(event.getSide()) : null;
				delta = -event.getValue();
				break;
			case HEALED:
				affected = event.getSide() >= 0 ? state.active(event.getSide()) : null;
				delta = event.getValue();
				break;
			default:
				affected = null;
				delta = 0;
				break;
		}
		if (affected == null)
		{
			return;
		}
		hpAnimPet = affected;
		Float rest = shownHp.get(affected);
		hpAnimFrom = rest != null ? rest : affected.getCurrentHp();
		hpAnimTo = Math.max(0f, Math.min(affected.getMaxHp(), hpAnimFrom + delta));
		if (PetBattlesConfig.devBattleTrace())
		{
			log.debug("[battle] hp {} {} -> {} (d={})", affected.getDisplayName(), hpAnimFrom, hpAnimTo, delta);
		}
	}

	/**
	 * Displayed HP for a pet's bar: the value currently on screen, which lags the resolved
	 * model. While this pet's damage/heal line is showing, it interpolates over the drain
	 * window (so the hit-splat lands first); otherwise it's the value the last line rested on.
	 */
	public float displayHp(BattlePet pet)
	{
		if (pet == null)
		{
			return 0f;
		}
		if (pet == hpAnimPet && currentEvent != null)
		{
			float p = getAnimationProgress();
			float t = p <= HP_DRAIN_START ? 0f
				: p >= HP_DRAIN_END ? 1f
				: (p - HP_DRAIN_START) / (HP_DRAIN_END - HP_DRAIN_START);
			return hpAnimFrom + (hpAnimTo - hpAnimFrom) * t;
		}
		Float rest = shownHp.get(pet);
		return rest != null ? rest : pet.getCurrentHp();
	}

	/**
	 * Whether a fainted pet should be drawn as a settled ghost: its faint line has played and
	 * is no longer the current event (while it IS current, the collapse animation runs instead).
	 */
	public boolean isFaintSettled(BattlePet pet)
	{
		if (pet == null || !faintShown.contains(pet))
		{
			return false;
		}
		return currentEvent == null
			|| currentEvent.getType() != BattleEvent.Type.FAINTED
			|| state.active(currentEvent.getSide()) != pet;
	}

	/**
	 * A move a pet reached with a full moveset, awaiting the player's forget-or-skip choice.
	 */
	private static final class PendingLearn
	{
		private final PetInstance pet;
		private final SpeciesDef species;
		private final MoveDef newMove;

		PendingLearn(PetInstance pet, SpeciesDef species, MoveDef newMove)
		{
			this.pet = pet;
			this.species = species;
			this.newMove = newMove;
		}
	}

	/**
	 * Running per-pet rewards across a battle, used to build the summary once it ends.
	 */
	private static final class Progress
	{
		private final int startLevel;
		private long xp;
		private final List<String> learned = new ArrayList<>();

		Progress(int startLevel)
		{
			this.startLevel = startLevel;
		}
	}

	/**
	 * Read-only view of the current move-learn choice for the overlay: the pet's display name,
	 * the move it wants to learn, and its four current moves (one of which may be forgotten).
	 */
	public static final class LearnPrompt
	{
		private final String petName;
		private final MoveDef newMove;
		private final List<MoveDef> currentMoves;

		LearnPrompt(String petName, MoveDef newMove, List<MoveDef> currentMoves)
		{
			this.petName = petName;
			this.newMove = newMove;
			this.currentMoves = currentMoves;
		}

		public String getPetName()
		{
			return petName;
		}

		public MoveDef getNewMove()
		{
			return newMove;
		}

		public List<MoveDef> getCurrentMoves()
		{
			return currentMoves;
		}
	}
}

package com.petbattles.battle;

import com.petbattles.PetBattlesConfig;
import com.petbattles.engine.BattleEvent;
import com.petbattles.engine.MoveDef;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.SoundEffectID;
import net.runelite.api.SoundEffectVolume;

/**
 * Plays a matching in-game sound effect as each battle event is surfaced. Sounds are the game's
 * own effects, triggered by numeric id through {@link Client#playSoundEffect(int, int)} — nothing
 * is bundled or decoded, so there are no audio assets to ship. Playback is gated by a config
 * toggle and scaled by a config volume (a 0–100% slider, independent of the in-game sound slider).
 *
 * <p>The move-to-sound mapping is an explicit, auditable matrix keyed on a move's {@code animation}
 * family — the same key that drives its on-screen effect — so sight and sound always agree and a
 * whole family shares one cue. A small {@link #MOVE_OVERRIDES} table wins first for the handful of
 * moves that want an exact thematic sound (skilling pets swinging real tools, a harpoon spear, an
 * arcane bolt). Every real move resolves to a sound, enforced by {@code everyBundledMoveMakesASound}.
 *
 * <p>IDs marked "wiki" below come from the OSRS Wiki "List of sound IDs" and should be confirmed
 * in-game (Developer Tools → Sound Effect); IDs referenced through {@link SoundEffectID} are
 * RuneLite-verified constants. {@link #soundIdFor} is pure/static so it is unit-tested without a
 * live client.
 */
public class BattleSoundManager
{
	/** No sound for this event (also guards {@link Client#playSoundEffect} against bad ids). */
	static final int SILENT = -1;

	/** Thematic exact matches, applied before the animation matrix. Move id → sound id. */
	private static final Map<String, Integer> MOVE_OVERRIDES = new HashMap<>();

	/**
	 * The matrix: animation family → sound id. Single source of truth for which sound a move makes.
	 */
	private static final Map<String, Integer> ANIMATION_SOUNDS = new HashMap<>();

	/** Fallback for a move whose animation isn't in the matrix (real content never hits this). */
	private static final int DEFAULT_SOUND = SoundEffectID.ATTACK_HIT;

	static
	{
		MOVE_OVERRIDES.put("pickaxe_poke", SoundEffectID.MINING_TINK);
		MOVE_OVERRIDES.put("log_toss", SoundEffectID.TREE_CHOP);
		MOVE_OVERRIDES.put("timber", SoundEffectID.TREE_FALLING);
		MOVE_OVERRIDES.put("harpoon", 2487);      // spear / harpoon thrust (wiki)
		MOVE_OVERRIDES.put("arcane_blast", 174);  // magic bolt — else the bolt family reads as crossbow (wiki)

		// -- contact: melee, nature whips/fangs, undead bashes, demon claws, dragon tails --
		ANIMATION_SOUNDS.put("slash", 2515);      // claw / scratch (wiki)
		ANIMATION_SOUNDS.put("bite", 1933);       // bite / chomp (wiki)
		ANIMATION_SOUNDS.put("shockwave", SoundEffectID.ATTACK_HIT);
		ANIMATION_SOUNDS.put("spin", SoundEffectID.ATTACK_HIT);
		ANIMATION_SOUNDS.put("whip", SoundEffectID.ATTACK_HIT);
		ANIMATION_SOUNDS.put("lunge", 2487);      // spear poke (wiki)
		ANIMATION_SOUNDS.put("flash", SoundEffectID.ATTACK_HIT);
		// -- ranged throws / shots --
		ANIMATION_SOUNDS.put("dart", 2696);       // dart throw (wiki)
		ANIMATION_SOUNDS.put("bolt", 2695);       // crossbow (wiki)
		ANIMATION_SOUNDS.put("chin", 2707);       // thrown weapon (wiki)
		// -- magic --
		ANIMATION_SOUNDS.put("swirl", 220);       // wind strike (wiki)
		ANIMATION_SOUNDS.put("orb", 207);         // water blast (wiki)
		ANIMATION_SOUNDS.put("drain", 174);       // soul drain — magic bolt (wiki)
		ANIMATION_SOUNDS.put("projectile", 174);  // generic magic bolt fallback (wiki)
		// -- fire --
		ANIMATION_SOUNDS.put("fireball", 155);    // fire blast (wiki)
		ANIMATION_SOUNDS.put("breath", 585);      // dragonfire (wiki)
		ANIMATION_SOUNDS.put("explosion", 162);   // fire wave — big AoE boom (wiki)
		// -- ice --
		ANIMATION_SOUNDS.put("ice_shard", 170);   // ice burst (wiki)
		ANIMATION_SOUNDS.put("barrage", 168);     // ice barrage (wiki)
		ANIMATION_SOUNDS.put("blizzard", 169);    // ice blitz (wiki)
		// -- nature status inflicters --
		ANIMATION_SOUNDS.put("roots", 151);       // entangle (wiki)
		ANIMATION_SOUNDS.put("cloud", 2408);      // poison gas (wiki)
		// -- self buffs / heals / enemy debuffs --
		ANIMATION_SOUNDS.put("sparkle", SoundEffectID.PRAYER_ACTIVATE_RAPID_HEAL);
		ANIMATION_SOUNDS.put("buff_aura", SoundEffectID.PRAYER_ACTIVATE_ULTIMATE_STRENGTH);
		ANIMATION_SOUNDS.put("grow", SoundEffectID.PRAYER_ACTIVATE_ULTIMATE_STRENGTH);
		ANIMATION_SOUNDS.put("wail", SoundEffectID.PRAYER_DEACTIVE_VWOOP);
		// -- skilling wood --
		ANIMATION_SOUNDS.put("spinning_log", SoundEffectID.TREE_CHOP);
	}

	private final Client client;
	private final PetBattlesConfig config;

	public BattleSoundManager(Client client, PetBattlesConfig config)
	{
		this.client = client;
		this.config = config;
	}

	/**
	 * Play the cue for this event, if any and if the config toggle is on. Must be called on the
	 * client thread (as the battle sequence already is).
	 */
	public void play(BattleEvent event, MoveDef move)
	{
		if (!config.battleSoundEffects())
		{
			return;
		}
		int id = soundIdFor(event, move);
		if (id <= 0)
		{
			return;
		}
		int volume = scaleVolume(config.battleSoundVolume());
		if (volume > 0)
		{
			client.playSoundEffect(id, volume);
		}
	}

	/** Map a 0–100 config percentage to the game's 0–{@value SoundEffectVolume#HIGH} volume scale. */
	static int scaleVolume(int percent)
	{
		int clamped = Math.max(0, Math.min(100, percent));
		return Math.round(clamped * SoundEffectVolume.HIGH / 100f);
	}

	/** The sound effect id for an event/move pair, or {@link #SILENT} for none. */
	static int soundIdFor(BattleEvent event, MoveDef move)
	{
		if (event == null)
		{
			return SILENT;
		}
		switch (event.getType())
		{
			case MOVE_USED:
				return moveSound(move);
			case MISSED:
				// The classic magic "splash" — a good generic whiff cue for any missed move.
				return SoundEffectID.MAGIC_SPLASH_BOING;
			default:
				return SILENT;
		}
	}

	private static int moveSound(MoveDef move)
	{
		if (move == null)
		{
			return SILENT;
		}
		Integer override = MOVE_OVERRIDES.get(move.getId());
		if (override != null)
		{
			return override;
		}
		Integer byAnimation = move.getAnimation() == null ? null : ANIMATION_SOUNDS.get(move.getAnimation());
		return byAnimation != null ? byAnimation : DEFAULT_SOUND;
	}
}

package com.petbattles.collection;

import com.petbattles.data.PetDatabase;
import com.petbattles.engine.SpeciesDef;
import com.petbattles.persist.RosterManager;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Keeps the owned-pet set in sync with the real collection log.
 *
 * Sources, all additive (a pet is never revoked):
 *  - Scraping the collection log page when the player opens it (script 2731 redraws
 *    the item grid; obtained items render at full opacity).
 *  - The "New item added to your collection log: X" game message (requires the
 *    player's in-game collection log notification setting).
 *  - The follower tracker also unlocks any pet seen following the player.
 */
@Slf4j
public class CollectionLogSync
{
	private static final Pattern COLLECTION_LOG_ADDITION =
		Pattern.compile("New item added to your collection log: (.+)");

	private final Client client;
	private final PetDatabase db;
	private final RosterManager roster;
	private final Runnable onUnlock;

	public CollectionLogSync(Client client, PetDatabase db, RosterManager roster, Runnable onUnlock)
	{
		this.client = client;
		this.db = db;
		this.roster = roster;
		this.onUnlock = onUnlock;
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.COLLECTION_DRAW_LIST || !roster.isLoaded())
		{
			return;
		}
		Widget contents = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
		if (contents == null)
		{
			return;
		}
		Widget[] items = contents.getDynamicChildren();
		if (items == null)
		{
			return;
		}
		boolean any = false;
		for (Widget item : items)
		{
			int itemId = item.getItemId();
			if (itemId <= 0)
			{
				continue;
			}
			SpeciesDef species = db.speciesByItemId(itemId);
			// Obtained collection log items draw fully opaque; unobtained are faded
			if (species != null && item.getOpacity() == 0 && roster.unlock(species.getId()))
			{
				log.debug("Collection log sync unlocked {}", species.getId());
				announce(species);
				any = true;
			}
		}
		if (any)
		{
			onUnlock.run();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE || !roster.isLoaded())
		{
			return;
		}
		Matcher m = COLLECTION_LOG_ADDITION.matcher(Text.removeTags(event.getMessage()));
		if (!m.matches())
		{
			return;
		}
		String itemName = m.group(1).trim();
		for (SpeciesDef species : db.allSpecies())
		{
			if (species.getName().equalsIgnoreCase(itemName))
			{
				if (roster.unlock(species.getId()))
				{
					announce(species);
					onUnlock.run();
				}
				return;
			}
		}
	}

	private void announce(SpeciesDef species)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
			"<col=ff7700>Pet Battles:</col> " + species.getName() + " joined your roster!", null);
	}
}

package com.petbattles.data;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.petbattles.engine.MoveDef;
import com.petbattles.engine.SpeciesDef;
import com.petbattles.engine.TrainerDef;
import com.petbattles.engine.TypeChart;
import com.petbattles.item.EquipItemDef;
import com.petbattles.quest.QuestDef;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;

/**
 * Loads the bundled JSON content resources. Uses the injected RuneLite Gson
 * (Plugin Hub disallows new Gson()).
 */
public class ContentLoader
{
	private static final String BASE = "/com/petbattles/data/";

	private final Gson gson;

	public ContentLoader(Gson gson)
	{
		this.gson = gson;
	}

	public List<SpeciesDef> loadSpecies()
	{
		return load("species.json", new TypeToken<List<SpeciesDef>>()
		{
		});
	}

	public List<MoveDef> loadMoves()
	{
		return load("moves.json", new TypeToken<List<MoveDef>>()
		{
		});
	}

	public List<TrainerDef> loadTrainers()
	{
		return load("trainers.json", new TypeToken<List<TrainerDef>>()
		{
		});
	}

	public List<EquipItemDef> loadEquipItems()
	{
		return load("items.json", new TypeToken<List<EquipItemDef>>()
		{
		});
	}

	public List<QuestDef> loadQuests()
	{
		return load("quests.json", new TypeToken<List<QuestDef>>()
		{
		});
	}

	public TypeChart loadTypeChart()
	{
		Map<String, Map<String, Double>> raw = load("typechart.json",
			new TypeToken<Map<String, Map<String, Double>>>()
			{
			});
		return TypeChart.fromMap(raw);
	}

	private <T> T load(String name, TypeToken<T> type)
	{
		try (InputStream in = ContentLoader.class.getResourceAsStream(BASE + name))
		{
			if (in == null)
			{
				throw new IllegalStateException("Missing bundled resource: " + name);
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				T result = gson.fromJson(reader, type.getType());
				if (result == null)
				{
					throw new IllegalStateException("Empty content resource: " + name);
				}
				return result;
			}
		}
		catch (IOException e)
		{
			throw new UncheckedIOException("Failed to load " + name, e);
		}
	}
}

package com.petbattles.data;

import com.petbattles.engine.MoveDef;
import com.petbattles.engine.SpeciesDef;
import com.petbattles.engine.TrainerDef;
import com.petbattles.engine.TypeChart;
import com.petbattles.item.EquipItemDef;
import com.petbattles.quest.QuestDef;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Indexed, immutable view of the loaded content.
 */
public class PetDatabase
{
	private final Map<String, SpeciesDef> speciesById;
	private final Map<String, MoveDef> movesById;
	private final Map<String, TrainerDef> trainersById;
	private final Map<Integer, SpeciesDef> speciesByItemId;
	private final Map<Integer, SpeciesDef> speciesByNpcId;
	// item/npc id -> the variant id it identifies (base-form ids never appear here)
	private final Map<Integer, String> variantIdByItemId;
	private final Map<Integer, String> variantIdByNpcId;
	private final Map<String, EquipItemDef> equipItemsById;
	private final Map<String, QuestDef> questsById;
	private final TypeChart typeChart;

	public PetDatabase(Collection<SpeciesDef> species, Collection<MoveDef> moves,
		Collection<TrainerDef> trainers, Collection<EquipItemDef> equipItems,
		Collection<QuestDef> quests, TypeChart typeChart)
	{
		Map<String, SpeciesDef> sById = new LinkedHashMap<>();
		Map<Integer, SpeciesDef> sByItem = new LinkedHashMap<>();
		Map<Integer, SpeciesDef> sByNpc = new LinkedHashMap<>();
		Map<Integer, String> vByItem = new LinkedHashMap<>();
		Map<Integer, String> vByNpc = new LinkedHashMap<>();
		for (SpeciesDef s : species)
		{
			sById.put(s.getId(), s);
			for (int itemId : s.getAllItemIds())
			{
				sByItem.put(itemId, s);
			}
			for (int npcId : s.getNpcIds())
			{
				sByNpc.put(npcId, s);
			}
			// Variant ids resolve to the same species (for ownership) but also tag which form is
			// active, so the follower/inventory trackers can flip the pet's variant on detection.
			for (SpeciesDef.Variant v : s.getVariants())
			{
				for (int itemId : v.getUnlockItemIds())
				{
					sByItem.put(itemId, s);
					vByItem.put(itemId, v.getId());
				}
				if (v.getItemId() > 0)
				{
					sByItem.put(v.getItemId(), s);
					vByItem.put(v.getItemId(), v.getId());
				}
				for (int npcId : v.getNpcIds())
				{
					sByNpc.put(npcId, s);
					vByNpc.put(npcId, v.getId());
				}
			}
		}
		Map<String, MoveDef> mById = new LinkedHashMap<>();
		for (MoveDef m : moves)
		{
			mById.put(m.getId(), m);
		}
		Map<String, TrainerDef> tById = new LinkedHashMap<>();
		for (TrainerDef t : trainers)
		{
			tById.put(t.getId(), t);
		}
		Map<String, EquipItemDef> eById = new LinkedHashMap<>();
		for (EquipItemDef e : equipItems)
		{
			eById.put(e.getId(), e);
		}
		Map<String, QuestDef> qById = new LinkedHashMap<>();
		for (QuestDef q : quests)
		{
			qById.put(q.getId(), q);
		}
		this.speciesById = Collections.unmodifiableMap(sById);
		this.movesById = Collections.unmodifiableMap(mById);
		this.trainersById = Collections.unmodifiableMap(tById);
		this.speciesByItemId = Collections.unmodifiableMap(sByItem);
		this.speciesByNpcId = Collections.unmodifiableMap(sByNpc);
		this.variantIdByItemId = Collections.unmodifiableMap(vByItem);
		this.variantIdByNpcId = Collections.unmodifiableMap(vByNpc);
		this.equipItemsById = Collections.unmodifiableMap(eById);
		this.questsById = Collections.unmodifiableMap(qById);
		this.typeChart = typeChart;
	}

	public static PetDatabase load(ContentLoader loader)
	{
		return new PetDatabase(loader.loadSpecies(), loader.loadMoves(),
			loader.loadTrainers(), loader.loadEquipItems(), loader.loadQuests(),
			loader.loadTypeChart());
	}

	public Collection<SpeciesDef> allSpecies()
	{
		return speciesById.values();
	}

	public Collection<MoveDef> allMoves()
	{
		return movesById.values();
	}

	public Collection<TrainerDef> allTrainers()
	{
		return trainersById.values();
	}

	public SpeciesDef species(String id)
	{
		return speciesById.get(id);
	}

	public MoveDef move(String id)
	{
		return movesById.get(id);
	}

	public TrainerDef trainer(String id)
	{
		return trainersById.get(id);
	}

	public EquipItemDef equipItem(String id)
	{
		return equipItemsById.get(id);
	}

	public Collection<EquipItemDef> allEquipItems()
	{
		return equipItemsById.values();
	}

	public QuestDef quest(String id)
	{
		return questsById.get(id);
	}

	public Collection<QuestDef> allQuests()
	{
		return questsById.values();
	}

	public SpeciesDef speciesByItemId(int itemId)
	{
		return speciesByItemId.get(itemId);
	}

	public SpeciesDef speciesByNpcId(int npcId)
	{
		return speciesByNpcId.get(npcId);
	}

	/**
	 * The variant id this item id identifies, or null if the id is a base-form (or unknown) id.
	 */
	public String variantByItemId(int itemId)
	{
		return variantIdByItemId.get(itemId);
	}

	/**
	 * The variant id this npc id identifies, or null if the id is a base-form (or unknown) id.
	 */
	public String variantByNpcId(int npcId)
	{
		return variantIdByNpcId.get(npcId);
	}

	public TypeChart getTypeChart()
	{
		return typeChart;
	}
}

package com.petbattles.easteregg;

import com.petbattles.data.PetDatabase;
import com.petbattles.engine.EasterEggDef;
import com.petbattles.engine.MoveDef;
import com.petbattles.engine.PetInstance;
import com.petbattles.engine.SpeciesDef;
import com.petbattles.follower.FollowerTracker;
import com.petbattles.persist.RosterManager;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Watches for hidden move-unlock triggers performed while the pet is following:
 * EMOTE (player animation), LOCATION (map region), STAT (xp gain in a skill).
 */
public class EasterEggTracker
{
	private static final int LOCATION_CHECK_INTERVAL_TICKS = 5;

	private final Client client;
	private final PetDatabase db;
	private final RosterManager roster;
	private final FollowerTracker follower;
	private final Runnable onUnlock;

	private final Map<Skill, Long> lastSkillXp = new EnumMap<>(Skill.class);
	private int tickCount;

	public EasterEggTracker(Client client, PetDatabase db, RosterManager roster,
		FollowerTracker follower, Runnable onUnlock)
	{
		this.client = client;
		this.db = db;
		this.roster = roster;
		this.follower = follower;
		this.onUnlock = onUnlock;
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		Player local = client.getLocalPlayer();
		if (event.getActor() != local || local == null)
		{
			return;
		}
		int animId = local.getAnimation();
		if (animId <= 0)
		{
			return;
		}
		forEachActiveEgg(EasterEggDef.TriggerKind.EMOTE, (species, pet, egg) ->
		{
			EasterEggDef.Trigger t = egg.getTrigger();
			if (t.getAnimId() == animId
				&& (t.getRegionId() <= 0 || t.getRegionId() == currentRegion()))
			{
				unlock(species, pet, egg);
			}
		});
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (++tickCount % LOCATION_CHECK_INTERVAL_TICKS != 0)
		{
			return;
		}
		int region = currentRegion();
		if (region <= 0)
		{
			return;
		}
		forEachActiveEgg(EasterEggDef.TriggerKind.LOCATION, (species, pet, egg) ->
		{
			if (egg.getTrigger().getRegionId() == region)
			{
				unlock(species, pet, egg);
			}
		});
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		Long previous = lastSkillXp.put(skill, (long) event.getXp());
		// First observation after login is baseline, not a gain
		if (previous == null || event.getXp() <= previous)
		{
			return;
		}
		forEachActiveEgg(EasterEggDef.TriggerKind.STAT, (species, pet, egg) ->
		{
			if (skill.name().equalsIgnoreCase(egg.getTrigger().getSkill()))
			{
				unlock(species, pet, egg);
			}
		});
	}

	/**
	 * Reset xp baselines (on logout) so relogging doesn't count the initial sync as gains.
	 */
	public void resetBaselines()
	{
		lastSkillXp.clear();
	}

	private interface EggVisitor
	{
		void visit(SpeciesDef species, PetInstance pet, EasterEggDef egg);
	}

	private void forEachActiveEgg(EasterEggDef.TriggerKind kind, EggVisitor visitor)
	{
		String speciesId = follower.getActiveSpeciesId();
		if (speciesId == null || !roster.isLoaded())
		{
			return;
		}
		SpeciesDef species = db.species(speciesId);
		if (species == null || species.getEasterEggs().isEmpty())
		{
			return;
		}
		PetInstance pet = roster.getOrCreatePet(speciesId);
		if (pet == null)
		{
			return;
		}
		for (EasterEggDef egg : species.getEasterEggs())
		{
			if (egg.getTrigger() != null
				&& egg.getTrigger().getKind() == kind
				&& !pet.getUnlockedEggMoves().contains(egg.getMove()))
			{
				visitor.visit(species, pet, egg);
			}
		}
	}

	private void unlock(SpeciesDef species, PetInstance pet, EasterEggDef egg)
	{
		MoveDef move = db.move(egg.getMove());
		if (move == null)
		{
			return;
		}
		pet.getUnlockedEggMoves().add(egg.getMove());
		if (pet.getEquippedMoves().size() < PetInstance.MAX_EQUIPPED_MOVES)
		{
			pet.equipMove(egg.getMove());
		}
		roster.petChanged();
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
			"<col=ff7700>Pet Battles:</col> ✦ " + species.getName()
				+ " discovered a secret move: " + move.getName() + "!", null);
		onUnlock.run();
	}

	private int currentRegion()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return -1;
		}
		WorldPoint wp = local.getWorldLocation();
		return wp == null ? -1 : wp.getRegionID();
	}
}

package com.petbattles.engine;

/**
 * One side's chosen action for a turn.
 */
public class BattleAction
{
	public enum Kind
	{
		MOVE,
		SWITCH,
		FLEE
	}

	private final Kind kind;
	private final int index; // move index for MOVE, team index for SWITCH

	private BattleAction(Kind kind, int index)
	{
		this.kind = kind;
		this.index = index;
	}

	public static BattleAction move(int index)
	{
		return new BattleAction(Kind.MOVE, index);
	}

	/**
	 * Switch the active pet to the given team index. Consumes the turn.
	 */
	public static BattleAction switchTo(int teamIndex)
	{
		return new BattleAction(Kind.SWITCH, teamIndex);
	}

	public static BattleAction flee()
	{
		return new BattleAction(Kind.FLEE, -1);
	}

	public Kind getKind()
	{
		return kind;
	}

	public int getMoveIndex()
	{
		return index;
	}

	public int getSwitchIndex()
	{
		return index;
	}
}

package com.petbattles.engine;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Deterministic turn resolver. No timing, no RuneLite — feed it actions and a Random,
 * get back an ordered event list. All randomness flows through the injected Random.
 */
public class BattleEngine
{
	private static final int STATUS_DURATION_TURNS = 3;
	private static final int FREEZE_THAW_PERCENT = 30;
	private static final int STUN_SKIP_PERCENT = 25;

	private final TypeChart typeChart;

	public BattleEngine(TypeChart typeChart)
	{
		this.typeChart = typeChart;
	}

	/**
	 * Create the opening state and its send-out events.
	 */
	public BattleState start(List<BattlePet> playerTeam, List<BattlePet> enemyTeam, List<BattleEvent> events)
	{
		BattleState state = new BattleState(playerTeam, enemyTeam);
		events.add(BattleEvent.of(BattleEvent.Type.PET_SENT_OUT, BattleState.PLAYER,
			"Go, " + state.active(BattleState.PLAYER).getDisplayName() + "!"));
		events.add(BattleEvent.of(BattleEvent.Type.PET_SENT_OUT, BattleState.ENEMY,
			"Enemy sends out " + state.active(BattleState.ENEMY).getDisplayName() + "!"));
		return state;
	}

	/**
	 * Resolve one full turn. Returns the ordered events that occurred.
	 */
	public List<BattleEvent> resolveTurn(BattleState state, BattleAction playerAction, BattleAction enemyAction, Random rng)
	{
		List<BattleEvent> events = new ArrayList<>();
		if (state.isOver() || state.awaitingForcedSwitch())
		{
			return events;
		}
		state.nextTurn();

		// Fleeing (forfeit) resolves before anything else
		if (playerAction.getKind() == BattleAction.Kind.FLEE)
		{
			state.setPhase(BattleState.Phase.FLED);
			events.add(BattleEvent.of(BattleEvent.Type.FLED, BattleState.PLAYER, "You fled from the battle!"));
			events.add(BattleEvent.of(BattleEvent.Type.BATTLE_END, -1, "The battle is over."));
			return events;
		}

		// Switches resolve before moves: the switch consumes the turn and the
		// opponent's attack lands on the incoming pet
		handleSwitch(state, BattleState.PLAYER, playerAction, events);
		handleSwitch(state, BattleState.ENEMY, enemyAction, events);

		// Speed decides order; ties are a coin flip
		int playerSpd = state.active(BattleState.PLAYER).effectiveSpd();
		int enemySpd = state.active(BattleState.ENEMY).effectiveSpd();
		int first;
		if (playerSpd != enemySpd)
		{
			first = playerSpd > enemySpd ? BattleState.PLAYER : BattleState.ENEMY;
		}
		else
		{
			first = rng.nextBoolean() ? BattleState.PLAYER : BattleState.ENEMY;
		}
		int second = BattleState.opponent(first);

		// A pet fainted by the first attacker stays the (fainted) active pet for the rest of
		// this turn: act() and endOfTurn() both no-op on a fainted pet, so the replacement
		// never acts with the fainted pet's queued move. The enemy's swap is deferred to
		// animation time; the player is prompted (PLAYER_MUST_SWITCH).
		act(state, first, actionFor(first, playerAction, enemyAction), events, rng);
		if (haltAfterStep(state))
		{
			return events;
		}
		act(state, second, actionFor(second, playerAction, enemyAction), events, rng);
		if (haltAfterStep(state))
		{
			return events;
		}

		endOfTurn(state, first, events);
		if (haltAfterStep(state))
		{
			return events;
		}
		endOfTurn(state, second, events);
		return events;
	}

	/**
	 * Whether turn resolution must stop here: the battle ended, or the player owes a
	 * forced switch. In the forced-switch case the round is over; the incoming pet plays
	 * from the next turn.
	 */
	private static boolean haltAfterStep(BattleState state)
	{
		return state.isOver() || state.awaitingForcedSwitch();
	}

	/**
	 * Resolve the player's forced replacement after a mid-turn faint. Consumes the round:
	 * the incoming pet does not attack now; normal play resumes next turn.
	 */
	public List<BattleEvent> resolveForcedSwitch(BattleState state, int teamIndex)
	{
		List<BattleEvent> events = new ArrayList<>();
		if (!state.awaitingForcedSwitch())
		{
			return events;
		}
		List<BattlePet> team = state.team(BattleState.PLAYER);
		if (teamIndex < 0 || teamIndex >= team.size() || team.get(teamIndex).isFainted())
		{
			// Invalid target: the UI only offers legal ones, so just keep waiting
			return events;
		}
		state.setActive(BattleState.PLAYER, teamIndex);
		BattlePet incoming = state.active(BattleState.PLAYER);
		state.setPhase(BattleState.Phase.IN_PROGRESS);
		events.add(BattleEvent.of(BattleEvent.Type.PET_SENT_OUT, BattleState.PLAYER,
			"Go, " + incoming.getDisplayName() + "!"));
		return events;
	}

	/**
	 * Apply the optional, cost-free swap offered after the enemy sends in a replacement (the
	 * "about to send out X — switch?" prompt): the incoming pet just takes over, no turn runs and
	 * the enemy gets no free hit. Invalid targets (out of range, fainted, already active) return no
	 * events. Leaves the phase untouched — the battle is between turns (IN_PROGRESS), and the next
	 * real turn is the player's to command.
	 */
	public List<BattleEvent> resolveOptionalSwitch(BattleState state, int teamIndex)
	{
		List<BattleEvent> events = new ArrayList<>();
		List<BattlePet> team = state.team(BattleState.PLAYER);
		if (teamIndex < 0 || teamIndex >= team.size()
			|| teamIndex == state.activeIndex(BattleState.PLAYER) || team.get(teamIndex).isFainted())
		{
			return events;
		}
		BattlePet outgoing = state.active(BattleState.PLAYER);
		state.setActive(BattleState.PLAYER, teamIndex);
		BattlePet incoming = state.active(BattleState.PLAYER);
		events.add(BattleEvent.of(BattleEvent.Type.PET_SENT_OUT, BattleState.PLAYER,
			outgoing.getDisplayName() + ", come back! Go, " + incoming.getDisplayName() + "!"));
		return events;
	}

	private static BattleAction actionFor(int side, BattleAction playerAction, BattleAction enemyAction)
	{
		return side == BattleState.PLAYER ? playerAction : enemyAction;
	}

	/**
	 * Validate and apply a SWITCH action; invalid targets (out of range, fainted,
	 * already active) are silently ignored.
	 */
	private void handleSwitch(BattleState state, int side, BattleAction action, List<BattleEvent> events)
	{
		if (action.getKind() != BattleAction.Kind.SWITCH)
		{
			return;
		}
		int target = action.getSwitchIndex();
		List<BattlePet> team = state.team(side);
		if (target < 0 || target >= team.size() || target == state.activeIndex(side)
			|| team.get(target).isFainted())
		{
			return;
		}
		BattlePet outgoing = state.active(side);
		state.setActive(side, target);
		BattlePet incoming = state.active(side);
		String text = side == BattleState.PLAYER
			? outgoing.getDisplayName() + ", come back! Go, " + incoming.getDisplayName() + "!"
			: "Enemy withdraws " + outgoing.getDisplayName() + " and sends out " + incoming.getDisplayName() + "!";
		events.add(BattleEvent.of(BattleEvent.Type.PET_SENT_OUT, side, text));
	}

	private void act(BattleState state, int side, BattleAction action, List<BattleEvent> events, Random rng)
	{
		BattlePet attacker = state.active(side);
		if (attacker.isFainted())
		{
			return;
		}
		if (action.getKind() != BattleAction.Kind.MOVE)
		{
			return;
		}

		// Status pre-checks: frozen pets may thaw, stunned pets may flinch
		if (attacker.getStatus() == BattlePet.Status.FREEZE)
		{
			if (rng.nextInt(100) < FREEZE_THAW_PERCENT)
			{
				attacker.cureStatus();
				events.add(BattleEvent.of(BattleEvent.Type.STATUS_END, side,
					attacker.getDisplayName() + " thawed out!"));
			}
			else
			{
				events.add(BattleEvent.of(BattleEvent.Type.STATUS_SKIP, side,
					attacker.getDisplayName() + " is frozen solid!"));
				return;
			}
		}
		else if (attacker.getStatus() == BattlePet.Status.STUN && rng.nextInt(100) < STUN_SKIP_PERCENT)
		{
			events.add(BattleEvent.of(BattleEvent.Type.STATUS_SKIP, side,
				attacker.getDisplayName() + " is stunned and can't move!"));
			return;
		}

		List<MoveDef> moves = attacker.getMoves();
		int idx = action.getMoveIndex();
		if (idx < 0 || idx >= moves.size())
		{
			return;
		}
		MoveDef move = moves.get(idx);
		BattlePet defender = state.active(BattleState.opponent(side));

		events.add(BattleEvent.moveUsed(side,
			move, attacker.getDisplayName() + " used " + move.getName() + "!"));

		if (rng.nextInt(100) >= move.getAccuracy())
		{
			events.add(BattleEvent.of(BattleEvent.Type.MISSED, side, "The attack missed!"));
			return;
		}

		if (!move.isStatusMove())
		{
			double eff = typeChart.effectiveness(move.getType(), defender.getTypes());
			int dmg = DamageCalc.damage(attacker.getLevel(), move.getPower(),
				attacker.effectiveAtk(), defender.effectiveDef(),
				attacker.hasStab(move.getType()), eff, rng);
			defender.damage(dmg);
			events.add(BattleEvent.damage(BattleState.opponent(side), dmg, eff,
				defender.getDisplayName() + " took " + dmg + " damage" + effectivenessSuffix(eff)));
		}

		// Secondary effect
		MoveEffect effect = move.getEffect();
		if (effect != MoveEffect.NONE && !defender.isFainted() && rng.nextInt(100) < move.getEffectChance())
		{
			applyEffect(state, side, attacker, defender, effect, events);
		}

		if (defender.isFainted())
		{
			handleFaint(state, BattleState.opponent(side), events);
		}
	}

	private void applyEffect(BattleState state, int side, BattlePet attacker, BattlePet defender,
		MoveEffect effect, List<BattleEvent> events)
	{
		if (effect.isStatus())
		{
			BattlePet.Status status = toStatus(effect);
			// Burn and poison last until the battle ends; freeze/stun are timed
			int turns = (status == BattlePet.Status.FREEZE || status == BattlePet.Status.STUN)
				? STATUS_DURATION_TURNS : Integer.MAX_VALUE;
			if (defender.applyStatus(status, turns))
			{
				events.add(BattleEvent.of(BattleEvent.Type.STATUS_APPLIED, BattleState.opponent(side),
					defender.getDisplayName() + " was " + statusVerb(status) + "!"));
			}
		}
		else if (effect == MoveEffect.HEAL)
		{
			int healed = attacker.heal(attacker.getMaxHp() / 2);
			if (healed > 0)
			{
				events.add(BattleEvent.value(BattleEvent.Type.HEALED, side, healed,
					attacker.getDisplayName() + " restored " + healed + " HP!"));
			}
		}
		else if (effect.isSelfBuff())
		{
			int applied = attacker.changeStage(effect, +1);
			if (applied != 0)
			{
				events.add(BattleEvent.of(BattleEvent.Type.STAT_CHANGED, side,
					attacker.getDisplayName() + "'s " + statName(effect) + " rose!"));
			}
		}
		else if (effect.isEnemyDebuff())
		{
			int applied = defender.changeStage(effect, -1);
			if (applied != 0)
			{
				events.add(BattleEvent.of(BattleEvent.Type.STAT_CHANGED, BattleState.opponent(side),
					defender.getDisplayName() + "'s " + statName(effect) + " fell!"));
			}
		}
	}

	private void endOfTurn(BattleState state, int side, List<BattleEvent> events)
	{
		BattlePet pet = state.active(side);
		if (pet.isFainted())
		{
			return;
		}
		BattlePet.Status status = pet.getStatus();
		if (status == BattlePet.Status.BURN || status == BattlePet.Status.POISON)
		{
			int chip = Math.max(1, pet.getMaxHp() / (status == BattlePet.Status.BURN ? 16 : 8));
			pet.damage(chip);
			events.add(BattleEvent.value(BattleEvent.Type.STATUS_TICK, side, chip,
				pet.getDisplayName() + " is hurt by " + statusNoun(status) + "! (" + chip + ")"));
			if (pet.isFainted())
			{
				handleFaint(state, side, events);
				return;
			}
		}
		if (status == BattlePet.Status.FREEZE || status == BattlePet.Status.STUN)
		{
			pet.tickStatus();
			if (pet.getStatus() == BattlePet.Status.NONE)
			{
				events.add(BattleEvent.of(BattleEvent.Type.STATUS_END, side,
					pet.getDisplayName() + " recovered!"));
			}
		}
	}

	private void handleFaint(BattleState state, int faintedSide, List<BattleEvent> events)
	{
		BattlePet fainted = state.active(faintedSide);
		events.add(BattleEvent.of(BattleEvent.Type.FAINTED, faintedSide,
			fainted.getDisplayName() + " fainted!"));
		if (state.allFainted(faintedSide))
		{
			boolean playerWon = faintedSide == BattleState.ENEMY;
			state.setPhase(playerWon ? BattleState.Phase.PLAYER_WON : BattleState.Phase.ENEMY_WON);
			events.add(BattleEvent.of(BattleEvent.Type.BATTLE_END, -1,
				playerWon ? "You won the battle!" : "You were defeated..."));
		}
		else if (faintedSide == BattleState.PLAYER)
		{
			// Stop and let the player pick a replacement; the forced switch consumes the
			// round, so the incoming pet never inherits the fainted pet's queued move.
			state.setPhase(BattleState.Phase.PLAYER_MUST_SWITCH);
		}
		else
		{
			// Enemy auto-sends its next pet, but the actual swap is deferred until the UI
			// shows this event — so the fainted pet plays its faint animation first instead
			// of the replacement popping in to take the hit.
			int next = state.nextAliveIndex(BattleState.ENEMY);
			BattlePet nextPet = state.team(BattleState.ENEMY).get(next);
			events.add(BattleEvent.deferredSendOut(BattleState.ENEMY, next,
				"Enemy sends out " + nextPet.getDisplayName() + "!"));
		}
	}

	private static BattlePet.Status toStatus(MoveEffect effect)
	{
		switch (effect)
		{
			case BURN:
				return BattlePet.Status.BURN;
			case FREEZE:
				return BattlePet.Status.FREEZE;
			case POISON:
				return BattlePet.Status.POISON;
			case STUN:
				return BattlePet.Status.STUN;
			default:
				return BattlePet.Status.NONE;
		}
	}

	private static String statusVerb(BattlePet.Status status)
	{
		switch (status)
		{
			case BURN:
				return "burned";
			case FREEZE:
				return "frozen";
			case POISON:
				return "poisoned";
			case STUN:
				return "stunned";
			default:
				return "afflicted";
		}
	}

	private static String statusNoun(BattlePet.Status status)
	{
		return status == BattlePet.Status.BURN ? "its burn" : "poison";
	}

	private static String statName(MoveEffect effect)
	{
		switch (effect)
		{
			case ATK_UP:
			case ATK_DOWN:
				return "Attack";
			case DEF_UP:
			case DEF_DOWN:
				return "Defence";
			case SPD_UP:
			case SPD_DOWN:
				return "Speed";
			default:
				return "stat";
		}
	}

	private static String effectivenessSuffix(double eff)
	{
		if (eff >= 2.0)
		{
			return " — it's super effective!";
		}
		if (eff <= 0.5)
		{
			return " — it's not very effective...";
		}
		return "!";
	}

	public TypeChart getTypeChart()
	{
		return typeChart;
	}
}

package com.petbattles.engine;

/**
 * One thing that happened during battle resolution, in order. The overlay drains these
 * for animation/log display; each carries a ready-made log line.
 */
public class BattleEvent
{
	public enum Type
	{
		PET_SENT_OUT,
		MOVE_USED,
		DAMAGE,
		MISSED,
		STATUS_APPLIED,
		STAT_CHANGED,
		STATUS_TICK,
		STATUS_SKIP,
		STATUS_END,
		HEALED,
		FAINTED,
		FLED,
		BATTLE_END,
		XP_GAINED,
		LEVEL_UP,
		MOVE_LEARNED
	}

	private final Type type;
	private final int side;   // BattleState.PLAYER / BattleState.ENEMY, or -1
	private final int value;  // damage, heal, level, xp... depending on type
	private final double effectiveness; // for DAMAGE
	private final String text;
	private final MoveDef move; // for MOVE_USED: drives the attack animation
	// PET_SENT_OUT only: when true, the active-pet swap to team slot `value` is applied by
	// the UI when this event is shown, not during resolution — so the fainted pet stays
	// on screen through its faint animation before the replacement appears.
	private final boolean deferredSwitch;

	public BattleEvent(Type type, int side, int value, double effectiveness, String text)
	{
		this(type, side, value, effectiveness, text, null, false);
	}

	private BattleEvent(Type type, int side, int value, double effectiveness, String text, MoveDef move)
	{
		this(type, side, value, effectiveness, text, move, false);
	}

	private BattleEvent(Type type, int side, int value, double effectiveness, String text, MoveDef move,
		boolean deferredSwitch)
	{
		this.type = type;
		this.side = side;
		this.value = value;
		this.effectiveness = effectiveness;
		this.text = text;
		this.move = move;
		this.deferredSwitch = deferredSwitch;
	}

	public static BattleEvent of(Type type, int side, String text)
	{
		return new BattleEvent(type, side, 0, 1.0, text);
	}

	/**
	 * A send-out whose active-pet swap (to team slot {@code teamIndex}) is deferred until
	 * the UI shows this event — used for the enemy's on-faint replacement.
	 */
	public static BattleEvent deferredSendOut(int side, int teamIndex, String text)
	{
		return new BattleEvent(Type.PET_SENT_OUT, side, teamIndex, 1.0, text, null, true);
	}

	public static BattleEvent moveUsed(int side, MoveDef move, String text)
	{
		return new BattleEvent(Type.MOVE_USED, side, 0, 1.0, text, move);
	}

	public static BattleEvent damage(int side, int amount, double effectiveness, String text)
	{
		return new BattleEvent(Type.DAMAGE, side, amount, effectiveness, text);
	}

	public static BattleEvent value(Type type, int side, int value, String text)
	{
		return new BattleEvent(type, side, value, 1.0, text);
	}

	public Type getType()
	{
		return type;
	}

	public int getSide()
	{
		return side;
	}

	public int getValue()
	{
		return value;
	}

	public double getEffectiveness()
	{
		return effectiveness;
	}

	public String getText()
	{
		return text;
	}

	public MoveDef getMove()
	{
		return move;
	}

	/**
	 * Whether this PET_SENT_OUT applies its active-pet swap when shown rather than during
	 * resolution (see {@link #deferredSendOut}).
	 */
	public boolean isDeferredSwitch()
	{
		return deferredSwitch;
	}

	@Override
	public String toString()
	{
		return type + ": " + text;
	}
}

package com.petbattles.engine;

import java.util.ArrayList;
import java.util.List;

/**
 * In-battle mutable state for one pet: current HP, stat stages, status condition.
 */
public class BattlePet
{
	public enum Status
	{
		NONE,
		BURN,
		FREEZE,
		POISON,
		STUN
	}

	public static final int MAX_STAGE = 4;
	public static final int MIN_STAGE = -4;

	private final SpeciesDef species;
	// Active metamorphosis form id (null = base). Folds into every species lookup below so the
	// battler's sprite/orientation/types/base follow the form; falls through to base when unset.
	private final String variantId;
	// Passive held-item modifier for this battler (null = holds nothing). Applied to the derived
	// stats below and to max HP; enemy battlers hold nothing in v1.
	private final ItemEffect heldEffect;
	private final String displayName;
	private int level;
	private final List<MoveDef> moves;
	private int maxHp;
	private int currentHp;
	private int atkStage;
	private int defStage;
	private int spdStage;
	private Status status = Status.NONE;
	private int statusTurns;
	// Cosmetics worn into the fight (EquipItemDef ids, null for none). Presentation only — they never
	// touch a stat, so they're set after construction rather than widening the constructor chain
	// again. Enemy battlers wear nothing.
	private String headCosmeticId;
	private String faceCosmeticId;

	public BattlePet(SpeciesDef species, String displayName, int level, List<MoveDef> moves)
	{
		this(species, displayName, level, moves, null, null);
	}

	/**
	 * @param startingHp carried-over HP from a previous battle; null starts at full
	 */
	public BattlePet(SpeciesDef species, String displayName, int level, List<MoveDef> moves, Integer startingHp)
	{
		this(species, displayName, level, moves, startingHp, null);
	}

	public BattlePet(SpeciesDef species, String displayName, int level, List<MoveDef> moves,
		Integer startingHp, String variantId)
	{
		this(species, displayName, level, moves, startingHp, variantId, null);
	}

	/**
	 * @param startingHp carried-over HP from a previous battle; null starts at full
	 * @param variantId  active metamorphosis form id, or null for the base form
	 * @param heldEffect passive held-item stat modifier, or null for none
	 */
	public BattlePet(SpeciesDef species, String displayName, int level, List<MoveDef> moves,
		Integer startingHp, String variantId, ItemEffect heldEffect)
	{
		this.species = species;
		this.variantId = variantId;
		this.heldEffect = heldEffect;
		this.displayName = displayName;
		this.level = level;
		this.moves = new ArrayList<>(moves);
		this.maxHp = computeMaxHp(level);
		this.currentHp = startingHp == null ? maxHp : Math.max(0, Math.min(maxHp, startingHp));
	}

	/**
	 * Max HP at {@code level}, folding in a held item's HP modifier (if any). Centralised so the
	 * constructor and {@link #growTo} stay in step.
	 */
	private int computeMaxHp(int level)
	{
		int base = Leveling.hpAtLevel(species.baseFor(variantId).getHp(), level);
		return Math.max(1, (int) Math.round(base * heldMultiplier(ItemEffect.Stat.HP)));
	}

	/** The held item's multiplier for {@code stat}, or 1.0 when this battler holds nothing. */
	private double heldMultiplier(ItemEffect.Stat stat)
	{
		return heldEffect == null ? 1.0 : heldEffect.multiplierFor(stat);
	}

	public SpeciesDef getSpecies()
	{
		return species;
	}

	/**
	 * Active metamorphosis form id, or null for the base form.
	 */
	public String getVariantId()
	{
		return variantId;
	}

	/**
	 * Types for this battler, honouring the active variant (tier 2); base types otherwise.
	 */
	public List<PetType> getTypes()
	{
		return species.typesFor(variantId);
	}

	/** The HEAD cosmetic worn into this fight (an {@code EquipItemDef} id), or null. */
	public String getHeadCosmeticId()
	{
		return headCosmeticId;
	}

	/** The FACE cosmetic worn into this fight (an {@code EquipItemDef} id), or null. */
	public String getFaceCosmeticId()
	{
		return faceCosmeticId;
	}

	/** Dress this battler for the scene. Purely cosmetic; safe to call at any point. */
	public void setCosmetics(String headCosmeticId, String faceCosmeticId)
	{
		this.headCosmeticId = headCosmeticId;
		this.faceCosmeticId = faceCosmeticId;
	}

	/**
	 * Whether the sprite art faces left, honouring the active variant's orientation override.
	 */
	public boolean isSpriteFacesLeft()
	{
		return species.spriteFacesLeftFor(variantId);
	}

	public String getDisplayName()
	{
		return displayName;
	}

	/**
	 * Sprite item id for this pet at its current level, honouring growth-stage evolution and the
	 * active metamorphosis form.
	 */
	public int getDisplayItemId()
	{
		return species.itemIdFor(variantId, level);
	}

	public int getLevel()
	{
		return level;
	}

	/**
	 * Grow this pet to a higher level mid-battle (from shared XP): raise max HP and add the
	 * gained HP to current, so leveling heals by the growth rather than leaving the bar looking
	 * emptier. Derived stats and the growth-stage sprite then reflect the new level for the rest
	 * of the fight. Returns the max-HP gained (0 if the level didn't actually increase).
	 */
	public int growTo(int newLevel)
	{
		if (newLevel <= level)
		{
			return 0;
		}
		int oldMax = maxHp;
		this.level = newLevel;
		this.maxHp = computeMaxHp(newLevel);
		int gain = maxHp - oldMax;
		if (gain > 0)
		{
			currentHp = Math.min(maxHp, currentHp + gain);
		}
		return Math.max(0, gain);
	}

	public List<MoveDef> getMoves()
	{
		return moves;
	}

	/**
	 * Replace this pet's in-battle moveset. Used to reflect a move learned/forgotten
	 * mid-battle so the new move is usable for the rest of the fight, without rebuilding
	 * the pet. The list is copied; empty replacements are ignored so a pet is never unarmed.
	 */
	public void setMoves(List<MoveDef> newMoves)
	{
		if (newMoves == null || newMoves.isEmpty())
		{
			return;
		}
		moves.clear();
		moves.addAll(newMoves);
	}

	public int getMaxHp()
	{
		return maxHp;
	}

	public int getCurrentHp()
	{
		return currentHp;
	}

	public boolean isFainted()
	{
		return currentHp <= 0;
	}

	public void damage(int amount)
	{
		currentHp = Math.max(0, currentHp - Math.max(0, amount));
	}

	public int heal(int amount)
	{
		int before = currentHp;
		currentHp = Math.min(maxHp, currentHp + Math.max(0, amount));
		return currentHp - before;
	}

	public Status getStatus()
	{
		return status;
	}

	public int getStatusTurns()
	{
		return statusTurns;
	}

	public boolean applyStatus(Status newStatus, int turns)
	{
		if (status != Status.NONE || newStatus == Status.NONE)
		{
			return false;
		}
		status = newStatus;
		statusTurns = turns;
		return true;
	}

	public void tickStatus()
	{
		if (status != Status.NONE && statusTurns > 0)
		{
			statusTurns--;
			if (statusTurns <= 0)
			{
				status = Status.NONE;
			}
		}
	}

	public void cureStatus()
	{
		status = Status.NONE;
		statusTurns = 0;
	}

	public int getAtkStage()
	{
		return atkStage;
	}

	public int getDefStage()
	{
		return defStage;
	}

	public int getSpdStage()
	{
		return spdStage;
	}

	/**
	 * Adjust a stat stage; returns the actual delta applied after clamping.
	 */
	public int changeStage(MoveEffect effect, int delta)
	{
		switch (effect)
		{
			case ATK_UP:
			case ATK_DOWN:
			{
				int before = atkStage;
				atkStage = clampStage(atkStage + delta);
				return atkStage - before;
			}
			case DEF_UP:
			case DEF_DOWN:
			{
				int before = defStage;
				defStage = clampStage(defStage + delta);
				return defStage - before;
			}
			case SPD_UP:
			case SPD_DOWN:
			{
				int before = spdStage;
				spdStage = clampStage(spdStage + delta);
				return spdStage - before;
			}
			default:
				return 0;
		}
	}

	private static int clampStage(int stage)
	{
		return Math.max(MIN_STAGE, Math.min(MAX_STAGE, stage));
	}

	private static double stageMultiplier(int stage)
	{
		return stage >= 0 ? (2.0 + stage) / 2.0 : 2.0 / (2.0 - stage);
	}

	public int effectiveAtk()
	{
		double v = Leveling.statAtLevel(species.baseFor(variantId).getAtk(), level) * stageMultiplier(atkStage);
		if (status == Status.BURN)
		{
			v *= 0.5;
		}
		v *= heldMultiplier(ItemEffect.Stat.ATK);
		return Math.max(1, (int) Math.round(v));
	}

	public int effectiveDef()
	{
		double v = Leveling.statAtLevel(species.baseFor(variantId).getDef(), level) * stageMultiplier(defStage);
		v *= heldMultiplier(ItemEffect.Stat.DEF);
		return Math.max(1, (int) Math.round(v));
	}

	public int effectiveSpd()
	{
		double v = Leveling.statAtLevel(species.baseFor(variantId).getSpd(), level) * stageMultiplier(spdStage);
		if (status == Status.STUN)
		{
			v *= 0.5;
		}
		v *= heldMultiplier(ItemEffect.Stat.SPD);
		return Math.max(1, (int) Math.round(v));
	}

	public boolean hasStab(PetType moveType)
	{
		return getTypes().contains(moveType);
	}
}

package com.petbattles.engine;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * Full state of an in-progress battle: both teams, active pets, phase.
 */
public class BattleState
{
	public static final int PLAYER = 0;
	public static final int ENEMY = 1;

	public enum Phase
	{
		IN_PROGRESS,
		// The player's active pet fainted mid-turn and they must choose a replacement
		// from the bench before play resumes. The forced switch consumes the round.
		PLAYER_MUST_SWITCH,
		PLAYER_WON,
		ENEMY_WON,
		FLED
	}

	private final List<BattlePet> playerTeam;
	private final List<BattlePet> enemyTeam;
	private final int[] activeIndex = {0, 0};
	// Team slots that have ever been the active pet, per side — the pets that "fought".
	// The initial lead counts, plus anything sent in via switch or on a faint.
	private final Set<Integer>[] participated;
	private Phase phase = Phase.IN_PROGRESS;
	private int turnNumber;

	@SuppressWarnings("unchecked")
	public BattleState(List<BattlePet> playerTeam, List<BattlePet> enemyTeam)
	{
		if (playerTeam.isEmpty() || enemyTeam.isEmpty())
		{
			throw new IllegalArgumentException("Both sides need at least one pet");
		}
		this.playerTeam = new ArrayList<>(playerTeam);
		this.enemyTeam = new ArrayList<>(enemyTeam);
		this.participated = new Set[]{new LinkedHashSet<>(), new LinkedHashSet<>()};
		// The opening lead on each side has already fought
		participated[PLAYER].add(activeIndex[PLAYER]);
		participated[ENEMY].add(activeIndex[ENEMY]);
	}

	public List<BattlePet> team(int side)
	{
		return side == PLAYER ? playerTeam : enemyTeam;
	}

	public BattlePet active(int side)
	{
		return team(side).get(activeIndex[side]);
	}

	public int activeIndex(int side)
	{
		return activeIndex[side];
	}

	public static int opponent(int side)
	{
		return side == PLAYER ? ENEMY : PLAYER;
	}

	public Phase getPhase()
	{
		return phase;
	}

	public void setPhase(Phase phase)
	{
		this.phase = phase;
	}

	/**
	 * True only for terminal phases. {@link Phase#PLAYER_MUST_SWITCH} is a mid-battle
	 * pause, not an ending, so it is not "over".
	 */
	public boolean isOver()
	{
		return phase == Phase.PLAYER_WON || phase == Phase.ENEMY_WON || phase == Phase.FLED;
	}

	/**
	 * Whether the battle is paused waiting for the player to send in a replacement pet.
	 */
	public boolean awaitingForcedSwitch()
	{
		return phase == Phase.PLAYER_MUST_SWITCH;
	}

	public int getTurnNumber()
	{
		return turnNumber;
	}

	public void nextTurn()
	{
		turnNumber++;
	}

	public boolean allFainted(int side)
	{
		for (BattlePet pet : team(side))
		{
			if (!pet.isFainted())
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Set the active pet directly (validated by the engine's switch handling).
	 */
	public void setActive(int side, int index)
	{
		activeIndex[side] = index;
		participated[side].add(index);
	}

	/**
	 * Team slot of the next non-fainted pet on this side, or -1 if the whole team is down.
	 * Does not change the active pet.
	 */
	public int nextAliveIndex(int side)
	{
		List<BattlePet> team = team(side);
		for (int i = 0; i < team.size(); i++)
		{
			if (!team.get(i).isFainted())
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * Switch the active pet to the next non-fainted team member; returns false if none remain.
	 */
	public boolean sendNext(int side)
	{
		int next = nextAliveIndex(side);
		if (next < 0)
		{
			return false;
		}
		setActive(side, next);
		return true;
	}

	/**
	 * Whether the pet at the given team slot has ever been the active pet this battle
	 * (the lead, or sent in via switch / on a faint). Drives "only pets that fought earn XP".
	 */
	public boolean hasFought(int side, int teamIndex)
	{
		return participated[side].contains(teamIndex);
	}
}

package com.petbattles.engine;

import java.util.Random;

/**
 * Damage formula: classic monster-battler shape, tuned for our stat scale.
 * damage = (((2*level/5 + 2) * power * atk/def) / 50 + 2) * STAB * typeEff * roll(0.85..1.0)
 */
public final class DamageCalc
{
	public static final double STAB_MULTIPLIER = 1.5;

	private DamageCalc()
	{
	}

	public static int damage(int attackerLevel, int power, int atk, int def,
		boolean stab, double typeEffectiveness, Random rng)
	{
		if (power <= 0 || typeEffectiveness <= 0)
		{
			return 0;
		}
		double base = ((2.0 * attackerLevel / 5.0 + 2.0) * power * atk / Math.max(1, def)) / 50.0 + 2.0;
		double roll = 0.85 + 0.15 * rng.nextDouble();
		double dmg = base * (stab ? STAB_MULTIPLIER : 1.0) * typeEffectiveness * roll;
		return Math.max(1, (int) Math.floor(dmg));
	}
}

