package com.petbattles.engine;

/**
 * XP curve and stat scaling. By default the curve is the real OSRS experience table
 * divided by 20, so a level-99 pet takes ~650k pet-XP instead of 13M. A dev toggle
 * ({@link #setFullCurve}) swaps in the full, unscaled OSRS table for authentic pacing.
 */
public final class Leveling
{
	public static final int MAX_LEVEL = 99;
	/** Default shipped pacing: the OSRS table divided by 20 (~650k xp to 99). */
	private static final long[] XP_FAST = buildTable(20);
	/** Full unscaled OSRS table (~13M xp to 99), behind the dev toggle. */
	private static final long[] XP_FULL = buildTable(1);
	// Read on the client thread by pet-level lookups; written from config changes.
	private static volatile boolean fullCurve;

	private static long[] buildTable(int divisor)
	{
		// OSRS formula: points(n) = floor(n + 300 * 2^(n/7)); xp(level) = floor(sum(points 1..level-1) / 4)
		long[] table = new long[MAX_LEVEL + 1];
		double points = 0;
		table[1] = 0;
		for (int lvl = 2; lvl <= MAX_LEVEL; lvl++)
		{
			int n = lvl - 1;
			points += Math.floor(n + 300.0 * Math.pow(2.0, n / 7.0));
			table[lvl] = (long) Math.floor(points / 4.0) / divisor;
		}
		return table;
	}

	private Leveling()
	{
	}

	/**
	 * Select the XP curve: false (default) uses the ÷20 fast pacing, true uses the full
	 * unscaled OSRS table. Changes the effective level of every pet, so callers should
	 * refresh any level-derived UI after flipping it.
	 */
	public static void setFullCurve(boolean full)
	{
		fullCurve = full;
	}

	private static long[] table()
	{
		return fullCurve ? XP_FULL : XP_FAST;
	}

	public static long xpForLevel(int level)
	{
		if (level < 1)
		{
			return 0;
		}
		if (level > MAX_LEVEL)
		{
			level = MAX_LEVEL;
		}
		return table()[level];
	}

	public static int levelForXp(long xp)
	{
		long[] table = table();
		for (int lvl = MAX_LEVEL; lvl >= 1; lvl--)
		{
			if (xp >= table[lvl])
			{
				return lvl;
			}
		}
		return 1;
	}

	public static int statAtLevel(int base, int level)
	{
		return (int) Math.round(base * (1.0 + level / 50.0));
	}

	public static int hpAtLevel(int baseHp, int level)
	{
		return (int) Math.round(baseHp * (1.0 + level / 40.0)) + 10;
	}

	/**
	 * XP for the follower pet when the player kills an NPC in the real game.
	 */
	public static long killXp(int npcCombatLevel, boolean typeMatch)
	{
		long xp = 5 + Math.max(0, npcCombatLevel) / 2;
		return typeMatch ? xp * 3 : xp;
	}

	/** How much each previous win against a trainer shaves off the next win's reward. */
	public static final double REPEAT_STEP = 0.10;

	/** The floor the {@link #repeatFactor(int) taper} settles at, however often you re-fight. */
	public static final double REPEAT_FLOOR = 0.50;

	/**
	 * Reward multiplier for beating a trainer you have already beaten {@code priorWins} times: full
	 * value the first time, then 10% less per prior win down to a 50% floor (so the 6th win and every
	 * one after pays half).
	 *
	 * <p>It replaced a flat half-rate on every re-fight, which made the Remote Battle Device — a whole
	 * quest's reward — barely worth using. A taper keeps the pull toward fresh trainers without
	 * punishing the second fight as harshly as the twentieth.
	 */
	public static double repeatFactor(int priorWins)
	{
		return Math.max(REPEAT_FLOOR, 1.0 - REPEAT_STEP * Math.max(0, priorWins));
	}

	/**
	 * Most levels a single pet may gain from one battle. On the compressed low-level curve a
	 * single early win would otherwise vault a level-1 pet deep into the teens (feedback #3);
	 * this caps the jump while leaving late-game pacing untouched (a capped 200 XP is a small
	 * fraction of a level by then anyway).
	 */
	public static final int MAX_LEVELS_PER_BATTLE = 5;

	/**
	 * Clamp a battle XP award so a pet finishes the battle at most {@link #MAX_LEVELS_PER_BATTLE}
	 * levels above the level it started that battle at. {@code currentXp} is the pet's XP right now
	 * (it may already have gained levels earlier in the same battle); returns the XP to actually
	 * apply, never more than {@code award} and never negative.
	 */
	public static long capBattleXp(long currentXp, long award, int battleStartLevel)
	{
		if (award <= 0)
		{
			return Math.max(0, award);
		}
		int capLevel = battleStartLevel + MAX_LEVELS_PER_BATTLE;
		if (capLevel >= MAX_LEVEL)
		{
			return award; // no cap needed near the level ceiling
		}
		long ceiling = xpForLevel(capLevel);
		if (currentXp >= ceiling)
		{
			return 0;
		}
		return Math.min(award, ceiling - currentXp);
	}

	/**
	 * XP for winning a plugin battle, scaled by relative levels (first-win amount).
	 */
	public static long battleWinXp(int enemyLevel, int yourLevel)
	{
		long xp = Math.round(25.0 * enemyLevel / Math.max(1, yourLevel));
		return Math.max(10, Math.min(200, xp));
	}

	/**
	 * XP for a battle win, tapered by {@link #repeatFactor(int)} against a trainer already beaten
	 * {@code priorWins} times.
	 */
	public static long battleWinXp(int enemyLevel, int yourLevel, int priorWins)
	{
		long xp = battleWinXp(enemyLevel, yourLevel);
		return Math.max(1, Math.round(xp * repeatFactor(priorWins)));
	}

	/**
	 * Coins for winning a plugin battle (first-win amount). A single flat per-battle reward for
	 * the player's wallet — not shared per pet like XP — scaled by the combined level of the
	 * trainer's team so tougher trainers pay more, then clamped to a sane band.
	 */
	public static long battleWinCoins(int totalEnemyLevels)
	{
		long coins = 10 + Math.max(0, totalEnemyLevels);
		return Math.max(10, Math.min(500, coins));
	}

	/**
	 * Coins for a battle win, tapered by {@link #repeatFactor(int)} against a trainer already beaten
	 * {@code priorWins} times, so a beaten trainer can't be farmed indefinitely for currency.
	 */
	public static long battleWinCoins(int totalEnemyLevels, int priorWins)
	{
		long coins = battleWinCoins(totalEnemyLevels);
		return Math.max(1, Math.round(coins * repeatFactor(priorWins)));
	}
}

package com.petbattles.engine;

/**
 * A move definition loaded from moves.json. power == 0 means a pure status/utility move.
 */
public class MoveDef
{
	private String id;
	private String name;
	private PetType type;
	private int power;
	private int accuracy;
	private MoveEffect effect = MoveEffect.NONE;
	private int effectChance;
	// Optional hand-authored animation id ("lunge", "whip", "projectile", "grow",
	// "shake", "flash", "sparkle"); null falls back to a category default.
	private String animation;

	public MoveDef()
	{
	}

	public MoveDef(String id, String name, PetType type, int power, int accuracy, MoveEffect effect, int effectChance)
	{
		this.id = id;
		this.name = name;
		this.type = type;
		this.power = power;
		this.accuracy = accuracy;
		this.effect = effect == null ? MoveEffect.NONE : effect;
		this.effectChance = effectChance;
	}

	public String getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	public PetType getType()
	{
		return type;
	}

	public int getPower()
	{
		return power;
	}

	public int getAccuracy()
	{
		return accuracy;
	}

	public MoveEffect getEffect()
	{
		return effect == null ? MoveEffect.NONE : effect;
	}

	public int getEffectChance()
	{
		return effectChance;
	}

	public String getAnimation()
	{
		return animation;
	}

	public boolean isStatusMove()
	{
		return power <= 0;
	}
}

package com.petbattles.engine;

/**
 * Secondary effect of a move. Status effects target the enemy; stat-up and heal target self.
 */
public enum MoveEffect
{
	NONE,
	BURN,   // enemy: chip damage each turn, attack halved
	FREEZE, // enemy: skips turns until thawed
	POISON, // enemy: chip damage each turn
	STUN,   // enemy: chance to skip each turn, speed halved
	ATK_UP,
	DEF_UP,
	SPD_UP,
	ATK_DOWN,
	DEF_DOWN,
	SPD_DOWN,
	HEAL;   // self: restore 50% max HP

	public boolean isStatus()
	{
		return this == BURN || this == FREEZE || this == POISON || this == STUN;
	}

	public boolean isSelfBuff()
	{
		return this == ATK_UP || this == DEF_UP || this == SPD_UP || this == HEAL;
	}

	public boolean isEnemyDebuff()
	{
		return this == ATK_DOWN || this == DEF_DOWN || this == SPD_DOWN;
	}
}

package com.petbattles.engine;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * A player's individual pet: persistent progression state (serialized to the roster blob).
 */
public class PetInstance
{
	public static final int MAX_EQUIPPED_MOVES = 4;

	private String speciesId;
	private String nickname;
	private long xp;
	private List<String> equippedMoves = new ArrayList<>();
	private Set<String> unlockedEggMoves = new LinkedHashSet<>();
	// HP carried over from the last battle; null = fully rested. 0 = fainted (can't
	// fight until rested at a bank). Absolute value, clamped to max HP on battle start.
	private Integer currentHp;
	// Active metamorphosis form (a SpeciesDef.Variant id), or null for the base form. Set from
	// read-only follower/inventory detection; a lens over presentation (and later combat), not a
	// separate roster entry — progression stays on this one instance.
	private String activeVariantId;
	// Equipped HELD item (an EquipItemDef id), or null. Applies its passive stat modifier in battle.
	private String heldItemId;
	// Equipped cosmetics (EquipItemDef ids), or null for a bare pet. Purely presentational: drawn on
	// the pet's battle chathead, no combat effect. Kept as two plain fields rather than a slot map so
	// the roster blob stays flat and this class keeps no dependency on the item package.
	private String headItemId;
	private String faceItemId;

	public PetInstance()
	{
	}

	public PetInstance(String speciesId)
	{
		this.speciesId = speciesId;
	}

	public String getSpeciesId()
	{
		return speciesId;
	}

	public String getNickname()
	{
		return nickname;
	}

	public void setNickname(String nickname)
	{
		this.nickname = nickname;
	}

	public long getXp()
	{
		return xp;
	}

	public int getLevel()
	{
		return Leveling.levelForXp(xp);
	}

	/**
	 * Add XP; returns the number of levels gained.
	 */
	public int addXp(long amount)
	{
		int before = getLevel();
		xp += Math.max(0, amount);
		return getLevel() - before;
	}

	/**
	 * Active metamorphosis form (a {@link SpeciesDef.Variant} id), or null for the base form.
	 */
	public String getActiveVariantId()
	{
		return activeVariantId;
	}

	public void setActiveVariantId(String activeVariantId)
	{
		this.activeVariantId = activeVariantId;
	}

	/**
	 * The equipped HELD item's id (an {@code EquipItemDef} id), or null if the pet holds nothing.
	 */
	public String getHeldItemId()
	{
		return heldItemId;
	}

	public void setHeldItemId(String heldItemId)
	{
		this.heldItemId = heldItemId;
	}

	/**
	 * The equipped HEAD cosmetic's id (an {@code EquipItemDef} id), or null if the pet wears none.
	 */
	public String getHeadItemId()
	{
		return headItemId;
	}

	public void setHeadItemId(String headItemId)
	{
		this.headItemId = headItemId;
	}

	/**
	 * The equipped FACE cosmetic's id (an {@code EquipItemDef} id), or null if the pet wears none.
	 */
	public String getFaceItemId()
	{
		return faceItemId;
	}

	public void setFaceItemId(String faceItemId)
	{
		this.faceItemId = faceItemId;
	}

	public Integer getCurrentHp()
	{
		return currentHp;
	}

	public void setCurrentHp(Integer currentHp)
	{
		this.currentHp = currentHp;
	}

	public boolean isFainted()
	{
		return currentHp != null && currentHp <= 0;
	}

	/**
	 * Fully rest this pet (bank heal): back to full HP and battle-ready.
	 */
	public void rest()
	{
		currentHp = null;
	}

	public List<String> getEquippedMoves()
	{
		if (equippedMoves == null)
		{
			equippedMoves = new ArrayList<>();
		}
		return equippedMoves;
	}

	public boolean equipMove(String moveId)
	{
		List<String> moves = getEquippedMoves();
		if (moves.contains(moveId) || moves.size() >= MAX_EQUIPPED_MOVES)
		{
			return false;
		}
		moves.add(moveId);
		return true;
	}

	public boolean unequipMove(String moveId)
	{
		return getEquippedMoves().remove(moveId);
	}

	public Set<String> getUnlockedEggMoves()
	{
		if (unlockedEggMoves == null)
		{
			unlockedEggMoves = new LinkedHashSet<>();
		}
		return unlockedEggMoves;
	}

	/**
	 * All move ids this pet can equip: learnset up to current level (for its active variant) plus
	 * unlocked egg moves.
	 */
	public List<String> availableMoves(SpeciesDef species)
	{
		List<String> moves = new ArrayList<>(species.movesKnownFor(activeVariantId, getLevel()));
		for (String egg : getUnlockedEggMoves())
		{
			if (!moves.contains(egg))
			{
				moves.add(egg);
			}
		}
		return moves;
	}
}

