package com.petbattles.engine;

import java.util.List;
import java.util.Map;

/**
 * Effectiveness matrix: attacker type -> defender type -> multiplier (2.0 / 1.0 / 0.5).
 * Dual-typed defenders multiply both columns.
 */
public class TypeChart
{
	private static final double S = 2.0; // super effective
	private static final double N = 1.0; // neutral
	private static final double W = 0.5; // not very effective

	// Row = attacking type, column = defending type; order matches PetType.values():
	// MEL   RNG   MAG   FIR   ICE   NAT   UND   DEM   DRG   SKL
	private static final double[][] DEFAULT =
	{
		{N,    S,    W,    N,    S,    N,    W,    N,    W,    N}, // MELEE
		{W,    N,    S,    N,    N,    W,    N,    N,    S,    N}, // RANGED
		{S,    W,    N,    W,    N,    N,    N,    S,    N,    S}, // MAGIC
		{N,    N,    W,    W,    S,    S,    S,    W,    W,    N}, // FIRE
		{N,    W,    N,    W,    W,    S,    N,    N,    S,    N}, // ICE
		{N,    S,    W,    W,    N,    W,    S,    N,    N,    W}, // NATURE
		{N,    N,    N,    W,    N,    S,    W,    S,    N,    S}, // UNDEAD
		{S,    N,    W,    S,    W,    N,    N,    W,    N,    S}, // DEMON
		{N,    W,    N,    W,    W,    S,    N,    S,    W,    S}, // DRAGON
		{N,    N,    N,    N,    S,    S,    S,    N,    N,    N}, // SKILLING
	};

	private final double[][] matrix;

	public TypeChart()
	{
		this(DEFAULT);
	}

	public TypeChart(double[][] matrix)
	{
		if (matrix.length != PetType.values().length)
		{
			throw new IllegalArgumentException("Type chart must have one row per type");
		}
		for (double[] row : matrix)
		{
			if (row.length != PetType.values().length)
			{
				throw new IllegalArgumentException("Type chart must have one column per type");
			}
		}
		this.matrix = matrix;
	}

	/**
	 * Build a chart from a JSON-friendly nested map keyed by type name; missing entries are neutral.
	 */
	public static TypeChart fromMap(Map<String, Map<String, Double>> map)
	{
		PetType[] types = PetType.values();
		double[][] m = new double[types.length][types.length];
		for (int a = 0; a < types.length; a++)
		{
			Map<String, Double> row = map.get(types[a].name());
			for (int d = 0; d < types.length; d++)
			{
				Double v = row == null ? null : row.get(types[d].name());
				m[a][d] = v == null ? N : v;
			}
		}
		return new TypeChart(m);
	}

	public double effectiveness(PetType attack, PetType defend)
	{
		return matrix[attack.ordinal()][defend.ordinal()];
	}

	public double effectiveness(PetType attack, List<PetType> defenderTypes)
	{
		double mult = 1.0;
		for (PetType t : defenderTypes)
		{
			mult *= effectiveness(attack, t);
		}
		return mult;
	}
}

package com.petbattles.engine.controller;

import com.petbattles.engine.BattleAction;
import com.petbattles.engine.BattlePet;
import com.petbattles.engine.BattleState;
import com.petbattles.engine.MoveDef;
import com.petbattles.engine.MoveEffect;
import com.petbattles.engine.TrainerDef;
import com.petbattles.engine.TypeChart;
import java.util.List;
import java.util.Random;

/**
 * Trainer AI. EASY picks randomly; MEDIUM maximizes expected damage;
 * HARD adds healing when low and status spreading when ahead.
 */
public class AiController implements OpponentController
{
	private final TrainerDef.Difficulty difficulty;
	private final TypeChart typeChart;

	public AiController(TrainerDef.Difficulty difficulty, TypeChart typeChart)
	{
		this.difficulty = difficulty;
		this.typeChart = typeChart;
	}

	@Override
	public BattleAction chooseAction(BattleState state, int side, Random rng)
	{
		BattlePet self = state.active(side);
		List<MoveDef> moves = self.getMoves();
		if (moves.isEmpty())
		{
			return BattleAction.flee();
		}
		if (difficulty == TrainerDef.Difficulty.EASY)
		{
			return BattleAction.move(rng.nextInt(moves.size()));
		}

		BattlePet target = state.active(BattleState.opponent(side));

		if (difficulty == TrainerDef.Difficulty.HARD)
		{
			// Heal when below 35% if we have a heal move
			if (self.getCurrentHp() * 100 < self.getMaxHp() * 35)
			{
				int healIdx = indexOfEffect(moves, MoveEffect.HEAL);
				if (healIdx >= 0)
				{
					return BattleAction.move(healIdx);
				}
			}
			// Spread a status if the target is clean and we have a reliable status move
			if (target.getStatus() == BattlePet.Status.NONE)
			{
				for (int i = 0; i < moves.size(); i++)
				{
					MoveDef m = moves.get(i);
					if (m.isStatusMove() && m.getEffect().isStatus() && m.getEffectChance() >= 75)
					{
						return BattleAction.move(i);
					}
				}
			}
		}

		// MEDIUM (and HARD fallback): argmax expected damage
		int bestIdx = 0;
		double bestScore = -1;
		for (int i = 0; i < moves.size(); i++)
		{
			MoveDef m = moves.get(i);
			double eff = typeChart.effectiveness(m.getType(), target.getTypes());
			double stab = self.hasStab(m.getType()) ? 1.5 : 1.0;
			double score = m.getPower() * eff * stab * (m.getAccuracy() / 100.0);
			if (score > bestScore)
			{
				bestScore = score;
				bestIdx = i;
			}
		}
		return BattleAction.move(bestIdx);
	}

	private static int indexOfEffect(List<MoveDef> moves, MoveEffect effect)
	{
		for (int i = 0; i < moves.size(); i++)
		{
			if (moves.get(i).getEffect() == effect)
			{
				return i;
			}
		}
		return -1;
	}
}

