package com.petbattles.follower;

import com.petbattles.data.PetDatabase;
import com.petbattles.engine.SpeciesDef;
import com.petbattles.persist.RosterManager;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.eventbus.Subscribe;

/**
 * Tracks which pet is currently following the player.
 *
 * Primary signal: varp 447 (FOLLOWER_NPC) — high 16 bits are the follower's NPC id.
 * Fallback: an NpcSpawned whose id is a known pet and which is interacting with us.
 * A pet seen following the player is also unlocked (you can't have a follower you
 * don't own), which makes this a live unlock source for fresh drops.
 */
@Slf4j
public class FollowerTracker
{
	private final Client client;
	private final PetDatabase db;
	private final RosterManager roster;
	private final Runnable onChange;

	private String activeSpeciesId;

	public FollowerTracker(Client client, PetDatabase db, RosterManager roster, Runnable onChange)
	{
		this.client = client;
		this.db = db;
		this.roster = roster;
		this.onChange = onChange;
	}

	/**
	 * Species id of the pet currently following the player, or null.
	 */
	public String getActiveSpeciesId()
	{
		return activeSpeciesId;
	}

	/**
	 * Re-read the follower varp (called after login/roster load).
	 */
	public void refresh()
	{
		apply(client.getVarpValue(VarPlayerID.FOLLOWER_NPC));
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() == VarPlayerID.FOLLOWER_NPC)
		{
			apply(event.getValue());
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		// Fallback path: catches the fresh-drop case before any varp read
		NPC npc = event.getNpc();
		SpeciesDef species = db.speciesByNpcId(npc.getId());
		if (species != null && npc.getInteracting() == client.getLocalPlayer())
		{
			setActive(species, db.variantByNpcId(npc.getId()));
		}
	}

	private void apply(int varpValue)
	{
		if (varpValue <= 0)
		{
			if (activeSpeciesId != null)
			{
				activeSpeciesId = null;
				onChange.run();
			}
			return;
		}
		int npcId = varpValue >>> 16;
		SpeciesDef species = db.speciesByNpcId(npcId);
		if (species != null)
		{
			setActive(species, db.variantByNpcId(npcId));
		}
	}

	private void setActive(SpeciesDef species, String variantId)
	{
		boolean changed = false;
		if (roster.isLoaded())
		{
			// Owning proof: it's following you
			roster.unlock(species.getId());
			roster.getOrCreatePet(species.getId());
			// The follower npc id carries the active metamorphosis form; record it. Done even when
			// the species is unchanged, so metamorphosing your current follower flips the form.
			changed = roster.setActiveVariant(species.getId(), variantId);
		}
		if (!species.getId().equals(activeSpeciesId))
		{
			activeSpeciesId = species.getId();
			log.debug("Active follower pet: {} (variant {})", species.getId(), variantId);
			changed = true;
		}
		if (changed)
		{
			onChange.run();
		}
	}
}

package com.petbattles.follower;

import com.petbattles.data.PetDatabase;
import com.petbattles.engine.SpeciesDef;
import com.petbattles.persist.RosterManager;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Keeps possession-gated pets ({@link SpeciesDef#isItemUnlock()}, i.e. the OSRS cat) in
 * sync with what the player actually owns in-game:
 *  - unlock when the pet item is seen in the inventory or bank (holding it is proof of
 *    ownership the collection log never records for these pets),
 *  - revoke when a matching game message shows the pet was traded away (e.g. handing a
 *    grown cat over for death runes).
 * The follower unlock path is handled separately by {@link FollowerTracker} via npc ids.
 */
@Slf4j
public class HeldItemTracker
{
	private final Client client;
	private final PetDatabase db;
	private final RosterManager roster;
	private final Runnable onChange;
	// Pre-compiled trade-away message patterns, by species id
	private final Map<String, Pattern> tradeInPatterns = new LinkedHashMap<>();

	public HeldItemTracker(Client client, PetDatabase db, RosterManager roster, Runnable onChange)
	{
		this.client = client;
		this.db = db;
		this.roster = roster;
		this.onChange = onChange;
		for (SpeciesDef species : db.allSpecies())
		{
			if (species.getTradeInMessage() != null && !species.getTradeInMessage().isEmpty())
			{
				tradeInPatterns.put(species.getId(),
					Pattern.compile(species.getTradeInMessage(), Pattern.CASE_INSENSITIVE));
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if ((id != InventoryID.INV && id != InventoryID.BANK) || !roster.isLoaded())
		{
			return;
		}
		scan(event.getItemContainer());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE || !roster.isLoaded()
			|| tradeInPatterns.isEmpty())
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());
		for (Map.Entry<String, Pattern> entry : tradeInPatterns.entrySet())
		{
			if (entry.getValue().matcher(message).find() && roster.removeOwnership(entry.getKey()))
			{
				SpeciesDef species = db.species(entry.getKey());
				log.debug("Trade-in revoked {}", entry.getKey());
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"<col=ff7700>Pet Battles:</col> " + species.getName() + " left your roster.", null);
				onChange.run();
				return;
			}
		}
	}

	private void scan(ItemContainer container)
	{
		if (container == null)
		{
			return;
		}
		boolean any = false;
		for (Item item : container.getItems())
		{
			int itemId = item.getId();
			if (itemId <= 0)
			{
				continue;
			}
			SpeciesDef species = db.speciesByItemId(itemId);
			if (species == null)
			{
				continue;
			}
			// Only possession-gated pets unlock this way; collection-log pets keep to the log
			if (species.isItemUnlock() && roster.unlock(species.getId()))
			{
				roster.getOrCreatePet(species.getId());
				log.debug("Held-item sync unlocked {}", species.getId());
				announce(species);
				any = true;
			}
			// Holding a metamorphosis form's item is proof that form is active — flip an owned
			// pet's variant to match (no-op if not owned or already on that form). Read-only.
			String variantId = db.variantByItemId(itemId);
			if (variantId != null && roster.setActiveVariant(species.getId(), variantId))
			{
				log.debug("Held-item sync set {} variant {}", species.getId(), variantId);
				any = true;
			}
		}
		if (any)
		{
			onChange.run();
		}
	}

	private void announce(SpeciesDef species)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
			"<col=ff7700>Pet Battles:</col> " + species.getName() + " joined your roster!", null);
	}
}

package com.petbattles.item;

import com.petbattles.engine.ItemEffect;

/**
 * A battle equip item loaded from {@code items.json}: either a {@code HELD} item (a passive stat
 * modifier a pet carries) or a cosmetic ({@code HEAD}/{@code FACE}, drawn on the sprite, no combat
 * effect). Data-shaped like {@code SpeciesDef}/{@code MoveDef}.
 *
 * <p>Deliberately distinct from the two pre-existing "item" concepts: the {@link Item} key-item
 * enum (quest rewards like the Remote Battle Device) and {@code follower.HeldItemTracker}
 * (possession-gated pet unlocks). See the naming note in the roadmap.
 */
public class EquipItemDef
{
	public enum Slot
	{
		/** A battle item a pet holds; carries a stat {@link #effect}. */
		HELD,
		/** Cosmetic head accessory (drawn on the sprite; no effect). */
		HEAD,
		/** Cosmetic face accessory (drawn on the sprite; no effect). */
		FACE
	}

	/** JSON shape of a held item's stat effect (absent for cosmetics). */
	public static class EffectData
	{
		private ItemEffect.Stat stat;
		private int magnitude;

		public EffectData()
		{
		}

		public ItemEffect.Stat getStat()
		{
			return stat;
		}

		public int getMagnitude()
		{
			return magnitude;
		}
	}

	private String id;
	private String name;
	private Slot slot = Slot.HELD;
	// Icon basename under /com/petbattles/items/<sprite>.png (used by the later cosmetic-render slice).
	private String sprite;
	private String examine;
	// Present only for HELD stat items; null for cosmetics.
	private EffectData effect;
	// Coin price in the store; 0 (or absent) means not sold. See the store MVP note: held items are
	// priced for now so the loop is testable, but the design moves them to quest rewards later.
	private int price;

	public EquipItemDef()
	{
	}

	public String getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	public Slot getSlot()
	{
		return slot == null ? Slot.HELD : slot;
	}

	public String getSprite()
	{
		return sprite;
	}

	public String getExamine()
	{
		return examine;
	}

	/**
	 * The passive stat modifier for a HELD item, or {@code null} for cosmetics (and any HELD item
	 * that declares no effect). A fresh {@link ItemEffect} is built per call from the JSON data.
	 */
	public ItemEffect getEffect()
	{
		return effect == null ? null : new ItemEffect(effect.getStat(), effect.getMagnitude());
	}

	/** Whether this is a cosmetic (drawn on the sprite, no combat effect) rather than a held item. */
	public boolean isCosmetic()
	{
		return getSlot() != Slot.HELD;
	}

	/** Coin price in the store, or 0 if this item isn't sold there. */
	public int getPrice()
	{
		return price;
	}

	/** Whether this item can currently be bought in the store. */
	public boolean isSold()
	{
		return price > 0;
	}
}

package com.petbattles.item;

/**
 * A reward the player has earned and keeps — the plugin's equivalent of a key item. Items are
 * awarded by quests today and will later come from shop rewards; the Items panel lists whichever
 * ones the player currently holds. Each item's icon is bundled at
 * {@code /com/petbattles/items/<id>.png}. Ownership is not stored here — it's derived from the
 * roster state that granted the item (see the Items panel's owned-items check), so an item and the
 * thing it unlocks can never drift apart.
 */
public enum Item
{
	/**
	 * Professor Oddenstein's Remote Battle Device, awarded by completing "Where's the remote?"
	 * ({@link com.petbattles.persist.RosterManager#isRemoteBattlesUnlocked()}). Holding it lets the
	 * player challenge any trainer straight from the panel.
	 */
	REMOTE_BATTLE_DEVICE("remote_battle_device", "Remote Battle Device",
		"Professor Oddenstein's contraption. Challenge any trainer straight from the panel, "
			+ "without standing next to them in the world."),

	/**
	 * The clue wrung from Ambassador Gimblewap in "A Series of Fortunate Events" — instructions to
	 * hide a tax that funds Probita's insurance fees, signed in an elegant hand: "White Beard." Owned
	 * once that chapter is done.
	 */
	SEALED_ENVELOPE("sealed_envelope", "Sealed Envelope",
		"A letter with instructions to Gimblewap to sneak in a tax to pay Probita insurance fees, "
			+ "signed in an elegant hand: \"White Beard\"."),

	/**
	 * The reformed Wise Old Man's parting gift for finishing "A Series of Fortunate Events" — the one
	 * cosmetic no coin can buy. Owned once the capstone is complete.
	 */
	BLUE_PARTY_HAT("blue_party_hat", "Blue party hat",
		"An old thief's treasure, pressed into your hands. Prestige you fought for, not bought.");

	private final String id;
	private final String name;
	private final String description;

	Item(String id, String name, String description)
	{
		this.id = id;
		this.name = name;
		this.description = description;
	}

	/** The item with this id, or null if none matches. */
	public static Item byId(String id)
	{
		for (Item item : values())
		{
			if (item.id.equals(id))
			{
				return item;
			}
		}
		return null;
	}

	public String getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	/** What the item is and what holding it grants the player. */
	public String getDescription()
	{
		return description;
	}
}

package com.petbattles.npc;

import com.petbattles.data.PetDatabase;
import com.petbattles.engine.TrainerDef;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.Subscribe;

/**
 * "Is the player standing next to a known trainer?" Trainer NPCs are tracked from
 * spawn/despawn events into a small set (no scene scans); proximity is re-evaluated once
 * per game tick against that set. Being near an undefeated trainer is what unlocks the
 * first panel Fight against them, replacing the old in-world right-click entry.
 */
@Slf4j
public class NearTrainerTracker
{
	private static final int TRAINER_RADIUS_TILES = 10;

	private final Client client;
	private final Runnable onChanged;
	// Reverse map: in-world NPC id -> trainer id
	private final Map<Integer, String> trainerIdByNpcId = new HashMap<>();
	private final Set<NPC> trainers = new HashSet<>();
	// Read from the Swing EDT by the panel; written on the client thread
	private volatile Set<String> nearTrainerIds = new HashSet<>();

	public NearTrainerTracker(Client client, PetDatabase db, Runnable onChanged)
	{
		this.client = client;
		this.onChanged = onChanged;
		for (TrainerDef trainer : db.allTrainers())
		{
			for (int npcId : trainer.getNpcIds())
			{
				trainerIdByNpcId.put(npcId, trainer.getId());
			}
		}
	}

	/**
	 * Whether the trainer with this id is currently within a few tiles of the player.
	 */
	public boolean isNear(String trainerId)
	{
		return nearTrainerIds.contains(trainerId);
	}

	/**
	 * Snapshot of every trainer id currently within a few tiles of the player. The
	 * challenge overlay needs the whole set (not just a single-id test) to list who
	 * you can battle right now.
	 */
	public Set<String> getNearTrainerIds()
	{
		return new LinkedHashSet<>(nearTrainerIds);
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned e)
	{
		if (trainerIdByNpcId.containsKey(e.getNpc().getId()))
		{
			trainers.add(e.getNpc());
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned e)
	{
		trainers.remove(e.getNpc());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOADING || e.getGameState() == GameState.LOGIN_SCREEN
			|| e.getGameState() == GameState.HOPPING)
		{
			trainers.clear();
			update();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		update();
	}

	private void update()
	{
		Set<String> now = computeNearby();
		if (!now.equals(nearTrainerIds))
		{
			log.debug("Near-trainer set changed: {} -> {} (tracking {} trainer NPC(s))",
				nearTrainerIds, now, trainers.size());
			nearTrainerIds = now;
			onChanged.run();
		}
	}

	private Set<String> computeNearby()
	{
		if (trainers.isEmpty() || client.getLocalPlayer() == null)
		{
			return new HashSet<>();
		}
		WorldPoint me = client.getLocalPlayer().getWorldLocation();
		if (me == null)
		{
			return new HashSet<>();
		}
		Set<String> near = new LinkedHashSet<>();
		for (NPC npc : trainers)
		{
			WorldPoint p = npc.getWorldLocation();
			if (p != null && me.distanceTo(p) <= TRAINER_RADIUS_TILES)
			{
				String trainerId = trainerIdByNpcId.get(npc.getId());
				if (trainerId != null)
				{
					near.add(trainerId);
				}
			}
		}
		return near;
	}
}

package com.petbattles.persist;

import com.petbattles.PetBattlesConfig;
import com.petbattles.data.PetDatabase;
import com.petbattles.engine.PetInstance;
import com.petbattles.engine.SpeciesDef;
import com.petbattles.item.EquipItemDef;
import com.petbattles.item.Item;
import com.petbattles.quest.QuestDef;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.BooleanSupplier;
import lombok.extern.slf4j.Slf4j;

/**
 * Runtime roster state: which species are owned, per-pet progression, and the battle team.
 * All mutations save through the store immediately (the blob is small).
 */
@Slf4j
public class RosterManager
{
	public static final int MAX_TEAM_SIZE = 3;

	/**
	 * Bump this whenever a content change (balance pass, movepool/level retune, XP-curve
	 * change) makes stored pet progression stale enough that every roster should be wiped
	 * back to a clean level-1 state on next load. Not every release needs this -- only bump
	 * when old progression would otherwise be invalid or misleading. Add a changelog line
	 * below each time you bump it, so it's clear which versions triggered a reset.
	 *
	 * Reset changelog:
	 *   (none yet -- bump to 1 and add a line here to trigger the first reset)
	 */
	public static final int PROGRESSION_RESET_VERSION = 0;

	// The capstone story quest whose key-item trophies (Sealed Envelope, Blue party hat) derive their
	// ownership from its progress -- see ownsItem. Kept here (not in QuestManager) because ownership
	// is read straight off questProgress, mirroring the REMOTE_BATTLE_DEVICE case. The steps that
	// grant them are read from the quest content, so re-ordering or dropping chapters can't desync
	// them.
	private static final String CAPSTONE_QUEST_ID = "series_of_fortunate_events";

	// The intro quest that hands over the Remote Battle Device. Completing it lets the player battle
	// already-defeated trainers remotely (see canRemoteFight). The complete step is read from the
	// quest content, so adding chapters can't desync this.
	private static final String REMOTE_QUEST_ID = "wheres_the_remote";

	private final PetDatabase db;
	private final RosterStore store;
	private RosterStore.RosterData data = new RosterStore.RosterData();
	private boolean loaded;
	// Team composition (add/remove) is bank-gated; reordering is not. The gate is
	// re-checked here so a stale panel can't edit the team away from a bank.
	private volatile BooleanSupplier teamEditGate = () -> true;

	public RosterManager(PetDatabase db, RosterStore store)
	{
		this.db = db;
		this.store = store;
	}

	public synchronized void load()
	{
		data = store.load();
		if (data.devUnlocked == null)
		{
			data.devUnlocked = new java.util.LinkedHashSet<>();
		}
		if (data.defeatedTrainers == null)
		{
			data.defeatedTrainers = new java.util.LinkedHashSet<>();
		}
		if (data.trainerWins == null)
		{
			data.trainerWins = new LinkedHashMap<>();
		}
		if (data.questProgress == null)
		{
			data.questProgress = new java.util.LinkedHashMap<>();
		}
		if (data.questFlags == null)
		{
			data.questFlags = new java.util.LinkedHashSet<>();
		}
		if (data.itemInventory == null)
		{
			data.itemInventory = new LinkedHashMap<>();
		}
		// Drop references to species/trainers that no longer exist in the content
		data.team.removeIf(id -> db.species(id) == null);
		data.ownedSpecies.removeIf(id -> db.species(id) == null);
		data.devUnlocked.removeIf(id -> db.species(id) == null);
		data.defeatedTrainers.removeIf(id -> db.trainer(id) == null);
		data.trainerWins.keySet().removeIf(id -> db.trainer(id) == null);
		// One-shot progression wipe when the code constant outruns what this roster has seen.
		if (data.progressionResetVersion < PROGRESSION_RESET_VERSION)
		{
			log.debug("Applying progression reset v{} (was v{}); wiping {} pet record(s)",
				PROGRESSION_RESET_VERSION, data.progressionResetVersion, data.pets.size());
			data.pets.clear();
			data.progressionResetVersion = PROGRESSION_RESET_VERSION;
			store.save(data);
		}
		boolean migrated = migrateWornHeldItemsIntoInventory();
		// Equip capacities are recomputed, never stored, so any save can be checked against them —
		// including one an older build left with two pets sharing a single amulet.
		int stripped = repairEquipCapacity();
		if (stripped > 0)
		{
			log.debug("Repaired {} over-capacity equip slot(s)", stripped);
		}
		if (migrated || stripped > 0)
		{
			store.save(data);
		}
		loaded = true;
	}

	public synchronized void unload()
	{
		if (loaded)
		{
			store.save(data);
		}
		data = new RosterStore.RosterData();
		loaded = false;
	}

	public boolean isLoaded()
	{
		return loaded;
	}

	private synchronized void save()
	{
		if (loaded)
		{
			store.save(data);
		}
	}

	public synchronized boolean isOwned(String speciesId)
	{
		return PetBattlesConfig.devUnlockAll()
			|| data.ownedSpecies.contains(speciesId)
			|| (PetBattlesConfig.devSelectLockedPets() && data.devUnlocked.contains(speciesId));
	}

	/**
	 * Whether the "select locked pets" testing option is currently enabled.
	 */
	public boolean isDevSelectEnabled()
	{
		return PetBattlesConfig.devSelectLockedPets();
	}

	/**
	 * Whether this species has been manually dev-unlocked (independent of the toggle state).
	 */
	public synchronized boolean isDevUnlocked(String speciesId)
	{
		return data.devUnlocked.contains(speciesId);
	}

	/**
	 * Manually unlock a species for testing. No-op for species already owned for real.
	 * Returns true if this added a new dev unlock.
	 */
	public synchronized boolean devUnlock(String speciesId)
	{
		if (db.species(speciesId) == null || data.ownedSpecies.contains(speciesId)
			|| !data.devUnlocked.add(speciesId))
		{
			return false;
		}
		save();
		return true;
	}

	/**
	 * Remove a manual dev unlock, also dropping the pet from the battle team.
	 */
	public synchronized boolean devLock(String speciesId)
	{
		if (!data.devUnlocked.remove(speciesId))
		{
			return false;
		}
		data.team.remove(speciesId);
		save();
		return true;
	}

	/**
	 * Give up ownership of a pet entirely: drop it from the owned set, the battle team and
	 * its progression record. Used when a possession-gated pet is traded away in-game (e.g.
	 * trading a grown cat for death runes). Returns true if the pet was owned.
	 */
	public synchronized boolean removeOwnership(String speciesId)
	{
		boolean owned = data.ownedSpecies.remove(speciesId);
		data.team.remove(speciesId);
		data.pets.remove(speciesId);
		data.devUnlocked.remove(speciesId);
		if (owned)
		{
			save();
		}
		return owned;
	}

	/**
	 * Testing aid: wipe all per-pet progression. Every pet drops back to level 1 with its
	 * starter moveset and full HP (records are recreated on demand by getOrCreatePet).
	 * Ownership, team composition and trainer wins are kept. Returns the number of pet
	 * records cleared.
	 */
	public synchronized int resetProgression()
	{
		int cleared = data.pets.size();
		log.debug("resetProgression invoked; clearing {} pet record(s), team={}", cleared, data.team);
		if (cleared > 0)
		{
			data.pets.clear();
			// Recreate team members' records now (fresh level-1) so the panel shows them
			// immediately rather than waiting for the next lazy getOrCreatePet.
			for (String speciesId : data.team)
			{
				getOrCreatePet(speciesId);
			}
			save();
		}
		return cleared;
	}

	/**
	 * Mark a species as owned (from collection log sync or a live drop). Additive only.
	 * Returns true if this is a new unlock.
	 */
	public synchronized boolean unlock(String speciesId)
	{
		if (db.species(speciesId) == null || data.ownedSpecies.contains(speciesId))
		{
			return false;
		}
		data.ownedSpecies.add(speciesId);
		save();
		return true;
	}

	/**
	 * Get the progression record for an owned species, creating it at level 1 with
	 * its starter moves equipped.
	 */
	public synchronized PetInstance getOrCreatePet(String speciesId)
	{
		PetInstance pet = data.pets.get(speciesId);
		if (pet == null)
		{
			SpeciesDef species = db.species(speciesId);
			if (species == null)
			{
				return null;
			}
			pet = new PetInstance(speciesId);
			for (String move : pet.availableMoves(species))
			{
				if (pet.getEquippedMoves().size() >= PetInstance.MAX_EQUIPPED_MOVES)
				{
					break;
				}
				pet.equipMove(move);
			}
			data.pets.put(speciesId, pet);
			save();
		}
		return pet;
	}

	public synchronized PetInstance getPet(String speciesId)
	{
		return data.pets.get(speciesId);
	}

	/**
	 * Record the active metamorphosis form for an owned pet (from read-only follower/inventory
	 * detection). No-op unless the pet is owned and the form actually changed. Returns true if it
	 * changed. Passing null reverts the pet to its base form (e.g. the player toggled back in-game).
	 */
	public synchronized boolean setActiveVariant(String speciesId, String variantId)
	{
		if (!isOwned(speciesId))
		{
			return false;
		}
		PetInstance pet = getOrCreatePet(speciesId);
		if (pet == null || Objects.equals(pet.getActiveVariantId(), variantId))
		{
			return false;
		}
		pet.setActiveVariantId(variantId);
		save();
		return true;
	}

	public synchronized List<String> getTeam()
	{
		// Copy: callers iterate outside the lock
		return new ArrayList<>(data.team);
	}

	public void setTeamEditGate(BooleanSupplier gate)
	{
		this.teamEditGate = gate;
	}

	/**
	 * Whether team composition may currently be changed (i.e. the player is at a bank).
	 */
	public boolean canEditTeam()
	{
		return teamEditGate.getAsBoolean();
	}

	public synchronized boolean addToTeam(String speciesId)
	{
		if (!canEditTeam() || data.team.contains(speciesId)
			|| data.team.size() >= MAX_TEAM_SIZE || !isOwned(speciesId))
		{
			return false;
		}
		data.team.add(speciesId);
		getOrCreatePet(speciesId);
		save();
		return true;
	}

	public synchronized boolean removeFromTeam(String speciesId)
	{
		if (!canEditTeam())
		{
			return false;
		}
		boolean removed = data.team.remove(speciesId);
		if (removed)
		{
			save();
		}
		return removed;
	}

	/**
	 * Move a team member up (-1) or down (+1) in send-out order. Not bank-gated:
	 * order stays adjustable anywhere.
	 */
	public synchronized boolean moveTeamMember(String speciesId, int delta)
	{
		int from = data.team.indexOf(speciesId);
		if (from < 0)
		{
			return false;
		}
		int to = from + delta;
		if (to < 0 || to >= data.team.size() || to == from)
		{
			return false;
		}
		Collections.swap(data.team, from, to);
		save();
		return true;
	}

	/**
	 * Drag-to-reorder: move {@code speciesId} to battle position {@code insertIndex} (0-based, among
	 * the team). Not bank-gated, like {@link #moveTeamMember}. Returns true if the order changed.
	 */
	public synchronized boolean reorderTeamToIndex(String speciesId, int insertIndex)
	{
		int from = data.team.indexOf(speciesId);
		if (from < 0)
		{
			return false;
		}
		int idx = Math.max(0, Math.min(insertIndex, data.team.size() - 1));
		if (idx == from)
		{
			return false;
		}
		data.team.remove(from);
		data.team.add(idx, speciesId);
		save();
		return true;
	}

	/**
	 * Whether this trainer has been beaten at least once (in-world first win).
	 */
	public synchronized boolean isTrainerDefeated(String trainerId)
	{
		return data.defeatedTrainers.contains(trainerId);
	}

	/**
	 * How many times this trainer has been beaten, which sets the re-fight reward taper (see
	 * {@link com.petbattles.engine.Leveling#repeatFactor(int)}). Saves written before the counter
	 * existed only know that a trainer was beaten, so one of those reads as a single win rather than
	 * handing a long-farmed trainer its first-win rate back.
	 */
	public synchronized int trainerWins(String trainerId)
	{
		Integer wins = data.trainerWins.get(trainerId);
		if (wins != null)
		{
			return wins;
		}
		return data.defeatedTrainers.contains(trainerId) ? 1 : 0;
	}

	/**
	 * Record a trainer win: flags the first defeat (which unlocks remote re-fights) and counts every
	 * win for the reward taper.
	 */
	public synchronized void recordTrainerDefeated(String trainerId)
	{
		if (db.trainer(trainerId) == null)
		{
			return;
		}
		// Count first: flagging the defeat would make trainerWins' legacy fallback read this very win
		// as a prior one, so a first clear would land on 2.
		int wins = trainerWins(trainerId);
		data.defeatedTrainers.add(trainerId);
		data.trainerWins.put(trainerId, wins + 1);
		save();
	}

	/**
	 * The step this quest has reached (0 = not started / in progress). Persistent.
	 */
	public synchronized int getQuestStep(String questId)
	{
		Integer step = data.questProgress.get(questId);
		return step == null ? 0 : step;
	}

	/**
	 * Advance a quest to at least the given step; no-op if already there or beyond.
	 * Returns true if this moved the quest forward (and persisted).
	 */
	public synchronized boolean advanceQuest(String questId, int step)
	{
		if (getQuestStep(questId) >= step)
		{
			return false;
		}
		data.questProgress.put(questId, step);
		save();
		return true;
	}

	/**
	 * Whether a one-off / branch quest flag is set. Persistent.
	 */
	public synchronized boolean hasFlag(String flag)
	{
		return data.questFlags.contains(flag);
	}

	/**
	 * Set a one-off / branch quest flag, persisting. Returns true if it wasn't already set.
	 */
	public synchronized boolean setFlag(String flag)
	{
		if (flag == null || !data.questFlags.add(flag))
		{
			return false;
		}
		save();
		return true;
	}

	/**
	 * A copy of the currently-set quest flags. Callers iterate outside the lock.
	 */
	public synchronized Set<String> getFlags()
	{
		return new LinkedHashSet<>(data.questFlags);
	}

	/**
	 * Testing aid: wipe all quest progress and flags back to not-started. This relocks anything a
	 * quest granted (e.g. remote battles / the Remote Battle Device item), so a developer can re-run
	 * the quest flow without clearing their whole roster. Returns the number of quest records cleared.
	 */
	public synchronized int resetQuests()
	{
		int cleared = data.questProgress.size();
		log.debug("resetQuests invoked; clearing {} quest record(s) and {} flag(s)",
			cleared, data.questFlags.size());
		if (cleared > 0 || !data.questFlags.isEmpty())
		{
			data.questProgress.clear();
			data.questFlags.clear();
			save();
		}
		return cleared;
	}

	/**
	 * Lifetime number of battles the player has started. Shown as a stat on the Items panel.
	 */
	public synchronized int getTotalBattles()
	{
		return data.totalBattles;
	}

	/**
	 * Count one more battle started, and persist. Called when a battle actually begins.
	 */
	public synchronized void recordBattleFought()
	{
		data.totalBattles++;
		save();
	}

	/**
	 * The player's soft-currency wallet balance: coins earned from battles and quests, spent in the
	 * store. Purely local -- never in-game GP, never real money, never reported anywhere.
	 */
	public synchronized long getCoins()
	{
		return data.coins;
	}

	/**
	 * Add coins to the wallet (a battle or quest reward), persisting. Non-positive amounts are
	 * ignored (the wallet is never drained by an "award"). Returns the new balance.
	 */
	public synchronized long addCoins(long amount)
	{
		if (amount > 0)
		{
			data.coins += amount;
			save();
		}
		return data.coins;
	}

	/**
	 * Spend coins if the wallet can cover it: deducts and persists, returning true on success.
	 * Returns false with no change if the amount is non-positive or exceeds the balance.
	 */
	public synchronized boolean spendCoins(long amount)
	{
		if (amount <= 0 || data.coins < amount)
		{
			return false;
		}
		data.coins -= amount;
		save();
		return true;
	}

	// --- Equip-item inventory (held items + cosmetics won from quests / bought in the store) ---
	//
	// The inventory is the TOTAL owned, worn or not — it is never decremented by equipping. See the
	// equipping block below for why the wear limit is enforced by counting wearers instead.

	/**
	 * A copy of the owned-equip-item counts ({@code EquipItemDef} id -> count). Callers iterate
	 * outside the lock.
	 */
	public synchronized Map<String, Integer> getItemInventory()
	{
		return new LinkedHashMap<>(data.itemInventory);
	}

	/**
	 * How many of this equip item the player owns in total, including any copies currently worn
	 * (0 if none).
	 */
	public synchronized int itemCount(String itemId)
	{
		Integer n = data.itemInventory.get(itemId);
		return n == null ? 0 : n;
	}

	/**
	 * Whether the player owns at least one of this equip item.
	 */
	public synchronized boolean hasItem(String itemId)
	{
		return itemCount(itemId) > 0;
	}

	/**
	 * Add {@code count} of an equip item to the inventory (a quest or store grant). Ignores unknown
	 * ids and non-positive counts. Returns true if anything was added.
	 */
	public synchronized boolean grantItem(String itemId, int count)
	{
		if (count <= 0 || db.equipItem(itemId) == null)
		{
			return false;
		}
		data.itemInventory.merge(itemId, count, Integer::sum);
		save();
		return true;
	}

	/**
	 * Remove {@code count} of an equip item if the player has enough (a store trade-in / consume).
	 * Returns false with no change otherwise. The key is dropped when its count reaches zero. Copies
	 * given up this way are taken off their wearers if that's the only way to stay within the new
	 * count, so the inventory and the pets can't disagree.
	 */
	public synchronized boolean takeItem(String itemId, int count)
	{
		if (count <= 0 || itemCount(itemId) < count)
		{
			return false;
		}
		int remaining = itemCount(itemId) - count;
		if (remaining > 0)
		{
			data.itemInventory.put(itemId, remaining);
		}
		else
		{
			data.itemInventory.remove(itemId);
		}
		stripExcessWearers(itemId);
		save();
		return true;
	}

	// --- Equipping (HELD / HEAD / FACE) ---
	//
	// One copy, one wearer, in every slot: an item may be worn by at most as many pets as the player
	// owns copies of it (see itemCapacity). Equipping does NOT consume — itemInventory holds the total
	// owned, and the limit is a capacity check recomputed from live state on each equip.
	//
	// Why counted rather than consumed. A decrement-on-equip / return-on-unequip pair has to be kept
	// perfectly in step by every code path forever, and when it does slip there is no way to tell
	// afterwards: two pets holding one amulet with no spares looks exactly like two amulets bought.
	// Counting wearers can always be checked, and repaired (see repairEquipCapacity). It also handles
	// the blue party hat, whose ownership is *derived* from quest progress (see ownsItem) and which
	// never enters the inventory, so there is no unit to move around.
	//
	// An item at capacity is not refused: equipping it *moves* it, taking it off the wearer that has
	// had it longest (roster insertion order). One amulet therefore behaves like one physical amulet
	// you can put on a different pet, rather than an error message.

	/**
	 * How many pets may wear this equip item at once: one per copy owned. Purchased copies come from
	 * the equip-item inventory; a derived-ownership trophy has capacity 1 with no inventory unit
	 * behind it. 0 when the player doesn't own it at all.
	 */
	public synchronized int itemCapacity(String itemId)
	{
		Item keyItem = Item.byId(itemId);
		int derived = keyItem != null && ownsItem(keyItem) ? 1 : 0;
		return Math.max(itemCount(itemId), derived);
	}

	/**
	 * The pets currently wearing this equip item in its own slot, in roster order (oldest record
	 * first). Empty for an unknown id.
	 */
	public synchronized List<String> itemWearers(String itemId)
	{
		List<String> wearers = new ArrayList<>();
		EquipItemDef item = db.equipItem(itemId);
		if (item == null)
		{
			return wearers;
		}
		for (Map.Entry<String, PetInstance> e : data.pets.entrySet())
		{
			if (itemId.equals(wornInSlot(e.getValue(), item.getSlot())))
			{
				wearers.add(e.getKey());
			}
		}
		return wearers;
	}

	/**
	 * Whether the player owns an equip item they could put on a pet: either it's in the equip-item
	 * inventory (bought or granted) or it's a key-item trophy whose ownership is derived from quest
	 * state.
	 */
	public synchronized boolean ownsEquipItem(String itemId)
	{
		if (hasItem(itemId))
		{
			return true;
		}
		Item keyItem = Item.byId(itemId);
		return keyItem != null && ownsItem(keyItem);
	}

	/**
	 * Every cosmetic the player owns, in content order — what the equip UI offers. Includes
	 * derived-ownership trophies, which never appear in the item inventory.
	 */
	public synchronized List<EquipItemDef> ownedCosmetics()
	{
		List<EquipItemDef> owned = new ArrayList<>();
		for (EquipItemDef item : db.allEquipItems())
		{
			if (item.isCosmetic() && ownsEquipItem(item.getId()))
			{
				owned.add(item);
			}
		}
		return owned;
	}

	/**
	 * Equip a HELD item on an owned pet, replacing whatever it was holding. The pet must be owned and
	 * the item must exist, be a HELD-slot item, and be owned. No-op (returns false) otherwise,
	 * including when it's already held.
	 */
	public synchronized boolean setHeldItem(String speciesId, String itemId)
	{
		EquipItemDef item = db.equipItem(itemId);
		return item != null && item.getSlot() == EquipItemDef.Slot.HELD && equip(speciesId, item);
	}

	/**
	 * Equip a cosmetic on an owned pet, into whichever slot ({@code HEAD}/{@code FACE}) the item
	 * declares — replacing whatever occupied that slot. The pet must be owned, the item must exist,
	 * be a cosmetic, and be owned. No-op (returns false) otherwise, including when it's already worn.
	 */
	public synchronized boolean setCosmetic(String speciesId, String itemId)
	{
		EquipItemDef item = db.equipItem(itemId);
		return item != null && item.isCosmetic() && equip(speciesId, item);
	}

	/**
	 * Put an item in its slot on an owned pet. Nothing is consumed, but the copy is not duplicated
	 * either: if every copy the player owns is already worn, this takes one off its longest-standing
	 * wearer rather than kitting out another pet for free. Callers wanting to tell the player who
	 * loses it should read {@link #itemWearers(String)} first.
	 */
	private boolean equip(String speciesId, EquipItemDef item)
	{
		String itemId = item.getId();
		if (!isOwned(speciesId) || !ownsEquipItem(itemId))
		{
			return false;
		}
		PetInstance pet = getOrCreatePet(speciesId);
		if (pet == null || Objects.equals(wornInSlot(pet, item.getSlot()), itemId))
		{
			return false;
		}
		// Make room for this pet: strip the oldest wearers until the copies owned can cover them all
		// plus this one. Normally that's at most one pet; a save left over-capacity by an older build
		// sheds its excess here.
		// ownsEquipItem above already implies at least one copy; the floor only keeps a future
		// ownership rule from turning a zero capacity into an empty-list index error.
		int capacity = Math.max(1, itemCapacity(itemId));
		List<String> wearers = itemWearers(itemId);
		for (int i = 0; wearers.size() - i >= capacity; i++)
		{
			applySlot(data.pets.get(wearers.get(i)), item.getSlot(), null);
		}
		applySlot(pet, item.getSlot(), itemId);
		save();
		return true;
	}

	/**
	 * Remove whatever HELD item an owned pet is carrying. Returns true if it was holding one. Nothing
	 * returns to the inventory — the copy was never taken out of it — so freeing the slot simply frees
	 * that copy for another pet.
	 */
	public synchronized boolean clearHeldItem(String speciesId)
	{
		PetInstance pet = getPet(speciesId);
		if (pet == null || pet.getHeldItemId() == null)
		{
			return false;
		}
		pet.setHeldItemId(null);
		save();
		return true;
	}

	/**
	 * Clear a pet's cosmetic slot. Returns true if it was wearing something there. As with held items,
	 * nothing returns to the inventory; the copy is simply free again.
	 */
	public synchronized boolean clearCosmetic(String speciesId, EquipItemDef.Slot slot)
	{
		PetInstance pet = getPet(speciesId);
		if (pet == null || wornInSlot(pet, slot) == null)
		{
			return false;
		}
		applySlot(pet, slot, null);
		save();
		return true;
	}

	/** What this pet wears in a given slot, or null. */
	private static String wornInSlot(PetInstance pet, EquipItemDef.Slot slot)
	{
		switch (slot)
		{
			case HEAD:
				return pet.getHeadItemId();
			case FACE:
				return pet.getFaceItemId();
			default:
				return pet.getHeldItemId();
		}
	}

	/** Write a pet's slot. */
	private static void applySlot(PetInstance pet, EquipItemDef.Slot slot, String itemId)
	{
		switch (slot)
		{
			case HEAD:
				pet.setHeadItemId(itemId);
				break;
			case FACE:
				pet.setFaceItemId(itemId);
				break;
			default:
				pet.setHeldItemId(itemId);
				break;
		}
	}

	/**
	 * Migrate a v1 roster, where the inventory held only *spares* because equipping a held item
	 * decremented it. Under the counted model the inventory is the total owned, so every held copy
	 * currently worn is credited back — for a save the old code kept in step, that reconstructs the
	 * purchase total exactly. Cosmetics were never consumed and so need no correction. Returns true if
	 * the blob was changed (callers save); does nothing on a v2 blob or a fresh roster.
	 */
	private boolean migrateWornHeldItemsIntoInventory()
	{
		if (data.v >= RosterStore.SCHEMA_VERSION)
		{
			return false;
		}
		int credited = 0;
		for (PetInstance pet : data.pets.values())
		{
			String held = pet.getHeldItemId();
			if (held != null && db.equipItem(held) != null)
			{
				data.itemInventory.merge(held, 1, Integer::sum);
				credited++;
			}
		}
		log.debug("Migrated roster v{} -> v{}: credited {} worn held item(s) back to the inventory",
			data.v, RosterStore.SCHEMA_VERSION, credited);
		data.v = RosterStore.SCHEMA_VERSION;
		return true;
	}

	/**
	 * Bring every equip item back within its capacity, stripping the longest-standing wearers of
	 * anything worn by more pets than the player owns copies of. Recomputed from state, so it is
	 * always safe to run; it is the repair half of the counted model. Returns how many slots it
	 * cleared. Does not save — callers do.
	 */
	private int repairEquipCapacity()
	{
		int stripped = 0;
		for (EquipItemDef item : db.allEquipItems())
		{
			stripped += stripExcessWearers(item.getId());
		}
		return stripped;
	}

	/** Strip wearers of one item beyond its capacity, oldest first. Returns how many were cleared. */
	private int stripExcessWearers(String itemId)
	{
		EquipItemDef item = db.equipItem(itemId);
		if (item == null)
		{
			return 0;
		}
		List<String> wearers = itemWearers(itemId);
		int excess = wearers.size() - itemCapacity(itemId);
		for (int i = 0; i < excess; i++)
		{
			applySlot(data.pets.get(wearers.get(i)), item.getSlot(), null);
		}
		return Math.max(0, excess);
	}

	/**
	 * Whether the player currently holds this reward item. Derived from the state that granted it
	 * (so an item and the thing it unlocks can't drift apart), not stored separately.
	 */
	public synchronized boolean ownsItem(Item item)
	{
		switch (item)
		{
			case REMOTE_BATTLE_DEVICE:
				return isRemoteBattlesUnlocked();
			case SEALED_ENVELOPE:
				// Wrung from Ambassador Gimblewap partway through the capstone.
			case BLUE_PARTY_HAT:
				// The Wise Old Man's parting gift for finishing the capstone.
			{
				int granted = capstoneStepAwarding(item);
				return granted >= 0 && getQuestStep(CAPSTONE_QUEST_ID) >= granted;
			}
			default:
				return false;
		}
	}

	/**
	 * The capstone step at which a key-item trophy is in the player's hands: one past the chapter whose
	 * reward names it, since a chapter's reward lands as its step moves on. Read from the quest content
	 * so re-ordering or dropping chapters can't leave a trophy stranded behind a step that no longer
	 * exists. -1 if no chapter awards this item.
	 */
	private int capstoneStepAwarding(Item item)
	{
		QuestDef quest = db.quest(CAPSTONE_QUEST_ID);
		if (quest == null)
		{
			return -1;
		}
		for (QuestDef.Chapter chapter : quest.getChapters())
		{
			QuestDef.Reward reward = chapter.getReward();
			if (reward != null && item.getId().equals(reward.getKeyItem()))
			{
				return chapter.getStep() + 1;
			}
		}
		return -1;
	}

	/**
	 * Whether the player owns the Remote Battle Device: either the dev "remote battles" toggle, or
	 * they have finished "Where's the remote?" (Professor Oddenstein's device). Owning the device does
	 * not by itself let you fight everyone remotely -- it must be calibrated against a trainer by
	 * beating them in person first (see {@link #canRemoteFight(String)}).
	 */
	public synchronized boolean isRemoteBattlesUnlocked()
	{
		if (PetBattlesConfig.devRemoteBattles())
		{
			return true;
		}
		QuestDef q = db.quest(REMOTE_QUEST_ID);
		return q != null && getQuestStep(REMOTE_QUEST_ID) >= q.completeStep();
	}

	/**
	 * Whether this trainer can be re-fought remotely: the device is owned and the trainer has already
	 * been beaten in person (the device only reaches trainers it has "calibrated" against). A first
	 * fight always has to happen in the world, next to the trainer.
	 */
	public synchronized boolean canRemoteFight(String trainerId)
	{
		return isRemoteBattlesUnlocked() && isTrainerDefeated(trainerId);
	}

	/**
	 * Rest every pet back to full HP (bank heal). Bank-gated like team composition.
	 * Returns false if not at a bank or nothing needed healing.
	 */
	public synchronized boolean restAllPets()
	{
		if (!canEditTeam() || !anyPetInjured())
		{
			return false;
		}
		for (PetInstance pet : data.pets.values())
		{
			pet.rest();
		}
		save();
		return true;
	}

	/**
	 * Whether any pet carries battle damage (or is fainted) and would benefit from a rest.
	 */
	public synchronized boolean anyPetInjured()
	{
		for (PetInstance pet : data.pets.values())
		{
			if (pet.getCurrentHp() != null)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether at least one team member is able to fight (not fainted).
	 */
	public synchronized boolean teamCanFight()
	{
		for (String speciesId : data.team)
		{
			PetInstance pet = data.pets.get(speciesId);
			if (pet == null || !pet.isFainted())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Persist after external mutation of a PetInstance (xp gain, move equip, egg unlock).
	 */
	public synchronized void petChanged()
	{
		save();
	}
}

package com.petbattles.persist;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.petbattles.PetBattlesConfig;
import com.petbattles.engine.PetInstance;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Persists the roster as one versioned JSON blob under RSProfile-scoped config,
 * so state is keyed to the logged-in RS account and rides RuneLite's config sync.
 */
@Slf4j
public class RosterStore
{
	private static final String KEY = "roster";
	/**
	 * v1: itemInventory held *spares* — equipping a held item decremented it. v2: it holds the total
	 * owned and equipping consumes nothing, the wear limit being a capacity check over wearers
	 * instead. {@link RosterManager#load()} migrates v1 blobs by crediting worn copies back.
	 */
	public static final int SCHEMA_VERSION = 2;

	/**
	 * The serialized shape. Add fields with defaults; bump v only on breaking changes.
	 */
	public static class RosterData
	{
		public int v = SCHEMA_VERSION;
		public Set<String> ownedSpecies = new LinkedHashSet<>();
		// Pets manually unlocked for testing via the "Dev: select locked pets" option.
		// Kept apart from ownedSpecies so it never masquerades as a real collection-log unlock.
		public Set<String> devUnlocked = new LinkedHashSet<>();
		public Map<String, PetInstance> pets = new LinkedHashMap<>();
		public List<String> team = new ArrayList<>();
		// Trainers beaten at least once (unlocks remote re-fights)
		public Set<String> defeatedTrainers = new LinkedHashSet<>();
		// How many times each trainer has been beaten, for the re-fight reward taper
		// (Leveling.repeatFactor). Absent for a trainer in defeatedTrainers means a pre-taper save,
		// which RosterManager.trainerWins reads as a single win.
		public Map<String, Integer> trainerWins = new LinkedHashMap<>();
		// Step reached per quest id (see com.petbattles.quest.Quest); absent = step 0 (not started).
		public Map<String, Integer> questProgress = new LinkedHashMap<>();
		// One-off / branch quest flags (e.g. a data-quest chapter's marker); see QuestManager.
		public Set<String> questFlags = new LinkedHashSet<>();
		// Highest RosterManager.PROGRESSION_RESET_VERSION already applied to this roster.
		// When the code constant exceeds this, load() wipes progression once and bumps it.
		public int progressionResetVersion = 0;
		// Lifetime count of battles started, shown as a stat on the Items panel.
		public int totalBattles = 0;
		// Soft-currency wallet: coins earned from battles/quests, spent in the store. Purely local
		// -- never in-game GP, never real money, never sent anywhere.
		public long coins = 0;
		// Owned equip items (EquipItemDef id -> count): held items and cosmetics won from quests or
		// bought in the store. A pet's equipped item references an id it owns here.
		public Map<String, Integer> itemInventory = new LinkedHashMap<>();
	}

	private final ConfigManager configManager;
	private final Gson gson;

	public RosterStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/**
	 * Load the blob for the current RS profile; empty data if absent or unreadable.
	 */
	public RosterData load()
	{
		String json = configManager.getRSProfileConfiguration(PetBattlesConfig.GROUP, KEY);
		if (json == null || json.isEmpty())
		{
			return new RosterData();
		}
		try
		{
			RosterData data = gson.fromJson(json, RosterData.class);
			return data == null ? new RosterData() : data;
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Corrupt pet-battles roster blob; starting fresh", e);
			return new RosterData();
		}
	}

	public void save(RosterData data)
	{
		configManager.setRSProfileConfiguration(PetBattlesConfig.GROUP, KEY, gson.toJson(data));
	}
}

package com.petbattles.quest;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The data vocabulary for a RuneScape-style conversation loaded from quests.json: an ordered list of
 * {@link Node nodes}, each either a spoken <b>line</b> or a player <b>choice</b>. A chapter's
 * {@code intro} and {@code rewardConversation} are {@code List<Conversation.Node>}; the runtime
 * cursor that pages through them is {@link ConversationState}.
 *
 * <p>Only the vocabulary lives here (plain Gson-populated fields). Branching is one level deep: a
 * choice option's {@code lines} are spoken lines, not further choices.
 */
public final class Conversation
{
	private Conversation()
	{
	}

	/** One beat of a conversation: a spoken line, or a choice menu ({@link #getChoice()} set). */
	public static class Node
	{
		// A line: who is speaking (a trainer id for their chathead, "player" for the player's, or
		// null for narration) and what they say.
		private String speaker;
		private String text;
		// A choice: the options the player may pick. When non-empty this node is a choice, not a line.
		private List<Option> choice;

		public Node()
		{
		}

		public Node(String speaker, String text)
		{
			this.speaker = speaker;
			this.text = text;
		}

		public String getSpeaker()
		{
			return speaker;
		}

		public String getText()
		{
			return text;
		}

		public List<Option> getChoice()
		{
			return choice == null ? Collections.emptyList() : choice;
		}

		/** Whether this node presents a choice menu (vs. a single spoken line). */
		public boolean isChoice()
		{
			return choice != null && !choice.isEmpty();
		}
	}

	/**
	 * One option in a choice menu: the button {@code label} the player picks, the {@code lines} that
	 * play in response, and whether picking it {@code exit}s the menu (vs. returning to it so the
	 * player can ask another question).
	 */
	public static class Option
	{
		private String label;
		private List<Node> lines = new ArrayList<>();
		private boolean exit;

		public Option()
		{
		}

		public Option(String label, List<Node> lines, boolean exit)
		{
			this.label = label;
			this.lines = lines;
			this.exit = exit;
		}

		public String getLabel()
		{
			return label;
		}

		/** The lines spoken in response to picking this option (may be empty). */
		public List<Node> getLines()
		{
			return lines == null ? Collections.emptyList() : lines;
		}

		/** Whether picking this option leaves the choice (true) or returns to the menu (false). */
		public boolean isExit()
		{
			return exit;
		}
	}
}

package com.petbattles.quest;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A runtime cursor that pages through a {@link Conversation} of {@link Conversation.Node nodes}.
 * Pure logic (no UI), so both render surfaces — the Quests-pane Story view and the battle
 * end-screen — drive the same state machine, and it is unit-testable.
 *
 * <p>Flow: a line is shown until {@link #advance()} (click-to-continue); a choice presents its
 * option labels until {@link #pick(int)}. Picking an option plays its lines, then either returns to
 * the choice menu (so the player can ask another question) or, if the option is an
 * {@link Conversation.Option#isExit() exit}, proceeds past the choice. The conversation is
 * {@link #isDone() done} once the cursor runs off the end.
 */
public final class ConversationState
{
	/** What the current cursor position asks the UI to render. */
	public enum Kind
	{
		LINE,
		CHOICE
	}

	/** A snapshot of the current beat: either a spoken line or a choice menu. */
	public static final class Frame
	{
		private final Kind kind;
		private final String speaker;
		private final String text;
		private final List<String> options;

		private Frame(Kind kind, String speaker, String text, List<String> options)
		{
			this.kind = kind;
			this.speaker = speaker;
			this.text = text;
			this.options = options;
		}

		public Kind getKind()
		{
			return kind;
		}

		/** LINE only: the speaker id ("player"/trainer id/null for narration). */
		public String getSpeaker()
		{
			return speaker;
		}

		/** LINE only: the spoken text. */
		public String getText()
		{
			return text;
		}

		/** CHOICE only: the option labels, in order (indices match {@link ConversationState#pick}). */
		public List<String> getOptions()
		{
			return options == null ? Collections.emptyList() : options;
		}
	}

	private final List<Conversation.Node> nodes;
	private int index;
	// The lines of the option the player just picked (null when not in a branch), the position within
	// them, whether finishing them exits the choice, and the choice node to return to.
	private List<Conversation.Node> branch;
	private int branchIndex;
	private boolean branchExits;
	private int choiceIndex;

	public ConversationState(List<Conversation.Node> nodes)
	{
		this.nodes = nodes == null ? Collections.emptyList() : nodes;
	}

	/** The current beat to render, or null when the conversation is finished. */
	public Frame current()
	{
		if (branch != null && branchIndex < branch.size())
		{
			Conversation.Node n = branch.get(branchIndex);
			return line(n);
		}
		if (index >= nodes.size())
		{
			return null;
		}
		Conversation.Node n = nodes.get(index);
		if (n.isChoice())
		{
			List<String> labels = new ArrayList<>();
			for (Conversation.Option opt : n.getChoice())
			{
				labels.add(opt.getLabel());
			}
			return new Frame(Kind.CHOICE, null, null, labels);
		}
		return line(n);
	}

	private Frame line(Conversation.Node n)
	{
		return new Frame(Kind.LINE, n.getSpeaker(), n.getText(), null);
	}

	public boolean isDone()
	{
		return current() == null;
	}

	/**
	 * Click-to-continue on a line. In a branch, steps to the next branch line and, when the branch is
	 * spent, either leaves the choice (exit option) or returns to its menu. On a main line, steps to
	 * the next node. No-op while a choice menu is showing (the UI calls {@link #pick(int)} there).
	 */
	public void advance()
	{
		if (branch != null)
		{
			branchIndex++;
			if (branchIndex >= branch.size())
			{
				boolean exit = branchExits;
				branch = null;
				branchIndex = 0;
				if (exit)
				{
					index = choiceIndex + 1;
				}
				// else: index stays on the choice node, so its menu shows again.
			}
			return;
		}
		if (index < nodes.size() && !nodes.get(index).isChoice())
		{
			index++;
		}
	}

	/**
	 * Pick option {@code i} of the current choice menu: play its lines (if any), then return to the
	 * menu unless it is an exit option. No-op unless a choice is currently showing and {@code i} is
	 * in range.
	 */
	public void pick(int i)
	{
		if (branch != null || index >= nodes.size())
		{
			return;
		}
		Conversation.Node node = nodes.get(index);
		if (!node.isChoice() || i < 0 || i >= node.getChoice().size())
		{
			return;
		}
		Conversation.Option opt = node.getChoice().get(i);
		choiceIndex = index;
		branchExits = opt.isExit();
		List<Conversation.Node> lines = opt.getLines();
		if (lines.isEmpty())
		{
			// Nothing to say: an exit option leaves the choice immediately; otherwise no-op.
			if (opt.isExit())
			{
				index = choiceIndex + 1;
			}
			return;
		}
		branch = lines;
		branchIndex = 0;
	}
}

package com.petbattles.quest;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A data-described, multi-chapter quest loaded from quests.json. A {@code QuestDef} is a sequence of
 * {@link Chapter chapters}, each a proximity-gated conversation: the player reaches the chapter's NPC
 * (or it plays immediately), works through its {@link Chapter#getIntro() intro} conversation, and
 * then either advances (a talk chapter) or is offered a battle whose victory advances the story and
 * hands over the reward (a battle or hunt chapter).
 *
 * <p>Progress is a per-quest int step
 * ({@link com.petbattles.persist.RosterStore.RosterData#questProgress}) = the index of the current
 * chapter, so the quest is complete once the step reaches {@link #getChapters()} size. Only the
 * mechanic is coded ({@link QuestManager}); the dialogue and rewards are data.
 */
public class QuestDef
{
	/**
	 * A reward granted when its chapter is cleared: any combination of an equip item, coins, and a
	 * one-off {@link com.petbattles.persist.RosterManager#setFlag(String) quest flag}. All optional.
	 */
	public static class Reward
	{
		private String item;
		private String keyItem;
		private long coins;
		private String flag;

		public Reward()
		{
		}

		/** Equip-item id to grant (one copy) via the inventory, or null for none. */
		public String getItem()
		{
			return item;
		}

		/**
		 * Key-item ({@link com.petbattles.item.Item}) id this chapter awards, or null. Unlike
		 * {@link #getItem()} these are trophies whose ownership is derived from quest progress (see
		 * {@link com.petbattles.persist.RosterManager#ownsItem}), so this is only used to name the
		 * reward in the announcement — nothing is granted into the inventory.
		 */
		public String getKeyItem()
		{
			return keyItem;
		}

		/** Coins to add to the wallet on top of the normal battle reward (0 = none). */
		public long getCoins()
		{
			return coins;
		}

		/** Quest flag to set, or null for none. */
		public String getFlag()
		{
			return flag;
		}
	}

	/**
	 * One hunt suspect's own dialogue, so the greybeards don't all speak with one voice. The
	 * {@code accuse} conversation plays when you confront them in person, before their Challenge
	 * appears; {@code concede} plays on a win that leaves the hunt unfinished (and points at another
	 * suspect); {@code finale} plays on the win that completes it, whoever happens to be last — so
	 * every suspect needs a finale that hands the story on to the next chapter.
	 */
	public static class Suspect
	{
		private String trainer;
		private List<Conversation.Node> accuse = new ArrayList<>();
		private List<Conversation.Node> concede = new ArrayList<>();
		private List<Conversation.Node> finale = new ArrayList<>();

		public Suspect()
		{
		}

		/** Trainer id this dialogue belongs to; matches an entry in the chapter's battle pool. */
		public String getTrainer()
		{
			return trainer;
		}

		/** Played in the Story view when you confront this suspect in person (may be empty). */
		public List<Conversation.Node> getAccuse()
		{
			return accuse == null ? Collections.emptyList() : accuse;
		}

		/** Played after beating them while the hunt is still unfinished (may be empty). */
		public List<Conversation.Node> getConcede()
		{
			return concede == null ? Collections.emptyList() : concede;
		}

		/** Played after beating them when that win completes the hunt (may be empty). */
		public List<Conversation.Node> getFinale()
		{
			return finale == null ? Collections.emptyList() : finale;
		}
	}

	/**
	 * One story beat: a proximity-gated conversation plus what clears it. A <b>talk</b> chapter
	 * (no battle/hunt) is cleared by finishing its {@link #getIntro() intro}; a <b>battle</b> chapter
	 * offers a fight against {@link #getBattleTrainer()} after the intro, then plays its
	 * {@link #getRewardConversation() reward conversation}; a <b>hunt</b> chapter needs several wins
	 * from {@link #getBattlePool()}.
	 */
	public static class Chapter
	{
		private int step;
		private String title;
		// The conversation played in the Story view once the chapter is reachable (see QuestManager /
		// ConversationState). Each node is a spoken line or a player choice.
		private List<Conversation.Node> intro = new ArrayList<>();
		// The indirect objective shown until the chapter's NPC is reached (e.g. "Ask around
		// Lumbridge."); the theme is to point, not name the destination.
		private String objective;
		// Trainer id the player must stand near to start a talk chapter's conversation; null = the
		// conversation plays immediately (pure narration).
		private String nearTrainer;
		// Trainer id to fight for a battle chapter (also the NPC to stand near); null otherwise.
		private String battleTrainer;
		// A hunt chapter: beat at least battlesRequired distinct members of this trainer-id pool.
		private List<String> battlePool = new ArrayList<>();
		private int battlesRequired;
		// Optional per-suspect dialogue for a hunt chapter (see Suspect). A pool member with no entry
		// here falls back to a generated concede line and the chapter's reward conversation.
		private List<Suspect> suspects = new ArrayList<>();
		// The conversation played on the battle end screen after the win (the NPC's payoff + hand-over).
		private List<Conversation.Node> rewardConversation = new ArrayList<>();
		private Reward reward;

		public Chapter()
		{
		}

		/** Index of this chapter; matches the quest's stored step while it is the current chapter. */
		public int getStep()
		{
			return step;
		}

		public String getTitle()
		{
			return title;
		}

		/** The Story-view conversation for this chapter (may be empty). */
		public List<Conversation.Node> getIntro()
		{
			return intro == null ? Collections.emptyList() : intro;
		}

		/** The indirect objective shown until the chapter's NPC is reached, or null. */
		public String getObjective()
		{
			return objective;
		}

		/** Trainer id to stand near to start a talk chapter, or null (plays immediately). */
		public String getNearTrainer()
		{
			return nearTrainer;
		}

		/** Trainer id to fight, or null for a talk chapter. */
		public String getBattleTrainer()
		{
			return battleTrainer;
		}

		/** The pool of trainer ids for a hunt chapter (empty if not a hunt). */
		public List<String> getBattlePool()
		{
			return battlePool == null ? Collections.emptyList() : battlePool;
		}

		/** How many distinct pool members must be beaten to clear a hunt chapter. */
		public int getBattlesRequired()
		{
			return battlesRequired;
		}

		/** Per-suspect dialogue for a hunt chapter (empty if none is authored). */
		public List<Suspect> getSuspects()
		{
			return suspects == null ? Collections.emptyList() : suspects;
		}

		/** The authored dialogue for one hunt suspect, or null if that trainer has none. */
		public Suspect getSuspect(String trainerId)
		{
			for (Suspect s : getSuspects())
			{
				if (s.getTrainer() != null && s.getTrainer().equals(trainerId))
				{
					return s;
				}
			}
			return null;
		}

		/** Whether this chapter is cleared by winning a single named battle. */
		public boolean isBattle()
		{
			return battleTrainer != null && !battleTrainer.isEmpty();
		}

		/** Whether this chapter is cleared by beating several trainers from a pool. */
		public boolean isHunt()
		{
			return !getBattlePool().isEmpty() && battlesRequired > 0;
		}

		/**
		 * The NPC whose proximity gates reaching this chapter's conversation (its battle trainer, or
		 * a talk chapter's {@code nearTrainer}), or null if it plays immediately.
		 */
		public String getGateTrainer()
		{
			if (isBattle())
			{
				return battleTrainer;
			}
			return nearTrainer != null && !nearTrainer.isEmpty() ? nearTrainer : null;
		}

		/** The end-screen conversation played after the story win (may be empty). */
		public List<Conversation.Node> getRewardConversation()
		{
			return rewardConversation == null ? Collections.emptyList() : rewardConversation;
		}

		/** The reward for clearing this chapter, or null for none. */
		public Reward getReward()
		{
			return reward;
		}
	}

	private String id;
	private String title;
	// Optional quest id that must be complete before this quest becomes available.
	private String requires;
	private List<Chapter> chapters = new ArrayList<>();

	public String getId()
	{
		return id;
	}

	public String getTitle()
	{
		return title;
	}

	/** Quest id that must be complete before this quest is available, or null for always available. */
	public String getRequires()
	{
		return requires;
	}

	public List<Chapter> getChapters()
	{
		return chapters == null ? Collections.emptyList() : chapters;
	}

	/** The step at (or beyond) which this quest is complete: past its last chapter. */
	public int completeStep()
	{
		return getChapters().size();
	}
}

package com.petbattles.quest;

import com.petbattles.data.PetDatabase;
import com.petbattles.engine.TrainerDef;
import com.petbattles.persist.RosterManager;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;

/**
 * The single owner of the player's live quest conversation, and the thing that decides what the quest
 * dialog frame shows at any moment. Quest talking is one surface now: the hub's Quests pane is a log
 * (chapter title + objective), while every spoken line, reply and Challenge comes from here.
 *
 * <p>Two things can occupy the frame. A conversation the player <b>earned</b> — a chapter's reward
 * payoff, handed in by {@link #play(List)} by the battle that cleared it — outranks everything and
 * plays expanded, so the post-battle scene reads exactly like every other quest scene. It waits for
 * the battle window to close first, so the NPC never talks over the level-up summary. Otherwise
 * each render resolves the one <b>beat</b> the world currently offers — the reachable chapter's
 * intro, a hunt suspect's accusation, or the Challenge left behind once a conversation is spent — and
 * turns it into a {@link Scene}. A beat the player hasn't clicked into renders as a compact
 * {@link Kind#PROMPT prompt} ("Talk to Hans"); {@link #open()} expands it into the full dialog, and
 * {@link #dismiss()} folds it back. A new beat always starts collapsed, so nothing ever expands into
 * the player's screen unasked.
 *
 * <p>Cursors are kept per beat key ({@code questId#step} for a chapter intro, {@code questId|trainer}
 * for an accusation) so stepping between them can't rewind either, and {@code latchKey} keeps an
 * open conversation on screen when a patrolling NPC wanders off mid-sentence — the latch ends with
 * the conversation, so the Challenge that follows still needs them genuinely in reach.
 *
 * <p>Pure logic over {@link PetDatabase} / {@link RosterManager} / {@link QuestManager} (all
 * synchronised), and unit-testable without any UI.
 */
public class QuestDialogSession
{
	/** Expand the prompt into the full dialog. */
	public static final String ACTION_OPEN = "questdialog.open";
	/** Fold the dialog back to its prompt. */
	public static final String ACTION_DISMISS = "questdialog.dismiss";
	/** Click-to-continue on a spoken line. */
	public static final String ACTION_CONTINUE = "questdialog.continue";
	/** Pick reply N of a choice; the index is appended. */
	public static final String ACTION_PICK = "questdialog.pick:";
	/** Finish a talk chapter whose conversation is already spent. */
	public static final String ACTION_DONE = "questdialog.done";
	/** Start a battle; the trainer id is appended (shared with the hub's own fight buttons). */
	public static final String ACTION_FIGHT = "fight:";

	/** What the dialog frame is currently being asked to draw. */
	public enum Kind
	{
		/** The collapsed pill: a chathead and "Talk to X" / "Challenge X". */
		PROMPT,
		/** A spoken line with a Continue. */
		LINE,
		/** A reply menu. */
		CHOICE,
		/** The conversation is spent: a Challenge (or a Continue that clears a talk chapter). */
		ACTION
	}

	/** One button in a scene: what it reads, what it dispatches, and whether it can be pressed. */
	public static final class Choice
	{
		private final String label;
		private final String action;
		private final boolean enabled;

		Choice(String label, String action, boolean enabled)
		{
			this.label = label;
			this.action = action;
			this.enabled = enabled;
		}

		public String getLabel()
		{
			return label;
		}

		public String getAction()
		{
			return action;
		}

		public boolean isEnabled()
		{
			return enabled;
		}
	}

	/** A snapshot of the dialog frame's contents; the renderer needs nothing else. */
	public static final class Scene
	{
		private final Kind kind;
		private final String title;
		private final String speaker;
		private final String speakerName;
		private final String text;
		private final List<Choice> choices;
		private final String hint;

		Scene(Kind kind, String title, String speaker, String speakerName, String text,
			List<Choice> choices, String hint)
		{
			this.kind = kind;
			this.title = title;
			this.speaker = speaker;
			this.speakerName = speakerName;
			this.text = text;
			this.choices = choices;
			this.hint = hint;
		}

		public Kind getKind()
		{
			return kind;
		}

		/** The chapter title, shown as the prompt's second line. */
		public String getTitle()
		{
			return title;
		}

		/** The chathead to draw: a trainer id, "player", or null for narration. */
		public String getSpeaker()
		{
			return speaker;
		}

		/** The speaker's display name ("You" for the player, "" for narration). */
		public String getSpeakerName()
		{
			return speakerName;
		}

		/** The body text (a spoken line, the prompt's label, or the Challenge's question). */
		public String getText()
		{
			return text;
		}

		/** The buttons, in order. */
		public List<Choice> getChoices()
		{
			return choices == null ? Collections.emptyList() : choices;
		}

		/** A muted warning drawn above the buttons (e.g. a knocked-out team), or null. */
		public String getHint()
		{
			return hint;
		}
	}

	/** The one thing the world currently offers the player, resolved fresh from quest state. */
	private static final class Beat
	{
		private String key;
		private String questId;
		private QuestDef.Chapter chapter;
		// The NPC this beat is with (the gate trainer or the suspect being confronted); null for
		// pure narration.
		private String trainerId;
		// The live conversation cursor, or null once it is spent.
		private ConversationState cursor;
		// Conversation spent, and a battle against trainerId is what clears the chapter.
		private boolean challenge;
	}

	private final PetDatabase db;
	private final RosterManager roster;
	private final QuestManager questManager;
	private final Supplier<Set<String>> nearTrainers;
	private final BooleanSupplier battleActive;

	// One cursor per beat key, kept for the login session so a spent conversation stays spent.
	private final Map<String, ConversationState> cursors = new HashMap<>();
	// The beat whose conversation is mid-flight (kept on screen even if its NPC walks away), or null.
	private String latchKey;
	// The beat the player has clicked into; anything else renders as a collapsed prompt.
	private String expandedKey;
	// A conversation handed in from outside (a battle's reward payoff): it outranks anything the world
	// is offering and plays expanded, because the player earned it rather than walked into it.
	private ConversationState playback;

	public QuestDialogSession(PetDatabase db, RosterManager roster, QuestManager questManager,
		Supplier<Set<String>> nearTrainers, BooleanSupplier battleActive)
	{
		this.db = db;
		this.roster = roster;
		this.questManager = questManager;
		this.nearTrainers = nearTrainers;
		this.battleActive = battleActive;
	}

	/**
	 * Play a conversation the player has just earned — a quest chapter's reward payoff, handed over by
	 * the battle that cleared it. It waits for the battle window to close, then takes over the frame
	 * until it is spent, after which the frame goes back to whatever the world is offering. Empty
	 * conversations are ignored.
	 */
	public synchronized void play(List<Conversation.Node> nodes)
	{
		playback = nodes == null || nodes.isEmpty() ? null : new ConversationState(nodes);
	}

	/** What the dialog frame should draw right now, or null when the player has nothing waiting. */
	public synchronized Scene current()
	{
		ConversationState.Frame earned = playbackFrame();
		if (earned != null)
		{
			return sceneOf(earned, speakerName(earned.getSpeaker()), null);
		}
		Beat beat = resolve();
		if (beat == null)
		{
			expandedKey = null;
			return null;
		}
		if (!beat.key.equals(expandedKey))
		{
			return promptScene(beat);
		}
		if (beat.cursor != null)
		{
			return frameScene(beat);
		}
		return actionScene(beat);
	}

	/** Expand the current prompt into the full dialog. */
	public synchronized void open()
	{
		Beat beat = resolve();
		if (beat != null)
		{
			expandedKey = beat.key;
		}
	}

	/** Fold the dialog back to its prompt. */
	public synchronized void dismiss()
	{
		expandedKey = null;
	}

	/** Click-to-continue on the open line; clears a talk chapter when the conversation runs out. */
	public synchronized void advance()
	{
		if (playbackFrame() != null)
		{
			playback.advance();
			return;
		}
		Beat beat = resolve();
		if (beat == null || beat.cursor == null)
		{
			return;
		}
		beat.cursor.advance();
		completeTalkIfSpent(beat);
	}

	/** Pick a reply in the open conversation; clears a talk chapter if that ends it. */
	public synchronized void pick(int option)
	{
		if (playbackFrame() != null)
		{
			playback.pick(option);
			return;
		}
		Beat beat = resolve();
		if (beat == null || beat.cursor == null)
		{
			return;
		}
		beat.cursor.pick(option);
		completeTalkIfSpent(beat);
	}

	/**
	 * Finish a talk chapter whose conversation was already spent when the player reopened it (the
	 * dialog's fallback Continue). Battle and hunt chapters are cleared by winning, not by this.
	 */
	public synchronized void completeTalk()
	{
		Beat beat = resolve();
		if (beat != null && beat.cursor == null && !beat.challenge)
		{
			questManager.completeTalk(beat.questId);
		}
	}

	/** One beat of a conversation as a scene: a spoken line with a Continue, or a reply menu. */
	private static Scene sceneOf(ConversationState.Frame frame, String speakerName, String title)
	{
		if (frame.getKind() == ConversationState.Kind.CHOICE)
		{
			List<Choice> choices = new ArrayList<>();
			List<String> options = frame.getOptions();
			for (int i = 0; i < options.size(); i++)
			{
				choices.add(new Choice(options.get(i), ACTION_PICK + i, true));
			}
			return new Scene(Kind.CHOICE, title, null, "", null, choices, null);
		}
		return new Scene(Kind.LINE, title, frame.getSpeaker(), speakerName, frame.getText(),
			Collections.singletonList(new Choice("Continue", ACTION_CONTINUE, true)), null);
	}

	/** Drop every cursor and collapse the frame (called on logout — progress itself is persisted). */
	public synchronized void reset()
	{
		cursors.clear();
		latchKey = null;
		expandedKey = null;
		playback = null;
	}

	/** The earned conversation's current beat, dropping it once it is spent. */
	private ConversationState.Frame playbackFrame()
	{
		// Held until the battle window is gone entirely: the player watches the fight out, answers any
		// forget-a-move prompts and reads their level-ups on the summary before the NPC says a word.
		if (playback == null || battleActive.getAsBoolean())
		{
			return null;
		}
		ConversationState.Frame frame = playback.current();
		if (frame == null)
		{
			playback = null;
		}
		return frame;
	}

	/**
	 * The one beat the world offers: the first available quest whose current chapter is reachable —
	 * its intro still running, or spent and leaving a Challenge / a hunt suspect to confront. Null
	 * when nothing is in reach.
	 */
	private Beat resolve()
	{
		// The battle overlay owns the screen while a fight is running; only an earned conversation
		// (the payoff waiting on its end screen) shows through.
		if (!roster.isLoaded() || battleActive.getAsBoolean())
		{
			return null;
		}
		Set<String> near = nearTrainers.get();
		for (QuestDef quest : db.allQuests())
		{
			if (!questManager.isAvailable(quest))
			{
				continue;
			}
			QuestDef.Chapter chapter = questManager.currentChapter(quest.getId());
			if (chapter == null)
			{
				continue;
			}
			String gate = chapter.getGateTrainer();
			String key = quest.getId() + "#" + chapter.getStep();
			if (gate != null && !near.contains(gate) && !key.equals(latchKey))
			{
				continue;
			}
			ConversationState cursor = cursor(key, chapter.getIntro());
			if (cursor.current() != null)
			{
				latchKey = key;
				return beat(key, quest.getId(), chapter, gate, cursor, false);
			}
			// Conversation spent: the latch ends here, so a Challenge still needs the NPC in reach —
			// a walked-away trainer can't be fought from across Gielinor.
			releaseLatch(key);
			if (gate != null && !near.contains(gate))
			{
				continue;
			}
			if (chapter.isHunt())
			{
				Beat hunt = huntBeat(quest, chapter, near);
				if (hunt != null)
				{
					return hunt;
				}
				continue;
			}
			return beat(key, quest.getId(), chapter, chapter.isBattle() ? chapter.getBattleTrainer() : gate,
				null, chapter.isBattle());
		}
		return null;
	}

	/**
	 * The hunt's beat: the first unbeaten suspect standing in front of the player, either mid-
	 * accusation or offering their Challenge. Suspects elsewhere in the world are the log's business.
	 */
	private Beat huntBeat(QuestDef quest, QuestDef.Chapter chapter, Set<String> near)
	{
		for (String memberId : chapter.getBattlePool())
		{
			if (questManager.isHuntMemberBeaten(quest, memberId))
			{
				continue;
			}
			String key = quest.getId() + "|" + memberId;
			if (!near.contains(memberId) && !key.equals(latchKey))
			{
				continue;
			}
			QuestDef.Suspect suspect = chapter.getSuspect(memberId);
			if (suspect != null && !suspect.getAccuse().isEmpty())
			{
				ConversationState cursor = cursor(key, suspect.getAccuse());
				if (cursor.current() != null)
				{
					latchKey = key;
					return beat(key, quest.getId(), chapter, memberId, cursor, false);
				}
				releaseLatch(key);
				if (!near.contains(memberId))
				{
					continue;
				}
			}
			return beat(key, quest.getId(), chapter, memberId, null, true);
		}
		return null;
	}

	private Beat beat(String key, String questId, QuestDef.Chapter chapter, String trainerId,
		ConversationState cursor, boolean challenge)
	{
		Beat beat = new Beat();
		beat.key = key;
		beat.questId = questId;
		beat.chapter = chapter;
		beat.trainerId = trainerId;
		beat.cursor = cursor;
		beat.challenge = challenge;
		return beat;
	}

	private ConversationState cursor(String key, List<Conversation.Node> nodes)
	{
		return cursors.computeIfAbsent(key, k -> new ConversationState(nodes));
	}

	private void releaseLatch(String key)
	{
		if (key.equals(latchKey))
		{
			latchKey = null;
		}
	}

	/** A talk chapter (neither battle nor hunt) clears the moment its conversation runs out. */
	private void completeTalkIfSpent(Beat beat)
	{
		if (beat.cursor.isDone() && !beat.chapter.isBattle() && !beat.chapter.isHunt())
		{
			questManager.completeTalk(beat.questId);
		}
	}

	/** The collapsed pill: whoever is waiting, and what opening the dialog would do. */
	private Scene promptScene(Beat beat)
	{
		String name = trainerName(beat.trainerId);
		String label;
		if (beat.cursor != null)
		{
			label = name.isEmpty() ? "Continue the story" : "Talk to " + name;
		}
		else if (beat.challenge)
		{
			label = "Challenge " + name;
		}
		else
		{
			label = "Continue the story";
		}
		return new Scene(Kind.PROMPT, beat.chapter.getTitle(), beat.trainerId, name, label,
			Collections.singletonList(new Choice(label, ACTION_OPEN, true)), null);
	}

	/** The open world beat's conversation, tagged with its chapter title for the prompt pill. */
	private Scene frameScene(Beat beat)
	{
		ConversationState.Frame frame = beat.cursor.current();
		return sceneOf(frame, speakerName(frame.getSpeaker()), beat.chapter.getTitle());
	}

	/** The conversation is spent: the Challenge it led to, or the Continue that clears a talk chapter. */
	private Scene actionScene(Beat beat)
	{
		if (!beat.challenge)
		{
			return new Scene(Kind.ACTION, beat.chapter.getTitle(), beat.trainerId,
				trainerName(beat.trainerId), "There's nothing more to say here.",
				Collections.singletonList(new Choice("Continue", ACTION_DONE, true)), null);
		}
		String name = trainerName(beat.trainerId);
		boolean ready = !roster.getTeam().isEmpty() && roster.teamCanFight();
		String hint = ready ? null
			: roster.getTeam().isEmpty() ? "Add a pet to your team first"
			: "Team knocked out - rest at a bank";
		return new Scene(Kind.ACTION, beat.chapter.getTitle(), beat.trainerId, name,
			"Send out your pets and settle this.",
			Collections.singletonList(new Choice("Challenge " + name, ACTION_FIGHT + beat.trainerId, ready)),
			hint);
	}

	/** Display name for a conversation speaker id: "You" for the player, else the trainer's name. */
	private String speakerName(String speaker)
	{
		return "player".equals(speaker) ? "You" : trainerName(speaker);
	}

	private String trainerName(String trainerId)
	{
		if (trainerId == null)
		{
			return "";
		}
		TrainerDef trainer = db.trainer(trainerId);
		return trainer != null ? trainer.getName() : trainerId;
	}
}

package com.petbattles.quest;

import com.petbattles.data.PetDatabase;
import com.petbattles.item.EquipItemDef;
import com.petbattles.item.Item;
import com.petbattles.persist.RosterManager;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

/**
 * The data-described quest hook: it drives the {@link QuestDef data quests} loaded from quests.json,
 * where every chapter is a proximity-gated conversation followed by a talk/battle/hunt objective.
 * Pure logic over {@link PetDatabase} and {@link RosterManager} (both fully synchronised), so it is
 * safe to call from either hub surface or the battle thread, and unit-testable with an in-memory
 * roster store.
 *
 * <p>A quest's stored step ({@link RosterManager#getQuestStep(String)}) is the index of its current
 * chapter; the quest is complete once the step passes the last chapter
 * ({@link QuestDef#completeStep()}). Rewards are applied at the moment a chapter is cleared, tied to
 * the step actually moving forward, so each grants exactly once.
 */
@Slf4j
public class QuestManager
{
	/**
	 * What clearing a battle/hunt chapter produced, for the caller to present on the battle end
	 * screen: the conversation to play (the NPC's payoff + hand-over) and what was awarded (for the
	 * plugin's system chat line). Returned only when a battle actually progressed a quest.
	 */
	public static final class DefeatResult
	{
		private final List<Conversation.Node> conversation;
		private final String rewardItemName;
		private final long rewardCoins;

		DefeatResult(List<Conversation.Node> conversation, String rewardItemName, long rewardCoins)
		{
			this.conversation = conversation;
			this.rewardItemName = rewardItemName;
			this.rewardCoins = rewardCoins;
		}

		/** The end-screen conversation to play (never null; may be empty). */
		public List<Conversation.Node> getConversation()
		{
			return conversation == null ? Collections.emptyList() : conversation;
		}

		/** Display name of the item the chapter awarded (held or key-item trophy), or null. */
		public String getRewardItemName()
		{
			return rewardItemName;
		}

		/** Coins granted by the chapter (0 if none). */
		public long getRewardCoins()
		{
			return rewardCoins;
		}
	}

	private final PetDatabase db;
	private final RosterManager roster;

	public QuestManager(PetDatabase db, RosterManager roster)
	{
		this.db = db;
		this.roster = roster;
	}

	/** The quest definition for this id, or null if unknown. */
	public QuestDef quest(String questId)
	{
		return db.quest(questId);
	}

	/**
	 * Whether a quest is available to the player: true unless its {@code requires} names another
	 * quest that isn't complete yet.
	 */
	public boolean isAvailable(QuestDef quest)
	{
		if (quest == null)
		{
			return false;
		}
		String requires = quest.getRequires();
		return requires == null || requires.isEmpty() || isComplete(requires);
	}

	/** Whether this quest has been carried past its last chapter. */
	public boolean isComplete(String questId)
	{
		QuestDef quest = db.quest(questId);
		return quest != null && roster.getQuestStep(questId) >= quest.completeStep();
	}

	/**
	 * The chapter this quest is currently on (its step), or null if the quest is unknown or complete.
	 */
	public QuestDef.Chapter currentChapter(String questId)
	{
		QuestDef quest = db.quest(questId);
		if (quest == null)
		{
			return null;
		}
		int step = roster.getQuestStep(questId);
		for (QuestDef.Chapter chapter : quest.getChapters())
		{
			if (chapter.getStep() == step)
			{
				return chapter;
			}
		}
		return null;
	}

	/**
	 * The player finished a talk chapter's conversation (a non-battle, non-hunt chapter): apply its
	 * reward and advance. No-op (returns false) if the quest is unavailable/complete or the current
	 * chapter is a battle/hunt chapter (which a win clears). The UI only calls this once the chapter
	 * is reachable and its conversation has run out, so proximity is enforced there.
	 */
	public boolean completeTalk(String questId)
	{
		QuestDef quest = db.quest(questId);
		if (quest == null || !isAvailable(quest))
		{
			return false;
		}
		QuestDef.Chapter chapter = currentChapter(questId);
		if (chapter == null || chapter.isBattle() || chapter.isHunt())
		{
			return false;
		}
		return applyRewardAndAdvance(questId, chapter);
	}

	/**
	 * A trainer was just beaten: if an available quest's current chapter is waiting on this trainer —
	 * a battle chapter naming it, or a hunt chapter with it in the pool — clear/progress that chapter
	 * and return the end-screen conversation. Returns null if no quest was waiting on this trainer, so
	 * a plain re-fight (or a re-fight of an already-counted suspect) does nothing.
	 */
	public DefeatResult onTrainerDefeated(String trainerId)
	{
		for (QuestDef quest : db.allQuests())
		{
			if (!isAvailable(quest))
			{
				continue;
			}
			QuestDef.Chapter chapter = currentChapter(quest.getId());
			if (chapter == null)
			{
				continue;
			}
			if (chapter.isBattle() && trainerId.equals(chapter.getBattleTrainer()))
			{
				return resolveClear(quest, chapter, chapter.getRewardConversation());
			}
			if (chapter.isHunt() && chapter.getBattlePool().contains(trainerId))
			{
				return resolveHunt(quest, chapter, trainerId);
			}
		}
		return null;
	}

	/** Clear a battle chapter: reward + advance, returning its end-screen conversation (or null). */
	private DefeatResult resolveClear(QuestDef quest, QuestDef.Chapter chapter,
		List<Conversation.Node> conversation)
	{
		QuestDef.Reward reward = chapter.getReward();
		String rewardName = rewardName(reward);
		long coins = reward != null ? reward.getCoins() : 0;
		if (!applyRewardAndAdvance(quest.getId(), chapter))
		{
			return null;
		}
		return new DefeatResult(conversation, rewardName, coins);
	}

	/**
	 * Progress a hunt chapter: flag this suspect if newly beaten, and once enough distinct suspects
	 * are down, clear the chapter (its reward conversation plays). Earlier wins return a short
	 * progress line; a re-fight of an already-counted suspect returns null.
	 */
	private DefeatResult resolveHunt(QuestDef quest, QuestDef.Chapter chapter, String trainerId)
	{
		boolean newlyBeaten = roster.setFlag(huntFlag(quest, trainerId));
		int beaten = countHuntBeaten(quest, chapter);
		int required = chapter.getBattlesRequired();
		QuestDef.Suspect suspect = chapter.getSuspect(trainerId);
		if (beaten >= required)
		{
			// Whoever went down last delivers the hand-off, so each suspect authors their own finale.
			List<Conversation.Node> finale = suspect != null ? suspect.getFinale() : null;
			return resolveClear(quest, chapter,
				finale == null || finale.isEmpty() ? chapter.getRewardConversation() : finale);
		}
		if (!newlyBeaten)
		{
			return null;
		}
		List<Conversation.Node> lines = new ArrayList<>(
			suspect != null ? suspect.getConcede() : Collections.<Conversation.Node>emptyList());
		if (lines.isEmpty())
		{
			lines.add(new Conversation.Node(trainerId,
				"Bah - you have me. But I'm not the one you're after; try another greybeard."));
		}
		// Narration (no speaker) so the authored concede lines stay verbatim.
		lines.add(new Conversation.Node(null, "Suspects defeated: " + beaten + "/" + required + "."));
		return new DefeatResult(lines, null, 0);
	}

	/**
	 * Grant a chapter's reward then advance the quest one step. The advance is what makes the reward
	 * one-off: it only moves forward from the chapter's own step, so a repeat call finds a different
	 * current chapter and skips. Returns whether the step moved forward.
	 */
	private boolean applyRewardAndAdvance(String questId, QuestDef.Chapter chapter)
	{
		// Advance first, so the reward is bound to the step actually moving forward: a defensive
		// repeat call can't re-grant because the step is already past this chapter.
		if (!roster.advanceQuest(questId, chapter.getStep() + 1))
		{
			return false;
		}
		QuestDef.Reward reward = chapter.getReward();
		if (reward != null)
		{
			if (reward.getItem() != null && !reward.getItem().isEmpty())
			{
				roster.grantItem(reward.getItem(), 1);
			}
			if (reward.getCoins() > 0)
			{
				roster.addCoins(reward.getCoins());
			}
			if (reward.getFlag() != null && !reward.getFlag().isEmpty())
			{
				roster.setFlag(reward.getFlag());
			}
		}
		log.debug("Quest {} cleared chapter {} ({})", questId, chapter.getStep(), chapter.getTitle());
		return true;
	}

	private String huntFlag(QuestDef quest, String trainerId)
	{
		return quest.getId() + ":wb:" + trainerId;
	}

	/** Whether a specific hunt suspect has already been beaten (for the Story view). */
	public boolean isHuntMemberBeaten(QuestDef quest, String trainerId)
	{
		return roster.hasFlag(huntFlag(quest, trainerId));
	}

	/** How many distinct hunt suspects have been beaten so far (for the Story view's N/M counter). */
	public int countHuntBeaten(QuestDef quest, QuestDef.Chapter chapter)
	{
		int n = 0;
		for (String member : chapter.getBattlePool())
		{
			if (roster.hasFlag(huntFlag(quest, member)))
			{
				n++;
			}
		}
		return n;
	}

	/** Display name of a chapter reward (held item or key-item trophy), or null for none. */
	private String rewardName(QuestDef.Reward reward)
	{
		if (reward == null)
		{
			return null;
		}
		if (reward.getItem() != null && !reward.getItem().isEmpty())
		{
			EquipItemDef item = db.equipItem(reward.getItem());
			return item != null ? item.getName() : null;
		}
		if (reward.getKeyItem() != null && !reward.getKeyItem().isEmpty())
		{
			Item item = Item.byId(reward.getKeyItem());
			return item != null ? item.getName() : null;
		}
		return null;
	}
}

package com.petbattles.ui;

import com.petbattles.engine.BattleEvent;
import com.petbattles.engine.MoveDef;
import com.petbattles.engine.MoveEffect;
import com.petbattles.engine.PetType;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.awt.geom.AffineTransform;
import java.awt.geom.Path2D;

/**
 * Maps the current battle event to sprite motion and overlay effects. Every effect is pure
 * interpolation over the session's 0→1 animation progress — no state, no allocation beyond
 * loop locals and a couple of small per-frame palettes — so it's safe to call every frame.
 *
 * <p>Each move carries an animation id that encodes both how the caster moves (a lunge, a
 * cast recoil, a swell, a spin) and what the effect looks like. The pet's type colour tints
 * the effect, so a shared id like {@code "explosion"} reads as fire, nature or dragon
 * depending on who threw it.
 */
public final class AttackAnimator
{
	private static final Color WHITE = Color.WHITE;

	/**
	 * Offset/scale applied to one pet sprite this frame.
	 */
	public static final class Transform
	{
		public static final Transform IDENTITY = new Transform(0, 0, 1f, 1f);

		public final int dx;
		public final int dy;
		public final float scale;
		public final float alpha;

		private Transform(int dx, int dy, float scale)
		{
			this(dx, dy, scale, 1f);
		}

		private Transform(int dx, int dy, float scale, float alpha)
		{
			this.dx = dx;
			this.dy = dy;
			this.scale = scale;
			this.alpha = alpha;
		}
	}

	private AttackAnimator()
	{
	}

	/**
	 * Resolve a move's animation id: hand-authored value, else a category default — heal →
	 * sparkle, self-buff → rising aura, enemy debuff → wail, enemy status → cloud, attack → flash.
	 */
	public static String animationId(MoveDef move)
	{
		if (move == null)
		{
			return "flash";
		}
		if (move.getAnimation() != null && !move.getAnimation().isEmpty())
		{
			return move.getAnimation();
		}
		MoveEffect effect = move.getEffect();
		if (move.isStatusMove())
		{
			if (effect == MoveEffect.HEAL)
			{
				return "sparkle";
			}
			if (effect.isSelfBuff())
			{
				return "buff_aura";
			}
			if (effect.isEnemyDebuff())
			{
				return "wail";
			}
			if (effect.isStatus())
			{
				return "cloud";
			}
			return "shake";
		}
		return "flash";
	}

	/**
	 * Sprite transform for {@code side} given the event being animated.
	 */
	public static Transform spriteTransform(BattleEvent event, MoveDef move, float progress,
		int side, Rectangle self, Rectangle other)
	{
		if (event == null)
		{
			return Transform.IDENTITY;
		}
		switch (event.getType())
		{
			case MOVE_USED:
				if (event.getSide() != side)
				{
					return Transform.IDENTITY;
				}
				return casterMotion(animationId(move), progress, self, other);
			case DAMAGE:
			case STATUS_APPLIED:
			case STAT_CHANGED:
			case STATUS_TICK:
				if (event.getSide() != side)
				{
					return Transform.IDENTITY;
				}
				// Horizontal jitter on the afflicted pet, settling as the event ends
				return new Transform(
					(int) (4 * Math.sin(progress * 6 * Math.PI) * (1 - progress)), 0, 1f);
			case FAINTED:
				if (event.getSide() != side)
				{
					return Transform.IDENTITY;
				}
				// Collapse: the fainted pet sinks, shrinks and fades before the next line
				return new Transform(0, (int) (self.height * 0.35f * progress),
					1f - 0.30f * progress, Math.max(0f, 1f - 0.85f * progress));
			default:
				return Transform.IDENTITY;
		}
	}

	/**
	 * How the caster itself moves while its move plays: contact moves lunge in, ranged/cast
	 * moves give a small forward throw, buffs swell, whirls shimmy.
	 */
	private static Transform casterMotion(String id, float progress, Rectangle self, Rectangle other)
	{
		switch (id)
		{
			case "grow":
			case "buff_aura":
				// Swell up and settle back (War Cry / Bulk Up / Harden)
				return new Transform(0, 0, 1f + 0.30f * (float) Math.sin(Math.PI * progress));
			case "lunge":
			case "whip":
			case "slash":
			case "bite":
			case "shockwave":
			{
				// Dart in to make contact and back out
				float f = 0.30f * (float) Math.sin(Math.PI * progress);
				int dx = (int) ((other.getCenterX() - self.getCenterX()) * f);
				int dy = (int) ((other.getCenterY() - self.getCenterY()) * f);
				return new Transform(dx, dy, 1f);
			}
			case "spin":
			{
				// Rapid shimmy with a scale pulse, suggesting a whirl
				int dx = (int) (6 * Math.sin(progress * 8 * Math.PI) * (1 - progress));
				return new Transform(dx, 0, 1f + 0.12f * (float) Math.sin(Math.PI * progress));
			}
			case "sparkle":
				// Gentle rise as it channels a heal
				return new Transform(0, (int) (-4 * Math.sin(Math.PI * progress)), 1f);
			default:
			{
				// Ranged / cast: a quick forward throw that peaks early then holds for the impact
				float f = 0.10f * (float) Math.sin(Math.PI * Math.min(1f, progress * 2f));
				int dx = (int) ((other.getCenterX() - self.getCenterX()) * f);
				int dy = (int) ((other.getCenterY() - self.getCenterY()) * f);
				return new Transform(dx, dy, 1f);
			}
		}
	}

	/**
	 * Overlay-drawn effects for the MOVE_USED phase. Call after the sprites are drawn.
	 */
	public static void drawEffects(Graphics2D g, BattleEvent event, MoveDef move, float progress,
		Rectangle attacker, Rectangle defender)
	{
		if (event == null || event.getType() != BattleEvent.Type.MOVE_USED || move == null)
		{
			return;
		}
		PetType type = move.getType();
		Color tc = new Color(type.getColorRgb());
		int seed = move.getId() == null ? move.hashCode() : move.getId().hashCode();
		switch (animationId(move))
		{
			// --- projectiles (travel from caster to defender, then land) ---
			case "projectile":
				drawProjectile(g, attacker, defender, progress, tc);
				break;
			case "dart":
				drawDart(g, attacker, defender, progress, tc);
				break;
			case "bolt":
				drawBolt(g, attacker, defender, progress, tc);
				break;
			case "orb":
				drawOrb(g, attacker, defender, progress, tc);
				break;
			case "swirl":
				drawSwirl(g, attacker, defender, progress, tc);
				break;
			case "fireball":
				drawFireball(g, attacker, defender, progress, seed, tc);
				break;
			case "ice_shard":
				drawIceShard(g, attacker, defender, progress, seed, tc);
				break;
			case "spinning_log":
				drawSpinningLog(g, attacker, defender, progress);
				break;
			case "chin":
				drawChin(g, attacker, defender, progress, seed);
				break;
			// --- cone ---
			case "breath":
				drawBreath(g, attacker, defender, progress, seed, tc);
				break;
			// --- area effects centred on the defender ---
			case "explosion":
				drawExplosion(g, defender, progress, seed, tc);
				break;
			case "barrage":
				drawBarrage(g, defender, progress, seed);
				break;
			case "blizzard":
				drawBlizzard(g, defender, progress, seed);
				break;
			case "cloud":
				drawCloud(g, defender, progress, seed);
				break;
			case "roots":
				drawRoots(g, defender, progress);
				break;
			// --- contact impacts ---
			case "slash":
				drawSlash(g, defender, progress, tc);
				break;
			case "bite":
				drawBite(g, defender, progress, seed, tc);
				break;
			case "shockwave":
				drawShockwave(g, defender, progress, tc);
				break;
			case "spin":
				drawSpinSlashes(g, defender, progress, tc);
				break;
			case "whip":
				drawWhipLash(g, attacker, defender, progress, tc);
				break;
			case "flash":
				drawFlash(g, defender, progress, tc);
				break;
			// --- caster-centred / status ---
			case "drain":
				drawDrain(g, attacker, defender, progress, seed);
				break;
			case "wail":
				drawWail(g, attacker, defender, progress, tc);
				break;
			case "grow":
			case "buff_aura":
				drawBuffAura(g, attacker, progress, seed, tc);
				break;
			case "sparkle":
				ParticleBurst.render(g, attacker, progress, seed, ParticleBurst.SPARKLE);
				break;
			default:
				break;
		}
	}

	// ------------------------------------------------------------------ projectiles

	private static void drawProjectile(Graphics2D g, Rectangle a, Rectangle d, float p, Color tc)
	{
		double x = lerp(a.getCenterX(), d.getCenterX(), p);
		double y = lerp(a.getCenterY(), d.getCenterY(), p) - 20 * Math.sin(Math.PI * p);
		g.setColor(tc);
		g.fillOval((int) x - 5, (int) y - 5, 10, 10);
		g.setColor(new Color(255, 255, 255, 180));
		g.fillOval((int) x - 2, (int) y - 2, 4, 4);
	}

	private static void drawDart(Graphics2D g, Rectangle a, Rectangle d, float p, Color tc)
	{
		double t = Math.min(1.0, p * 1.25);
		double hx = lerp(a.getCenterX(), d.getCenterX(), t);
		double hy = lerp(a.getCenterY(), d.getCenterY(), t);
		double tt = Math.max(0.0, t - 0.12);
		double sx = lerp(a.getCenterX(), d.getCenterX(), tt);
		double sy = lerp(a.getCenterY(), d.getCenterY(), tt);
		Stroke os = g.getStroke();
		g.setStroke(new BasicStroke(2.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(tc);
		g.drawLine((int) sx, (int) sy, (int) hx, (int) hy);
		// arrowhead
		g.setColor(WHITE);
		g.fillOval((int) hx - 2, (int) hy - 2, 4, 4);
		g.setStroke(os);
	}

	private static void drawBolt(Graphics2D g, Rectangle a, Rectangle d, float p, Color tc)
	{
		double t = Math.min(1.0, p * 1.5);
		double hx = lerp(a.getCenterX(), d.getCenterX(), t);
		double hy = lerp(a.getCenterY(), d.getCenterY(), t);
		double tt = Math.max(0.0, t - 0.22);
		double sx = lerp(a.getCenterX(), d.getCenterX(), tt);
		double sy = lerp(a.getCenterY(), d.getCenterY(), tt);
		Stroke os = g.getStroke();
		g.setStroke(new BasicStroke(5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(alpha(tc, 210));
		g.drawLine((int) sx, (int) sy, (int) hx, (int) hy);
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(new Color(255, 255, 255, 230));
		g.drawLine((int) sx, (int) sy, (int) hx, (int) hy);
		g.setStroke(os);
		if (t >= 1.0)
		{
			int r = (int) (14 * (p - 0.66) / 0.34);
			g.setColor(alpha(WHITE, (int) (200 * (1 - p))));
			g.drawOval((int) hx - r, (int) hy - r, r * 2, r * 2);
		}
	}

	private static void drawOrb(Graphics2D g, Rectangle a, Rectangle d, float p, Color tc)
	{
		double t = Math.min(1.0, p * 1.2);
		double x = lerp(a.getCenterX(), d.getCenterX(), t);
		double y = lerp(a.getCenterY(), d.getCenterY(), t) - 16 * Math.sin(Math.PI * t);
		if (t < 1.0)
		{
			g.setColor(alpha(tc, 90));
			g.fillOval((int) x - 11, (int) y - 11, 22, 22);
			g.setColor(tc);
			g.fillOval((int) x - 7, (int) y - 7, 14, 14);
			g.setColor(new Color(255, 255, 255, 220));
			g.fillOval((int) x - 3, (int) y - 3, 6, 6);
		}
		if (p > 0.7)
		{
			// splash ring on landing
			int r = (int) (26 * (p - 0.7) / 0.3);
			Stroke os = g.getStroke();
			g.setStroke(new BasicStroke(3f));
			g.setColor(alpha(tc, (int) (200 * (1 - p))));
			g.drawOval((int) d.getCenterX() - r, (int) d.getCenterY() - r, r * 2, r * 2);
			g.setStroke(os);
		}
	}

	private static void drawSwirl(Graphics2D g, Rectangle a, Rectangle d, float p, Color tc)
	{
		double x = lerp(a.getCenterX(), d.getCenterX(), p);
		double y = lerp(a.getCenterY(), d.getCenterY(), p) - 14 * Math.sin(Math.PI * p);
		Stroke os = g.getStroke();
		g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		AffineTransform old = g.getTransform();
		g.translate(x, y);
		g.rotate(p * 6 * Math.PI);
		g.setColor(alpha(tc, 220));
		g.drawArc(-9, -9, 18, 18, 20, 200);
		g.drawArc(-6, -6, 12, 12, 200, 200);
		g.setTransform(old);
		g.setStroke(os);
	}

	private static void drawFireball(Graphics2D g, Rectangle a, Rectangle d, float p, int seed, Color tc)
	{
		double t = Math.min(1.0, p * 1.2);
		double hx = lerp(a.getCenterX(), d.getCenterX(), t);
		double hy = lerp(a.getCenterY(), d.getCenterY(), t) - 14 * Math.sin(Math.PI * t);
		if (t < 1.0)
		{
			// trailing embers
			for (int k = 1; k <= 4; k++)
			{
				double tk = t - 0.07 * k;
				if (tk <= 0)
				{
					continue;
				}
				double ex = lerp(a.getCenterX(), d.getCenterX(), tk);
				double ey = lerp(a.getCenterY(), d.getCenterY(), tk) - 14 * Math.sin(Math.PI * tk);
				Color c = ParticleBurst.EMBER[k % ParticleBurst.EMBER.length];
				g.setColor(alpha(c, 200 - k * 40));
				int s = 6 - k;
				g.fillOval((int) ex - s / 2, (int) ey - s / 2, s, s);
			}
			g.setColor(tc);
			g.fillOval((int) hx - 7, (int) hy - 7, 14, 14);
			g.setColor(new Color(255, 245, 200, 230));
			g.fillOval((int) hx - 3, (int) hy - 3, 6, 6);
		}
		if (p > 0.65)
		{
			drawExplosion(g, d, (float) ((p - 0.65) / 0.35), seed, tc);
		}
	}

	private static void drawIceShard(Graphics2D g, Rectangle a, Rectangle d, float p, int seed, Color tc)
	{
		if (p < 0.75)
		{
			double t = Math.min(1.0, p / 0.75);
			double x = lerp(a.getCenterX(), d.getCenterX(), t);
			double y = lerp(a.getCenterY(), d.getCenterY(), t) - 16 * Math.sin(Math.PI * t);
			int[] xs = {(int) x, (int) x + 5, (int) x, (int) x - 5};
			int[] ys = {(int) y - 9, (int) y, (int) y + 9, (int) y};
			g.setColor(tc);
			g.fillPolygon(xs, ys, 4);
			g.setColor(new Color(255, 255, 255, 200));
			g.drawPolygon(xs, ys, 4);
		}
		else
		{
			// shatter on landing
			ParticleBurst.render(g, d, (float) ((p - 0.75) / 0.25), seed, ParticleBurst.FROST);
		}
	}

	private static void drawSpinningLog(Graphics2D g, Rectangle a, Rectangle d, float p)
	{
		double x = lerp(a.getCenterX(), d.getCenterX(), p);
		double y = lerp(a.getCenterY(), d.getCenterY(), p) - 22 * Math.sin(Math.PI * p);
		AffineTransform old = g.getTransform();
		g.translate(x, y);
		g.rotate(p * 4 * Math.PI);
		g.setColor(new Color(120, 80, 45));
		g.fillRoundRect(-12, -4, 24, 8, 4, 4);
		g.setColor(new Color(80, 52, 28));
		g.drawRoundRect(-12, -4, 24, 8, 4, 4);
		g.drawLine(-6, -4, -6, 4);
		g.drawLine(4, -4, 4, 4);
		g.setTransform(old);
	}

	private static void drawChin(Graphics2D g, Rectangle a, Rectangle d, float p, int seed)
	{
		if (p < 0.55)
		{
			double t = p / 0.55;
			double x = lerp(a.getCenterX(), d.getCenterX(), t);
			double y = lerp(a.getCenterY(), d.getCenterY(), t) - 18 * Math.sin(Math.PI * t);
			g.setColor(new Color(90, 60, 40));
			g.fillOval((int) x - 5, (int) y - 5, 10, 10);
		}
		else
		{
			drawExplosion(g, d, (float) ((p - 0.55) / 0.45), seed, new Color(230, 130, 40));
		}
	}

	// ------------------------------------------------------------------ cone

	private static void drawBreath(Graphics2D g, Rectangle a, Rectangle d, float p, int seed, Color tc)
	{
		double ax = a.getCenterX();
		double ay = a.getCenterY();
		double ang = Math.atan2(d.getCenterY() - ay, d.getCenterX() - ax);
		double dist = Math.hypot(d.getCenterX() - ax, d.getCenterY() - ay);
		double ca = Math.cos(ang);
		double sa = Math.sin(ang);
		for (int i = 0; i < 18; i++)
		{
			int h = hash(seed, i);
			double lat = (h & 0xFF) / 255.0 - 0.5;
			double along = ((h >>> 8) & 0xFF) / 255.0;
			double pr = clamp((p - along * 0.3) / 0.7, 0, 1);
			if (pr <= 0)
			{
				continue;
			}
			double r = pr * dist * 0.95;
			double spread = 0.38 * r * lat;
			double px = ax + ca * r - sa * spread;
			double py = ay + sa * r + ca * spread;
			Color c = ParticleBurst.EMBER[Math.floorMod(h >>> 16, ParticleBurst.EMBER.length)];
			// tint toward the move's type so dragon breath differs from fire breath
			g.setColor(alpha(mix(c, tc, 0.4f), (int) (220 * (1 - pr))));
			int s = 5 - (int) (pr * 3);
			g.fillOval((int) px - s, (int) py - s, s * 2, s * 2);
		}
	}

	// ------------------------------------------------------------------ area effects

	private static void drawExplosion(Graphics2D g, Rectangle d, float p, int seed, Color tc)
	{
		int cx = (int) d.getCenterX();
		int cy = (int) d.getCenterY();
		// central flash
		int fa = (int) (170 * Math.sin(Math.PI * p));
		if (fa > 0)
		{
			g.setColor(alpha(WHITE, fa));
			g.fillOval(cx - 10, cy - 10, 20, 20);
		}
		// expanding ring
		int r = (int) (p * Math.max(d.width, d.height) * 0.85);
		Stroke os = g.getStroke();
		g.setStroke(new BasicStroke(3f));
		g.setColor(alpha(tc, (int) (200 * (1 - p))));
		g.drawOval(cx - r, cy - r, r * 2, r * 2);
		g.setStroke(os);
		ParticleBurst.render(g, d, p, seed, new Color[]{tc, tc.brighter(), new Color(255, 240, 210)});
	}

	private static void drawBarrage(Graphics2D g, Rectangle d, float p, int seed)
	{
		int baseY = d.y + d.height - 2;
		int n = 6;
		g.setColor(alpha(new Color(140, 200, 240), (int) (110 * Math.sin(Math.PI * p))));
		g.fillRoundRect(d.x, d.y, d.width, d.height, 12, 12);
		Stroke os = g.getStroke();
		g.setStroke(new BasicStroke(1.5f));
		for (int i = 0; i < n; i++)
		{
			int h = hash(seed, i);
			double phase = clamp((p - i * 0.05) / 0.5, 0, 1);
			// erupt fast, then hold
			double grow = phase < 0.6 ? phase / 0.6 : 1.0;
			double crystalH = grow * d.height * (0.65 + ((h & 0x7) / 7.0) * 0.5);
			int x = d.x + (int) (d.width * (i + 0.5) / n) + ((h >>> 4 & 0x7) - 3);
			int w = 6 + (h >>> 8 & 0x3);
			int tipY = baseY - (int) crystalH;
			int[] xs = {x - w, x + w, x};
			int[] ys = {baseY, baseY, tipY};
			g.setColor(new Color(150, 210, 245, 235));
			g.fillPolygon(xs, ys, 3);
			g.setColor(new Color(235, 250, 255, 235));
			g.drawPolygon(xs, ys, 3);
			g.drawLine(x, baseY, x, tipY);
		}
		g.setStroke(os);
		if (p > 0.7)
		{
			ParticleBurst.render(g, d, (float) ((p - 0.7) / 0.3), seed, ParticleBurst.FROST);
		}
	}

	private static void drawBlizzard(Graphics2D g, Rectangle d, float p, int seed)
	{
		g.setColor(alpha(new Color(180, 225, 255), (int) (80 * Math.sin(Math.PI * p))));
		g.fillRoundRect(d.x, d.y, d.width, d.height, 12, 12);
		Stroke os = g.getStroke();
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (int i = 0; i < 20; i++)
		{
			int h = hash(seed, i);
			int x = d.x + Math.floorMod(h, Math.max(1, d.width));
			double phase = ((p * 1.6) + (h >>> 8 & 0xFF) / 255.0) % 1.0;
			int y = d.y + (int) (phase * (d.height + 12)) - 6;
			Color c = ParticleBurst.FROST[Math.floorMod(h >>> 16, ParticleBurst.FROST.length)];
			g.setColor(alpha(c, 220));
			g.drawLine(x, y, x - 4, y + 10);
		}
		g.setStroke(os);
	}

	private static void drawCloud(Graphics2D g, Rectangle d, float p, int seed)
	{
		int cx = (int) d.getCenterX();
		int cy = (int) d.getCenterY();
		float env = (float) Math.sin(Math.PI * Math.min(1f, p * 1.2f));
		for (int i = 0; i < 7; i++)
		{
			int h = hash(seed, i);
			int ox = (h & 0x1F) - 16;
			int oy = ((h >>> 5) & 0x1F) - 16;
			int rise = (int) (p * 12);
			int rad = 10 + (h >>> 10 & 0x7) + (int) (p * 6);
			Color c = ParticleBurst.TOXIN[Math.floorMod(h >>> 16, ParticleBurst.TOXIN.length)];
			g.setColor(alpha(c, (int) (120 * env)));
			g.fillOval(cx + ox - rad, cy + oy - rise - rad, rad * 2, rad * 2);
		}
	}

	private static void drawRoots(Graphics2D g, Rectangle d, float p)
	{
		int baseY = d.y + d.height;
		int n = 4;
		Stroke os = g.getStroke();
		g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(new Color(60, 130, 55, 235));
		for (int i = 0; i < n; i++)
		{
			int x = d.x + (int) (d.width * (i + 0.5) / n);
			int climb = (int) (p * d.height);
			Path2D vine = new Path2D.Double();
			vine.moveTo(x, baseY);
			int segs = 6;
			for (int s = 1; s <= segs; s++)
			{
				double f = (double) s / segs;
				if (f * d.height > climb)
				{
					break;
				}
				double wob = Math.sin(f * Math.PI * 3 + i) * 6;
				vine.lineTo(x + wob, baseY - f * d.height);
			}
			g.draw(vine);
		}
		g.setStroke(os);
	}

	// ------------------------------------------------------------------ contact impacts

	private static void drawSlash(Graphics2D g, Rectangle d, float p, Color tc)
	{
		Stroke os = g.getStroke();
		for (int i = 0; i < 3; i++)
		{
			float start = 0.12f + i * 0.16f;
			float local = (p - start) / 0.35f;
			if (local <= 0 || local >= 1)
			{
				continue;
			}
			int a = (int) (230 * (1 - local));
			int ox = (i - 1) * 12;
			int x1 = d.x + d.width / 4 + ox;
			int y1 = d.y + d.height / 4;
			int x2 = d.x + 3 * d.width / 4 + ox;
			int y2 = d.y + 3 * d.height / 4;
			g.setStroke(new BasicStroke(5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(alpha(tc, a));
			g.drawLine(x1, y1, x2, y2);
			g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(alpha(WHITE, a));
			g.drawLine(x1, y1, x2, y2);
		}
		g.setStroke(os);
	}

	private static void drawBite(Graphics2D g, Rectangle d, float p, int seed, Color tc)
	{
		int cx = (int) d.getCenterX();
		int cy = (int) d.getCenterY();
		int w = d.width / 3;
		int gap = (int) ((1 - Math.sin(Math.PI * p)) * d.height * 0.32);
		Stroke os = g.getStroke();
		g.setStroke(new BasicStroke(4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(alpha(WHITE, 220));
		// upper jaw (teeth pointing down)
		int[] ux = {cx - w, cx - w / 2, cx, cx + w / 2, cx + w};
		int uy0 = cy - gap - 8;
		int[] uy = {uy0, uy0 + 8, uy0, uy0 + 8, uy0};
		g.drawPolyline(ux, uy, 5);
		// lower jaw (teeth pointing up)
		int ly0 = cy + gap + 8;
		int[] ly = {ly0, ly0 - 8, ly0, ly0 - 8, ly0};
		g.drawPolyline(ux, ly, 5);
		g.setStroke(os);
		if (p > 0.45)
		{
			// status-coloured splash as the jaws close
			ParticleBurst.render(g, new Rectangle(cx - 6, cy - 6, 12, 12),
				(float) ((p - 0.45) / 0.55), seed, new Color[]{tc, tc.brighter(), WHITE});
		}
	}

	private static void drawShockwave(Graphics2D g, Rectangle d, float p, Color tc)
	{
		int cx = (int) d.getCenterX();
		int cy = (int) d.getCenterY();
		if (p < 0.3)
		{
			g.setColor(alpha(WHITE, (int) (220 * (1 - p / 0.3))));
			g.fillOval(cx - 12, cy - 12, 24, 24);
		}
		Stroke os = g.getStroke();
		g.setStroke(new BasicStroke(4f));
		for (int k = 0; k < 2; k++)
		{
			float local = p - k * 0.18f;
			if (local <= 0)
			{
				continue;
			}
			int r = (int) (local * d.width * 0.9);
			g.setColor(alpha(tc, (int) (200 * (1 - local))));
			g.drawOval(cx - r, cy - r, r * 2, r * 2);
		}
		g.setStroke(os);
	}

	private static void drawSpinSlashes(Graphics2D g, Rectangle d, float p, Color tc)
	{
		int cx = (int) d.getCenterX();
		int cy = (int) d.getCenterY();
		int r = (int) (d.width * 0.5);
		Stroke os = g.getStroke();
		g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(alpha(tc, (int) (220 * Math.sin(Math.PI * p))));
		for (int i = 0; i < 6; i++)
		{
			double a = p * 4 * Math.PI + i * Math.PI / 3;
			int x = cx + (int) (Math.cos(a) * r);
			int y = cy + (int) (Math.sin(a) * r);
			int x2 = cx + (int) (Math.cos(a) * (r - 9));
			int y2 = cy + (int) (Math.sin(a) * (r - 9));
			g.drawLine(x, y, x2, y2);
		}
		g.setStroke(os);
	}

	private static void drawWhipLash(Graphics2D g, Rectangle a, Rectangle d, float p, Color tc)
	{
		double ext = Math.sin(Math.PI * p);
		double ax = a.getCenterX();
		double ay = a.getCenterY();
		double ex = lerp(ax, d.getCenterX(), ext);
		double ey = lerp(ay, d.getCenterY(), ext);
		double mx = (ax + ex) / 2;
		double my = Math.min(ay, ey) - 22 * ext;
		Path2D lash = new Path2D.Double();
		lash.moveTo(ax, ay);
		lash.quadTo(mx, my, ex, ey);
		Stroke os = g.getStroke();
		g.setStroke(new BasicStroke(3f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(tc);
		g.draw(lash);
		g.setStroke(os);
		if (ext > 0.9)
		{
			g.setColor(alpha(WHITE, 200));
			g.fillOval((int) ex - 4, (int) ey - 4, 8, 8);
		}
	}

	private static void drawFlash(Graphics2D g, Rectangle d, float p, Color tc)
	{
		int a = (int) (140 * Math.sin(Math.PI * p));
		if (a > 0)
		{
			g.setColor(alpha(tc, a));
			g.fillRoundRect(d.x, d.y, d.width, d.height, 12, 12);
		}
	}

	// ------------------------------------------------------------------ caster / status

	private static void drawDrain(Graphics2D g, Rectangle a, Rectangle d, float p, int seed)
	{
		for (int i = 0; i < 12; i++)
		{
			int h = hash(seed, i);
			double pr = ((p * 1.3) + (h & 0xFF) / 255.0) % 1.0;
			double x = lerp(d.getCenterX(), a.getCenterX(), pr) + ((h >>> 8 & 0x7) - 3);
			double y = lerp(d.getCenterY(), a.getCenterY(), pr) - 10 * Math.sin(Math.PI * pr)
				+ ((h >>> 11 & 0x7) - 3);
			Color c = ParticleBurst.SHADOW[Math.floorMod(h >>> 16, ParticleBurst.SHADOW.length)];
			g.setColor(alpha(c, (int) (220 * (1 - pr))));
			g.fillOval((int) x - 3, (int) y - 3, 6, 6);
		}
	}

	private static void drawWail(Graphics2D g, Rectangle a, Rectangle d, float p, Color tc)
	{
		int ax = (int) a.getCenterX();
		int ay = (int) a.getCenterY();
		int dir = d.getCenterX() >= ax ? 1 : -1;
		double reach = Math.abs(d.getCenterX() - ax);
		Stroke os = g.getStroke();
		g.setStroke(new BasicStroke(2.5f));
		for (int k = 0; k < 3; k++)
		{
			double local = clamp((p - k * 0.14) / 0.7, 0, 1);
			if (local <= 0)
			{
				continue;
			}
			int rx = (int) (local * reach);
			int ry = (int) (12 + local * d.height * 0.5);
			g.setColor(alpha(tc, (int) (200 * (1 - local))));
			g.drawArc(ax - (dir < 0 ? rx : 0), ay - ry, rx, ry * 2,
				dir > 0 ? -70 : 110, 140);
		}
		g.setStroke(os);
		if (p > 0.6)
		{
			g.setColor(alpha(tc, (int) (90 * (1 - p))));
			g.fillRoundRect(d.x, d.y, d.width, d.height, 12, 12);
		}
	}

	private static void drawBuffAura(Graphics2D g, Rectangle a, float p, int seed, Color tc)
	{
		for (int i = 0; i < 14; i++)
		{
			int h = hash(seed, i);
			double pr = ((p) + (h & 0xFF) / 255.0) % 1.0;
			int x = (int) a.getCenterX() + ((h >>> 8 & 0x3F) - 32);
			int y = a.y + a.height - (int) (pr * a.height);
			g.setColor(alpha(tc, (int) (200 * (1 - pr))));
			int s = 2 + (h >>> 14 & 1);
			g.fillRect(x, y, s, s);
		}
		// a couple of rising chevrons
		Stroke os = g.getStroke();
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(alpha(tc, (int) (220 * Math.sin(Math.PI * p))));
		int cx = (int) a.getCenterX();
		int cy = a.y + a.height / 2 - (int) (p * a.height * 0.4);
		g.drawPolyline(new int[]{cx - 8, cx, cx + 8}, new int[]{cy + 6, cy - 4, cy + 6}, 3);
		g.setStroke(os);
	}

	// ------------------------------------------------------------------ helpers

	private static int hash(int seed, int i)
	{
		return (seed * 31 + i) * 0x9E3779B9;
	}

	private static double lerp(double from, double to, double t)
	{
		return from + (to - from) * t;
	}

	private static double clamp(double v, double lo, double hi)
	{
		return v < lo ? lo : (v > hi ? hi : v);
	}

	private static Color alpha(Color c, int a)
	{
		int clamped = a < 0 ? 0 : (a > 255 ? 255 : a);
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), clamped);
	}

	private static Color mix(Color a, Color b, float t)
	{
		return new Color(
			(int) (a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) (a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) (a.getBlue() + (b.getBlue() - a.getBlue()) * t));
	}
}

package com.petbattles.ui;

import com.petbattles.battle.BattleSession;
import com.petbattles.data.PetDatabase;
import com.petbattles.engine.BattleEvent;
import com.petbattles.engine.BattlePet;
import com.petbattles.engine.BattleState;
import com.petbattles.engine.MoveDef;
import com.petbattles.engine.PetType;
import com.petbattles.engine.SpeciesDef;
import com.petbattles.item.EquipItemDef;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The battle scene: enemy pet top-right, player pet bottom-left, HP bars, battle log,
 * and a 2x2 grid of move buttons plus Run/Close. Buttons cache their local-space
 * rectangles each frame; BattleInputHandler hit-tests against them.
 */
public class BattleOverlay extends Overlay
{
	public static final int WIDTH = 340;
	public static final int HEIGHT = 250;

	private static final Color PANEL_BG = new Color(20, 24, 28, 235);
	private static final Color PANEL_EDGE = new Color(90, 75, 40);
	private static final Color BUTTON_BG = new Color(45, 50, 58);
	private static final Color BUTTON_HOVER = new Color(70, 78, 90);
	private static final Color BUTTON_EDGE = new Color(120, 110, 80);
	private static final Color HP_GREEN = new Color(60, 180, 75);
	private static final Color HP_YELLOW = new Color(220, 180, 40);
	private static final Color HP_RED = new Color(200, 60, 50);
	private static final Color LOG_TEXT = new Color(230, 225, 210);

	private static final Color SPLAT_RED = new Color(161, 22, 21);
	private static final Color SPLAT_SUPER = new Color(220, 80, 10);
	private static final Color SPLAT_RESIST = new Color(110, 45, 45);
	private static final Color SPLAT_BLUE = new Color(40, 66, 155);

	// Sprite positions shared by the pet drawing and the effect layers
	private static final Rectangle ENEMY_SPRITE = new Rectangle(WIDTH - 96, 24, 72, 72);
	private static final Rectangle PLAYER_SPRITE = new Rectangle(24, 88, 72, 72);

	/**
	 * A clickable region, in overlay-local coordinates.
	 */
	public static class Button
	{
		public final Rectangle rect;
		public final String action; // "move:N", "flee", "close"

		Button(Rectangle rect, String action)
		{
			this.rect = rect;
			this.action = action;
		}
	}

	private final BattleSession session;
	private final PetDatabase db;
	private final Sprites sprites;
	private final PetChatheads chatheads;
	private final ChatheadAnchors anchors;
	private final ItemSprites itemSprites;
	private final List<Button> buttons = new ArrayList<>();
	private Point hoverPoint;
	private volatile boolean swapMenuOpen;

	public BattleOverlay(BattleSession session, PetDatabase db, Sprites sprites, PetChatheads chatheads,
		ChatheadAnchors anchors, ItemSprites itemSprites)
	{
		this.session = session;
		this.db = db;
		this.sprites = sprites;
		this.chatheads = chatheads;
		this.anchors = anchors;
		this.itemSprites = itemSprites;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
	}

	/**
	 * Current buttons in overlay-local space; the input handler translates using getBounds().
	 */
	public synchronized List<Button> getButtons()
	{
		return new ArrayList<>(buttons);
	}

	public void setHoverPoint(Point localPoint)
	{
		this.hoverPoint = localPoint;
	}

	public void setSwapMenuOpen(boolean open)
	{
		this.swapMenuOpen = open;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!session.isActive())
		{
			synchronized (this)
			{
				buttons.clear();
			}
			return null;
		}
		BattleState state = session.getState();
		if (state == null)
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);

		// Frame
		g.setColor(PANEL_BG);
		g.fillRoundRect(0, 0, WIDTH, HEIGHT, 10, 10);
		g.setColor(PANEL_EDGE);
		g.setStroke(new BasicStroke(2));
		g.drawRoundRect(0, 0, WIDTH, HEIGHT, 10, 10);

		BattlePet enemy = state.active(BattleState.ENEMY);
		BattlePet player = state.active(BattleState.PLAYER);

		// Trainer name banner
		g.setFont(FontManager.getRunescapeSmallFont());
		g.setColor(new Color(200, 190, 160));
		String title = session.getTrainer() != null ? "vs " + session.getTrainer().getName() : "Battle";
		g.drawString(title, 10, 14);

		// The end-of-battle summary replaces the battle scene entirely. A quest chapter cleared by this
		// battle plays its payoff in the quest dialog frame alongside it (see QuestDialogSession), so
		// the summary is all this panel has left to show.
		if (session.getPhase() == BattleSession.Phase.ENDED)
		{
			List<Button> endButtons = new ArrayList<>();
			drawSummary(g, state, endButtons);
			synchronized (this)
			{
				buttons.clear();
				buttons.addAll(endButtons);
			}
			return new Dimension(WIDTH, HEIGHT);
		}

		BattleEvent current = session.getPhase() == BattleSession.Phase.ANIMATING
			? session.getCurrentEvent() : null;
		MoveDef currentMove = session.getCurrentMove();
		float progress = session.getAnimationProgress();

		// A fainted pet is "settled" (drawn as a faint ghost) only once its faint line has
		// actually played — the session gates this so the collapse never fires during the
		// earlier attack/damage lines (which read the already-resolved model).
		boolean enemySettled = session.isFaintSettled(enemy);
		boolean playerSettled = session.isFaintSettled(player);

		// Orient each pet toward its opponent: the player's pet should face right, the enemy's
		// left. A left-facing sprite is mirrored on the player side; a right-facing one on the
		// enemy side (spriteFacesLeft defaults true, so most pets flip only on the player side).
		boolean enemyMirror = !enemy.isSpriteFacesLeft();
		boolean playerMirror = player.isSpriteFacesLeft();

		// Enemy: info card top-left, full-body item icon top-right (the "far" pet).
		drawPetInfo(g, enemy, 10, 22, false);
		drawPetSprite(g, enemy, ENEMY_SPRITE,
			AttackAnimator.spriteTransform(current, currentMove, progress, BattleState.ENEMY, ENEMY_SPRITE, PLAYER_SPRITE),
			enemySettled, enemyMirror, null);

		// Player: the near pet is drawn as a foreground chathead (bundled, pre-oriented to face
		// right) when one exists, giving the scene depth; otherwise it falls back to the item icon.
		SpeciesDef playerSpecies = player.getSpecies();
		PetChatheads.Chathead playerChat = chatheads.resolve(playerSpecies.getId(), player.getVariantId(),
			playerSpecies.chatheadStageKeyFor(player.getVariantId(), player.getLevel()));
		drawPetSprite(g, player, PLAYER_SPRITE,
			AttackAnimator.spriteTransform(current, currentMove, progress, BattleState.PLAYER, PLAYER_SPRITE, ENEMY_SPRITE),
			playerSettled, playerMirror, playerChat);
		drawPetInfo(g, player, WIDTH - 150, 92, true);

		// Attack effects and hit splats ride the current event
		if (current != null)
		{
			Rectangle attackerRect = spriteRect(current.getSide());
			Rectangle defenderRect = spriteRect(BattleState.opponent(current.getSide()));
			AttackAnimator.drawEffects(g, current, currentMove, progress, attackerRect, defenderRect);
			drawEventEffects(g, current, progress);
		}

		List<Button> newButtons = new ArrayList<>();
		if (session.getPhase() == BattleSession.Phase.ANIMATING)
		{
			// Turn is resolving: no move grid, just a wide dialog box with the current line
			drawDialogBox(g);
		}
		else
		{
			// Buttons
			int btnY = HEIGHT - 44;
			if (session.getPhase() == BattleSession.Phase.FORCED_SWITCH)
			{
				// Active pet fainted: a replacement must be chosen before play resumes
				g.setFont(FontManager.getRunescapeSmallFont());
				g.setColor(new Color(240, 210, 120));
				g.drawString("Send out your next pet!", 12, btnY - 4);
				drawSwapMenu(g, state, btnY, newButtons, SwapMode.FORCED);
			}
			else if (session.getPhase() == BattleSession.Phase.FREE_SWITCH)
			{
				// Enemy just sent in a replacement after a KO: offer one cost-free swap. The rows
				// start a little higher than the usual button strip so the inline "Keep" option
				// beneath the bench pets (up to two) still clears the bottom edge — worst case is
				// three 22px rows from here ending at ~240 of the 250-tall overlay.
				int freeTop = 178;
				g.setFont(FontManager.getRunescapeSmallFont());
				g.setColor(new Color(240, 210, 120));
				g.drawString(clip(g, enemy.getDisplayName() + " is up! Switch pets free?", WIDTH - 24),
					12, freeTop - 6);
				drawSwapMenu(g, state, freeTop, newButtons, SwapMode.FREE);
			}
			else if (session.getPhase() == BattleSession.Phase.LEARN_MOVE)
			{
				// A pet levelled into a new move with a full moveset: forget one or skip
				drawLearnPrompt(g, btnY, newButtons);
			}
			else if (swapMenuOpen && session.isAwaitingInput())
			{
				drawSwapMenu(g, state, btnY, newButtons, SwapMode.VOLUNTARY);
			}
			else
			{
				swapMenuOpen = false;
				boolean enabled = session.isAwaitingInput();
				List<MoveDef> moves = player.getMoves();
				// Taller 2x2 move cards filling the space freed by the removed log strip; each
				// card shows power/accuracy and the type match-up against the current enemy.
				int gridTop = 162;
				int bw = (WIDTH - 24 - 8) / 2;
				int bh = 38;
				int stride = bh + 6;
				for (int i = 0; i < 4; i++)
				{
					int col = i % 2;
					int row = i / 2;
					Rectangle r = new Rectangle(12 + col * (bw + 8), gridTop + row * stride, bw, bh);
					if (i < moves.size())
					{
						drawMoveCard(g, r, moves.get(i), enabled, enemy);
						newButtons.add(new Button(r, "move:" + i));
					}
					else
					{
						drawButton(g, r, "—", false, null);
					}
				}
				Rectangle swap = new Rectangle(WIDTH - 118, 4, 54, 14);
				boolean canSwap = enabled && hasBenchTarget(state);
				drawButton(g, swap, "Swap", canSwap, null);
				if (canSwap)
				{
					newButtons.add(new Button(swap, "swapmenu"));
				}
				Rectangle flee = new Rectangle(WIDTH - 60, 4, 50, 14);
				drawButton(g, flee, "Run", enabled, null);
				newButtons.add(new Button(flee, "flee"));
			}
		}
		synchronized (this)
		{
			buttons.clear();
			buttons.addAll(newButtons);
		}

		return new Dimension(WIDTH, HEIGHT);
	}

	/**
	 * Post-battle summary: the outcome headline, then a dedicated slot for every pet on the
	 * battle team — its icon, ending HP, XP gained and any level-ups / moves learned — and a
	 * Close button. Level-up fireworks play over the pet's own icon here, so the celebration
	 * always lands on the pet that actually grew rather than whoever was last on the field.
	 */
	private void drawSummary(Graphics2D g, BattleState state, List<Button> newButtons)
	{
		BattleState.Phase phase = state.getPhase();
		String headline;
		Color headlineColor;
		if (phase == BattleState.Phase.PLAYER_WON)
		{
			headline = "Victory!";
			headlineColor = HP_GREEN;
		}
		else if (phase == BattleState.Phase.FLED)
		{
			headline = "You fled the battle";
			headlineColor = HP_YELLOW;
		}
		else
		{
			headline = "Defeat...";
			headlineColor = HP_RED;
		}
		g.setFont(FontManager.getRunescapeBoldFont());
		g.setColor(headlineColor);
		FontMetrics hm = g.getFontMetrics();
		g.drawString(headline, (WIDTH - hm.stringWidth(headline)) / 2, 36);

		List<BattleSession.SummaryEntry> entries = session.getSummary();
		int top = 44;
		int bottom = HEIGHT - 40;
		if (entries.isEmpty())
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			g.setColor(LOG_TEXT);
			g.drawString("No pets took part.", 16, top + 12);
		}
		else
		{
			int slotH = Math.min(58, (bottom - top) / entries.size());
			int y = top;
			for (BattleSession.SummaryEntry e : entries)
			{
				drawSummarySlot(g, e, y, slotH);
				y += slotH;
			}
		}

		Rectangle close = new Rectangle(WIDTH / 2 - 40, HEIGHT - 32, 80, 24);
		drawButton(g, close, "Close", true, null);
		newButtons.add(new Button(close, "close"));
	}

	/**
	 * One pet's dedicated summary slot: growth-stage icon on the left, then name/level, an
	 * HP bar and a status/rewards line. Pets that levelled up get a looping firework burst
	 * over their icon.
	 */
	private void drawSummarySlot(Graphics2D g, BattleSession.SummaryEntry e, int y, int slotH)
	{
		int cardH = slotH - 4;
		g.setColor(new Color(0, 0, 0, 90));
		g.fillRoundRect(8, y, WIDTH - 16, cardH, 6, 6);

		// Icon slot on the left
		int iconSize = Math.min(40, cardH - 8);
		int iconX = 14;
		int iconY = y + (cardH - iconSize) / 2;
		Rectangle iconRect = new Rectangle(iconX, iconY, iconSize, iconSize);
		g.setColor(new Color(255, 255, 255, 18));
		g.fillRoundRect(iconX, iconY, iconSize, iconSize, 4, 4);
		Image img = sprites.itemImage(e.getDisplayItemId());
		if (img != null)
		{
			// A knocked-out or benched pet's icon is dimmed to read as "out of the fight".
			float iconAlpha = e.isFainted() ? 0.3f : e.isFought() ? 1f : 0.5f;
			Composite prev = g.getComposite();
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, iconAlpha));
			g.drawImage(img, iconX, iconY, iconSize, iconSize, null);
			g.setComposite(prev);
		}

		int textX = iconX + iconSize + 8;
		int textRight = WIDTH - 14;
		int textW = textRight - textX;

		// Name + level line
		g.setFont(FontManager.getRunescapeSmallFont());
		g.setColor(Color.WHITE);
		String name = e.getName() + "  Lv" + e.getLevel() + (e.getLevelsGained() > 0 ? " ▲" : "");
		g.drawString(clip(g, name, textW - 46), textX, y + 13);

		// XP gained, right-aligned on the name line
		if (e.getXpGained() > 0)
		{
			g.setColor(new Color(150, 220, 150));
			String xp = "+" + e.getXpGained() + " XP";
			g.drawString(xp, textRight - g.getFontMetrics().stringWidth(xp), y + 13);
		}

		// HP bar
		int barY = y + 18;
		double frac = e.getMaxHp() > 0 ? (double) e.getCurrentHp() / e.getMaxHp() : 0;
		g.setColor(new Color(40, 40, 40));
		g.fillRect(textX, barY, textW, 5);
		g.setColor(e.isFainted() ? HP_RED : hpColor(frac));
		g.fillRect(textX, barY, (int) (textW * Math.max(0, frac)), 5);

		// Status / rewards line: HP text on the right, level-up + moves note on the left
		int lineY = barY + 17;
		g.setFont(FontManager.getRunescapeSmallFont());
		String hp = e.isFainted() ? "Knocked out"
			: !e.isFought() ? "Didn't battle"
			: e.getCurrentHp() + " / " + e.getMaxHp() + " HP";
		g.setColor(e.isFainted() ? HP_RED : LOG_TEXT);
		int hpW = g.getFontMetrics().stringWidth(hp);
		g.drawString(hp, textRight - hpW, lineY);

		if (e.getLevelsGained() > 0 || !e.getLearnedMoves().isEmpty())
		{
			StringBuilder note = new StringBuilder();
			if (e.getLevelsGained() > 0)
			{
				note.append("Grew ").append(e.getLevelsGained()).append(e.getLevelsGained() == 1 ? " level" : " levels");
			}
			if (!e.getLearnedMoves().isEmpty())
			{
				note.append(note.length() > 0 ? ", learned " : "Learned ").append(String.join(", ", e.getLearnedMoves()));
			}
			g.setColor(new Color(210, 200, 160));
			g.drawString(clip(g, note.toString(), textW - hpW - 6), textX, lineY);
		}

		// Looping level-up fireworks over this pet's own icon
		if (e.getLevelsGained() > 0)
		{
			float progress = (System.currentTimeMillis() % 1300L) / 1300f;
			ParticleBurst.render(g, iconRect, progress, e.getLevel(), ParticleBurst.FIREWORKS);
		}
	}

	private static boolean hasBenchTarget(BattleState state)
	{
		List<BattlePet> team = state.team(BattleState.PLAYER);
		for (int i = 0; i < team.size(); i++)
		{
			if (i != state.activeIndex(BattleState.PLAYER) && !team.get(i).isFainted())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Which flavour of bench picker is on screen: a mandatory replacement after the player's own
	 * pet fainted (FORCED, no decline), a voluntary mid-turn swap that costs the turn (VOLUNTARY,
	 * "Back" to cancel), or the cost-free post-KO swap (FREE, "Keep" to decline).
	 */
	private enum SwapMode { FORCED, VOLUNTARY, FREE }

	/**
	 * Bench picker shown in place of the move grid: each healthy bench pet with its
	 * offensive type match-up against the current enemy. The mode decides which action the rows
	 * submit and whether a decline button is shown (see {@link SwapMode}).
	 */
	private void drawSwapMenu(Graphics2D g, BattleState state, int btnY, List<Button> newButtons, SwapMode mode)
	{
		BattlePet enemy = state.active(BattleState.ENEMY);
		List<BattlePet> team = state.team(BattleState.PLAYER);
		int active = state.activeIndex(BattleState.PLAYER);
		int rowY = btnY;
		for (int i = 0; i < team.size(); i++)
		{
			if (i == active || team.get(i).isFainted())
			{
				continue;
			}
			BattlePet bench = team.get(i);
			double best = 0;
			for (PetType type : bench.getTypes())
			{
				best = Math.max(best, session.getTypeChart().effectiveness(type, enemy.getTypes()));
			}
			String label = bench.getDisplayName() + "  Lv" + bench.getLevel()
				+ "  " + bench.getCurrentHp() + "/" + bench.getMaxHp()
				+ "  hits " + String.format("%.1fx", best);
			Color accent = best >= 2.0 ? HP_GREEN : best <= 0.5 ? HP_RED : null;
			Rectangle r = new Rectangle(12, rowY, WIDTH - 24, 18);
			drawButton(g, r, label, true, accent);
			String prefix = mode == SwapMode.FORCED ? "forceswitch:"
				: mode == SwapMode.FREE ? "freeswitch:" : "switch:";
			newButtons.add(new Button(r, prefix + i));
			rowY += 22;
		}
		if (mode == SwapMode.VOLUNTARY)
		{
			Rectangle back = new Rectangle(WIDTH - 60, 4, 50, 14);
			drawButton(g, back, "Back", true, null);
			newButtons.add(new Button(back, "swapcancel"));
		}
		else if (mode == SwapMode.FREE)
		{
			// Decline sits inline as one more option row beneath the bench pets, so it reads as
			// part of the same "who's up next?" choice rather than a stray corner button.
			Rectangle keep = new Rectangle(12, rowY, WIDTH - 24, 18);
			drawButton(g, keep, "Keep current pet", true, null);
			newButtons.add(new Button(keep, "freeswitchcancel"));
		}
	}

	/**
	 * The forget-a-move chooser shown when a pet levels into a new move with all four slots
	 * full: a header naming the new move, the four current moves as "forget" buttons, and a
	 * "Keep moves" button to decline. Mirrors the move grid's layout and hit-test idiom.
	 */
	private void drawLearnPrompt(Graphics2D g, int btnY, List<Button> newButtons)
	{
		BattleSession.LearnPrompt prompt = session.getLearnPrompt();
		if (prompt == null)
		{
			return;
		}
		MoveDef newMove = prompt.getNewMove();
		String stats = newMove.getType().getDisplayName()
			+ (newMove.isStatusMove() ? ", status" : ", " + newMove.getPower() + " pow");
		g.setFont(FontManager.getRunescapeSmallFont());
		g.setColor(new Color(240, 210, 120));
		String header = prompt.getPetName() + " learns " + newMove.getName() + " [" + stats + "] - forget:";
		g.drawString(clip(g, header, WIDTH - 96), 12, btnY - 4);

		List<MoveDef> moves = prompt.getCurrentMoves();
		int bw = (WIDTH - 24 - 8) / 2;
		int bh = 18;
		for (int i = 0; i < 4; i++)
		{
			int col = i % 2;
			int row = i / 2;
			Rectangle r = new Rectangle(12 + col * (bw + 8), btnY + row * (bh + 4), bw, bh);
			if (i < moves.size())
			{
				MoveDef m = moves.get(i);
				drawButton(g, r, m.getName(), true, new Color(m.getType().getColorRgb()));
				newButtons.add(new Button(r, "learn:" + i));
			}
			else
			{
				drawButton(g, r, "—", false, null);
			}
		}
		Rectangle keep = new Rectangle(WIDTH - 84, 4, 74, 14);
		drawButton(g, keep, "Keep moves", true, null);
		newButtons.add(new Button(keep, "learnskip"));
	}

	/**
	 * Per-event effect layer: OSRS-style hit splats over the affected pet sprite.
	 */
	private void drawEventEffects(Graphics2D g, BattleEvent event, float progress)
	{
		switch (event.getType())
		{
			case DAMAGE:
			{
				Color color = event.getEffectiveness() >= 2.0 ? SPLAT_SUPER
					: event.getEffectiveness() <= 0.5 ? SPLAT_RESIST : SPLAT_RED;
				drawHitsplat(g, spriteRect(event.getSide()), String.valueOf(event.getValue()), color, progress);
				break;
			}
			case MISSED:
				// A whiff renders as the OSRS blue 0 splat on the would-be defender
				drawHitsplat(g, spriteRect(BattleState.opponent(event.getSide())), "0", SPLAT_BLUE, progress);
				break;
			case LEVEL_UP:
				// Deliberately no field fireworks here: the levelling pet may be benched, and
				// the field only shows the active pet. Level-ups are celebrated in the
				// post-battle summary, over the correct pet's slot (see drawSummarySlot).
				break;
			case HEALED:
				ParticleBurst.render(g, spriteRect(event.getSide()), progress,
					event.getValue(), ParticleBurst.SPARKLE);
				break;
			default:
				break;
		}
	}

	private static Rectangle spriteRect(int side)
	{
		return side == BattleState.PLAYER ? PLAYER_SPRITE : ENEMY_SPRITE;
	}

	/**
	 * HP-bar fill colour by remaining fraction: green &gt; 50%, yellow &gt; 20%, else red.
	 */
	private static Color hpColor(double frac)
	{
		return frac > 0.5 ? HP_GREEN : frac > 0.2 ? HP_YELLOW : HP_RED;
	}

	/**
	 * A four-lobed splat that pops in, holds, and fades over the animation progress.
	 */
	private void drawHitsplat(Graphics2D g, Rectangle target, String number, Color color, float progress)
	{
		// Pop in over the first 15%, fade out over the last 25%
		float scale = Math.min(1f, progress / 0.15f);
		float alpha = progress > 0.75f ? Math.max(0f, 1f - (progress - 0.75f) / 0.25f) : 1f;
		if (scale <= 0f || alpha <= 0f)
		{
			return;
		}
		int cx = target.x + target.width / 2;
		int cy = target.y + target.height / 2;
		int r = (int) (13 * scale);

		Color body = new Color(color.getRed(), color.getGreen(), color.getBlue(), (int) (230 * alpha));
		g.setColor(body);
		// Four overlapping lobes plus a centre give the classic splat silhouette
		g.fillOval(cx - r, cy - r / 2 - 2, r, r);
		g.fillOval(cx, cy - r / 2 - 2, r, r);
		g.fillOval(cx - r / 2 - 2, cy - r, r, r);
		g.fillOval(cx - r / 2 - 2, cy, r, r);
		g.fillOval(cx - r + 2, cy - r / 2, 2 * r - 4, r);

		g.setFont(FontManager.getRunescapeSmallFont());
		g.setColor(new Color(255, 255, 255, (int) (255 * alpha)));
		FontMetrics fm = g.getFontMetrics();
		g.drawString(number, cx - fm.stringWidth(number) / 2,
			cy + (fm.getAscent() - fm.getDescent()) / 2);
	}

	/**
	 * Quest-dialog style text box shown while the turn plays out. In manual-advance
	 * mode a blinking chevron invites the next click / Space press.
	 */
	private void drawDialogBox(Graphics2D g)
	{
		int boxY = 156;
		int boxH = HEIGHT - boxY - 8;
		g.setColor(new Color(0, 0, 0, 170));
		g.fillRoundRect(6, boxY, WIDTH - 12, boxH, 8, 8);
		g.setColor(PANEL_EDGE);
		g.setStroke(new BasicStroke(1));
		g.drawRoundRect(6, boxY, WIDTH - 12, boxH, 8, 8);

		BattleEvent event = session.getCurrentEvent();
		if (event != null)
		{
			g.setFont(FontManager.getRunescapeFont());
			g.setColor(LOG_TEXT);
			int textY = boxY + 22;
			for (String line : wrap(g, event.getText(), WIDTH - 40))
			{
				g.drawString(line, 16, textY);
				textY += 16;
				if (textY > boxY + boxH - 6)
				{
					break;
				}
			}
		}

		// Blinking "continue" chevron once the line's animation has played out
		if (session.isManualAdvance() && session.getAnimationProgress() >= 1f
			&& (System.currentTimeMillis() / 450) % 2 == 0)
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			g.setColor(new Color(240, 220, 120));
			g.drawString("▼", WIDTH - 26, boxY + boxH - 8);
		}
	}

	private static List<String> wrap(Graphics2D g, String text, int maxWidth)
	{
		FontMetrics fm = g.getFontMetrics();
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(candidate) > maxWidth && line.length() > 0)
			{
				lines.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(candidate);
			}
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

	private void drawPetInfo(Graphics2D g, BattlePet pet, int x, int y, boolean showExactHp)
	{
		int w = 140;
		g.setColor(new Color(0, 0, 0, 130));
		g.fillRoundRect(x, y, w, showExactHp ? 66 : 48, 8, 8);

		// Level (subtext) right-aligned, then the name (title) filling the rest of the top line
		g.setFont(Fonts.SUBTEXT);
		g.setColor(new Color(200, 190, 160));
		String lv = "Lv" + pet.getLevel();
		int lvW = g.getFontMetrics().stringWidth(lv);
		g.drawString(lv, x + w - lvW - 6, y + 15);
		g.setFont(Fonts.TITLE);
		g.setColor(Color.WHITE);
		g.drawString(clip(g, pet.getDisplayName(), w - lvW - 16), x + 6, y + 15);

		// Types — chip sized from the font metrics so the text sits centred inside it (native
		// RuneScape font metrics differ from a hardcoded box).
		g.setFont(Fonts.SUBTEXT);
		FontMetrics tfm = g.getFontMetrics();
		int chipTop = y + 19;
		int chipH = tfm.getAscent() + tfm.getDescent() + 2;
		int chipBaseline = chipTop + tfm.getAscent() + 1;
		int tx = x + 6;
		for (PetType type : pet.getTypes())
		{
			int tw = tfm.stringWidth(type.getDisplayName()) + 8;
			g.setColor(new Color(type.getColorRgb()));
			g.fillRoundRect(tx, chipTop, tw, chipH, 4, 4);
			g.setColor(Color.WHITE);
			g.drawString(type.getDisplayName(), tx + 4, chipBaseline);
			tx += tw + 4;
		}
		// Status tag
		if (pet.getStatus() != BattlePet.Status.NONE)
		{
			g.setColor(HP_RED);
			g.drawString(pet.getStatus().name(), tx + 2, chipBaseline);
		}

		// HP bar — drawn from the session's displayed HP, which lags the resolved model so the
		// bar drains in step with the hit-splat instead of snapping the instant a turn resolves.
		int barY = chipTop + chipH + 4;
		int barW = w - 12;
		float shownHp = session.displayHp(pet);
		double frac = pet.getMaxHp() > 0 ? Math.max(0, Math.min(1, shownHp / pet.getMaxHp())) : 0;
		g.setColor(new Color(40, 40, 40));
		g.fillRect(x + 6, barY, barW, 6);
		g.setColor(hpColor(frac));
		g.fillRect(x + 6, barY, (int) (barW * frac), 6);
		if (showExactHp)
		{
			g.setFont(Fonts.SUBTEXT);
			g.setColor(Color.WHITE);
			g.drawString(Math.max(0, Math.round(shownHp)) + " / " + pet.getMaxHp(), x + 6, barY + 20);
		}
	}

	/**
	 * Draw one pet into its sprite box. When {@code override} is non-null (the player's foreground
	 * chathead) it is used verbatim — already oriented to face right, so the {@code mirror} flag is
	 * ignored — and blitted with aspect preserved and bilinear smoothing, with any worn cosmetics
	 * placed on top of it. Otherwise the pet's item icon is used with the mirror flag and the
	 * overlay's nearest-neighbour pixel look.
	 *
	 * <p>Cosmetics ride the chathead only. The icon fallback and the far enemy are full-body art, so
	 * the head-finding measurement has no head to find and would sit a hat on a tail; a bare pet is
	 * a better miss than a wrong one.
	 */
	private void drawPetSprite(Graphics2D g, BattlePet pet, Rectangle rect, AttackAnimator.Transform t,
		boolean settledFaint, boolean mirror, PetChatheads.Chathead override)
	{
		int size = Math.round(rect.width * t.scale);
		int x = rect.x + t.dx + (rect.width - size) / 2;
		int y = rect.y + t.dy + (rect.height - size) / 2;
		Image img = override != null ? override.getImage() : sprites.itemImage(pet.getDisplayItemId());
		if (img == null)
		{
			return;
		}
		// A settled-fainted pet lingers as a faint ghost (no opaque dim box); otherwise the
		// transform alpha drives the mid-faint collapse and normal full opacity.
		float alpha = settledFaint ? 0.2f : t.alpha;
		Composite prev = null;
		if (alpha < 1f)
		{
			prev = g.getComposite();
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0f, alpha)));
		}
		if (override != null)
		{
			// Cosmetics are drawn inside this composite so they fade with the pet during a faint
			// rather than hanging in the air over a vanishing head.
			Rectangle placed = blitFit(g, override.getImage(), x, y, size);
			drawCosmetics(g, pet, override, placed);
		}
		else
		{
			blitSprite(g, img, x, y, size, mirror);
		}
		if (prev != null)
		{
			g.setComposite(prev);
		}
	}

	/**
	 * Place this pet's worn cosmetics on its drawn chathead. The anchors are normalised to the
	 * chathead image, so {@code placed} — where that image actually landed on screen — is the only
	 * transform needed, and the cosmetics track the pet through every lunge and recoil for free.
	 *
	 * <p>The chathead art is pre-oriented facing right and the override path ignores the mirror
	 * flag, so no anchor ever needs flipping.
	 */
	private void drawCosmetics(Graphics2D g, BattlePet pet, PetChatheads.Chathead chathead, Rectangle placed)
	{
		if (placed == null || (pet.getHeadCosmeticId() == null && pet.getFaceCosmeticId() == null))
		{
			return;
		}
		ChatheadAnchors.Anchors a = anchors.anchors(chathead.getKey(), pet.getSpecies().getId(),
			chathead.getImage());
		// Face first, then head: a hat brim should overlap glasses, never the other way round.
		drawCosmetic(g, pet.getFaceCosmeticId(), a.getFace(), placed, false);
		drawCosmetic(g, pet.getHeadCosmeticId(), a.getHead(), placed, true);
	}

	/**
	 * Draw one cosmetic at its anchor. {@code bottomAligned} distinguishes the two slots: a head
	 * cosmetic hangs its bottom edge on the anchor (so the hat meets the skull whatever its height),
	 * while a face cosmetic centres on it.
	 */
	private void drawCosmetic(Graphics2D g, String itemId, ChatheadAnchors.Anchor anchor,
		Rectangle placed, boolean bottomAligned)
	{
		if (itemId == null)
		{
			return;
		}
		EquipItemDef item = db.equipItem(itemId);
		BufferedImage art = item == null ? null : itemSprites.sprite(item.getSprite());
		if (art == null || art.getWidth() <= 0 || art.getHeight() <= 0)
		{
			return;
		}
		int w = Math.max(1, Math.round(placed.width * anchor.getWidth()));
		int h = Math.max(1, Math.round(w * (art.getHeight() / (float) art.getWidth())));
		int cx = placed.x + Math.round(placed.width * anchor.getX());
		int cy = placed.y + Math.round(placed.height * anchor.getY());
		int dx = cx - w / 2;
		int dy = bottomAligned ? cy - h : cy - h / 2;

		Object prevHint = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(art, dx, dy, w, h, null);
		if (prevHint != null)
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, prevHint);
		}
	}

	/**
	 * Blit an already-oriented image into a size×size box, preserving its aspect ratio (centred)
	 * and using bilinear scaling — chatheads are wider than tall and low-res, so squashing them to
	 * a square or hard-scaling them with nearest-neighbour would look poor.
	 *
	 * @return where the image actually landed, so callers can place things relative to it, or null
	 *         if there was nothing to draw
	 */
	private static Rectangle blitFit(Graphics2D g, Image img, int x, int y, int size)
	{
		int iw = img.getWidth(null);
		int ih = img.getHeight(null);
		if (iw <= 0 || ih <= 0)
		{
			return null;
		}
		float scale = Math.min((float) size / iw, (float) size / ih);
		int w = Math.max(1, Math.round(iw * scale));
		int h = Math.max(1, Math.round(ih * scale));
		int dx = x + (size - w) / 2;
		int dy = y + (size - h) / 2;
		Object prevHint = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(img, dx, dy, w, h, null);
		if (prevHint != null)
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, prevHint);
		}
		return new Rectangle(dx, dy, w, h);
	}

	/**
	 * Draw a sprite scaled into a size×size box, optionally mirrored horizontally (to flip a
	 * pet's facing). Uses the dest/src form so the mirror is a simple swap of the x extents.
	 */
	private static void blitSprite(Graphics2D g, Image img, int x, int y, int size, boolean mirror)
	{
		int iw = img.getWidth(null);
		int ih = img.getHeight(null);
		if (iw <= 0 || ih <= 0)
		{
			return;
		}
		if (mirror)
		{
			g.drawImage(img, x + size, y, x, y + size, 0, 0, iw, ih, null);
		}
		else
		{
			g.drawImage(img, x, y, x + size, y + size, 0, 0, iw, ih, null);
		}
	}

	/**
	 * A move choice card: the move name, a stats line (power/accuracy, or "Status"), a
	 * type-colour accent stripe, and the offensive match-up multiplier against the current
	 * enemy (green if super-effective, red if resisted). Hit-tested like a plain button.
	 */
	private void drawMoveCard(Graphics2D g, Rectangle r, MoveDef m, boolean enabled, BattlePet enemy)
	{
		boolean hover = enabled && hoverPoint != null && r.contains(hoverPoint);
		g.setColor(hover ? BUTTON_HOVER : BUTTON_BG);
		g.fillRoundRect(r.x, r.y, r.width, r.height, 6, 6);
		g.setColor(enabled ? BUTTON_EDGE : new Color(70, 70, 70));
		g.setStroke(new BasicStroke(1));
		g.drawRoundRect(r.x, r.y, r.width, r.height, 6, 6);

		// Type-colour accent stripe down the left edge
		g.setColor(new Color(m.getType().getColorRgb()));
		g.fillRect(r.x + 3, r.y + 3, 4, r.height - 6);

		int textX = r.x + 12;
		Color textColor = enabled ? Color.WHITE : new Color(140, 140, 140);
		Color subColor = enabled ? new Color(205, 200, 180) : new Color(120, 120, 120);

		// Name
		g.setFont(Fonts.TITLE);
		g.setColor(textColor);
		g.drawString(clip(g, m.getName(), r.width - 18), textX, r.y + 16);

		// Stats line: power (or "Status") + accuracy
		g.setFont(Fonts.SUBTEXT);
		g.setColor(subColor);
		String stats = (m.isStatusMove() ? "Status" : m.getPower() + " pow") + "  " + m.getAccuracy() + "%";
		g.drawString(stats, textX, r.y + 33);

		// Offensive match-up multiplier against the enemy (attacks only), right-aligned
		if (!m.isStatusMove() && enemy != null)
		{
			double eff = session.getTypeChart().effectiveness(m.getType(), enemy.getTypes());
			String effStr = "x" + trimEffectiveness(eff);
			g.setColor(!enabled ? new Color(120, 120, 120)
				: eff >= 2.0 ? HP_GREEN : eff <= 0.5 ? HP_RED : subColor);
			FontMetrics fm = g.getFontMetrics();
			g.drawString(effStr, r.x + r.width - fm.stringWidth(effStr) - 8, r.y + 33);
		}
	}

	/**
	 * Compact effectiveness multiplier text: whole numbers drop the decimal (2, 1), fractions
	 * keep it (0.5, 0.25).
	 */
	private static String trimEffectiveness(double eff)
	{
		return eff == Math.rint(eff) ? String.valueOf((int) eff) : String.valueOf(eff);
	}

	private void drawButton(Graphics2D g, Rectangle r, String label, boolean enabled, Color accent)
	{
		boolean hover = enabled && hoverPoint != null && r.contains(hoverPoint);
		g.setColor(hover ? BUTTON_HOVER : BUTTON_BG);
		g.fillRoundRect(r.x, r.y, r.width, r.height, 6, 6);
		g.setColor(enabled ? BUTTON_EDGE : new Color(70, 70, 70));
		g.setStroke(new BasicStroke(1));
		g.drawRoundRect(r.x, r.y, r.width, r.height, 6, 6);
		if (accent != null)
		{
			g.setColor(accent);
			g.fillRect(r.x + 3, r.y + 3, 4, r.height - 6);
		}
		g.setFont(FontManager.getRunescapeSmallFont());
		g.setColor(enabled ? Color.WHITE : new Color(140, 140, 140));
		FontMetrics fm = g.getFontMetrics();
		String text = clip(g, label, r.width - 14);
		g.drawString(text, r.x + (r.width - fm.stringWidth(text)) / 2 + (accent != null ? 3 : 0),
			r.y + (r.height + fm.getAscent() - fm.getDescent()) / 2);
	}

	private static String clip(Graphics2D g, String text, int maxWidth)
	{
		FontMetrics fm = g.getFontMetrics();
		if (fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		String ellipsis = "…";
		StringBuilder sb = new StringBuilder();
		for (char c : text.toCharArray())
		{
			if (fm.stringWidth(sb.toString() + c + ellipsis) > maxWidth)
			{
				break;
			}
			sb.append(c);
		}
		return sb + ellipsis;
	}
}

package com.petbattles.ui;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.reflect.TypeToken;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

/**
 * Works out where a cosmetic sits on a pet chathead.
 *
 * <p>There are 164 chatheads and no two heads are the same shape, so the placement is derived from
 * the art itself rather than hand-authored: one pass over the alpha channel finds the head, and the
 * two anchors fall out of it. This works because a chathead render <em>is</em> a head — there's no
 * body to confuse the measurements.
 *
 * <p>The trick that makes it generalise is measuring the opaque width <em>at the anchor's own
 * row</em> rather than across the whole image. Sizing sunglasses to the head's width at the eye line
 * shrinks them onto a beaver's narrow snout and widens them across a bloodhound's jowls, with no
 * per-species data. Eye <em>detection</em> is not attempted and would not survive this many art
 * styles; instead the eye line is taken as a fixed fraction of head height, which holds up because
 * OSRS chatheads are consistently framed.
 *
 * <p>Note that the bundled chatheads are all cropped tight to the art, so in practice the bounding
 * box comes out as the whole image. The scan is still done rather than assumed: it costs one pass
 * per image at load, it's what makes the per-row widths available, and art added later (or exported
 * by a different hand) is under no obligation to stay trimmed.
 *
 * <p>Expect a good-not-perfect result. Run {@code ./gradlew previewCosmetics} to see every
 * chathead/cosmetic pairing on one page, and correct whatever lands wrong by hand in
 * {@code chathead_anchors.json}, which overrides individual fields on top of the derived values —
 * see {@link #anchors(String, String, BufferedImage)} for how keys resolve.
 */
@Slf4j
public class ChatheadAnchors
{
	private static final String OVERRIDES = "/com/petbattles/data/chathead_anchors.json";

	/** Alpha at or below this counts as transparent — art edges are often faintly feathered. */
	private static final int ALPHA_FLOOR = 8;

	/** The top slice of the head averaged into the crown anchor's x. */
	private static final float CROWN_BAND = 0.15f;

	/**
	 * How far a hat's base sits below the crown, as a fraction of the <em>skull width</em> that sized
	 * it. Measured against width rather than head height on purpose: a hat's drawn height scales with
	 * the width it's given, so its overlap has to scale with the same number or the two drift apart.
	 * Against head height, a wide flat head (a beaver, a mole) gets a big hat and almost no sink, and
	 * the hat floats off the top of the skull.
	 *
	 * <p>Some sink is always wanted — a hat resting exactly on the outline reads as hovering, and on
	 * an eared pet the crown is an ear tip rather than the skull.
	 */
	private static final float CROWN_SINK = 0.16f;

	/** The row whose width sizes a head cosmetic: the upper skull, not the widest point. */
	private static final float SKULL_ROW = 0.25f;

	/** Eye line as a fraction of head height, measured down from the crown. */
	private static final float EYE_ROW = 0.40f;

	/**
	 * Head cosmetic width as a fraction of the skull width at {@link #SKULL_ROW}. Well under 1: a hat
	 * as wide as the skull is drawn correspondingly tall and towers off the top of the sprite box.
	 */
	private static final float HEAD_WIDTH = 0.62f;

	/** Face cosmetic width as a fraction of the head width at the eye line. */
	private static final float FACE_WIDTH = 0.52f;

	/**
	 * Where one cosmetic goes, in coordinates normalised to the chathead image (0..1 of its width
	 * and height) so the numbers survive the art being re-exported at another resolution and are
	 * readable when hand-tuned.
	 *
	 * <p>{@link #x} is always the horizontal centre. {@link #y} means different things per slot, in
	 * each case the edge that should touch the head: for a HEAD cosmetic it is where the
	 * <em>bottom</em> of the hat sits; for a FACE cosmetic it is the <em>centre</em> of the item.
	 */
	public static class Anchor
	{
		private final float x;
		private final float y;
		private final float width;

		public Anchor(float x, float y, float width)
		{
			this.x = x;
			this.y = y;
			this.width = width;
		}

		public float getX()
		{
			return x;
		}

		public float getY()
		{
			return y;
		}

		/** Drawn width of the cosmetic, as a fraction of the chathead image's width. */
		public float getWidth()
		{
			return width;
		}
	}

	/** Both cosmetic anchors for one chathead image. Never null, even for unreadable art. */
	public static class Anchors
	{
		private final Anchor head;
		private final Anchor face;

		Anchors(Anchor head, Anchor face)
		{
			this.head = head;
			this.face = face;
		}

		public Anchor getHead()
		{
			return head;
		}

		public Anchor getFace()
		{
			return face;
		}
	}

	/** JSON shape of a hand-tuned override. Any absent field keeps the derived value. */
	private static class AnchorOverride
	{
		private Float x;
		private Float y;
		private Float width;
	}

	private static class Override
	{
		private AnchorOverride head;
		private AnchorOverride face;
	}

	private final Map<String, Override> overrides;

	// Keyed by the chathead key the image resolved from, so each image is measured once.
	private final Map<String, Anchors> cache = new HashMap<>();

	public ChatheadAnchors(Gson gson)
	{
		this(gson, OVERRIDES);
	}

	/** Visible for testing: read the correction sheet from somewhere other than the bundled path. */
	ChatheadAnchors(Gson gson, String overridesResource)
	{
		this.overrides = loadOverrides(gson, overridesResource);
	}

	/**
	 * Anchors for a chathead, derived from its alpha channel and then patched by any hand-tuned
	 * override. Overrides are looked up by the key the image actually resolved from first (so a
	 * single variant or growth stage can be corrected on its own), then by bare species id (so one
	 * entry can cover every form of a pet). Results are cached per key — the alpha scan runs once
	 * per image, never per frame.
	 *
	 * @param key       the chathead key the image resolved from, e.g. {@code cat__black__kitten}
	 * @param speciesId the species id, used as the fallback override key
	 * @param image     the chathead art to measure
	 */
	public synchronized Anchors anchors(String key, String speciesId, BufferedImage image)
	{
		Anchors cached = cache.get(key);
		if (cached != null)
		{
			return cached;
		}
		Anchors derived = derive(image);
		Override o = overrides.get(key);
		if (o == null)
		{
			o = overrides.get(speciesId);
		}
		Anchors result = o == null ? derived : new Anchors(
			patch(derived.getHead(), o.head), patch(derived.getFace(), o.face));
		cache.put(key, result);
		return result;
	}

	/** Apply an override's present fields on top of a derived anchor. */
	private static Anchor patch(Anchor base, AnchorOverride o)
	{
		if (o == null)
		{
			return base;
		}
		return new Anchor(
			o.x == null ? base.getX() : o.x,
			o.y == null ? base.getY() : o.y,
			o.width == null ? base.getWidth() : o.width);
	}

	/**
	 * Measure a chathead: find the head's alpha bounding box, then place the crown and eye-line
	 * anchors within it. Unreadable or fully transparent art falls back to whole-image guesses so a
	 * cosmetic still draws somewhere sane rather than vanishing.
	 */
	private static Anchors derive(BufferedImage image)
	{
		int w = image == null ? 0 : image.getWidth();
		int h = image == null ? 0 : image.getHeight();
		if (w <= 0 || h <= 0)
		{
			return fallback();
		}

		int minX = w;
		int minY = h;
		int maxX = -1;
		int maxY = -1;
		// Opaque extents per row, so a cosmetic can be sized against the head's width at its own
		// height rather than against the whole bounding box.
		int[] rowMin = new int[h];
		int[] rowMax = new int[h];
		for (int y = 0; y < h; y++)
		{
			rowMin[y] = w;
			rowMax[y] = -1;
			for (int x = 0; x < w; x++)
			{
				if ((image.getRGB(x, y) >>> 24) <= ALPHA_FLOOR)
				{
					continue;
				}
				if (x < rowMin[y])
				{
					rowMin[y] = x;
				}
				rowMax[y] = x;
			}
			if (rowMax[y] < 0)
			{
				continue;
			}
			minX = Math.min(minX, rowMin[y]);
			maxX = Math.max(maxX, rowMax[y]);
			minY = Math.min(minY, y);
			maxY = y;
		}
		if (maxY < 0)
		{
			return fallback();
		}

		int headH = maxY - minY + 1;
		int headW = maxX - minX + 1;

		// Crown x: the centroid of the top band, not the bounding box centre. On an asymmetric head
		// the box centre drifts toward whichever side has the longer ear; the band centroid stays on
		// the skull, which is where a hat belongs.
		int bandBottom = Math.min(maxY, minY + Math.max(0, Math.round(headH * CROWN_BAND)));
		long sum = 0;
		long count = 0;
		for (int y = minY; y <= bandBottom; y++)
		{
			if (rowMax[y] < 0)
			{
				continue;
			}
			int rowWidth = rowMax[y] - rowMin[y] + 1;
			sum += (long) (rowMin[y] + rowMax[y]) * rowWidth;
			count += 2L * rowWidth;
		}
		float crownX = count > 0 ? sum / (float) count : minX + headW / 2f;
		float skullW = rowWidth(rowMin, rowMax, clampRow(minY + headH * SKULL_ROW, minY, maxY), headW);
		// Clamped into the head so a very wide, very flat face can't sink the hat out through the jaw.
		float crownY = Math.min(minY + skullW * CROWN_SINK, minY + headH * 0.5f);

		// Eye line: a fixed fraction down the head. Its x follows that row's own centre so heads
		// drawn at an angle keep their glasses on the face rather than off to one side.
		int eyeRow = clampRow(minY + headH * EYE_ROW, minY, maxY);
		float eyeW = rowWidth(rowMin, rowMax, eyeRow, headW);
		float eyeX = rowMax[eyeRow] >= 0
			? (rowMin[eyeRow] + rowMax[eyeRow]) / 2f
			: minX + headW / 2f;

		return new Anchors(
			new Anchor(crownX / w, crownY / h, (skullW * HEAD_WIDTH) / w),
			new Anchor(eyeX / w, eyeRow / (float) h, (eyeW * FACE_WIDTH) / w));
	}

	/** Opaque width on a row, falling back to the head's full width for a fully transparent one. */
	private static float rowWidth(int[] rowMin, int[] rowMax, int row, int headW)
	{
		return rowMax[row] >= 0 ? rowMax[row] - rowMin[row] + 1 : headW;
	}

	private static int clampRow(float row, int min, int max)
	{
		return Math.max(min, Math.min(max, Math.round(row)));
	}

	/** Centred guesses for art we couldn't measure, so a cosmetic still lands roughly right. */
	private static Anchors fallback()
	{
		return new Anchors(new Anchor(0.5f, 0.10f, 0.5f), new Anchor(0.5f, 0.40f, 0.5f));
	}

	/**
	 * Hand-tuned overrides bundled alongside the other content. Absent or unreadable means "derive
	 * everything" — the file is a correction sheet, not a requirement, so a bad edit degrades to the
	 * automatic placement instead of breaking the battle scene.
	 *
	 * <p>Entries are converted one at a time and keys starting with {@code _} are skipped, so the
	 * file can carry its own documentation and one malformed entry costs only that pet's tuning
	 * rather than every other correction in the file.
	 */
	private static Map<String, Override> loadOverrides(Gson gson, String resource)
	{
		Map<String, Override> parsed = new LinkedHashMap<>();
		try (InputStream in = ChatheadAnchors.class.getResourceAsStream(resource))
		{
			if (in == null)
			{
				return parsed;
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				Map<String, JsonElement> raw = gson.fromJson(reader,
					new TypeToken<Map<String, JsonElement>>()
					{
					}.getType());
				if (raw == null)
				{
					return parsed;
				}
				for (Map.Entry<String, JsonElement> e : raw.entrySet())
				{
					if (e.getKey().startsWith("_"))
					{
						continue;
					}
					try
					{
						Override o = gson.fromJson(e.getValue(), Override.class);
						if (o != null)
						{
							parsed.put(e.getKey(), o);
						}
					}
					catch (RuntimeException bad)
					{
						log.debug("Ignoring malformed chathead anchor override for {}", e.getKey(), bad);
					}
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Could not read chathead anchor overrides; using derived placement only", e);
		}
		return parsed;
	}
}

package com.petbattles.ui;

import java.awt.Font;
import net.runelite.client.ui.FontManager;

/**
 * Shared fonts for the plugin's custom-drawn overlays, so titles and subtext read consistently
 * everywhere and can be swapped in one place. These use the RuneLite RuneScape fonts at their
 * NATIVE size: they are pixel fonts and render cleanly only at native size — deriving them to
 * other sizes (e.g. 15f/18f) gives uneven, gappy letter spacing. Bold reads as the title tier,
 * the regular font as the (slightly lighter, same-height) subtext tier.
 */
final class Fonts
{
	private Fonts()
	{
	}

	/** Primary / heading text: pet names, move names, headlines. */
	public static final Font TITLE = FontManager.getRunescapeBoldFont();
	/** Secondary text: stats, hints, HP numbers, type chips. */
	public static final Font SUBTEXT = FontManager.getRunescapeFont();
}

package com.petbattles.ui;

import com.petbattles.data.PetDatabase;
import com.petbattles.engine.PetInstance;
import com.petbattles.engine.TrainerDef;
import com.petbattles.item.EquipItemDef;
import com.petbattles.persist.RosterManager;
import java.util.function.Consumer;

/**
 * Maps a hub button's action string to a state change on a {@link HubView} or a roster mutation /
 * callback. Rendering-agnostic and thread-agnostic: {@link RosterManager} is fully synchronised, so
 * this is safe to call from the overlay's client thread or the panel's EDT. The client-touching
 * callbacks ({@code fight} / {@code locate} / {@code examine}) are expected to marshal themselves
 * onto the client thread. Shared by both hub surfaces ({@link HubInputHandler} and {@link HubPanel}).
 */
public class HubActions
{
	private final HubView view;
	private final PetDatabase db;
	private final RosterManager roster;
	private final Consumer<String> fightAction;
	private final Consumer<String> locateAction;
	private final Consumer<String> examineAction;
	private final Runnable onRest;

	public HubActions(HubView view, PetDatabase db, RosterManager roster,
		Consumer<String> fightAction, Consumer<String> locateAction, Consumer<String> examineAction,
		Runnable onRest)
	{
		this.view = view;
		this.db = db;
		this.roster = roster;
		this.fightAction = fightAction;
		this.locateAction = locateAction;
		this.examineAction = examineAction;
		this.onRest = onRest;
	}

	public void dispatch(String action)
	{
		// Any hub action other than typing into / clearing the search field drops its focus.
		if (!"trainers.search.focus".equals(action) && !"trainers.search.clear".equals(action))
		{
			view.blurSearch();
		}
		if ("chip".equals(action) || "menu".equals(action))
		{
			view.openMenu();
		}
		else if ("collapse".equals(action))
		{
			view.collapse();
		}
		else if ("open:team".equals(action))
		{
			view.openPane(HubView.Pane.TEAM);
		}
		else if ("open:challenge".equals(action))
		{
			view.openPane(HubView.Pane.CHALLENGE);
		}
		else if ("open:trainers".equals(action))
		{
			view.openPane(HubView.Pane.TRAINERS);
		}
		else if ("open:quests".equals(action))
		{
			view.openPane(HubView.Pane.QUESTS);
		}
		else if (action.startsWith("open:quest:"))
		{
			view.openQuest(action.substring("open:quest:".length()));
		}
		else if ("open:items".equals(action))
		{
			view.openPane(HubView.Pane.ITEMS);
		}
		else if ("open:store".equals(action))
		{
			view.openPane(HubView.Pane.STORE);
		}
		else if ("open:dev".equals(action))
		{
			view.openPane(HubView.Pane.DEV);
		}
		else if ("open:devpets".equals(action))
		{
			view.openPane(HubView.Pane.DEVPETS);
		}
		else if ("devpets.page:1".equals(action))
		{
			view.devPetsPage(+1);
		}
		else if ("devpets.page:-1".equals(action))
		{
			view.devPetsPage(-1);
		}
		else if (action.startsWith("open:pet:"))
		{
			view.openPet(action.substring("open:pet:".length()));
		}
		else if (action.startsWith("equip.open:"))
		{
			view.openEquip(action.substring("equip.open:".length()));
		}
		else if (action.startsWith("store.buy:"))
		{
			buy(action.substring("store.buy:".length()));
		}
		else if ("store.page:1".equals(action))
		{
			view.storePage(+1);
		}
		else if ("store.page:-1".equals(action))
		{
			view.storePage(-1);
		}
		else if (action.startsWith("pet.held.clear:"))
		{
			roster.clearHeldItem(action.substring("pet.held.clear:".length()));
		}
		else if (action.startsWith("pet.held:"))
		{
			String[] parts = action.substring("pet.held:".length()).split(":", 2);
			if (parts.length == 2)
			{
				roster.setHeldItem(parts[0], parts[1]);
			}
		}
		else if (action.startsWith("pet.cosmetic.clear:"))
		{
			String[] parts = action.substring("pet.cosmetic.clear:".length()).split(":", 2);
			if (parts.length == 2)
			{
				clearCosmetic(parts[0], parts[1]);
			}
		}
		else if (action.startsWith("pet.cosmetic:"))
		{
			String[] parts = action.substring("pet.cosmetic:".length()).split(":", 2);
			if (parts.length == 2)
			{
				roster.setCosmetic(parts[0], parts[1]);
			}
		}
		else if (action.startsWith("pet.move:"))
		{
			String[] parts = action.substring("pet.move:".length()).split(":", 2);
			if (parts.length == 2)
			{
				toggleMove(parts[0], parts[1]);
			}
		}
		else if (action.startsWith("dev.unlock:"))
		{
			roster.devUnlock(action.substring("dev.unlock:".length()));
		}
		else if (action.startsWith("dev.lock:"))
		{
			roster.devLock(action.substring("dev.lock:".length()));
		}
		else if (action.startsWith("dev.confirm:"))
		{
			view.armConfirm(action.substring("dev.confirm:".length()));
		}
		else if ("dev.cancel".equals(action))
		{
			view.clearConfirm();
		}
		else if (action.startsWith("dev.reset:"))
		{
			String key = action.substring("dev.reset:".length());
			if ("progression".equals(key))
			{
				roster.resetProgression();
			}
			else if ("quests".equals(key))
			{
				roster.resetQuests();
			}
			view.clearConfirm();
		}
		else if (action.startsWith("quest:"))
		{
			view.toggleQuest(action.substring(6));
		}
		else if (action.startsWith("trainers.filter:"))
		{
			String value = action.substring(16);
			if ("RANDOM".equals(value))
			{
				view.setRandomFilter();
			}
			else
			{
				view.setTrainerFilter("ALL".equals(value) ? null : TrainerDef.Difficulty.valueOf(value));
			}
		}
		else if ("trainers.page:1".equals(action))
		{
			view.trainersPage(+1);
		}
		else if ("trainers.page:-1".equals(action))
		{
			view.trainersPage(-1);
		}
		else if ("trainers.search.focus".equals(action))
		{
			view.focusSearch();
		}
		else if ("trainers.search.clear".equals(action))
		{
			view.clearSearch();
		}
		else if (action.startsWith("locate:"))
		{
			locateAction.accept(action.substring(7));
		}
		else if (action.startsWith("item.examine:"))
		{
			examineAction.accept(action.substring("item.examine:".length()));
		}
		else if (action.startsWith("team.remove:"))
		{
			roster.removeFromTeam(action.substring(12));
		}
		else if (action.startsWith("team.add:"))
		{
			roster.addToTeam(action.substring(9));
		}
		else if ("team.page:1".equals(action))
		{
			view.addPage(+1);
		}
		else if ("team.page:-1".equals(action))
		{
			view.addPage(-1);
		}
		else if ("rest".equals(action))
		{
			if (roster.restAllPets())
			{
				onRest.run();
			}
		}
		else if (action.startsWith("fight:"))
		{
			fightAction.accept(action.substring(6));
		}
		else if ("chal.page:1".equals(action))
		{
			view.challengePageDelta(+1);
		}
		else if ("chal.page:-1".equals(action))
		{
			view.challengePageDelta(-1);
		}
	}

	/** Buy one of a sold equip item: spend its price, then grant it. No-op if unknown/unaffordable. */
	private void buy(String itemId)
	{
		EquipItemDef item = db.equipItem(itemId);
		if (item != null && item.isSold() && roster.spendCoins(item.getPrice()))
		{
			roster.grantItem(item.getId(), 1);
		}
	}

	/** Clear a cosmetic slot named by the action string; ignores anything that isn't a real slot. */
	private void clearCosmetic(String speciesId, String slotName)
	{
		for (EquipItemDef.Slot slot : EquipItemDef.Slot.values())
		{
			if (slot.name().equals(slotName))
			{
				roster.clearCosmetic(speciesId, slot);
				return;
			}
		}
	}

	/** Toggle a move in the pet's loadout, keeping at least one equipped and at most the cap. */
	private void toggleMove(String speciesId, String moveId)
	{
		PetInstance pet = roster.getOrCreatePet(speciesId);
		if (pet == null)
		{
			return;
		}
		if (pet.getEquippedMoves().contains(moveId))
		{
			if (pet.getEquippedMoves().size() > 1)
			{
				pet.unequipMove(moveId);
				roster.petChanged();
			}
		}
		else if (pet.equipMove(moveId))
		{
			roster.petChanged();
		}
	}
}

package com.petbattles.ui;

import com.petbattles.battle.BattleSession;
import com.petbattles.persist.RosterManager;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.util.function.Supplier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseWheelListener;

/**
 * Routes canvas clicks on the floating {@link HubOverlay} to its {@link HubView}'s buttons,
 * mirroring {@link com.petbattles.battle.BattleInputHandler}. Mouse events arrive on the AWT
 * thread; overlay state changes and roster mutations are marshalled onto the client thread via
 * {@link HubActions}. Clicks that land on the hub are consumed so they don't leak into the world.
 * While a battle is running the hub is hidden, so nothing here fires.
 */
public class HubInputHandler extends MouseAdapter implements MouseWheelListener
{
	private final HubView view;
	private final HubActions actions;
	private final Supplier<Rectangle> bounds;
	private final RosterManager roster;
	private final BattleSession session;
	private final ClientThread clientThread;
	// The team species currently being dragged to reorder, or null. AWT-thread only.
	private String dragSpecies;
	// Overlay-local point where the drag began, for tap-vs-drag discrimination.
	private Point dragStart;

	public HubInputHandler(HubView view, HubActions actions, Supplier<Rectangle> bounds,
		RosterManager roster, BattleSession session, ClientThread clientThread)
	{
		this.view = view;
		this.actions = actions;
		this.bounds = bounds;
		this.roster = roster;
		this.session = session;
		this.clientThread = clientThread;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		// Hub is hidden during battle; Alt+click is overlay repositioning.
		if (session.isActive() || e.getButton() != MouseEvent.BUTTON1 || e.isAltDown())
		{
			return e;
		}
		Rectangle bnds = bounds.get();
		if (bnds == null || !bnds.contains(e.getPoint()))
		{
			return e;
		}
		Point local = new Point(e.getX() - bnds.x, e.getY() - bnds.y);
		for (HubView.Button button : view.getButtons())
		{
			if (button.rect.contains(local))
			{
				String action = button.action;
				if (action.startsWith("team.slot:"))
				{
					// Press on a team slot begins a drag-to-reorder; a tap (no movement) opens the
					// pet's detail pane on release instead.
					dragSpecies = action.substring("team.slot:".length());
					dragStart = local;
					view.beginTeamDrag(dragSpecies, local);
				}
				else
				{
					clientThread.invokeLater(() -> actions.dispatch(action));
				}
				break;
			}
		}
		// Swallow every click on the hub so it never falls through to the game world.
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		if (dragSpecies == null || session.isActive())
		{
			return e;
		}
		Rectangle bnds = bounds.get();
		if (bnds != null)
		{
			view.updateDragPoint(new Point(e.getX() - bnds.x, e.getY() - bnds.y));
		}
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		if (dragSpecies == null)
		{
			return e;
		}
		String dragged = dragSpecies;
		Point start = dragStart;
		dragSpecies = null;
		dragStart = null;
		view.endTeamDrag();
		Rectangle bnds = bounds.get();
		if (bnds != null)
		{
			Point local = new Point(e.getX() - bnds.x, e.getY() - bnds.y);
			if (start != null && local.distance(start) < 5)
			{
				// A tap opens the pet's detail pane rather than reordering.
				clientThread.invokeLater(() -> actions.dispatch("open:pet:" + dragged));
			}
			else
			{
				int index = view.teamDropIndex(local.x);
				clientThread.invokeLater(() -> roster.reorderTeamToIndex(dragged, index));
			}
		}
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		if (session.isActive())
		{
			view.setHoverPoint(null);
			return e;
		}
		Rectangle bnds = bounds.get();
		if (bnds != null && bnds.contains(e.getPoint()))
		{
			view.setHoverPoint(new Point(e.getX() - bnds.x, e.getY() - bnds.y));
		}
		else
		{
			view.setHoverPoint(null);
		}
		return e;
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e)
	{
		if (session.isActive())
		{
			return e;
		}
		Rectangle bnds = bounds.get();
		if (bnds == null || !bnds.contains(e.getPoint()) || !view.isScrollablePaneOpen())
		{
			return e;
		}
		int rotation = e.getWheelRotation();
		if (rotation != 0)
		{
			// Scroll the hovered pane's list instead of zooming the game camera underneath.
			clientThread.invokeLater(() -> view.scroll(rotation));
			e.consume();
		}
		return e;
	}
}

package com.petbattles.ui;

import com.petbattles.battle.BattleSession;
import java.awt.event.KeyEvent;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.KeyListener;

/**
 * Feeds typed characters into the hub's Trainers name-search box while it has focus. It only ever
 * reacts to real keypresses, and only while the box is focused — every key passes straight through
 * untouched otherwise, so it never steals input from the game (or generates any).
 */
public class HubKeyListener implements KeyListener
{
	private final HubView view;
	private final BattleSession session;
	private final ClientThread clientThread;

	public HubKeyListener(HubView view, BattleSession session, ClientThread clientThread)
	{
		this.view = view;
		this.session = session;
		this.clientThread = clientThread;
	}

	private boolean active()
	{
		return view.isSearchFocused() && !session.isActive();
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
		if (!active())
		{
			return;
		}
		char c = e.getKeyChar();
		if (c != KeyEvent.CHAR_UNDEFINED && c >= ' ' && !Character.isISOControl(c))
		{
			clientThread.invokeLater(() -> view.appendSearch(c));
			e.consume();
		}
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (!active())
		{
			return;
		}
		switch (e.getKeyCode())
		{
			case KeyEvent.VK_BACK_SPACE:
				clientThread.invokeLater(view::backspaceSearch);
				e.consume();
				break;
			case KeyEvent.VK_ESCAPE:
			case KeyEvent.VK_ENTER:
				clientThread.invokeLater(view::blurSearch);
				e.consume();
				break;
			default:
				break;
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
	}
}

package com.petbattles.ui;

