	private void drawButtonBg(Graphics2D g, Rectangle r, boolean enabled)
	{
		Point hp = hoverPoint;
		boolean hover = enabled && hp != null && r.contains(hp);
		g.setColor(hover ? BUTTON_HOVER : BUTTON_BG);
		g.fillRoundRect(r.x, r.y, r.width, r.height, 6, 6);
		g.setColor(enabled ? BUTTON_EDGE : BUTTON_DISABLED_EDGE);
		g.setStroke(new BasicStroke(1));
		g.drawRoundRect(r.x, r.y, r.width, r.height, 6, 6);
	}

	/**
	 * Draw an image scaled to fit within the box while preserving its aspect ratio,
	 * centred. No-op until an async item icon has loaded (width reported as -1).
	 */
	private void drawFit(Graphics2D g, Image img, int bx, int by, int bw, int bh)
	{
		if (img == null)
		{
			return;
		}
		int iw = img.getWidth(null);
		int ih = img.getHeight(null);
		if (iw <= 0 || ih <= 0)
		{
			return;
		}
		double scale = Math.min(bw / (double) iw, bh / (double) ih);
		int w = Math.max(1, (int) Math.round(iw * scale));
		int h = Math.max(1, (int) Math.round(ih * scale));
		g.drawImage(img, bx + (bw - w) / 2, by + (bh - h) / 2, w, h, null);
	}

	private void drawIcon(Graphics2D g, Rectangle r, Icon icon, Color color)
	{
		int cx = r.x + r.width / 2;
		int cy = r.y + r.height / 2;
		int s = 3;
		g.setColor(color);
		switch (icon)
		{
			case UP:
				g.fillPolygon(new int[]{cx, cx - s, cx + s}, new int[]{cy - s, cy + s, cy + s}, 3);
				break;
			case DOWN:
				g.fillPolygon(new int[]{cx, cx - s, cx + s}, new int[]{cy + s, cy - s, cy - s}, 3);
				break;
			case LEFT:
				g.fillPolygon(new int[]{cx - s, cx + s, cx + s}, new int[]{cy, cy - s, cy + s}, 3);
				break;
			case RIGHT:
				g.fillPolygon(new int[]{cx + s, cx - s, cx - s}, new int[]{cy, cy - s, cy + s}, 3);
				break;
			case CLOSE:
				g.setStroke(new BasicStroke(2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.drawLine(cx - s, cy - s, cx + s, cy + s);
				g.drawLine(cx - s, cy + s, cx + s, cy - s);
				break;
			case MENU:
				g.setStroke(new BasicStroke(1));
				g.drawLine(cx - s, cy - s, cx + s, cy - s);
				g.drawLine(cx - s, cy, cx + s, cy);
				g.drawLine(cx - s, cy + s, cx + s, cy + s);
				break;
			default:
				break;
		}
	}

	private List<SpeciesDef> availableToAdd(List<String> team)
	{
		List<SpeciesDef> out = new ArrayList<>();
		for (SpeciesDef species : db.allSpecies())
		{
			if (!team.contains(species.getId()) && roster.isOwned(species.getId()))
			{
				out.add(species);
			}
		}
		return out;
	}

	private List<TrainerDef> nearbyTrainers()
	{
		List<TrainerDef> out = new ArrayList<>();
		for (String id : nearTrainers.get())
		{
			TrainerDef trainer = db.trainer(id);
			if (trainer != null)
			{
				out.add(trainer);
			}
		}
		out.sort(Comparator.comparing(TrainerDef::getName));
		return out;
	}

	private void clearButtons()
	{
		synchronized (this)
		{
			buttons.clear();
		}
	}

	private static String clip(Graphics2D g, String text, int maxWidth)
	{
		FontMetrics fm = g.getFontMetrics();
		if (fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		String ellipsis = "…";
		StringBuilder sb = new StringBuilder();
		for (char c : text.toCharArray())
		{
			if (fm.stringWidth(sb.toString() + c + ellipsis) > maxWidth)
			{
				break;
			}
			sb.append(c);
		}
		return sb + ellipsis;
	}
}

package com.petbattles.ui;

import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.ImageUtil;

/**
 * Loads and caches the bundled equip-item art at {@code /com/petbattles/items/<sprite>.png} for
 * drawing onto pets.
 *
 * <p>Images come back <em>trimmed</em> to their opaque bounds. These are inventory icons, so each
 * sits in a differently-sized pocket of transparent padding; scaling the raw file to a target width
 * would make that padding part of the measurement and every cosmetic would land at its own
 * arbitrary size. Trimming first means a requested width is the width of the hat.
 */
@Slf4j
public class ItemSprites
{
	private static final String BASE = "/com/petbattles/items/";

	/** Alpha at or below this counts as padding, matching {@link ChatheadAnchors}. */
	private static final int ALPHA_FLOOR = 8;

	// Cache holds the trimmed image, or null once we've confirmed there's no resource.
	private final Map<String, BufferedImage> cache = new HashMap<>();

	/**
	 * The trimmed art for an item sprite name, or null if none is bundled (callers skip drawing).
	 */
	public synchronized BufferedImage sprite(String name)
	{
		if (name == null)
		{
			return null;
		}
		if (cache.containsKey(name))
		{
			return cache.get(name);
		}
		BufferedImage trimmed = null;
		String path = BASE + name + ".png";
		if (getClass().getResource(path) != null)
		{
			BufferedImage raw = ImageUtil.loadImageResource(getClass(), path);
			trimmed = raw == null ? null : trim(raw);
		}
		else
		{
			log.debug("No item sprite bundled at {}", path);
		}
		cache.put(name, trimmed);
		return trimmed;
	}

	/** Crop an image to its opaque bounds, or return it unchanged if it's blank or already tight. */
	private static BufferedImage trim(BufferedImage img)
	{
		int w = img.getWidth();
		int h = img.getHeight();
		int minX = w;
		int minY = h;
		int maxX = -1;
		int maxY = -1;
		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				if ((img.getRGB(x, y) >>> 24) <= ALPHA_FLOOR)
				{
					continue;
				}
				minX = Math.min(minX, x);
				maxX = Math.max(maxX, x);
				minY = Math.min(minY, y);
				maxY = y;
			}
		}
		if (maxX < 0 || (minX == 0 && minY == 0 && maxX == w - 1 && maxY == h - 1))
		{
			return img;
		}
		return img.getSubimage(minX, minY, maxX - minX + 1, maxY - minY + 1);
	}
}

package com.petbattles.ui;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;

/**
 * Stateless firework/sparkle burst: particles sit on parametric arcs driven purely by
 * an externally supplied 0→1 progress, so rendering is cheap and deterministic —
 * no per-frame state, no allocation beyond the loop locals.
 */
public final class ParticleBurst
{
	/** OSRS level-up firework palette. */
	public static final Color[] FIREWORKS = {
		new Color(255, 80, 60),
		new Color(255, 210, 60),
		new Color(90, 220, 90),
		new Color(90, 150, 255),
		new Color(240, 240, 240),
	};

	/** Soft white/gold sparkle, for heals and rests. */
	public static final Color[] SPARKLE = {
		new Color(255, 250, 210),
		new Color(255, 225, 130),
		new Color(220, 240, 255),
	};

	/** Warm embers, for fire bursts and explosions. */
	public static final Color[] EMBER = {
		new Color(255, 230, 120),
		new Color(255, 140, 40),
		new Color(230, 70, 30),
	};

	/** Pale blue/white ice, for shatters and blizzards. */
	public static final Color[] FROST = {
		new Color(210, 240, 255),
		new Color(150, 205, 240),
		new Color(255, 255, 255),
	};

	/** Sickly greens, for poison clouds and spores. */
	public static final Color[] TOXIN = {
		new Color(120, 200, 70),
		new Color(80, 150, 40),
		new Color(170, 220, 90),
	};

	/** Dark purple wisps, for soul drain and shadow magic. */
	public static final Color[] SHADOW = {
		new Color(150, 70, 190),
		new Color(90, 40, 130),
		new Color(200, 120, 230),
	};

	private ParticleBurst()
	{
	}

	/**
	 * Draw a burst centred on the target rect. Particles fly out on arcs with a little
	 * gravity droop and fade near the end. Same seed → same burst shape every frame.
	 */
	public static void render(Graphics2D g, Rectangle target, float progress, int seed, Color[] palette)
	{
		if (progress <= 0f || progress >= 1f)
		{
			return;
		}
		int cx = target.x + target.width / 2;
		int cy = target.y + target.height / 2;
		int count = 18;
		float alpha = progress > 0.6f ? 1f - (progress - 0.6f) / 0.4f : 1f;
		for (int i = 0; i < count; i++)
		{
			// Cheap deterministic per-particle variation from the seed
			int h = (seed * 31 + i) * 0x9E3779B9;
			double angle = 2 * Math.PI * i / count + ((h & 0xFF) / 255.0 - 0.5) * 0.5;
			double speed = 26 + ((h >>> 8) & 0x3F);
			double px = cx + Math.cos(angle) * speed * progress;
			double py = cy + Math.sin(angle) * speed * progress + 18 * progress * progress;
			Color base = palette[Math.floorMod(h >>> 16, palette.length)];
			g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), (int) (255 * alpha)));
			int size = ((h >>> 24) & 1) == 0 ? 3 : 2;
			g.fillRect((int) px, (int) py, size, size);
		}
	}
}

