package com.petbattles.ui;

import com.petbattles.quest.QuestDialogSession;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.function.Consumer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.MouseAdapter;

/**
 * Routes canvas clicks on the {@link QuestDialogOverlay} to its buttons, mirroring
 * {@link HubInputHandler}. Mouse events arrive on the AWT thread; conversation state changes are
 * marshalled onto the client thread. Clicks that land on the frame are consumed so they don't leak
 * into the world; when the frame is drawing nothing it has no buttons, so nothing here fires.
 */
public class QuestDialogInputHandler extends MouseAdapter
{
	private final QuestDialogOverlay overlay;
	private final QuestDialogSession dialog;
	private final ClientThread clientThread;
	private final Consumer<String> fightAction;

	public QuestDialogInputHandler(QuestDialogOverlay overlay, QuestDialogSession dialog,
		ClientThread clientThread, Consumer<String> fightAction)
	{
		this.overlay = overlay;
		this.dialog = dialog;
		this.clientThread = clientThread;
		this.fightAction = fightAction;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		// Alt+click is overlay repositioning. An empty button list means the frame drew nothing this
		// frame, so its bounds are stale and the click isn't ours.
		List<QuestDialogOverlay.Button> hits = overlay.getButtons();
		if (hits.isEmpty() || e.getButton() != MouseEvent.BUTTON1 || e.isAltDown())
		{
			return e;
		}
		Rectangle bounds = overlay.getBounds();
		if (bounds == null || !bounds.contains(e.getPoint()))
		{
			return e;
		}
		Point local = new Point(e.getX() - bounds.x, e.getY() - bounds.y);
		for (QuestDialogOverlay.Button button : hits)
		{
			if (button.rect.contains(local))
			{
				String action = button.action;
				clientThread.invokeLater(() -> dispatch(action));
				break;
			}
		}
		// Swallow every click on the frame so it never falls through to the game world.
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		Rectangle bounds = overlay.getButtons().isEmpty() ? null : overlay.getBounds();
		overlay.setHoverPoint(bounds != null && bounds.contains(e.getPoint())
			? new Point(e.getX() - bounds.x, e.getY() - bounds.y) : null);
		return e;
	}

	private void dispatch(String action)
	{
		if (QuestDialogSession.ACTION_OPEN.equals(action))
		{
			dialog.open();
		}
		else if (QuestDialogSession.ACTION_DISMISS.equals(action))
		{
			dialog.dismiss();
		}
		else if (QuestDialogSession.ACTION_CONTINUE.equals(action))
		{
			dialog.advance();
		}
		else if (action.startsWith(QuestDialogSession.ACTION_PICK))
		{
			dialog.pick(Integer.parseInt(action.substring(QuestDialogSession.ACTION_PICK.length())));
		}
		else if (QuestDialogSession.ACTION_DONE.equals(action))
		{
			dialog.completeTalk();
		}
		else if (action.startsWith(QuestDialogSession.ACTION_FIGHT))
		{
			fightAction.accept(action.substring(QuestDialogSession.ACTION_FIGHT.length()));
		}
	}
}

package com.petbattles.ui;

import com.petbattles.quest.QuestDialogSession;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The quest dialog frame: a movable card above the chatbox that carries every quest conversation
 * outside of battle. It shows nothing at all until the player has a beat waiting, then a compact
 * prompt pill ("Talk to Hans"); clicking that expands it into the full dialog — chathead, line,
 * Continue or replies — and finally the chapter's Challenge. All of that is decided by
 * {@link QuestDialogSession} and drawn by {@link QuestDialogView}; this class supplies only the
 * overlay chrome and the per-frame button list that {@link QuestDialogInputHandler} hit-tests.
 *
 * <p>The session keeps the frame off the screen for as long as a battle window is up — the fight, its
 * forget-a-move prompts and the level-up summary all play out first — and then hands over any payoff
 * conversation the battle earned.
 */
public class QuestDialogOverlay extends Overlay
{
	private static final Color PANEL_BG = new Color(20, 24, 28, 235);
	private static final Color PANEL_EDGE = new Color(90, 75, 40);

	/** A clickable region, in overlay-local coordinates. */
	public static class Button
	{
		public final Rectangle rect;
		public final String action;

		Button(Rectangle rect, String action)
		{
			this.rect = rect;
			this.action = action;
		}
	}

	private final QuestDialogSession dialog;
	private final QuestDialogView view;
	private final List<Button> buttons = new ArrayList<>();

	public QuestDialogOverlay(QuestDialogSession dialog, Portraits portraits)
	{
		this.dialog = dialog;
		this.view = new QuestDialogView(portraits::portrait);
		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
	}

	/** Current buttons in overlay-local space; the input handler translates using getBounds(). */
	public synchronized List<Button> getButtons()
	{
		return new ArrayList<>(buttons);
	}

	public void setHoverPoint(Point localPoint)
	{
		view.setHoverPoint(localPoint);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		QuestDialogSession.Scene scene = dialog.current();
		if (scene == null)
		{
			synchronized (this)
			{
				buttons.clear();
			}
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		List<Button> newButtons = new ArrayList<>();
		Dimension size;
		if (scene.getKind() == QuestDialogSession.Kind.PROMPT)
		{
			size = new Dimension(QuestDialogView.PROMPT_WIDTH, QuestDialogView.PROMPT_HEIGHT);
			drawPanel(g, size);
			view.drawPrompt(g, scene, (r, action) -> newButtons.add(new Button(r, action)));
		}
		else
		{
			size = new Dimension(QuestDialogView.WIDTH, view.measure(g, QuestDialogView.WIDTH, scene));
			drawPanel(g, size);
			view.draw(g, 0, 0, size.width, scene, (r, action) -> newButtons.add(new Button(r, action)),
				-1, true);
		}
		synchronized (this)
		{
			buttons.clear();
			buttons.addAll(newButtons);
		}
		return size;
	}

	private void drawPanel(Graphics2D g, Dimension size)
	{
		g.setColor(PANEL_BG);
		g.fillRoundRect(0, 0, size.width, size.height, 10, 10);
		g.setColor(PANEL_EDGE);
		g.setStroke(new BasicStroke(2));
		g.drawRoundRect(0, 0, size.width, size.height, 10, 10);
	}
}

package com.petbattles.ui;

import com.petbattles.quest.QuestDialogSession;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Function;
import net.runelite.client.ui.FontManager;

/**
 * Draws a {@link QuestDialogSession.Scene}: the speaker's name, their chathead framed on the left,
 * their line wrapped on the right, and the scene's buttons beneath — the post-battle quest dialog's
 * layout, lifted out so the standalone {@link QuestDialogOverlay} and the battle end screen are
 * literally the same picture.
 *
 * <p>The renderer owns no state beyond the hover point and where to find chatheads; hosts pass their
 * own {@code Graphics2D} and collect the buttons it lays out ({@code rect -> action}), then hit-test
 * those themselves. Sizes are measured before drawing ({@link #measure}) so a host can paint its
 * panel at the right height first.
 */
public class QuestDialogView
{
	/** The expanded dialog's width, matched to the battle overlay so the layouts agree. */
	public static final int WIDTH = 340;
	/** The collapsed prompt pill, sized like the rest toast plus room for a chathead. */
	public static final int PROMPT_WIDTH = 232;
	public static final int PROMPT_HEIGHT = 58;

	private static final Color PANEL_EDGE = new Color(90, 75, 40);
	private static final Color BUTTON_BG = new Color(45, 50, 58);
	private static final Color BUTTON_HOVER = new Color(70, 78, 90);
	private static final Color BUTTON_EDGE = new Color(120, 110, 80);
	private static final Color NAME = new Color(240, 210, 120);
	private static final Color TEXT = new Color(230, 225, 210);
	private static final Color MUTED = new Color(160, 155, 140);

	private static final int PAD = 12;
	private static final int NAME_H = 16;
	private static final int PORTRAIT_W = 72;
	private static final int PORTRAIT_H = 84;
	private static final int LINE_H = 16;
	private static final int BUTTON_H = 26;
	private static final int BUTTON_GAP = 6;
	private static final int HINT_H = 16;

	private final Function<String, BufferedImage> portraits;
	// Written from the AWT thread by the input handler, read on the render thread.
	private volatile Point hoverPoint;

	public QuestDialogView(Function<String, BufferedImage> portraits)
	{
		this.portraits = portraits;
	}

	public void setHoverPoint(Point localPoint)
	{
		this.hoverPoint = localPoint;
	}

	/**
	 * The height the expanded scene needs at this width, so the host can paint its panel before the
	 * content goes in. Must stay in step with {@link #draw}.
	 */
	public int measure(Graphics2D g, int width, QuestDialogSession.Scene scene)
	{
		int h = 8 + NAME_H + 4 + bodyHeight(g, width, scene) + 8;
		if (scene.getHint() != null)
		{
			h += HINT_H;
		}
		return h + scene.getChoices().size() * (BUTTON_H + BUTTON_GAP) + 6;
	}

	/**
	 * Draw the expanded scene into the box at ({@code x}, {@code y}), adding each button it lays out
	 * to {@code out}. {@code fixedButtonY} pins the button row to a host-local y (the battle overlay's
	 * fixed-height panel wants its Continue at the bottom); pass a negative value to let the buttons
	 * flow under the text. {@code closeable} adds the fold-back cross in the top-right corner.
	 */
	public void draw(Graphics2D g, int x, int y, int width, QuestDialogSession.Scene scene,
		BiConsumer<Rectangle, String> out, int fixedButtonY, boolean closeable)
	{
		boolean choice = scene.getKind() == QuestDialogSession.Kind.CHOICE;
		int textX = x + PAD;
		int textW = width - PAD * 2;

		g.setFont(FontManager.getRunescapeBoldFont());
		g.setColor(NAME);
		int nameW = textW - (closeable ? 20 : 0);
		g.drawString(clip(g, choice ? "" : scene.getSpeakerName(), nameW), textX, y + 8 + 12);
		if (closeable)
		{
			Rectangle close = new Rectangle(x + width - PAD - 12, y + 8, 12, 12);
			drawClose(g, close);
			out.accept(close, QuestDialogSession.ACTION_DISMISS);
		}

		int bodyY = y + 8 + NAME_H + 4;
		BufferedImage chathead = chathead(scene);
		if (chathead != null)
		{
			g.setColor(new Color(255, 255, 255, 18));
			g.fillRoundRect(textX, bodyY, PORTRAIT_W, PORTRAIT_H, 6, 6);
			g.setColor(PANEL_EDGE);
			g.setStroke(new BasicStroke(1));
			g.drawRoundRect(textX, bodyY, PORTRAIT_W, PORTRAIT_H, 6, 6);
			drawFit(g, chathead, textX + 2, bodyY + 2, PORTRAIT_W - 4, PORTRAIT_H - 4);
			textX += PORTRAIT_W + 10;
			textW -= PORTRAIT_W + 10;
		}

		g.setFont(FontManager.getRunescapeFont());
		g.setColor(TEXT);
		int ty = bodyY + 12;
		for (String line : wrap(g, scene.getText(), textW))
		{
			g.drawString(line, textX, ty);
			ty += LINE_H;
		}

		int by = bodyY + bodyHeight(g, width, scene) + 8;
		if (scene.getHint() != null)
		{
			g.setColor(new Color(220, 180, 40));
			g.drawString(clip(g, scene.getHint(), width - PAD * 2), x + PAD, by + 11);
			by += HINT_H;
		}
		if (fixedButtonY >= 0)
		{
			by = fixedButtonY;
		}
		// A lone Continue is a narrow centred button; replies and Challenges take the full width.
		List<QuestDialogSession.Choice> choices = scene.getChoices();
		boolean narrow = choices.size() == 1
			&& QuestDialogSession.ACTION_CONTINUE.equals(choices.get(0).getAction());
		for (QuestDialogSession.Choice option : choices)
		{
			Rectangle r = narrow
				? new Rectangle(x + width / 2 - 50, by, 100, BUTTON_H - 2)
				: new Rectangle(x + PAD, by, width - PAD * 2, BUTTON_H - 2);
			drawButton(g, r, option.getLabel(), option.isEnabled());
			if (option.isEnabled())
			{
				out.accept(r, option.getAction());
			}
			by += BUTTON_H + BUTTON_GAP;
		}
	}

	/**
	 * Draw the collapsed prompt pill: a small chathead, the action ("Talk to Hans") and the chapter
	 * title beneath it. The whole card is the button.
	 */
	public void drawPrompt(Graphics2D g, QuestDialogSession.Scene scene, BiConsumer<Rectangle, String> out)
	{
		int px = 8;
		int pw = 36;
		int ph = 42;
		int textX = px;
		BufferedImage chathead = chathead(scene);
		if (chathead != null)
		{
			g.setColor(new Color(255, 255, 255, 18));
			g.fillRoundRect(px, 8, pw, ph, 6, 6);
			drawFit(g, chathead, px + 2, 10, pw - 4, ph - 4);
			textX = px + pw + 8;
		}
		g.setFont(FontManager.getRunescapeBoldFont());
		g.setColor(NAME);
		g.drawString(clip(g, scene.getText(), PROMPT_WIDTH - textX - 10), textX, 26);
		if (scene.getTitle() != null)
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			g.setColor(MUTED);
			g.drawString(clip(g, scene.getTitle(), PROMPT_WIDTH - textX - 10), textX, 42);
		}
		out.accept(new Rectangle(0, 0, PROMPT_WIDTH, PROMPT_HEIGHT), QuestDialogSession.ACTION_OPEN);
	}

	/** The chathead for this scene, or null for narration, the player, and reply menus. */
	private BufferedImage chathead(QuestDialogSession.Scene scene)
	{
		String speaker = scene.getSpeaker();
		if (scene.getKind() == QuestDialogSession.Kind.CHOICE || speaker == null
			|| "player".equals(speaker))
		{
			// The player has no chathead (RuneLite exposes no clean way to render the local player's),
			// so their lines drop the picture frame and keep just the name row — an empty frame reads
			// as a missing asset, no frame reads as narration.
			return null;
		}
		return portraits.apply(speaker);
	}

	/** The text/chathead band's height: the taller of the framed chathead and the wrapped line. */
	private int bodyHeight(Graphics2D g, int width, QuestDialogSession.Scene scene)
	{
		if (scene.getKind() == QuestDialogSession.Kind.CHOICE)
		{
			return 0;
		}
		BufferedImage chathead = chathead(scene);
		int textW = width - PAD * 2 - (chathead != null ? PORTRAIT_W + 10 : 0);
		g.setFont(FontManager.getRunescapeFont());
		int textH = wrap(g, scene.getText(), textW).size() * LINE_H + 4;
		return Math.max(chathead != null ? PORTRAIT_H : 0, textH);
	}

	private void drawButton(Graphics2D g, Rectangle r, String label, boolean enabled)
	{
		Point hover = hoverPoint;
		boolean hovered = enabled && hover != null && r.contains(hover);
		g.setColor(hovered ? BUTTON_HOVER : BUTTON_BG);
		g.fillRoundRect(r.x, r.y, r.width, r.height, 6, 6);
		g.setColor(enabled ? BUTTON_EDGE : new Color(70, 70, 70));
		g.setStroke(new BasicStroke(1));
		g.drawRoundRect(r.x, r.y, r.width, r.height, 6, 6);
		g.setFont(FontManager.getRunescapeSmallFont());
		g.setColor(enabled ? Color.WHITE : new Color(140, 140, 140));
		FontMetrics fm = g.getFontMetrics();
		String text = clip(g, label, r.width - 14);
		g.drawString(text, r.x + (r.width - fm.stringWidth(text)) / 2,
			r.y + (r.height + fm.getAscent() - fm.getDescent()) / 2);
	}

	/** The fold-back cross: drawn as strokes so it doesn't depend on the game font having a glyph. */
	private void drawClose(Graphics2D g, Rectangle r)
	{
		Point hover = hoverPoint;
		g.setColor(hover != null && r.contains(hover) ? Color.WHITE : MUTED);
		g.setStroke(new BasicStroke(2));
		g.drawLine(r.x + 2, r.y + 2, r.x + r.width - 2, r.y + r.height - 2);
		g.drawLine(r.x + r.width - 2, r.y + 2, r.x + 2, r.y + r.height - 2);
	}

	/** Draw an image scaled to fit the box while preserving aspect ratio, centred. */
	private static void drawFit(Graphics2D g, BufferedImage img, int bx, int by, int bw, int bh)
	{
		if (img == null || img.getWidth() <= 0 || img.getHeight() <= 0)
		{
			return;
		}
		double scale = Math.min(bw / (double) img.getWidth(), bh / (double) img.getHeight());
		int w = Math.max(1, (int) Math.round(img.getWidth() * scale));
		int h = Math.max(1, (int) Math.round(img.getHeight() * scale));
		g.drawImage(img, bx + (bw - w) / 2, by + (bh - h) / 2, w, h, null);
	}

	private static List<String> wrap(Graphics2D g, String text, int maxWidth)
	{
		List<String> lines = new ArrayList<>();
		if (text == null || text.isEmpty())
		{
			return lines;
		}
		FontMetrics fm = g.getFontMetrics();
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(candidate) > maxWidth && line.length() > 0)
			{
				lines.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(candidate);
			}
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

	private static String clip(Graphics2D g, String text, int maxWidth)
	{
		FontMetrics fm = g.getFontMetrics();
		if (text == null || fm.stringWidth(text) <= maxWidth)
		{
			return text == null ? "" : text;
		}
		String ellipsis = "…";
		StringBuilder sb = new StringBuilder();
		for (char c : text.toCharArray())
		{
			if (fm.stringWidth(sb.toString() + c + ellipsis) > maxWidth)
			{
				break;
			}
			sb.append(c);
		}
		return sb + ellipsis;
	}
}

package com.petbattles.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Short, purely cosmetic "your pets are resting" toast played after a bank heal:
 * a zZz card with a sparkle burst, gone after a couple of seconds.
 */
public class RestOverlay extends Overlay
{
	private static final int DURATION_MS = 2500;
	private static final int WIDTH = 200;
	private static final int HEIGHT = 56;

	private volatile long startMs;

	public RestOverlay()
	{
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/**
	 * Start (or restart) the animation. Safe from any thread.
	 */
	public void play()
	{
		startMs = System.currentTimeMillis();
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		long elapsed = System.currentTimeMillis() - startMs;
		if (startMs == 0 || elapsed >= DURATION_MS)
		{
			return null;
		}
		float progress = elapsed / (float) DURATION_MS;
		float alpha = progress > 0.8f ? (1f - progress) / 0.2f : 1f;

		g.setColor(new Color(20, 24, 28, (int) (225 * alpha)));
		g.fillRoundRect(0, 0, WIDTH, HEIGHT, 10, 10);
		g.setColor(new Color(90, 75, 40, (int) (255 * alpha)));
		g.setStroke(new BasicStroke(2));
		g.drawRoundRect(0, 0, WIDTH, HEIGHT, 10, 10);

		g.setFont(FontManager.getRunescapeFont());
		g.setColor(new Color(230, 225, 210, (int) (255 * alpha)));
		g.drawString("Your pets are resting…", 14, 24);
		g.setFont(FontManager.getRunescapeBoldFont());
		g.setColor(new Color(240, 220, 120, (int) (255 * alpha)));
		// A drowsy zZz drifting up as the toast plays
		g.drawString("z", 150, 40 - (int) (6 * progress));
		g.drawString("Z", 160, 34 - (int) (10 * progress));
		g.drawString("z", 172, 28 - (int) (14 * progress));

		ParticleBurst.render(g, new Rectangle(0, 8, WIDTH, HEIGHT - 16),
			progress, 7, ParticleBurst.SPARKLE);
		return new Dimension(WIDTH, HEIGHT);
	}
}

package com.petbattles.ui;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JLabel;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Bridges item icons onto Swing labels. Item images must be requested on the client
 * thread; AsyncBufferedImage repaints the target when the sprite arrives.
 */
@Singleton
public class Sprites
{
	private final ItemManager itemManager;
	private final ClientThread clientThread;

	@Inject
	public Sprites(ItemManager itemManager, ClientThread clientThread)
	{
		this.itemManager = itemManager;
		this.clientThread = clientThread;
	}

	public void applyItemIcon(JLabel label, int itemId)
	{
		clientThread.invokeLater(() ->
		{
			AsyncBufferedImage img = itemManager.getImage(itemId);
			img.addTo(label);
		});
	}

	/**
	 * Fetch the raw async image for overlay use (caller may keep the reference; it
	 * fills in once loaded).
	 */
	public AsyncBufferedImage itemImage(int itemId)
	{
		return itemManager.getImage(itemId);
	}
}

package com.petbattles.xp;

import com.petbattles.PetBattlesConfig;
import com.petbattles.data.PetDatabase;
import com.petbattles.engine.LearnsetEntry;
import com.petbattles.engine.Leveling;
import com.petbattles.engine.MoveDef;
import com.petbattles.engine.PetInstance;
import com.petbattles.engine.SpeciesDef;
import com.petbattles.follower.FollowerTracker;
import com.petbattles.persist.RosterManager;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.client.eventbus.Subscribe;

/**
 * Awards XP to the active follower pet when the player kills an NPC.
 * Kill attribution: NPCs we've hitsplat recently (within an expiry window) count as ours.
 */
public class KillXpTracker
{
	private static final int ATTRIBUTION_WINDOW_TICKS = 50;

	private final Client client;
	private final PetDatabase db;
	private final RosterManager roster;
	private final FollowerTracker follower;
	private final PetBattlesConfig config;
	private final Runnable onXpGained;

	private final Map<Integer, Integer> recentTargets = new HashMap<>(); // npc index -> last hit tick
	private int tickCount;

	public KillXpTracker(Client client, PetDatabase db, RosterManager roster,
		FollowerTracker follower, PetBattlesConfig config, Runnable onXpGained)
	{
		this.client = client;
		this.db = db;
		this.roster = roster;
		this.follower = follower;
		this.config = config;
		this.onXpGained = onXpGained;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		tickCount++;
		if (tickCount % 25 == 0)
		{
			Iterator<Map.Entry<Integer, Integer>> it = recentTargets.entrySet().iterator();
			while (it.hasNext())
			{
				if (tickCount - it.next().getValue() > ATTRIBUTION_WINDOW_TICKS)
				{
					it.remove();
				}
			}
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Actor actor = event.getActor();
		if (actor instanceof NPC && event.getHitsplat().isMine())
		{
			recentTargets.put(((NPC) actor).getIndex(), tickCount);
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Actor actor = event.getActor();
		if (!(actor instanceof NPC))
		{
			return;
		}
		NPC npc = (NPC) actor;
		Integer lastHit = recentTargets.remove(npc.getIndex());
		if (lastHit == null || tickCount - lastHit > ATTRIBUTION_WINDOW_TICKS)
		{
			return;
		}

		String speciesId = follower.getActiveSpeciesId();
		if (speciesId == null || !roster.isLoaded())
		{
			return;
		}
		SpeciesDef species = db.species(speciesId);
		PetInstance pet = roster.getOrCreatePet(speciesId);
		if (species == null || pet == null || pet.getLevel() >= Leveling.MAX_LEVEL)
		{
			return;
		}

		boolean typeMatch = isTypeMatch(species, npc);
		long xp = Leveling.killXp(npc.getCombatLevel(), typeMatch);
		int oldLevel = pet.getLevel();
		int gained = pet.addXp(xp);
		roster.petChanged();

		if (gained > 0)
		{
			int newLevel = pet.getLevel();
			message(species.getName() + " grew to level " + newLevel + "!"
				+ (typeMatch ? " (home-turf bonus)" : ""));
			announceNewMoves(pet, species, oldLevel, newLevel);
			onXpGained.run();
		}
		else if (typeMatch && config.showXpMessages())
		{
			message(species.getName() + " gained " + xp + " XP (home-turf bonus)!");
		}
	}

	private static boolean isTypeMatch(SpeciesDef species, NPC npc)
	{
		String name = npc.getName();
		if (name == null)
		{
			return false;
		}
		String lower = name.toLowerCase();
		for (String tag : species.getNpcXpTags())
		{
			if (lower.contains(tag.toLowerCase()))
			{
				return true;
			}
		}
		return false;
	}

	private void announceNewMoves(PetInstance pet, SpeciesDef species, int oldLevel, int newLevel)
	{
		for (LearnsetEntry entry : species.getLearnset())
		{
			if (entry.getLevel() > oldLevel && entry.getLevel() <= newLevel)
			{
				MoveDef move = db.move(entry.getMove());
				if (move == null || pet.getEquippedMoves().contains(entry.getMove()))
				{
					continue;
				}
				if (pet.getEquippedMoves().size() < PetInstance.MAX_EQUIPPED_MOVES)
				{
					pet.equipMove(entry.getMove());
					roster.petChanged();
					message(species.getName() + " learned " + move.getName() + "!");
				}
				else
				{
					// Moveset is full. Outside a battle there's no overlay to prompt on, so just
					// point the player at the Moves editor; the move is already available there.
					message(species.getName() + " can learn " + move.getName()
						+ "! Its moveset is full - open Moves to swap it in.");
				}
			}
		}
	}

	private void message(String text)
	{
		if (config.showXpMessages())
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"<col=ff7700>Pet Battles:</col> " + text, null);
		}
	}
}

package com.petbattles;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
