	@Test
	public void playerFaintPausesForForcedSwitchWithoutAutoSend()
	{
		MoveDef smash = new MoveDef("smash", "Smash", PetType.MELEE, 250, 100, MoveEffect.NONE, 0);
		BattlePet lead = TestPets.slowPet("lead", PetType.SKILLING, 1, TestPets.TACKLE);
		BattlePet bench = TestPets.pet("bench", PetType.RANGED, 20, TestPets.ARROW);
		BattlePet enemy = TestPets.fastPet("enemy", PetType.MELEE, 99, smash);

		List<BattleEvent> events = new ArrayList<>();
		BattleState state = start(TestPets.teamOf(lead, bench), TestPets.teamOf(enemy), events);
		List<BattleEvent> turn = engine.resolveTurn(state, BattleAction.move(0), BattleAction.move(0), new Random(1));

		assertTrue("player pet fainted", turn.stream().anyMatch(
			e -> e.getType() == BattleEvent.Type.FAINTED && e.getSide() == BattleState.PLAYER));
		assertTrue("battle pauses for a forced switch", state.awaitingForcedSwitch());
		assertFalse(state.isOver());
		// No auto-advance to the bench, and the replacement neither was sent nor attacked
		assertEquals("lead stays the active slot until the player picks", 0, state.activeIndex(BattleState.PLAYER));
		assertFalse("no player send-out happens automatically", turn.stream().anyMatch(
			e -> e.getType() == BattleEvent.Type.PET_SENT_OUT && e.getSide() == BattleState.PLAYER));
		assertFalse("the incoming pet never inherits the fainted pet's queued move", turn.stream().anyMatch(
			e -> e.getType() == BattleEvent.Type.MOVE_USED && e.getSide() == BattleState.PLAYER));
		assertEquals("bench pet is untouched", bench.getMaxHp(), bench.getCurrentHp());
	}

	@Test
	public void forcedSwitchSendsInChosenPetAndConsumesTheRound()
	{
		MoveDef smash = new MoveDef("smash", "Smash", PetType.MELEE, 250, 100, MoveEffect.NONE, 0);
		BattlePet lead = TestPets.slowPet("lead", PetType.SKILLING, 1, TestPets.TACKLE);
		BattlePet bench = TestPets.pet("bench", PetType.RANGED, 20, TestPets.ARROW);
		BattlePet enemy = TestPets.fastPet("enemy", PetType.MELEE, 99, smash);

		List<BattleEvent> events = new ArrayList<>();
		BattleState state = start(TestPets.teamOf(lead, bench), TestPets.teamOf(enemy), events);
		engine.resolveTurn(state, BattleAction.move(0), BattleAction.move(0), new Random(1));
		assertTrue(state.awaitingForcedSwitch());

		List<BattleEvent> sw = engine.resolveForcedSwitch(state, 1);
		assertTrue("forced switch emits a send-out", sw.stream().anyMatch(
			e -> e.getType() == BattleEvent.Type.PET_SENT_OUT && e.getSide() == BattleState.PLAYER));
		assertEquals(1, state.activeIndex(BattleState.PLAYER));
		assertFalse("play resumes after the pick", state.awaitingForcedSwitch());
		assertTrue(state.hasFought(BattleState.PLAYER, 1));
		// The incoming pet did not counter-attack this round: it and the enemy are unhurt
		assertEquals(bench.getMaxHp(), bench.getCurrentHp());
		assertEquals(enemy.getMaxHp(), enemy.getCurrentHp());
	}

	@Test
	public void dotFaintRoutesThroughForcedSwitch()
	{
		// A no-damage enemy move plus a burn on a near-dead lead: the burn tick at
		// end of turn is what faints the player, and it must pause for a forced switch.
		BattlePet lead = new BattlePet(TestPets.species("lead", PetType.MELEE, 50, 50, 50, 50),
			"lead", 5, Arrays.asList(TestPets.TACKLE), 3);
		BattlePet bench = TestPets.pet("bench", PetType.MELEE, 20, TestPets.TACKLE);
		BattlePet enemy = TestPets.pet("enemy", PetType.MELEE, 5, TestPets.BUFF_MOVE);
		lead.applyStatus(BattlePet.Status.BURN, Integer.MAX_VALUE);

		List<BattleEvent> events = new ArrayList<>();
		BattleState state = start(TestPets.teamOf(lead, bench), TestPets.teamOf(enemy), events);
		List<BattleEvent> turn = engine.resolveTurn(state, BattleAction.move(0), BattleAction.move(0), new Random(1));

		assertTrue("burn chipped the lead", turn.stream().anyMatch(e -> e.getType() == BattleEvent.Type.STATUS_TICK));
		assertTrue("the burn faint is the player's", turn.stream().anyMatch(
			e -> e.getType() == BattleEvent.Type.FAINTED && e.getSide() == BattleState.PLAYER));
		assertTrue("a DOT faint still pauses for a forced switch", state.awaitingForcedSwitch());
		assertFalse(state.isOver());
	}

	@Test
	public void switchChangesActivePetAndConsumesTurn()
	{
		BattlePet first = TestPets.fastPet("first", PetType.MELEE, 20, TestPets.TACKLE);
		BattlePet second = TestPets.fastPet("second", PetType.RANGED, 20, TestPets.ARROW);
		BattlePet enemy = TestPets.slowPet("enemy", PetType.MELEE, 20, TestPets.TACKLE);

		List<BattleEvent> events = new ArrayList<>();
		BattleState state = start(TestPets.teamOf(first, second), TestPets.teamOf(enemy), events);

		List<BattleEvent> turn = engine.resolveTurn(state, BattleAction.switchTo(1), BattleAction.move(0), new Random(1));

		assertEquals(1, state.activeIndex(BattleState.PLAYER));
		assertTrue("switch emits a send-out",
			turn.stream().anyMatch(e -> e.getType() == BattleEvent.Type.PET_SENT_OUT && e.getSide() == BattleState.PLAYER));
		// Switching consumed the player's turn: no player move was used
		assertFalse(turn.stream().anyMatch(e -> e.getType() == BattleEvent.Type.MOVE_USED && e.getSide() == BattleState.PLAYER));
		// The enemy still acted, and its damage landed on the newly sent-out pet
		assertTrue(turn.stream().anyMatch(e -> e.getType() == BattleEvent.Type.MOVE_USED && e.getSide() == BattleState.ENEMY));
		assertTrue(second.getCurrentHp() < second.getMaxHp());
		assertEquals(first.getMaxHp(), first.getCurrentHp());
	}

	@Test
	public void switchToFaintedOrInvalidTargetIsIgnored()
	{
		BattlePet first = TestPets.fastPet("first", PetType.MELEE, 20, TestPets.TACKLE);
		BattlePet downed = TestPets.fastPet("downed", PetType.MELEE, 20, TestPets.TACKLE);
		downed.damage(downed.getMaxHp());
		BattlePet enemy = TestPets.slowPet("enemy", PetType.MELEE, 20, TestPets.TACKLE);

		List<BattleEvent> events = new ArrayList<>();
		BattleState state = start(TestPets.teamOf(first, downed), TestPets.teamOf(enemy), events);

		engine.resolveTurn(state, BattleAction.switchTo(1), BattleAction.move(0), new Random(1));
		assertEquals("cannot switch to a fainted pet", 0, state.activeIndex(BattleState.PLAYER));

		engine.resolveTurn(state, BattleAction.switchTo(0), BattleAction.move(0), new Random(1));
		assertEquals("switching to the active pet is a no-op", 0, state.activeIndex(BattleState.PLAYER));

		engine.resolveTurn(state, BattleAction.switchTo(7), BattleAction.move(0), new Random(1));
		assertEquals("out-of-range switch is a no-op", 0, state.activeIndex(BattleState.PLAYER));
	}

	@Test
	public void optionalSwitchIsFreeAndRunsNoTurn()
	{
		BattlePet first = TestPets.pet("first", PetType.MELEE, 20, TestPets.TACKLE);
		BattlePet bench = TestPets.pet("bench", PetType.MELEE, 20, TestPets.TACKLE);
		BattlePet enemy = TestPets.pet("enemy", PetType.MELEE, 20, TestPets.TACKLE);

		List<BattleEvent> events = new ArrayList<>();
		BattleState state = start(TestPets.teamOf(first, bench), TestPets.teamOf(enemy), events);

		List<BattleEvent> out = engine.resolveOptionalSwitch(state, 1);
		// The incoming pet takes over, one send-out line, and nobody attacked (no free enemy hit).
		assertEquals(1, state.activeIndex(BattleState.PLAYER));
		assertEquals(1, out.size());
		assertEquals(BattleEvent.Type.PET_SENT_OUT, out.get(0).getType());
		assertEquals(BattleState.PLAYER, out.get(0).getSide());
		assertFalse(out.stream().anyMatch(e -> e.getType() == BattleEvent.Type.MOVE_USED));
		assertEquals(first.getMaxHp(), first.getCurrentHp());
		assertEquals(bench.getMaxHp(), bench.getCurrentHp());
		assertEquals(enemy.getMaxHp(), enemy.getCurrentHp());
	}

	@Test
	public void optionalSwitchToInvalidTargetIsIgnored()
	{
		BattlePet first = TestPets.pet("first", PetType.MELEE, 20, TestPets.TACKLE);
		BattlePet downed = TestPets.pet("downed", PetType.MELEE, 20, TestPets.TACKLE);
		downed.damage(downed.getMaxHp());
		BattlePet enemy = TestPets.pet("enemy", PetType.MELEE, 20, TestPets.TACKLE);

		List<BattleEvent> events = new ArrayList<>();
		BattleState state = start(TestPets.teamOf(first, downed), TestPets.teamOf(enemy), events);

		assertTrue("fainted target", engine.resolveOptionalSwitch(state, 1).isEmpty());
		assertTrue("already-active target", engine.resolveOptionalSwitch(state, 0).isEmpty());
		assertTrue("out-of-range target", engine.resolveOptionalSwitch(state, 7).isEmpty());
		assertTrue("decline (negative index)", engine.resolveOptionalSwitch(state, -1).isEmpty());
		assertEquals(0, state.activeIndex(BattleState.PLAYER));
	}

	@Test
	public void resolveTurnOnFinishedBattleDoesNothing()
	{
		List<BattleEvent> events = new ArrayList<>();
		BattleState state = start(
			TestPets.teamOf(TestPets.pet("a", PetType.MELEE, 10, TestPets.TACKLE)),
			TestPets.teamOf(TestPets.pet("b", PetType.MELEE, 10, TestPets.TACKLE)),
			events);
		state.setPhase(BattleState.Phase.PLAYER_WON);
		assertTrue(engine.resolveTurn(state, BattleAction.move(0), BattleAction.move(0), new Random(1)).isEmpty());
	}
}

package com.petbattles.engine;

import java.util.Random;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class DamageCalcTest
{
	@Test
	public void damageIsWithinRollBounds()
	{
		// With rng fixed at extremes, damage spans exactly the 0.85..1.0 roll window
		int min = DamageCalc.damage(50, 80, 100, 100, false, 1.0, fixed(0.0));
		int max = DamageCalc.damage(50, 80, 100, 100, false, 1.0, fixed(0.9999));
		assertTrue(min > 0);
		assertTrue(max >= min);
		assertTrue("max/min ratio should be ~1.176", max <= Math.ceil(min / 0.85));
	}

	@Test
	public void stabMultiplies()
	{
		int plain = DamageCalc.damage(50, 80, 100, 100, false, 1.0, fixed(0.5));
		int stab = DamageCalc.damage(50, 80, 100, 100, true, 1.0, fixed(0.5));
		assertTrue(stab > plain);
	}

	@Test
	public void typeEffectivenessScales()
	{
		int neutral = DamageCalc.damage(50, 80, 100, 100, false, 1.0, fixed(0.5));
		int superEff = DamageCalc.damage(50, 80, 100, 100, false, 2.0, fixed(0.5));
		int notVery = DamageCalc.damage(50, 80, 100, 100, false, 0.5, fixed(0.5));
		assertTrue(superEff > neutral && neutral > notVery);
	}

	@Test
	public void minimumOneDamage()
	{
		assertTrue(DamageCalc.damage(1, 1, 1, 999, false, 0.5, fixed(0.0)) >= 1);
	}

	@Test
	public void zeroPowerDealsNothing()
	{
		assertEquals(0, DamageCalc.damage(50, 0, 100, 100, true, 2.0, fixed(0.5)));
	}

	@Test
	public void deterministicWithSeed()
	{
		assertEquals(
			DamageCalc.damage(50, 80, 120, 90, true, 2.0, new Random(42)),
			DamageCalc.damage(50, 80, 120, 90, true, 2.0, new Random(42)));
	}

	private static Random fixed(double value)
	{
		return new Random()
		{
			@Override
			public double nextDouble()
			{
				return value;
			}
		};
	}
}

package com.petbattles.engine;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Held-item stat modifiers on {@link BattlePet}. A pet with base stats 50 at level 50 derives each
 * stat to exactly 100 ({@code statAtLevel(50,50)}), so a percent item lands on a clean number.
 */
public class HeldItemStatTest
{
	private static BattlePet pet(ItemEffect effect)
	{
		SpeciesDef sp = TestPets.species("t", PetType.MELEE, 50, 50, 50, 50);
		return new BattlePet(sp, "t", 50, Arrays.asList(TestPets.TACKLE), null, null, effect);
	}

	@Test
	public void multiplierAppliesOnlyToItsOwnStat()
	{
		ItemEffect atk = new ItemEffect(ItemEffect.Stat.ATK, 15);
		assertEquals(1.15, atk.multiplierFor(ItemEffect.Stat.ATK), 1e-9);
		assertEquals(1.0, atk.multiplierFor(ItemEffect.Stat.DEF), 1e-9);
		assertEquals(1.0, atk.multiplierFor(ItemEffect.Stat.SPD), 1e-9);
		assertEquals(1.0, atk.multiplierFor(ItemEffect.Stat.HP), 1e-9);
	}

	@Test
	public void noItemLeavesStatsUnmodified()
	{
		BattlePet plain = pet(null);
		assertEquals(100, plain.effectiveAtk());
		assertEquals(100, plain.effectiveDef());
		assertEquals(100, plain.effectiveSpd());
	}

	@Test
	public void atkItemBoostsOnlyAttack()
	{
		BattlePet plain = pet(null);
		BattlePet held = pet(new ItemEffect(ItemEffect.Stat.ATK, 15));
		assertEquals(115, held.effectiveAtk());
		// The other stats are untouched.
		assertEquals(plain.effectiveDef(), held.effectiveDef());
		assertEquals(plain.effectiveSpd(), held.effectiveSpd());
		assertEquals(plain.getMaxHp(), held.getMaxHp());
	}

	@Test
	public void defAndSpdItemsBoostTheirStat()
	{
		assertEquals(115, pet(new ItemEffect(ItemEffect.Stat.DEF, 15)).effectiveDef());
		assertEquals(115, pet(new ItemEffect(ItemEffect.Stat.SPD, 15)).effectiveSpd());
	}

	@Test
	public void hpItemBoostsMaxHpAndStartsFull()
	{
		BattlePet plain = pet(null);
		BattlePet held = pet(new ItemEffect(ItemEffect.Stat.HP, 12));
		assertEquals(Math.round(plain.getMaxHp() * 1.12), held.getMaxHp());
		assertTrue("HP item raises the ceiling", held.getMaxHp() > plain.getMaxHp());
		// A fresh battler (null startingHp) begins at its boosted full.
		assertEquals(held.getMaxHp(), held.getCurrentHp());
	}

	@Test
	public void hpItemBoostSurvivesLevelUp()
	{
		BattlePet plain = pet(null);
		BattlePet held = pet(new ItemEffect(ItemEffect.Stat.HP, 12));
		plain.growTo(60);
		held.growTo(60);
		// growTo recomputes max HP through the same held-item hook, so the boost still holds.
		assertEquals(Math.round(plain.getMaxHp() * 1.12), held.getMaxHp());
	}
}

package com.petbattles.engine;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class LevelingTest
{
	@Test
	public void levelOneIsZeroXp()
	{
		assertEquals(0, Leveling.xpForLevel(1));
	}

	@Test
	public void curveIsStrictlyIncreasing()
	{
		for (int lvl = 2; lvl <= Leveling.MAX_LEVEL; lvl++)
		{
			assertTrue("level " + lvl, Leveling.xpForLevel(lvl) > Leveling.xpForLevel(lvl - 1));
		}
	}

	@Test
	public void levelForXpInvertsXpForLevel()
	{
		for (int lvl = 1; lvl <= Leveling.MAX_LEVEL; lvl++)
		{
			assertEquals(lvl, Leveling.levelForXp(Leveling.xpForLevel(lvl)));
			if (lvl > 1)
			{
				assertEquals(lvl - 1, Leveling.levelForXp(Leveling.xpForLevel(lvl) - 1));
			}
		}
	}

	@Test
	public void curveIsScaledOsrs()
	{
		// Real OSRS level 99 is 13,034,431 xp; ours is that / 20
		assertEquals(13034431L / 20, Leveling.xpForLevel(99), 1);
	}

	@Test
	public void fullCurveMatchesUnscaledOsrs()
	{
		try
		{
			Leveling.setFullCurve(true);
			// Full curve is the real OSRS table (level 99 = 13,034,431 xp), ~20x the default
			assertEquals(13034431L, Leveling.xpForLevel(99), 20);
			assertTrue(Leveling.xpForLevel(99) > 10_000_000L);
		}
		finally
		{
			Leveling.setFullCurve(false);
		}
		// Default pacing restored for the rest of the suite
		assertEquals(13034431L / 20, Leveling.xpForLevel(99), 1);
	}

	@Test
	public void statsGrowWithLevel()
	{
		assertTrue(Leveling.statAtLevel(50, 99) > Leveling.statAtLevel(50, 1));
		assertTrue(Leveling.hpAtLevel(50, 99) > Leveling.hpAtLevel(50, 1));
		// Level 1 pets are still viable
		assertTrue(Leveling.hpAtLevel(40, 1) >= 20);
	}

	@Test
	public void xpAwards()
	{
		assertEquals(5, Leveling.killXp(0, false));
		assertEquals(65, Leveling.killXp(120, false));
		assertEquals(195, Leveling.killXp(120, true));
		// battle win xp clamps to [10, 200]
		assertEquals(10, Leveling.battleWinXp(1, 99));
		assertEquals(200, Leveling.battleWinXp(99, 1));
		assertEquals(25, Leveling.battleWinXp(50, 50));
	}

	@Test
	public void repeatWinsTaperTenPercentPerWinToAHalfRateFloor()
	{
		assertEquals(1.0, Leveling.repeatFactor(0), 1e-9);
		assertEquals(0.9, Leveling.repeatFactor(1), 1e-9);
		assertEquals(0.5, Leveling.repeatFactor(5), 1e-9);
		// The taper settles at the floor rather than running to nothing.
		assertEquals(Leveling.REPEAT_FLOOR, Leveling.repeatFactor(6), 1e-9);
		assertEquals(Leveling.REPEAT_FLOOR, Leveling.repeatFactor(500), 1e-9);
		// A nonsensical negative count can't pay more than the first win.
		assertEquals(1.0, Leveling.repeatFactor(-3), 1e-9);
	}

	@Test
	public void repeatWinXpFollowsTheTaper()
	{
		long first = Leveling.battleWinXp(50, 50, 0);
		assertEquals(Leveling.battleWinXp(50, 50), first);
		assertEquals(Math.round(first * 0.9), Leveling.battleWinXp(50, 50, 1));
		assertTrue("the second win still beats the old flat half rate",
			Leveling.battleWinXp(50, 50, 1) > Math.round(first * Leveling.REPEAT_FLOOR));
		assertEquals(Math.round(first * Leveling.REPEAT_FLOOR), Leveling.battleWinXp(50, 50, 9));
		// Repeats never round down to zero
		assertTrue(Leveling.battleWinXp(1, 99, 9) >= 1);
	}

	@Test
	public void battleWinCoinsScaleWithTrainerStrengthAndClamp()
	{
		// Flat per-battle reward scales with the combined enemy team level.
		assertTrue(Leveling.battleWinCoins(60) > Leveling.battleWinCoins(10));
		// Clamped to [10, 500] so a trivial or a giant trainer can't pay nothing / a fortune.
		assertEquals(10, Leveling.battleWinCoins(0));
		assertEquals(500, Leveling.battleWinCoins(10_000));
	}

	@Test
	public void repeatWinCoinsFollowTheSameTaper()
	{
		long first = Leveling.battleWinCoins(60, 0);
		assertEquals(Leveling.battleWinCoins(60), first);
		assertEquals(Math.round(first * 0.9), Leveling.battleWinCoins(60, 1));
		assertEquals(Math.round(first * Leveling.REPEAT_FLOOR), Leveling.battleWinCoins(60, 5));
		assertTrue(Leveling.battleWinCoins(60, 1) < first);
		// Repeats never round down to zero.
		assertTrue(Leveling.battleWinCoins(0, 9) >= 1);
	}

	@Test
	public void capBattleXpLimitsLevelsPerBattle()
	{
		int start = 1;
		long ceiling = Leveling.xpForLevel(start + Leveling.MAX_LEVELS_PER_BATTLE);

		// A level-1 pet (0 xp) offered a huge award lands exactly at the cap level.
		long capped = Leveling.capBattleXp(0, 10_000_000L, start);
		assertEquals(ceiling, capped);
		assertEquals(start + Leveling.MAX_LEVELS_PER_BATTLE, Leveling.levelForXp(capped));

		// An award that stays within the cap passes through untouched.
		assertEquals(ceiling - 1, Leveling.capBattleXp(0, ceiling - 1, start));

		// Once the pet has already reached the cap this battle, further awards give nothing.
		assertEquals(0, Leveling.capBattleXp(ceiling, 500, start));

		// Near the level ceiling the cap never blocks progress.
		assertEquals(500, Leveling.capBattleXp(Leveling.xpForLevel(97), 500, 97));
	}

	@Test
	public void petInstanceLevelsUp()
	{
		PetInstance pet = new PetInstance("baby_mole");
		assertEquals(1, pet.getLevel());
		int gained = pet.addXp(Leveling.xpForLevel(5));
		assertEquals(4, gained);
		assertEquals(5, pet.getLevel());
	}
}

package com.petbattles.engine;

import com.google.gson.Gson;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Variant resolution: "variant wins" over growth stages, and everything a variant does not name
 * falls through to the base form. Built via Gson so the JSON-shaped private fields populate.
 */
public class SpeciesDefVariantTest
{
	private static final String JSON =
		"{"
			+ "\"id\":\"x\",\"name\":\"Base\",\"itemId\":100,\"altItemIds\":[101],"
			+ "\"npcIds\":[1],\"types\":[\"FIRE\"],"
			+ "\"base\":{\"hp\":50,\"atk\":50,\"def\":50,\"spd\":50},"
			+ "\"learnset\":[{\"level\":1,\"move\":\"tackle\"},{\"level\":10,\"move\":\"ember\"}],"
			+ "\"growthStages\":[{\"level\":1,\"name\":\"BaseYoung\",\"itemId\":100},"
			+ "{\"level\":10,\"name\":\"BaseOld\",\"itemId\":110}],"
			+ "\"variants\":["
			// flat sprite+name override, plus tier-2 type/base and an orientation override
			+ "{\"id\":\"blue\",\"name\":\"Blue\",\"itemId\":200,\"npcIds\":[2],"
			+ "\"unlockItemIds\":[201],\"spriteFacesLeft\":false,\"types\":[\"ICE\"],"
			+ "\"base\":{\"hp\":60,\"atk\":60,\"def\":60,\"spd\":60}},"
			// variant with its own growth-stage art
			+ "{\"id\":\"staged\",\"itemId\":300,"
			+ "\"growthStages\":[{\"level\":1,\"name\":\"StagedYoung\",\"itemId\":300},"
			+ "{\"level\":10,\"name\":\"StagedOld\",\"itemId\":310}]},"
			// type-only override: no sprite/name, so those fall through to the base
			+ "{\"id\":\"typeonly\",\"types\":[\"MAGIC\"]}"
			+ "]}";

	private final SpeciesDef s = new Gson().fromJson(JSON, SpeciesDef.class);

	@Test
	public void nullVariantMatchesLegacyResolution()
	{
		assertNull(s.variant(null));
		assertNull(s.variant("does-not-exist"));
		assertEquals(s.nameAt(1), s.nameFor(null, 1));
		assertEquals("BaseYoung", s.nameFor(null, 1));
		assertEquals("BaseOld", s.nameFor(null, 10));
		assertEquals(s.itemIdAt(10), s.itemIdFor(null, 10));
		assertEquals(110, s.itemIdFor(null, 10));
		assertEquals(s.movesKnownAt(10), s.movesKnownFor(null, 10));
	}

	@Test
	public void flatVariantWinsOverBaseGrowthStages()
	{
		// Blue has no stage art, so its flat name/sprite apply at every level and the base
		// growth stages are bypassed while the variant is active.
		assertEquals("Blue", s.nameFor("blue", 1));
		assertEquals("Blue", s.nameFor("blue", 10));
		assertEquals(200, s.itemIdFor("blue", 1));
		assertEquals(200, s.itemIdFor("blue", 10));
	}

	@Test
	public void variantMayDeclareItsOwnGrowthStages()
	{
		assertEquals("StagedYoung", s.nameFor("staged", 1));
		assertEquals("StagedOld", s.nameFor("staged", 10));
		assertEquals(300, s.itemIdFor("staged", 1));
		assertEquals(310, s.itemIdFor("staged", 10));
	}

	@Test
	public void unnamedOverridesFallThroughToBase()
	{
		// typeonly overrides only types, so name/sprite come from the base (incl. base growth).
		assertEquals("BaseOld", s.nameFor("typeonly", 10));
		assertEquals(110, s.itemIdFor("typeonly", 10));
	}

	@Test
	public void typesAndBaseFollowTheVariant()
	{
		assertEquals(PetType.FIRE, s.typesFor(null).get(0));
		assertEquals(PetType.ICE, s.typesFor("blue").get(0));
		assertEquals(PetType.MAGIC, s.typesFor("typeonly").get(0));
		// staged declares no types, so it inherits the base
		assertEquals(PetType.FIRE, s.typesFor("staged").get(0));

		assertEquals(60, s.baseFor("blue").getHp());
		assertEquals(50, s.baseFor("staged").getHp());
		assertEquals(50, s.baseFor(null).getHp());
	}

	@Test
	public void spriteOrientationOverride()
	{
		assertTrue(s.spriteFacesLeftFor(null));
		assertFalse(s.spriteFacesLeftFor("blue"));
		assertTrue(s.spriteFacesLeftFor("staged"));
	}

	@Test
	public void getAllItemIdsFoldsInVariantOwnershipSignals()
	{
		// base item + alternates + each variant's item and unlock ids — so a form id moved out of
		// altItemIds into a variant still counts as an unlock. Growth-stage art ids are NOT owned.
		assertTrue(s.getAllItemIds().contains(100));
		assertTrue(s.getAllItemIds().contains(101));
		assertTrue("blue variant item", s.getAllItemIds().contains(200));
		assertTrue("blue unlock item", s.getAllItemIds().contains(201));
		assertTrue("staged variant item", s.getAllItemIds().contains(300));
		assertFalse("stage art is not an ownership id", s.getAllItemIds().contains(310));
		assertFalse("base stage art is not an ownership id", s.getAllItemIds().contains(110));
	}
}

