package com.petbattles.engine;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class TypeChartTest
{
	private final TypeChart chart = new TypeChart();

	@Test
	public void combatTriangle()
	{
		assertEquals(2.0, chart.effectiveness(PetType.MELEE, PetType.RANGED), 0.001);
		assertEquals(2.0, chart.effectiveness(PetType.RANGED, PetType.MAGIC), 0.001);
		assertEquals(2.0, chart.effectiveness(PetType.MAGIC, PetType.MELEE), 0.001);
		assertEquals(0.5, chart.effectiveness(PetType.RANGED, PetType.MELEE), 0.001);
		assertEquals(0.5, chart.effectiveness(PetType.MAGIC, PetType.RANGED), 0.001);
		assertEquals(0.5, chart.effectiveness(PetType.MELEE, PetType.MAGIC), 0.001);
	}

	@Test
	public void osrsFlavors()
	{
		// Dragon hunter crossbow: Ranged > Dragon
		assertEquals(2.0, chart.effectiveness(PetType.RANGED, PetType.DRAGON), 0.001);
		// Demonbane spells: Magic > Demon
		assertEquals(2.0, chart.effectiveness(PetType.MAGIC, PetType.DEMON), 0.001);
		// Fire cremates the Undead but Dragons shrug it off
		assertEquals(2.0, chart.effectiveness(PetType.FIRE, PetType.UNDEAD), 0.001);
		assertEquals(0.5, chart.effectiveness(PetType.FIRE, PetType.DRAGON), 0.001);
		// Ice freezes the firebreather
		assertEquals(2.0, chart.effectiveness(PetType.ICE, PetType.DRAGON), 0.001);
		// Skilling pets chop down Nature
		assertEquals(2.0, chart.effectiveness(PetType.SKILLING, PetType.NATURE), 0.001);
	}

	@Test
	public void rebalance2026()
	{
		// Dragon no longer super-effective against Melee
		assertEquals(1.0, chart.effectiveness(PetType.DRAGON, PetType.MELEE), 0.001);
		// Undead now punishes Demons
		assertEquals(2.0, chart.effectiveness(PetType.UNDEAD, PetType.DEMON), 0.001);
		// Skilling gains an offensive niche vs Ice and Undead (Nature unchanged)
		assertEquals(2.0, chart.effectiveness(PetType.SKILLING, PetType.ICE), 0.001);
		assertEquals(2.0, chart.effectiveness(PetType.SKILLING, PetType.UNDEAD), 0.001);
		// Skilling survivability: no longer weak to Melee or Ranged...
		assertEquals(1.0, chart.effectiveness(PetType.MELEE, PetType.SKILLING), 0.001);
		assertEquals(1.0, chart.effectiveness(PetType.RANGED, PetType.SKILLING), 0.001);
		// ...but still 2x from Magic, Undead, Demon and Dragon
		assertEquals(2.0, chart.effectiveness(PetType.MAGIC, PetType.SKILLING), 0.001);
		assertEquals(2.0, chart.effectiveness(PetType.UNDEAD, PetType.SKILLING), 0.001);
		assertEquals(2.0, chart.effectiveness(PetType.DEMON, PetType.SKILLING), 0.001);
		assertEquals(2.0, chart.effectiveness(PetType.DRAGON, PetType.SKILLING), 0.001);
		// Ice still resists Dragon attacks and Ice offense vs Dragon is retained
		assertEquals(0.5, chart.effectiveness(PetType.DRAGON, PetType.ICE), 0.001);
		assertEquals(2.0, chart.effectiveness(PetType.ICE, PetType.DRAGON), 0.001);
	}

	@Test
	public void dualTypesMultiply()
	{
		// Fire vs [Undead, Nature] = 2.0 * 2.0 = 4.0
		assertEquals(4.0, chart.effectiveness(PetType.FIRE,
			Arrays.asList(PetType.UNDEAD, PetType.NATURE)), 0.001);
		// Melee vs [Ranged, Magic] = 2.0 * 0.5 = 1.0
		assertEquals(1.0, chart.effectiveness(PetType.MELEE,
			Arrays.asList(PetType.RANGED, PetType.MAGIC)), 0.001);
	}

	@Test
	public void everyMatchupIsDefined()
	{
		for (PetType atk : PetType.values())
		{
			for (PetType def : PetType.values())
			{
				double eff = chart.effectiveness(atk, def);
				org.junit.Assert.assertTrue(atk + " vs " + def + " = " + eff,
					eff == 0.5 || eff == 1.0 || eff == 2.0);
			}
		}
	}
}

package com.petbattles.persist;

import com.google.gson.Gson;
import com.petbattles.data.ContentLoader;
import com.petbattles.data.PetDatabase;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The soft-currency wallet on {@link RosterManager}. Uses the real bundled content plus an
 * in-memory {@link RosterStore} so no RuneLite ConfigManager is needed.
 */
public class RosterManagerCoinsTest
{
	private RosterManager loadedManager()
	{
		PetDatabase db = PetDatabase.load(new ContentLoader(new Gson()));
		RosterStore store = new RosterStore(null, null)
		{
			private RosterData data = new RosterData();

			@Override
			public RosterData load()
			{
				return data;
			}

			@Override
			public void save(RosterData d)
			{
				this.data = d;
			}
		};
		RosterManager roster = new RosterManager(db, store);
		roster.load();
		return roster;
	}

	@Test
	public void walletStartsEmpty()
	{
		assertEquals(0, loadedManager().getCoins());
	}

	@Test
	public void addCoinsAccumulatesAndIgnoresNonPositive()
	{
		RosterManager roster = loadedManager();
		assertEquals(30, roster.addCoins(30));
		assertEquals(50, roster.addCoins(20));
		// Non-positive amounts are no-ops (never drain the wallet).
		assertEquals(50, roster.addCoins(0));
		assertEquals(50, roster.addCoins(-15));
		assertEquals(50, roster.getCoins());
	}

	@Test
	public void spendCoinsDeductsOnlyWhenAffordable()
	{
		RosterManager roster = loadedManager();
		roster.addCoins(100);
		assertTrue(roster.spendCoins(40));
		assertEquals(60, roster.getCoins());
		// Can't overspend, and the balance is untouched on a failed spend.
		assertFalse(roster.spendCoins(61));
		assertEquals(60, roster.getCoins());
		// Non-positive spends are rejected too.
		assertFalse(roster.spendCoins(0));
		assertFalse(roster.spendCoins(-5));
		assertEquals(60, roster.getCoins());
		// Spending the exact balance is allowed.
		assertTrue(roster.spendCoins(60));
		assertEquals(0, roster.getCoins());
	}
}

package com.petbattles.persist;

import com.google.gson.Gson;
import com.petbattles.data.ContentLoader;
import com.petbattles.data.PetDatabase;
import com.petbattles.engine.PetInstance;
import com.petbattles.item.EquipItemDef;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Cosmetic (HEAD/FACE) equipping on {@link RosterManager}. The behaviour that matters here and
 * differs from held items: equipping a cosmetic never consumes it, yet it still can't be duplicated
 * — a cosmetic may be worn by at most as many pets as the player owns copies of it, and equipping
 * one that's fully out moves it. Uses the real bundled {@code items.json}: {@code wizard_hat} and
 * {@code blue_party_hat} (HEAD), {@code stick} (HELD). Content defines no FACE item at present, so
 * the tests that need one supply their own — see {@link #loadedManagerWithFaceCosmetic()}.
 */
public class RosterManagerCosmeticsTest
{
	private static final String SPECIES = "baby_mole";
	private static final String SPECIES2 = "pet_snakeling";
	private static final String SPECIES3 = "baby_chinchompa";
	/** The capstone quest that grants the blue party hat; its own constant is private to the manager. */
	private static final String CAPSTONE_QUEST_ID = "series_of_fortunate_events";
	/** A FACE cosmetic that exists only in this test's content; see loadedManagerWithFaceCosmetic. */
	private static final String FACE_ITEM = "test_goggles";

	private RosterManager loadedManager()
	{
		return loadedManager(PetDatabase.load(new ContentLoader(new Gson())));
	}

	private RosterManager loadedManager(PetDatabase db)
	{
		RosterStore store = new RosterStore(null, null)
		{
			private RosterData data = new RosterData();

			@Override
			public RosterData load()
			{
				return data;
			}

			@Override
			public void save(RosterData d)
			{
				this.data = d;
			}
		};
		RosterManager roster = new RosterManager(db, store);
		roster.load();
		return roster;
	}

	/**
	 * The real content plus one synthetic FACE cosmetic.
	 *
	 * <p>The shipped {@code items.json} currently defines no FACE item — the sunglasses were pulled
	 * because a front-facing icon doesn't read on a three-quarter chathead — but the slot is live in
	 * code, and slot routing is exactly where a copy-paste bug would hide. Supplying our own item
	 * keeps that path covered without putting one back in the game.
	 */
	private RosterManager loadedManagerWithFaceCosmetic()
	{
		Gson gson = new Gson();
		ContentLoader loader = new ContentLoader(gson);
		List<EquipItemDef> items = new ArrayList<>(loader.loadEquipItems());
		// No sprite: nothing here renders, and naming a real PNG would imply otherwise.
		items.add(gson.fromJson("{\"id\":\"" + FACE_ITEM + "\",\"name\":\"Test goggles\","
			+ "\"slot\":\"FACE\",\"price\":10}", EquipItemDef.class));
		return loadedManager(new PetDatabase(loader.loadSpecies(), loader.loadMoves(),
			loader.loadTrainers(), items, loader.loadQuests(), loader.loadTypeChart()));
	}

	@Test
	public void equippingACosmeticFillsItsOwnSlotAndConsumesNothing()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.grantItem("wizard_hat", 1);

		assertTrue(roster.setCosmetic(SPECIES, "wizard_hat"));
		PetInstance pet = roster.getPet(SPECIES);
		assertEquals("wizard_hat", pet.getHeadItemId());
		assertNull(pet.getFaceItemId());
		// Unlike a held item, the unit is not decremented — the wear limit is enforced by counting
		// wearers (below), not by moving stock, so the inventory still reads one hat owned.
		assertEquals(1, roster.itemCount("wizard_hat"));
		assertEquals(1, roster.itemCapacity("wizard_hat"));
	}

	@Test
	public void headAndFaceSlotsAreIndependent()
	{
		RosterManager roster = loadedManagerWithFaceCosmetic();
		roster.unlock(SPECIES);
		roster.grantItem("wizard_hat", 1);
		roster.grantItem(FACE_ITEM, 1);

		// Each item routes to the slot it declares, and neither displaces the other.
		assertTrue(roster.setCosmetic(SPECIES, "wizard_hat"));
		assertTrue(roster.setCosmetic(SPECIES, FACE_ITEM));
		PetInstance pet = roster.getPet(SPECIES);
		assertEquals("wizard_hat", pet.getHeadItemId());
		assertEquals(FACE_ITEM, pet.getFaceItemId());

		assertTrue(roster.clearCosmetic(SPECIES, EquipItemDef.Slot.FACE));
		assertEquals("wizard_hat", pet.getHeadItemId());
		assertNull(pet.getFaceItemId());
	}

	@Test
	public void shippedContentDefinesNoFaceCosmetic()
	{
		// Guards the state this repo is deliberately in: the FACE slot is live in code but empty in
		// content. If a FACE item is added back, delete this test — and check it reads well on a
		// three-quarter chathead first (./gradlew previewCosmetics).
		RosterManager roster = loadedManager();
		for (EquipItemDef item : roster.ownedCosmetics())
		{
			assertEquals(EquipItemDef.Slot.HEAD, item.getSlot());
		}
		roster.advanceQuest(CAPSTONE_QUEST_ID, 99);
		roster.grantItem("wizard_hat", 1);
		assertEquals(2, roster.ownedCosmetics().size());
	}

	@Test
	public void oneCopyDressesOnePetAtATimeAndEquippingItAgainMovesIt()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.unlock(SPECIES2);
		roster.grantItem("wizard_hat", 1);

		assertTrue(roster.setCosmetic(SPECIES, "wizard_hat"));
		assertEquals(Collections.singletonList(SPECIES), roster.itemWearers("wizard_hat"));

		// One hat, so dressing the second pet takes it off the first rather than cloning it.
		assertTrue(roster.setCosmetic(SPECIES2, "wizard_hat"));
		assertNull(roster.getPet(SPECIES).getHeadItemId());
		assertEquals("wizard_hat", roster.getPet(SPECIES2).getHeadItemId());
		assertEquals(Collections.singletonList(SPECIES2), roster.itemWearers("wizard_hat"));
		// Still nothing consumed: the hat is owned exactly once throughout.
		assertEquals(1, roster.itemCount("wizard_hat"));

		// Freeing the slot frees the copy, so the first pet can have it back.
		assertTrue(roster.clearCosmetic(SPECIES2, EquipItemDef.Slot.HEAD));
		assertTrue(roster.itemWearers("wizard_hat").isEmpty());
		assertTrue(roster.setCosmetic(SPECIES, "wizard_hat"));
		assertEquals("wizard_hat", roster.getPet(SPECIES).getHeadItemId());
	}

	@Test
	public void ownedQuantityRaisesHowManyPetsCanWearIt()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.unlock(SPECIES2);
		roster.grantItem("wizard_hat", 2);
		assertEquals(2, roster.itemCapacity("wizard_hat"));

		// Two hats bought, two pets dressed — the second equip displaces nobody.
		assertTrue(roster.setCosmetic(SPECIES, "wizard_hat"));
		assertTrue(roster.setCosmetic(SPECIES2, "wizard_hat"));
		assertEquals("wizard_hat", roster.getPet(SPECIES).getHeadItemId());
		assertEquals("wizard_hat", roster.getPet(SPECIES2).getHeadItemId());
		assertEquals(Arrays.asList(SPECIES, SPECIES2), roster.itemWearers("wizard_hat"));

		// A third pet with only two hats owned takes one off the longest-standing wearer.
		roster.unlock(SPECIES3);
		assertTrue(roster.setCosmetic(SPECIES3, "wizard_hat"));
		assertNull(roster.getPet(SPECIES).getHeadItemId());
		assertEquals(Arrays.asList(SPECIES2, SPECIES3), roster.itemWearers("wizard_hat"));
	}

	@Test
	public void equippingIntoAnOccupiedSlotReplacesWithoutConsumingEither()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.grantItem("wizard_hat", 1);
		roster.grantItem("blue_party_hat", 1);

		assertTrue(roster.setCosmetic(SPECIES, "wizard_hat"));
		assertTrue(roster.setCosmetic(SPECIES, "blue_party_hat"));
		assertEquals("blue_party_hat", roster.getPet(SPECIES).getHeadItemId());
		// Neither was consumed, so the displaced hat is owned, unworn, and free to equip again.
		assertEquals(1, roster.itemCount("wizard_hat"));
		assertTrue(roster.ownsEquipItem("wizard_hat"));
		assertTrue(roster.itemWearers("wizard_hat").isEmpty());
	}

	@Test
	public void rejectsUnownedPetsUnownedItemsHeldItemsAndRepeats()
	{
		RosterManager roster = loadedManager();
		roster.grantItem("wizard_hat", 1);
		// Pet not unlocked yet.
		assertFalse(roster.setCosmetic(SPECIES, "wizard_hat"));

		roster.unlock(SPECIES);
		// Cosmetic the player doesn't own.
		assertFalse(roster.setCosmetic(SPECIES, "blue_party_hat"));
		// A HELD item is not a cosmetic and must not land in a cosmetic slot.
		roster.grantItem("stick", 1);
		assertFalse(roster.setCosmetic(SPECIES, "stick"));
		// Unknown id.
		assertFalse(roster.setCosmetic(SPECIES, "no_such_item"));
		// Nothing was written: a rejected equip must not even bring the pet instance into being.
		PetInstance beforeAnySuccess = roster.getPet(SPECIES);
		assertTrue(beforeAnySuccess == null || beforeAnySuccess.getHeadItemId() == null);

		assertTrue(roster.setCosmetic(SPECIES, "wizard_hat"));
		// Already worn — no redundant save.
		assertFalse(roster.setCosmetic(SPECIES, "wizard_hat"));
	}

	@Test
	public void clearingAnEmptySlotIsANoOp()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		assertFalse(roster.clearCosmetic(SPECIES, EquipItemDef.Slot.HEAD));
		assertFalse(roster.clearCosmetic(SPECIES, EquipItemDef.Slot.FACE));
	}

	@Test
	public void bluePartyHatIsWearableOffDerivedOwnershipWithNoInventoryUnit()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		// The trophy is earned from the capstone, so it never enters the item inventory. Before the
		// quest is done it is neither owned nor equippable.
		assertEquals(0, roster.itemCount("blue_party_hat"));
		assertFalse(roster.ownsEquipItem("blue_party_hat"));
		assertFalse(roster.setCosmetic(SPECIES, "blue_party_hat"));

		roster.advanceQuest(CAPSTONE_QUEST_ID, 99);
		assertTrue(roster.ownsEquipItem("blue_party_hat"));
		assertTrue(roster.setCosmetic(SPECIES, "blue_party_hat"));
		assertEquals("blue_party_hat", roster.getPet(SPECIES).getHeadItemId());
		assertEquals(0, roster.itemCount("blue_party_hat"));
	}

	@Test
	public void theTrophyIsOneHatEvenThoughItHasNoInventoryUnit()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.unlock(SPECIES2);
		roster.advanceQuest(CAPSTONE_QUEST_ID, 99);

		// Derived ownership gives capacity 1 with nothing in the inventory to count, so the trophy
		// moves between pets exactly like a bought hat rather than dressing the whole team.
		assertEquals(0, roster.itemCount("blue_party_hat"));
		assertEquals(1, roster.itemCapacity("blue_party_hat"));

		assertTrue(roster.setCosmetic(SPECIES, "blue_party_hat"));
		assertTrue(roster.setCosmetic(SPECIES2, "blue_party_hat"));
		assertNull(roster.getPet(SPECIES).getHeadItemId());
		assertEquals(Collections.singletonList(SPECIES2), roster.itemWearers("blue_party_hat"));
	}

	@Test
	public void aHeldItemIsNeverAcceptedIntoACosmeticSlot()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.grantItem("stick", 1);

		// Capacity and wearers are slot-agnostic — every item is counted the same way — but the slot
		// an item declares is still the only one it can go into.
		assertFalse(roster.setCosmetic(SPECIES, "stick"));
		assertTrue(roster.setHeldItem(SPECIES, "stick"));
		assertEquals(Collections.singletonList(SPECIES), roster.itemWearers("stick"));
		assertNull(roster.getPet(SPECIES).getHeadItemId());

		assertTrue(roster.itemWearers("no_such_item").isEmpty());
		assertEquals(0, roster.itemCapacity("wizard_hat"));
	}

	@Test
	public void ownedCosmeticsListsOnlyOwnedCosmeticsNeverHeldItems()
	{
		RosterManager roster = loadedManager();
		assertTrue(roster.ownedCosmetics().isEmpty());

		roster.grantItem("stick", 1);
		assertTrue(roster.ownedCosmetics().isEmpty());

		roster.grantItem("wizard_hat", 1);
		List<String> ids = roster.ownedCosmetics().stream()
			.map(EquipItemDef::getId).collect(Collectors.toList());
		assertEquals(1, ids.size());
		assertTrue(ids.contains("wizard_hat"));
	}
}

package com.petbattles.persist;

import com.google.gson.Gson;
import com.petbattles.data.ContentLoader;
import com.petbattles.data.PetDatabase;
import com.petbattles.engine.PetInstance;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * What {@link RosterManager#load()} does to a roster written by an older build.
 *
 * <p>Two things happen on load. A v1 blob is migrated: back then the inventory held only *spares*
 * because equipping a held item decremented it, so every worn copy is credited back to make the
 * count the true total. Then, at any version, every equip item is brought back within its capacity —
 * this is the half that catches a save where one amulet ended up on two pets, which the old
 * consume-on-equip model could produce and could not detect afterwards.
 */
public class RosterManagerEquipRepairTest
{
	private static final String SPECIES = "baby_mole";
	private static final String SPECIES2 = "pet_snakeling";

	/** A manager over a pre-seeded blob, as if it had just been read off disk. */
	private RosterManager managerOver(RosterStore.RosterData seed)
	{
		PetDatabase db = PetDatabase.load(new ContentLoader(new Gson()));
		RosterStore store = new RosterStore(null, null)
		{
			private RosterStore.RosterData data = seed;

			@Override
			public RosterStore.RosterData load()
			{
				return data;
			}

			@Override
			public void save(RosterStore.RosterData d)
			{
				this.data = d;
			}
		};
		RosterManager roster = new RosterManager(db, store);
		roster.load();
		return roster;
	}

	private static PetInstance petHolding(String itemId)
	{
		PetInstance pet = new PetInstance();
		pet.setHeldItemId(itemId);
		return pet;
	}

	@Test
	public void v1SparesBecomeTotalsByCreditingWornCopies()
	{
		// A healthy v1 save: three sticks bought, one of them worn, so the blob recorded two spares.
		RosterStore.RosterData v1 = new RosterStore.RosterData();
		v1.v = 1;
		v1.ownedSpecies.add(SPECIES);
		v1.pets.put(SPECIES, petHolding("stick"));
		v1.itemInventory.put("stick", 2);

		RosterManager roster = managerOver(v1);
		assertEquals("the worn copy is credited back", 3, roster.itemCount("stick"));
		assertEquals("stick", roster.getPet(SPECIES).getHeldItemId());
		assertEquals(Collections.singletonList(SPECIES), roster.itemWearers("stick"));
	}

	@Test
	public void migrationRunsOnceAndLeavesAV2SaveAlone()
	{
		RosterStore.RosterData v1 = new RosterStore.RosterData();
		v1.v = 1;
		v1.ownedSpecies.add(SPECIES);
		v1.pets.put(SPECIES, petHolding("stick"));
		v1.itemInventory.put("stick", 1);

		RosterManager roster = managerOver(v1);
		assertEquals(2, roster.itemCount("stick"));
		// The blob was rewritten at v2, so a second load must not credit the worn copy again.
		roster.unload();
		roster.load();
		assertEquals(2, roster.itemCount("stick"));
	}

	@Test
	public void twoPetsSharingOneHeldItemAreCreditedAsTwoCopies()
	{
		// The shape the old consume-on-equip build could leave behind: two pets holding one amulet
		// with nothing in the inventory. After crediting, that reads as two owned and two worn — which
		// is consistent — so the repair leaves both alone.
		RosterStore.RosterData v1 = new RosterStore.RosterData();
		v1.v = 1;
		v1.ownedSpecies.addAll(Arrays.asList(SPECIES, SPECIES2));
		v1.pets.put(SPECIES, petHolding("amulet_of_the_rogue"));
		v1.pets.put(SPECIES2, petHolding("amulet_of_the_rogue"));

		RosterManager roster = managerOver(v1);
		assertEquals(2, roster.itemCount("amulet_of_the_rogue"));
		assertEquals(Arrays.asList(SPECIES, SPECIES2), roster.itemWearers("amulet_of_the_rogue"));
	}

	@Test
	public void wearersBeyondTheCountAreStrippedOldestFirst()
	{
		// A v2 save that is simply wrong: one amulet owned, two pets wearing it. The repair keeps the
		// most recent wearer, since the older one has had the longer run of it.
		RosterStore.RosterData v2 = new RosterStore.RosterData();
		v2.ownedSpecies.addAll(Arrays.asList(SPECIES, SPECIES2));
		v2.pets.put(SPECIES, petHolding("amulet_of_the_rogue"));
		v2.pets.put(SPECIES2, petHolding("amulet_of_the_rogue"));
		v2.itemInventory.put("amulet_of_the_rogue", 1);

		RosterManager roster = managerOver(v2);
		assertNull(roster.getPet(SPECIES).getHeldItemId());
		assertEquals("amulet_of_the_rogue", roster.getPet(SPECIES2).getHeldItemId());
		assertEquals(Collections.singletonList(SPECIES2), roster.itemWearers("amulet_of_the_rogue"));
	}

	@Test
	public void aCosmeticWornWithNoCopiesOwnedIsStripped()
	{
		// Cosmetics were never consumed, so they are not credited on migration — a hat worn with an
		// empty inventory is simply not owned, and the repair takes it off.
		RosterStore.RosterData v2 = new RosterStore.RosterData();
		v2.ownedSpecies.add(SPECIES);
		PetInstance pet = new PetInstance();
		pet.setHeadItemId("wizard_hat");
		v2.pets.put(SPECIES, pet);

		RosterManager roster = managerOver(v2);
		assertNull(roster.getPet(SPECIES).getHeadItemId());
	}

	@Test
	public void aConsistentSaveIsLeftExactlyAsItWas()
	{
		RosterStore.RosterData v2 = new RosterStore.RosterData();
		v2.ownedSpecies.addAll(Arrays.asList(SPECIES, SPECIES2));
		v2.pets.put(SPECIES, petHolding("stick"));
		v2.pets.put(SPECIES2, petHolding("stick"));
		v2.itemInventory.put("stick", 2);
		v2.itemInventory.put("wizard_hat", 1);

		RosterManager roster = managerOver(v2);
		assertEquals(2, roster.itemCount("stick"));
		assertEquals(1, roster.itemCount("wizard_hat"));
		assertEquals(Arrays.asList(SPECIES, SPECIES2), roster.itemWearers("stick"));
		assertTrue(roster.itemWearers("wizard_hat").isEmpty());
	}
}

package com.petbattles.persist;

import com.google.gson.Gson;
import com.petbattles.data.ContentLoader;
import com.petbattles.data.PetDatabase;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The equip-item inventory and held-item equipping on {@link RosterManager}. Uses the real bundled
 * {@code items.json} plus an in-memory {@link RosterStore}. Ids: {@code stick} (HELD),
 * {@code wizard_hat} (HEAD cosmetic).
 *
 * <p>The rule under test: the inventory counts every copy owned, worn or not, and an item may be
 * held by at most that many pets. Equipping consumes nothing — see
 * {@link RosterManagerEquipRepairTest} for what happens to a save that breaks the rule.
 */
public class RosterManagerItemsTest
{
	private static final String SPECIES = "baby_mole";
	private static final String SPECIES2 = "pet_snakeling";

	private RosterManager loadedManager()
	{
		PetDatabase db = PetDatabase.load(new ContentLoader(new Gson()));
		RosterStore store = new RosterStore(null, null)
		{
			private RosterData data = new RosterData();

			@Override
			public RosterData load()
			{
				return data;
			}

			@Override
			public void save(RosterData d)
			{
				this.data = d;
			}
		};
		RosterManager roster = new RosterManager(db, store);
		roster.load();
		return roster;
	}

	@Test
	public void inventoryStartsEmpty()
	{
		RosterManager roster = loadedManager();
		assertEquals(0, roster.itemCount("stick"));
		assertFalse(roster.hasItem("stick"));
		assertTrue(roster.getItemInventory().isEmpty());
	}

	@Test
	public void grantAccumulatesAndRejectsUnknownOrNonPositive()
	{
		RosterManager roster = loadedManager();
		assertTrue(roster.grantItem("stick", 2));
		assertEquals(2, roster.itemCount("stick"));
		assertTrue(roster.grantItem("stick", 1));
		assertEquals(3, roster.itemCount("stick"));
		// Unknown id and non-positive counts are rejected.
		assertFalse(roster.grantItem("no_such_item", 1));
		assertFalse(roster.grantItem("stick", 0));
		assertFalse(roster.grantItem("stick", -1));
		assertEquals(3, roster.itemCount("stick"));
	}

	@Test
	public void takeRemovesOnlyWhenEnoughAndDropsKeyAtZero()
	{
		RosterManager roster = loadedManager();
		roster.grantItem("stick", 2);
		assertFalse("cannot take more than owned", roster.takeItem("stick", 3));
		assertEquals(2, roster.itemCount("stick"));
		assertTrue(roster.takeItem("stick", 1));
		assertEquals(1, roster.itemCount("stick"));
		assertTrue(roster.takeItem("stick", 1));
		assertEquals(0, roster.itemCount("stick"));
		assertFalse(roster.hasItem("stick"));
		assertTrue("key dropped at zero", roster.getItemInventory().isEmpty());
	}

	@Test
	public void equipRequiresOwnedPetOwnedHeldItem()
	{
		RosterManager roster = loadedManager();
		// Not owned yet -> cannot equip.
		assertFalse(roster.setHeldItem(SPECIES, "stick"));

		roster.unlock(SPECIES);
		// Owned pet, but the item isn't in the inventory.
		assertFalse(roster.setHeldItem(SPECIES, "stick"));

		roster.grantItem("stick", 1);
		assertTrue(roster.setHeldItem(SPECIES, "stick"));
		assertEquals("stick", roster.getPet(SPECIES).getHeldItemId());

		// Re-equipping the same item is a no-op.
		assertFalse(roster.setHeldItem(SPECIES, "stick"));
	}

	@Test
	public void cannotEquipCosmeticOrUnknownAsHeld()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.grantItem("wizard_hat", 1);
		// wizard_hat is a HEAD cosmetic, not a HELD item.
		assertFalse(roster.setHeldItem(SPECIES, "wizard_hat"));
		assertFalse(roster.setHeldItem(SPECIES, "no_such_item"));
		// Both equips bailed before the pet record was lazily created — nothing was equipped.
		assertNull(roster.getPet(SPECIES));
	}

	@Test
	public void clearHeldItemRemovesIt()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.grantItem("stick", 1);
		roster.setHeldItem(SPECIES, "stick");

		assertTrue(roster.clearHeldItem(SPECIES));
		assertNull(roster.getPet(SPECIES).getHeldItemId());
		// Nothing to clear now.
		assertFalse(roster.clearHeldItem(SPECIES));
	}

	@Test
	public void equippingConsumesNothingAndTheCountStaysTheTotalOwned()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.grantItem("stick", 2);
		assertTrue(roster.setHeldItem(SPECIES, "stick"));
		// The inventory is the total owned, worn copies included — nothing is decremented.
		assertEquals(2, roster.itemCount("stick"));
		assertEquals(2, roster.itemCapacity("stick"));
		assertEquals(Collections.singletonList(SPECIES), roster.itemWearers("stick"));
	}

	@Test
	public void oneCopyIsHeldByOnePetAndEquippingItAgainMovesIt()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.unlock(SPECIES2);
		roster.grantItem("stick", 1);
		assertTrue(roster.setHeldItem(SPECIES, "stick"));

		// One stick, so arming the second pet takes it off the first rather than cloning the bonus.
		assertTrue(roster.setHeldItem(SPECIES2, "stick"));
		assertNull(roster.getPet(SPECIES).getHeldItemId());
		assertEquals("stick", roster.getPet(SPECIES2).getHeldItemId());
		assertEquals(Collections.singletonList(SPECIES2), roster.itemWearers("stick"));
		assertEquals(1, roster.itemCount("stick"));
	}

	@Test
	public void ownedQuantityIsHowManyPetsCanHoldIt()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.unlock(SPECIES2);
		roster.grantItem("stick", 2);

		assertTrue(roster.setHeldItem(SPECIES, "stick"));
		assertTrue(roster.setHeldItem(SPECIES2, "stick"));
		// Two bought, two armed, neither displaced.
		assertEquals(Arrays.asList(SPECIES, SPECIES2), roster.itemWearers("stick"));
		assertEquals("stick", roster.getPet(SPECIES).getHeldItemId());
	}

	@Test
	public void unequippingFreesTheCopyWithoutChangingTheCount()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.unlock(SPECIES2);
		roster.grantItem("stick", 1);
		roster.setHeldItem(SPECIES, "stick");
		assertEquals(1, roster.itemCount("stick"));

		assertTrue(roster.clearHeldItem(SPECIES));
		assertEquals("the count never moved", 1, roster.itemCount("stick"));
		assertTrue(roster.itemWearers("stick").isEmpty());
		// Freed, so the other pet takes it with nothing displaced.
		assertTrue(roster.setHeldItem(SPECIES2, "stick"));
	}

	@Test
	public void swappingReleasesThePreviousItemForAnotherPet()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.unlock(SPECIES2);
		roster.grantItem("stick", 1);
		roster.grantItem("sturdy_bracer", 1);
		roster.setHeldItem(SPECIES, "stick");

		assertTrue(roster.setHeldItem(SPECIES, "sturdy_bracer"));
		assertEquals("sturdy_bracer", roster.getPet(SPECIES).getHeldItemId());
		// Both are still owned, and the displaced stick is now free for the other pet.
		assertEquals(1, roster.itemCount("stick"));
		assertEquals(1, roster.itemCount("sturdy_bracer"));
		assertTrue(roster.itemWearers("stick").isEmpty());
		assertTrue(roster.setHeldItem(SPECIES2, "stick"));
	}

	@Test
	public void givingAnItemAwayTakesItOffTheWearer()
	{
		RosterManager roster = loadedManager();
		roster.unlock(SPECIES);
		roster.grantItem("stick", 1);
		roster.setHeldItem(SPECIES, "stick");

		// Losing the only copy has to take it off the pet too, or the pet would hold what isn't owned.
		assertTrue(roster.takeItem("stick", 1));
		assertEquals(0, roster.itemCount("stick"));
		assertNull(roster.getPet(SPECIES).getHeldItemId());
	}
}

package com.petbattles.persist;

import com.google.gson.Gson;
import com.petbattles.data.ContentLoader;
import com.petbattles.data.PetDatabase;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Quest progression and the remote-battle unlock it gates. "Where's the Remote?" is a data quest;
 * completing it (owning the Remote Battle Device) is what lets the player re-fight already-beaten
 * trainers remotely. Uses the real bundled content plus an in-memory {@link RosterStore}.
 */
public class RosterManagerQuestTest
{
	private static final String REMOTE = "wheres_the_remote";

	private final PetDatabase db = PetDatabase.load(new ContentLoader(new Gson()));

	private RosterManager loadedManager()
	{
		RosterStore store = new RosterStore(null, null)
		{
			private RosterData data = new RosterData();

			@Override
			public RosterData load()
			{
				return data;
			}

			@Override
			public void save(RosterData d)
			{
				this.data = d;
			}
		};
		RosterManager roster = new RosterManager(db, store);
		roster.load();
		return roster;
	}

	private int completeStep()
	{
		return db.quest(REMOTE).completeStep();
	}

	@Test
	public void questStartsUnstartedAndRemoteLocked()
	{
		RosterManager roster = loadedManager();
		assertEquals(0, roster.getQuestStep(REMOTE));
		assertFalse("remote battles locked until the device is earned", roster.isRemoteBattlesUnlocked());
	}

	@Test
	public void completingQuestUnlocksRemoteBattles()
	{
		RosterManager roster = loadedManager();
		assertTrue(roster.advanceQuest(REMOTE, completeStep()));
		assertTrue(roster.isRemoteBattlesUnlocked());
	}

	@Test
	public void canRemoteFightOnlyAfterBeatingInPerson()
	{
		RosterManager roster = loadedManager();
		roster.advanceQuest(REMOTE, completeStep()); // owns the device
		assertFalse("un-calibrated trainer: not yet remote-fightable", roster.canRemoteFight("gertrude"));
		roster.recordTrainerDefeated("gertrude");
		assertTrue("beaten in person -> now remote-fightable", roster.canRemoteFight("gertrude"));
	}

	@Test
	public void advanceQuestIsIdempotentAndNeverRegresses()
	{
		RosterManager roster = loadedManager();
		assertTrue(roster.advanceQuest(REMOTE, 1));
		assertFalse("already at (or beyond) the target step: no forward movement",
			roster.advanceQuest(REMOTE, 1));
		assertFalse(roster.advanceQuest(REMOTE, 0));
		assertEquals(1, roster.getQuestStep(REMOTE));
	}
}

package com.petbattles.persist;

import com.google.gson.Gson;
import com.petbattles.data.ContentLoader;
import com.petbattles.data.PetDatabase;
import com.petbattles.engine.Leveling;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The per-trainer win counter that drives the re-fight reward taper
 * ({@link Leveling#repeatFactor(int)}). Uses the real bundled content plus an in-memory
 * {@link RosterStore} so no RuneLite ConfigManager is needed.
 */
public class RosterManagerTrainerWinsTest
{
	private static final String TRAINER = "hans";

	/** An in-memory store seeded with {@code seed}, so a pre-taper save can be replayed. */
	private RosterManager loadedManager(RosterStore.RosterData seed)
	{
		PetDatabase db = PetDatabase.load(new ContentLoader(new Gson()));
		RosterStore store = new RosterStore(null, null)
		{
			private RosterData data = seed;

			@Override
			public RosterData load()
			{
				return data;
			}

			@Override
			public void save(RosterData d)
			{
				this.data = d;
			}
		};
		RosterManager roster = new RosterManager(db, store);
		roster.load();
		return roster;
	}

	private RosterManager loadedManager()
	{
		return loadedManager(new RosterStore.RosterData());
	}

	@Test
	public void winsCountUpFromZeroAndFlagTheFirstDefeat()
	{
		RosterManager roster = loadedManager();
		assertEquals(0, roster.trainerWins(TRAINER));
		assertFalse(roster.isTrainerDefeated(TRAINER));

		roster.recordTrainerDefeated(TRAINER);
		assertEquals(1, roster.trainerWins(TRAINER));
		assertTrue("the first win is what unlocks remote re-fights", roster.isTrainerDefeated(TRAINER));

		roster.recordTrainerDefeated(TRAINER);
		roster.recordTrainerDefeated(TRAINER);
		assertEquals(3, roster.trainerWins(TRAINER));
		assertEquals("other trainers are counted separately", 0, roster.trainerWins("probita"));
	}

	@Test
	public void unknownTrainersAreNotRecorded()
	{
		RosterManager roster = loadedManager();
		roster.recordTrainerDefeated("not_a_trainer");
		assertEquals(0, roster.trainerWins("not_a_trainer"));
		assertFalse(roster.isTrainerDefeated("not_a_trainer"));
	}

	@Test
	public void aSaveFromBeforeTheCounterReadsAsASingleWin()
	{
		// Pre-taper saves only recorded *that* a trainer was beaten. Reading that as one win keeps a
		// long-farmed trainer off the full first-win rate; the next win then counts from there.
		RosterStore.RosterData legacy = new RosterStore.RosterData();
		legacy.defeatedTrainers.add(TRAINER);
		RosterManager roster = loadedManager(legacy);

		assertEquals(1, roster.trainerWins(TRAINER));
		assertTrue(Leveling.repeatFactor(roster.trainerWins(TRAINER)) < 1.0);

		roster.recordTrainerDefeated(TRAINER);
		assertEquals(2, roster.trainerWins(TRAINER));
	}

	@Test
	public void countsForTrainersDroppedFromTheContentAreCleanedUpOnLoad()
	{
		RosterStore.RosterData stale = new RosterStore.RosterData();
		stale.trainerWins.put("removed_trainer", 4);
		stale.defeatedTrainers.add("removed_trainer");

		assertEquals(0, loadedManager(stale).trainerWins("removed_trainer"));
	}
}

package com.petbattles.quest;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** The pure conversation cursor: line paging, choice branches (ask again vs exit), completion. */
public class ConversationStateTest
{
	private static Conversation.Node line(String speaker, String text)
	{
		return new Conversation.Node(speaker, text);
	}

	private static Conversation.Node choice(Conversation.Option... options)
	{
		// The choice list is private + Gson-populated in production, so tests use a small subtype
		// whose choice is set directly.
		return new TestChoiceNode(Arrays.asList(options));
	}

	/** A Node whose choice list is set directly, for tests (production sets it via Gson). */
	private static final class TestChoiceNode extends Conversation.Node
	{
		private final List<Conversation.Option> options;

		TestChoiceNode(List<Conversation.Option> options)
		{
			this.options = options;
		}

		@Override
		public List<Conversation.Option> getChoice()
		{
			return options;
		}

		@Override
		public boolean isChoice()
		{
			return options != null && !options.isEmpty();
		}
	}

	@Test
	public void emptyConversationIsImmediatelyDone()
	{
		ConversationState s = new ConversationState(new ArrayList<>());
		assertTrue(s.isDone());
		assertNull(s.current());
	}

	@Test
	public void linearLinesPageThroughInOrder()
	{
		ConversationState s = new ConversationState(Arrays.asList(
			line("hans", "Rumour has it..."),
			line("player", "Where, exactly?"),
			line("hans", "Draynor way, I heard.")));

		assertEquals(ConversationState.Kind.LINE, s.current().getKind());
		assertEquals("hans", s.current().getSpeaker());
		assertEquals("Rumour has it...", s.current().getText());
		s.advance();
		assertEquals("player", s.current().getSpeaker());
		s.advance();
		assertEquals("Draynor way, I heard.", s.current().getText());
		assertFalse(s.isDone());
		s.advance();
		assertTrue(s.isDone());
		assertNull(s.current());
	}

	@Test
	public void choiceQuestionReturnsToMenuThenExitProceeds()
	{
		Conversation.Option ask = new Conversation.Option("Ask about the wall",
			Arrays.asList(line("banker", "Fresh mortar, that.")), false);
		Conversation.Option leave = new Conversation.Option("Say nothing", new ArrayList<>(), true);
		ConversationState s = new ConversationState(Arrays.asList(
			line("banker", "Deposit? Withdrawal?"),
			choice(ask, leave),
			line("guard", "Stop snooping!")));

		s.advance(); // past the opening line -> the choice menu
		assertEquals(ConversationState.Kind.CHOICE, s.current().getKind());
		assertEquals(Arrays.asList("Ask about the wall", "Say nothing"), s.current().getOptions());

		// Ask the question: its line plays, then we return to the menu.
		s.pick(0);
		assertEquals("Fresh mortar, that.", s.current().getText());
		s.advance();
		assertEquals(ConversationState.Kind.CHOICE, s.current().getKind());

		// Ask again — a non-exit option is repeatable.
		s.pick(0);
		assertEquals("Fresh mortar, that.", s.current().getText());
		s.advance();
		assertEquals(ConversationState.Kind.CHOICE, s.current().getKind());

		// Take the exit option: proceed past the choice to the next line.
		s.pick(1);
		assertEquals(ConversationState.Kind.LINE, s.current().getKind());
		assertEquals("Stop snooping!", s.current().getText());
		s.advance();
		assertTrue(s.isDone());
	}

	@Test
	public void exitOptionWithLinesPlaysThemThenProceeds()
	{
		Conversation.Option go = new Conversation.Option("Let's get on with it",
			Arrays.asList(line("player", "Right. Enough talk.")), true);
		ConversationState s = new ConversationState(Arrays.asList(
			choice(go),
			line("professor", "Splendid!")));

		assertEquals(ConversationState.Kind.CHOICE, s.current().getKind());
		s.pick(0);
		assertEquals("Right. Enough talk.", s.current().getText());
		s.advance(); // finish the exit branch -> past the choice
		assertEquals("Splendid!", s.current().getText());
		s.advance();
		assertTrue(s.isDone());
	}

	@Test
	public void pickAndAdvanceAreNoOpsInTheWrongState()
	{
		ConversationState s = new ConversationState(Arrays.asList(line("hans", "Hello.")));
		s.pick(0); // no choice showing -> ignored
		assertEquals("Hello.", s.current().getText());
		// advance() on a choice menu is a no-op (UI must pick):
		Conversation.Option leave = new Conversation.Option("Bye", new ArrayList<>(), true);
		ConversationState c = new ConversationState(Arrays.asList(choice(leave), line("x", "after")));
		c.advance();
		assertEquals(ConversationState.Kind.CHOICE, c.current().getKind());
	}
}

package com.petbattles.quest;

import com.google.gson.Gson;
import com.petbattles.data.ContentLoader;
import com.petbattles.data.PetDatabase;
import com.petbattles.persist.RosterManager;
import com.petbattles.persist.RosterStore;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The quest dialog frame's state machine, driven against the real bundled content ("Where's the
 * Remote?": a Hans talk chapter followed by the Professor's battle chapter) plus an in-memory
 * {@link RosterStore}, so no RuneLite ConfigManager or UI is involved.
 */
public class QuestDialogSessionTest
{
	private static final String REMOTE = "wheres_the_remote";

	private final Set<String> near = new HashSet<>();
	private boolean battling;

	private PetDatabase database()
	{
		return PetDatabase.load(new ContentLoader(new Gson()));
	}

	private RosterManager loadedManager(PetDatabase db)
	{
		RosterStore store = new RosterStore(null, null)
		{
			private RosterData data = new RosterData();

			@Override
			public RosterData load()
			{
				return data;
			}

			@Override
			public void save(RosterData d)
			{
				this.data = d;
			}
		};
		RosterManager roster = new RosterManager(db, store);
		roster.load();
		return roster;
	}

	private QuestDialogSession session(RosterManager roster, PetDatabase db)
	{
		return new QuestDialogSession(db, roster, new QuestManager(db, roster), () -> near,
			() -> battling);
	}

	/**
	 * Page through whatever conversation is open until it is spent, taking the last reply of any
	 * choice (the authored exit option). Guarded against a cursor that refuses to move on.
	 */
	private void talkThrough(QuestDialogSession dialog)
	{
		dialog.open();
		int guard = 0;
		while (guard++ < 100)
		{
			QuestDialogSession.Scene scene = dialog.current();
			if (scene == null)
			{
				return;
			}
			if (scene.getKind() == QuestDialogSession.Kind.LINE)
			{
				dialog.advance();
			}
			else if (scene.getKind() == QuestDialogSession.Kind.CHOICE)
			{
				dialog.pick(scene.getChoices().size() - 1);
			}
			else
			{
				return;
			}
		}
	}

	@Test
	public void nothingIsOfferedWhileNoQuestNpcIsInReach()
	{
		PetDatabase db = database();
		QuestDialogSession dialog = session(loadedManager(db), db);

		assertNull("no beat with nobody around", dialog.current());
	}

	@Test
	public void reachingTheChapterNpcOffersACollapsedPrompt()
	{
		PetDatabase db = database();
		QuestDialogSession dialog = session(loadedManager(db), db);
		near.add("hans");

		QuestDialogSession.Scene scene = dialog.current();
		assertNotNull(scene);
		assertEquals(QuestDialogSession.Kind.PROMPT, scene.getKind());
		assertEquals("Talk to Hans", scene.getText());
		assertEquals("Start from Scratch", scene.getTitle());
		assertEquals("hans", scene.getSpeaker());
		assertEquals(QuestDialogSession.ACTION_OPEN, scene.getChoices().get(0).getAction());
	}

	@Test
	public void openingThePromptStartsTheConversationAndDismissingFoldsItBack()
	{
		PetDatabase db = database();
		QuestDialogSession dialog = session(loadedManager(db), db);
		near.add("hans");

		dialog.open();
		QuestDialogSession.Scene scene = dialog.current();
		assertEquals(QuestDialogSession.Kind.LINE, scene.getKind());
		assertEquals("Hans", scene.getSpeakerName());
		assertTrue(scene.getText().startsWith("Hello. Lovely day for it."));
		assertEquals(QuestDialogSession.ACTION_CONTINUE, scene.getChoices().get(0).getAction());

		dialog.dismiss();
		assertEquals("dismissing collapses without losing the cursor",
			QuestDialogSession.Kind.PROMPT, dialog.current().getKind());
		dialog.open();
		assertEquals("reopening resumes the same line", scene.getText(), dialog.current().getText());
	}

	@Test
	public void payingThroughATalkChapterClearsItAndTheNextChapterStartsCollapsed()
	{
		PetDatabase db = database();
		RosterManager roster = loadedManager(db);
		QuestDialogSession dialog = session(roster, db);
		near.add("hans");

		talkThrough(dialog);

		assertEquals("the talk chapter cleared itself", 1, roster.getQuestStep(REMOTE));
		assertNull("Hans has nothing left to say", dialog.current());
	}

	@Test
	public void aBattleChapterEndsInAChallengeInsideTheFrame()
	{
		PetDatabase db = database();
		RosterManager roster = loadedManager(db);
		QuestDialogSession dialog = session(roster, db);
		near.add("hans");
		talkThrough(dialog);
		near.clear();
		near.add("professor_oddenstein");

		talkThrough(dialog);

		QuestDialogSession.Scene scene = dialog.current();
		assertNotNull(scene);
		assertEquals(QuestDialogSession.Kind.ACTION, scene.getKind());
		QuestDialogSession.Choice challenge = scene.getChoices().get(0);
		assertEquals("Challenge Professor Oddenstein", challenge.getLabel());
		assertEquals(QuestDialogSession.ACTION_FIGHT + "professor_oddenstein", challenge.getAction());
		assertFalse("no team, so the challenge is offered but not pressable", challenge.isEnabled());
		assertEquals("Add a pet to your team first", scene.getHint());
		assertEquals("the battle, not the frame, clears the chapter", 1, roster.getQuestStep(REMOTE));
	}

	@Test
	public void anOpenConversationSurvivesTheNpcWanderingOffButTheChallengeDoesNot()
	{
		PetDatabase db = database();
		QuestDialogSession dialog = session(loadedManager(db), db);
		near.add("hans");
		dialog.open();
		dialog.advance();

		near.clear();
		QuestDialogSession.Scene scene = dialog.current();
		assertNotNull("a patrolling Hans can't cut his own scene short", scene);
		assertEquals(QuestDialogSession.Kind.LINE, scene.getKind());

		// Once it is spent the latch ends, so the chapter is out of reach again.
		near.add("hans");
		talkThrough(dialog);
		near.clear();
		assertNull("the Professor still has to be found in person", dialog.current());
	}

	@Test
	public void repliesAreOfferedAsAChoiceAndPickingOnePlaysItsLines()
	{
		PetDatabase db = database();
		RosterManager roster = loadedManager(db);
		QuestDialogSession dialog = session(roster, db);
		near.add("hans");
		talkThrough(dialog);
		near.clear();
		near.add("professor_oddenstein");
		dialog.open();

		QuestDialogSession.Scene scene = dialog.current();
		while (scene.getKind() == QuestDialogSession.Kind.LINE)
		{
			dialog.advance();
			scene = dialog.current();
		}
		assertEquals(QuestDialogSession.Kind.CHOICE, scene.getKind());
		assertFalse("the Professor's chapter asks the player something", scene.getChoices().isEmpty());
		assertEquals(QuestDialogSession.ACTION_PICK + "0", scene.getChoices().get(0).getAction());

		dialog.pick(0);
		assertEquals("picking a reply plays its lines", QuestDialogSession.Kind.LINE,
			dialog.current().getKind());
	}

	@Test
	public void resetDropsEveryCursorSoTheNextLoginStartsFresh()
	{
		PetDatabase db = database();
		QuestDialogSession dialog = session(loadedManager(db), db);
		near.add("hans");
		dialog.open();
		dialog.advance();
		dialog.advance();

		dialog.reset();

		QuestDialogSession.Scene scene = dialog.current();
		assertEquals(QuestDialogSession.Kind.PROMPT, scene.getKind());
		dialog.open();
		assertTrue("the chapter reads from its first line again",
			dialog.current().getText().startsWith("Hello. Lovely day for it."));
	}

	@Test
	public void thePayoffWaitsForTheBattleWindowThenOutranksTheWorld()
	{
		PetDatabase db = database();
		QuestDialogSession dialog = session(loadedManager(db), db);
		near.add("hans");
		battling = true;

		assertNull("the battle window owns the screen while a fight runs", dialog.current());

		// The battle clears a chapter and hands over its payoff, but the summary (level-ups, learned
		// moves) and any forget-a-move prompt still have the screen: the NPC waits his turn.
		dialog.play(db.quest(REMOTE).getChapters().get(1).getRewardConversation());
		assertNull("nothing talks over the level-up summary", dialog.current());

		battling = false;
		QuestDialogSession.Scene scene = dialog.current();
		assertNotNull(scene);
		assertEquals("an earned conversation opens expanded, not as a pill",
			QuestDialogSession.Kind.LINE, scene.getKind());
		assertEquals("Professor Oddenstein", scene.getSpeakerName());
		assertEquals("it outranks the Hans beat the world is offering", "Professor Oddenstein",
			dialog.current().getSpeakerName());

		int guard = 0;
		while (dialog.current() != null && dialog.current().getKind() == QuestDialogSession.Kind.LINE
			&& guard++ < 100)
		{
			dialog.advance();
		}
		assertEquals("Hans is offered again once the payoff is spent",
			QuestDialogSession.Kind.PROMPT, dialog.current().getKind());
	}

	@Test
	public void anEmptyPayoffLeavesTheFrameAlone()
	{
		PetDatabase db = database();
		QuestDialogSession dialog = session(loadedManager(db), db);

		dialog.play(Collections.emptyList());

		assertNull("a chapter with no payoff conversation shows nothing", dialog.current());
	}

	@Test
	public void nothingIsOfferedBeforeTheRosterHasLoaded()
	{
		PetDatabase db = database();
		RosterManager roster = new RosterManager(db, new RosterStore(null, null)
		{
			@Override
			public RosterData load()
			{
				return new RosterData();
			}

			@Override
			public void save(RosterData d)
			{
			}
		});
		QuestDialogSession dialog = session(roster, db);
		near.addAll(Collections.singleton("hans"));

		assertNull("no quest prompts on the login screen", dialog.current());
	}
}

package com.petbattles.quest;

import com.google.gson.Gson;
import com.petbattles.data.ContentLoader;
import com.petbattles.data.PetDatabase;
import com.petbattles.item.Item;
import com.petbattles.persist.RosterManager;
import com.petbattles.persist.RosterStore;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The data-described quest framework, driven through the whole capstone "A Series of Fortunate
 * Events" plus its prerequisite "Where's the Remote?". Uses the real bundled content plus an
 * in-memory {@link RosterStore} so no RuneLite ConfigManager is needed.
 */
public class QuestManagerTest
{
	private static final String REMOTE = "wheres_the_remote";
	private static final String CAPSTONE = "series_of_fortunate_events";
	private static final String GIMBLEWAP = "ambassador_gimblewap";
	private static final String WISE_OLD_MAN = "wise_old_man";

	// No shipped chapter is a hunt any more, but QuestDef/QuestManager still support one, so the hunt
	// engine is covered against this fixture rather than against quests.json. Ch.0 is a plain talk so
	// the hunt sits at step 1, proving the counter isn't tied to being the first chapter.
	private static final String HUNT_QUEST = "hunt_fixture";
	private static final String SUSPECT_A = "greybeard_a";
	private static final String SUSPECT_B = "greybeard_b";
	private static final String SUSPECT_C = "greybeard_c";
	private static final String HUNT_QUEST_JSON = "{"
		+ "'id':'" + HUNT_QUEST + "','title':'Hunt Fixture','chapters':["
		+ "{'step':0,'title':'Opening','intro':[{'text':'A rumour of greybeards.'}]},"
		+ "{'step':1,'title':'The Hunt',"
		+ "'battlePool':['" + SUSPECT_A + "','" + SUSPECT_B + "','" + SUSPECT_C + "'],"
		+ "'battlesRequired':3,"
		+ "'suspects':[{'trainer':'" + SUSPECT_C + "',"
		+ "'concede':[{'speaker':'" + SUSPECT_C + "','text':'Not I.'}],"
		+ "'finale':[{'speaker':'" + SUSPECT_C + "','text':'Which leaves Draynor.'}]}]}"
		+ "]}";

	private PetDatabase database()
	{
		return PetDatabase.load(new ContentLoader(new Gson()));
	}

	/** The bundled content plus {@link #HUNT_QUEST_JSON}, for exercising the dormant hunt path. */
	private PetDatabase databaseWithHuntFixture()
	{
		ContentLoader loader = new ContentLoader(new Gson());
		List<QuestDef> quests = new ArrayList<>(loader.loadQuests());
		quests.add(new Gson().fromJson(HUNT_QUEST_JSON.replace('\'', '"'), QuestDef.class));
		return new PetDatabase(loader.loadSpecies(), loader.loadMoves(), loader.loadTrainers(),
			loader.loadEquipItems(), quests, loader.loadTypeChart());
	}

	private RosterManager loadedManager()
	{
		return loadedManager(database());
	}

	private RosterManager loadedManager(PetDatabase db)
	{
		RosterStore store = new RosterStore(null, null)
		{
			private RosterData data = new RosterData();

			@Override
			public RosterData load()
			{
				return data;
			}

			@Override
			public void save(RosterData d)
			{
				this.data = d;
			}
		};
		RosterManager roster = new RosterManager(db, store);
		roster.load();
		return roster;
	}

	private QuestManager questManager(RosterManager roster)
	{
		return questManager(roster, database());
	}

	private QuestManager questManager(RosterManager roster, PetDatabase db)
	{
		return new QuestManager(db, roster);
	}

	/** Mark the prerequisite quest complete so the capstone is available. */
	private void unlockCapstone(RosterManager roster, QuestManager quests)
	{
		roster.advanceQuest(REMOTE, quests.quest(REMOTE).completeStep());
	}

	/** Perform the correct clearing action for whatever chapter a quest is currently on. */
	private void clearCurrentChapter(QuestManager quests, String questId)
	{
		QuestDef.Chapter ch = quests.currentChapter(questId);
		if (ch == null)
		{
			return;
		}
		if (ch.isBattle())
		{
			quests.onTrainerDefeated(ch.getBattleTrainer());
		}
		else if (ch.isHunt())
		{
			for (String member : ch.getBattlePool())
			{
				quests.onTrainerDefeated(member);
			}
		}
		else
		{
			quests.completeTalk(questId);
		}
	}

	/** Drive an available capstone forward until it sits on {@code targetStep}. */
	private void driveCapstoneToStep(RosterManager roster, QuestManager quests, int targetStep)
	{
		unlockCapstone(roster, quests);
		int guard = 0;
		while (roster.getQuestStep(CAPSTONE) < targetStep && guard++ < 50)
		{
			clearCurrentChapter(quests, CAPSTONE);
		}
		assertEquals("driven to the expected capstone step", targetStep, roster.getQuestStep(CAPSTONE));
	}

	@Test
	public void remoteQuestStartsWithHansTalkChapter()
	{
		RosterManager roster = loadedManager();
		QuestManager quests = questManager(roster);

		QuestDef.Chapter ch = quests.currentChapter(REMOTE);
		assertNotNull(ch);
		assertEquals(0, ch.getStep());
		assertFalse("Hans is a talk chapter, not a battle", ch.isBattle());
		assertEquals("hans", ch.getGateTrainer());
	}

	@Test
	public void beatingTheProfessorCompletesTheRemoteQuest()
	{
		RosterManager roster = loadedManager();
		QuestManager quests = questManager(roster);
		assertFalse(roster.isRemoteBattlesUnlocked());

		quests.completeTalk(REMOTE);                       // Hans -> advance to the Professor
		assertEquals(1, roster.getQuestStep(REMOTE));
		QuestManager.DefeatResult r = quests.onTrainerDefeated("professor_oddenstein");
		assertNotNull(r);
		assertEquals("Remote Battle Device", r.getRewardItemName());
		assertTrue("the device unlocks remote battles", roster.isRemoteBattlesUnlocked());
		assertTrue(quests.isComplete(REMOTE));
	}

	@Test
	public void capstoneLockedUntilRemoteQuestComplete()
	{
		RosterManager roster = loadedManager();
		QuestManager quests = questManager(roster);

		assertFalse("locked before the prerequisite is done", quests.isAvailable(quests.quest(CAPSTONE)));
		unlockCapstone(roster, quests);
		assertTrue("unlocked once the prerequisite is complete", quests.isAvailable(quests.quest(CAPSTONE)));
	}

	@Test
	public void offChapterOrLockedTrainerDefeatDoesNothing()
	{
		RosterManager roster = loadedManager();
		QuestManager quests = questManager(roster);
		// Capstone locked (no prerequisite): beating a story trainer must not progress it.
		assertNull(quests.onTrainerDefeated("draynor_guard"));

		driveCapstoneToStep(roster, quests, 1); // on the guard battle chapter now
		// A trainer that isn't this chapter's target does nothing.
		assertNull(quests.onTrainerDefeated("martin_thwait"));
		assertEquals(1, roster.getQuestStep(CAPSTONE));
	}

	@Test
	public void battleChaptersGrantHeldItemsAndAdvance()
	{
		RosterManager roster = loadedManager();
		QuestManager quests = questManager(roster);

		// The Draynor guard carries no reward block: the win still clears the chapter and returns its
		// end-screen conversation, it just hands over nothing.
		driveCapstoneToStep(roster, quests, 1);
		QuestManager.DefeatResult guard = quests.onTrainerDefeated("draynor_guard");
		assertNotNull("beating the guard clears the chapter", guard);
		assertNull("no reward block on the guard chapter", guard.getRewardItemName());
		assertEquals(0, guard.getRewardCoins());
		assertFalse("the guard's payoff still plays", guard.getConversation().isEmpty());
		assertEquals(2, roster.getQuestStep(CAPSTONE));

		driveCapstoneToStep(roster, quests, 3);
		QuestManager.DefeatResult martin = quests.onTrainerDefeated("martin_thwait");
		assertEquals("Amulet of the Rogue", martin.getRewardItemName());
		assertEquals(60, martin.getRewardCoins());
		assertEquals(1, roster.itemCount("amulet_of_the_rogue"));
	}

	@Test
	public void talkChapterAdvancesOnCompleteTalk()
	{
		RosterManager roster = loadedManager();
		QuestManager quests = questManager(roster);
		driveCapstoneToStep(roster, quests, 4); // Audience with the King (a talk chapter)

		assertFalse(quests.currentChapter(CAPSTONE).isBattle());
		assertTrue(quests.completeTalk(CAPSTONE));
		assertEquals(5, roster.getQuestStep(CAPSTONE));
	}

	@Test
	public void gimblewapAwardsTheSealedEnvelope()
	{
		RosterManager roster = loadedManager();
		QuestManager quests = questManager(roster);
		driveCapstoneToStep(roster, quests, 5);
		assertFalse(roster.ownsItem(Item.SEALED_ENVELOPE));

		QuestManager.DefeatResult r = quests.onTrainerDefeated(GIMBLEWAP);
		assertEquals("Sealed Envelope", r.getRewardItemName());
		assertTrue(roster.ownsItem(Item.SEALED_ENVELOPE));
		assertEquals(6, roster.getQuestStep(CAPSTONE));
	}

	@Test
	public void huntNeedsThreeDistinctWinsAndIgnoresRepeats()
	{
		PetDatabase db = databaseWithHuntFixture();
		RosterManager roster = loadedManager(db);
		QuestManager quests = questManager(roster, db);
		assertTrue("fixture talk chapter clears onto the hunt", quests.completeTalk(HUNT_QUEST));
		assertEquals(1, roster.getQuestStep(HUNT_QUEST));
		assertTrue(quests.currentChapter(HUNT_QUEST).isHunt());

		assertNotNull(quests.onTrainerDefeated(SUSPECT_A));   // progress
		assertEquals(1, roster.getQuestStep(HUNT_QUEST));
		assertNull(quests.onTrainerDefeated(SUSPECT_A));      // repeat: no double-count
		assertEquals(1, quests.countHuntBeaten(quests.quest(HUNT_QUEST), quests.currentChapter(HUNT_QUEST)));
		assertNotNull(quests.onTrainerDefeated(SUSPECT_B));
		assertEquals(1, roster.getQuestStep(HUNT_QUEST));
		assertNotNull(quests.onTrainerDefeated(SUSPECT_C));   // third distinct -> clears
		assertEquals(2, roster.getQuestStep(HUNT_QUEST));
		assertTrue(quests.isComplete(HUNT_QUEST));
	}

	@Test
	public void finaleAwardsBluePartyHatAndCompletes()
	{
		RosterManager roster = loadedManager();
		QuestManager quests = questManager(roster);
		driveCapstoneToStep(roster, quests, 6); // the Wise Old Man closes the story
		assertFalse(roster.ownsItem(Item.BLUE_PARTY_HAT));
		long before = roster.getCoins();

		QuestManager.DefeatResult r = quests.onTrainerDefeated(WISE_OLD_MAN);
		assertEquals("Blue party hat", r.getRewardItemName());
		assertEquals(before + 500, roster.getCoins());
		assertTrue(roster.ownsItem(Item.BLUE_PARTY_HAT));
		assertTrue(quests.isComplete(CAPSTONE));
	}

	@Test
	public void wholeArcPlaysThroughToComplete()
	{
		RosterManager roster = loadedManager();
		QuestManager quests = questManager(roster);
		// Read the end from the content, so adding or dropping a chapter doesn't strand this test.
		driveCapstoneToStep(roster, quests, quests.quest(CAPSTONE).completeStep());
		assertTrue(quests.isComplete(CAPSTONE));
		assertTrue(roster.ownsItem(Item.SEALED_ENVELOPE));
		assertTrue(roster.ownsItem(Item.BLUE_PARTY_HAT));
	}
}

package com.petbattles.tools;

import com.google.gson.Gson;
import com.petbattles.data.ContentLoader;
import com.petbattles.data.PetDatabase;
import com.petbattles.engine.BattleEvent;
import com.petbattles.engine.BattleState;
import com.petbattles.engine.MoveDef;
import com.petbattles.engine.PetType;
import com.petbattles.ui.AttackAnimator;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageTypeSpecifier;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.metadata.IIOMetadataNode;
import javax.imageio.stream.ImageOutputStream;

/**
 * Build-time tool (never on the plugin classpath): renders every move's attack animation to a
 * looping GIF by driving the real {@link AttackAnimator} through a stand-in battle scene, and
 * writes an HTML contact sheet indexing them. This lets you eyeball all the bespoke animations
 * outside the game client — no need to level a pet to each move first.
 *
 * <p>Run via {@code ./gradlew previewAnimations}; writes into {@code build/animations/} only.
 * The player pet is treated as the caster (bottom-left), so effects fly toward the enemy
 * placeholder (top-right), exactly as the overlay lays them out. Placeholder pets are plain
 * blobs — the point is the effect and the caster's motion, not the pet art.
 */
public final class AnimationPreviewGenerator
{
	// Mirrors BattleOverlay's scene geometry so motion/scale read the same as in-game.
	private static final int W = 340;
	private static final int H = 250;
	private static final Rectangle ENEMY_SPRITE = new Rectangle(W - 96, 24, 72, 72);
	private static final Rectangle PLAYER_SPRITE = new Rectangle(24, 88, 72, 72);

	private static final int FRAMES = 30;
	private static final int DELAY_CENTIS = 4; // ~40ms/frame → ~1.2s loop

	private AnimationPreviewGenerator()
	{
	}

	public static void main(String[] args) throws IOException
	{
		Path dir = Paths.get(args.length > 0 ? args[0] : "build/animations");
		Files.createDirectories(dir);
		PetDatabase db = PetDatabase.load(new ContentLoader(new Gson()));

		int written = 0;
		for (MoveDef move : db.allMoves())
		{
			writeGif(renderFrames(move), dir.resolve(move.getId() + ".gif"));
			written++;
		}
		Path index = dir.resolve("index.html");
		Files.write(index, renderIndex(db).getBytes(StandardCharsets.UTF_8));
		System.out.println("Wrote " + written + " animation GIFs and "
			+ index.toAbsolutePath() + " — open it in a browser.");
	}

	// ------------------------------------------------------------------ frame rendering

	private static List<BufferedImage> renderFrames(MoveDef move)
	{
		// The player pet casts; effects travel player → enemy.
		BattleEvent event = BattleEvent.moveUsed(BattleState.PLAYER, move, "");
		Color casterColor = new Color(move.getType().getColorRgb()).brighter();
		List<BufferedImage> frames = new ArrayList<>(FRAMES);
		for (int i = 0; i < FRAMES; i++)
		{
			float progress = FRAMES == 1 ? 0.5f : (float) i / (FRAMES - 1);
			BufferedImage img = new BufferedImage(W, H, BufferedImage.TYPE_INT_RGB);
			Graphics2D g = img.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);

			drawScene(g);
			// Defender stays put (its transform resolves to IDENTITY for the caster's MOVE_USED),
			// caster plays its motion — both via the real AttackAnimator path.
			drawPet(g, ENEMY_SPRITE,
				AttackAnimator.spriteTransform(event, move, progress, BattleState.ENEMY, ENEMY_SPRITE, PLAYER_SPRITE),
				new Color(120, 124, 132));
			drawPet(g, PLAYER_SPRITE,
				AttackAnimator.spriteTransform(event, move, progress, BattleState.PLAYER, PLAYER_SPRITE, ENEMY_SPRITE),
				casterColor);
			AttackAnimator.drawEffects(g, event, move, progress, PLAYER_SPRITE, ENEMY_SPRITE);

			g.dispose();
			frames.add(img);
		}
		return frames;
	}

	private static void drawScene(Graphics2D g)
	{
		g.setColor(new Color(24, 27, 32));
		g.fillRect(0, 0, W, H);
		// A soft ground band, echoing the battle backdrop, so vertical motion has a reference.
		g.setColor(new Color(34, 40, 34));
		g.fillRect(0, H - 70, W, 70);
		g.setColor(new Color(44, 52, 44));
		g.drawLine(0, H - 70, W, H - 70);
	}

	private static void drawPet(Graphics2D g, Rectangle rect, AttackAnimator.Transform t, Color color)
	{
		Graphics2D gg = (Graphics2D) g.create();
		gg.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, clamp01(t.alpha)));
		double cx = rect.getCenterX() + t.dx;
		double cy = rect.getCenterY() + t.dy;
		double w = rect.width * t.scale;
		double h = rect.height * t.scale;
		int x = (int) (cx - w / 2);
		int y = (int) (cy - h / 2);
		gg.setColor(color);
		gg.fillOval(x, y, (int) w, (int) h);
		gg.setColor(color.darker());
		gg.drawOval(x, y, (int) w, (int) h);
		// A pair of eyes so orientation and squash/stretch are legible.
		gg.setColor(Color.WHITE);
		int eye = Math.max(3, (int) (w * 0.12));
		gg.fillOval((int) (cx - w * 0.22), (int) (cy - h * 0.12), eye, eye);
		gg.fillOval((int) (cx + w * 0.10), (int) (cy - h * 0.12), eye, eye);
		gg.dispose();
	}

	private static float clamp01(float v)
	{
		return v < 0f ? 0f : (v > 1f ? 1f : v);
	}

	// ------------------------------------------------------------------ animated GIF

	private static void writeGif(List<BufferedImage> frames, Path out) throws IOException
	{
		ImageWriter writer = ImageIO.getImageWritersBySuffix("gif").next();
		try (ImageOutputStream ios = ImageIO.createImageOutputStream(Files.newOutputStream(out)))
		{
			writer.setOutput(ios);
			writer.prepareWriteSequence(null);
			ImageWriteParam param = writer.getDefaultWriteParam();
			for (int i = 0; i < frames.size(); i++)
			{
				BufferedImage frame = frames.get(i);
				IIOMetadata meta = writer.getDefaultImageMetadata(
					new ImageTypeSpecifier(frame), param);
				configureGifFrame(meta, i == 0);
				writer.writeToSequence(new IIOImage(frame, null, meta), param);
			}
			writer.endWriteSequence();
		}
		finally
		{
			writer.dispose();
		}
	}

	private static void configureGifFrame(IIOMetadata meta, boolean firstFrame) throws IOException
	{
		String format = meta.getNativeMetadataFormatName();
		IIOMetadataNode root = (IIOMetadataNode) meta.getAsTree(format);

		IIOMetadataNode gce = childNode(root, "GraphicControlExtension");
		gce.setAttribute("disposalMethod", "none");
		gce.setAttribute("userInputFlag", "FALSE");
		gce.setAttribute("transparentColorFlag", "FALSE");
		gce.setAttribute("delayTime", Integer.toString(DELAY_CENTIS));
		gce.setAttribute("transparentColorIndex", "0");

		if (firstFrame)
		{
			// NETSCAPE2.0 application extension → loop forever (0).
			IIOMetadataNode appExts = childNode(root, "ApplicationExtensions");
			IIOMetadataNode app = new IIOMetadataNode("ApplicationExtension");
			app.setAttribute("applicationID", "NETSCAPE");
			app.setAttribute("authenticationCode", "2.0");
			app.setUserObject(new byte[]{0x1, 0x0, 0x0});
			appExts.appendChild(app);
		}
		meta.setFromTree(format, root);
	}

	private static IIOMetadataNode childNode(IIOMetadataNode root, String name)
	{
		for (int i = 0; i < root.getLength(); i++)
		{
			if (root.item(i).getNodeName().equalsIgnoreCase(name))
			{
				return (IIOMetadataNode) root.item(i);
			}
		}
		IIOMetadataNode node = new IIOMetadataNode(name);
		root.appendChild(node);
		return node;
	}

	// ------------------------------------------------------------------ index page

	private static String renderIndex(PetDatabase db)
	{
		StringBuilder html = new StringBuilder();
		html.append("<!doctype html><html><head><meta charset=\"utf-8\">")
			.append("<title>Pet Battles — Animation Preview</title><style>")
			.append("body{font-family:sans-serif;background:#16181c;color:#e6e1d2;margin:20px}")
			.append("h1,h2{color:#f0dc78}")
			.append(".grid{display:flex;flex-wrap:wrap;gap:12px}")
			.append(".cell{background:#22262c;border:1px solid #5a4b28;border-radius:8px;padding:8px;width:180px}")
			.append(".cell img{width:170px;height:125px;background:#000;border-radius:4px;image-rendering:pixelated}")
			.append(".name{font-weight:bold;margin:6px 0 2px}")
			.append(".badge{display:inline-block;padding:1px 7px;border-radius:4px;color:#fff;font-size:11px;margin-right:4px}")
			.append(".meta{color:#9a948a;font-size:11px}")
			.append("code{color:#8fd0ff}")
			.append("</style></head><body>");
		html.append("<h1>Pet Battles — Animation Preview</h1>");
		html.append("<p class=\"meta\">Generated from moves.json via <code>./gradlew previewAnimations</code>. ")
			.append("Caster (coloured, bottom-left) throws toward the grey defender (top-right), as in battle. ")
			.append(db.allMoves().size()).append(" moves.</p>");

		for (PetType group : PetType.values())
		{
			StringBuilder cells = new StringBuilder();
			for (MoveDef move : db.allMoves())
			{
				if (move.getType() != group)
				{
					continue;
				}
				cells.append("<div class=\"cell\">")
					.append("<img loading=\"lazy\" alt=\"").append(esc(move.getName()))
					.append("\" src=\"").append(esc(move.getId())).append(".gif\">")
					.append("<div class=\"name\">").append(esc(move.getName())).append("</div>")
					.append(badge(move.getType()))
					.append("<div class=\"meta\">anim: <code>")
					.append(esc(AttackAnimator.animationId(move))).append("</code>")
					.append(move.getPower() > 0 ? " · pow " + move.getPower() : " · status")
					.append("</div></div>");
			}
			if (cells.length() > 0)
			{
				html.append("<h2>").append(esc(group.getDisplayName())).append("</h2>")
					.append("<div class=\"grid\">").append(cells).append("</div>");
			}
		}
		return html.append("</body></html>").toString();
	}

	private static String badge(PetType type)
	{
		return "<span class=\"badge\" style=\"background:#"
			+ String.format("%06x", type.getColorRgb() & 0xFFFFFF) + "\">"
			+ esc(type.getDisplayName()) + "</span>";
	}

	private static String esc(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.petbattles.tools;

import com.google.gson.Gson;
import com.petbattles.data.ContentLoader;
import com.petbattles.data.PetDatabase;
import com.petbattles.engine.SpeciesDef;
import com.petbattles.item.EquipItemDef;
import com.petbattles.ui.ChatheadAnchors;
import com.petbattles.ui.ItemSprites;
import com.petbattles.ui.PetChatheads;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import javax.imageio.ImageIO;

/**
 * Build-time QA tool (never on the plugin classpath): composites every bundled chathead with every
 * cosmetic using the real {@link ChatheadAnchors} placement, and writes an HTML contact sheet.
 *
 * <p>Cosmetic placement is derived from the art rather than hand-authored, so the only way to know
 * whether a hat sits on a head is to look at it — 164 chatheads is far too many to check by
 * levelling pets in-game. This renders all of them at once so the misses can be spotted and
 * corrected in {@code chathead_anchors.json}, then re-run to confirm.
 *
 * <p>Each tile draws the derived anchors on top: a horizontal bar where a hat's base sits and a
 * cross at the eye line, both as wide as the cosmetic would be drawn. When something looks wrong,
 * those marks say whether the measurement missed or the item art is simply the wrong shape.
 *
 * <p>Run via {@code ./gradlew previewCosmetics}; writes into {@code build/cosmetics/} only.
 */
public final class CosmeticPreviewGenerator
{
	/** Chathead box size in a tile, matching the overlay's 72px sprite box. */
	private static final int BOX = 72;

	private static final Color BG = new Color(38, 34, 28);
	private static final Color HEAD_MARK = new Color(120, 220, 140, 200);
	private static final Color FACE_MARK = new Color(120, 180, 255, 200);

	private CosmeticPreviewGenerator()
	{
	}

	public static void main(String[] args) throws IOException
	{
		Path dir = Paths.get(args.length > 0 ? args[0] : "build/cosmetics");
		Files.createDirectories(dir);

		PetDatabase db = PetDatabase.load(new ContentLoader(new Gson()));
		PetChatheads chatheads = new PetChatheads();
		ChatheadAnchors anchors = new ChatheadAnchors(new Gson());
		ItemSprites itemSprites = new ItemSprites();

		List<EquipItemDef> cosmetics = new ArrayList<>();
		for (EquipItemDef item : db.allEquipItems())
		{
			if (item.isCosmetic())
			{
				cosmetics.add(item);
			}
		}

		StringBuilder rows = new StringBuilder();
		int written = 0;
		for (SpeciesDef species : db.allSpecies())
		{
			for (String variantId : forms(species))
			{
				PetChatheads.Chathead head = chatheads.resolve(species.getId(), variantId, null);
				if (head == null)
				{
					continue;
				}
				ChatheadAnchors.Anchors a = anchors.anchors(head.getKey(), species.getId(), head.getImage());
				StringBuilder tiles = new StringBuilder();
				for (EquipItemDef item : cosmetics)
				{
					BufferedImage art = itemSprites.sprite(item.getSprite());
					if (art == null)
					{
						continue;
					}
					String file = head.getKey() + "__" + item.getId() + ".png";
					ImageIO.write(render(head.getImage(), a, item, art), "png", dir.resolve(file).toFile());
					written++;
					tiles.append("<figure><img src=\"").append(file).append("\">")
						.append("<figcaption>").append(item.getName()).append("</figcaption></figure>");
				}
				if (tiles.length() > 0)
				{
					rows.append("<section><h2>").append(head.getKey()).append("</h2>")
						.append(tiles).append("</section>");
				}
			}
		}

		Path index = dir.resolve("index.html");
		Files.write(index, page(rows.toString()).getBytes(StandardCharsets.UTF_8));
		System.out.println("Wrote " + written + " cosmetic previews and "
			+ index.toAbsolutePath() + " — open it in a browser.");
	}

	/** Base form plus every metamorphosis variant, since each can have its own chathead art. */
	private static List<String> forms(SpeciesDef species)
	{
		List<String> forms = new ArrayList<>();
		forms.add(null);
		for (SpeciesDef.Variant variant : species.getVariants())
		{
			forms.add(variant.getId());
		}
		return forms;
	}

	/**
	 * One tile: the chathead fitted into a BOX-square exactly as {@code BattleOverlay} fits it, the
	 * cosmetic placed on its anchor, and the anchor marks drawn over the top.
	 */
	private static BufferedImage render(BufferedImage chathead, ChatheadAnchors.Anchors a,
		EquipItemDef item, BufferedImage art)
	{
		BufferedImage tile = new BufferedImage(BOX, BOX, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = tile.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.setColor(BG);
		g.fillRect(0, 0, BOX, BOX);

		// Same aspect-preserving fit the overlay uses, so the preview matches what ships.
		int iw = chathead.getWidth();
		int ih = chathead.getHeight();
		float scale = Math.min((float) BOX / iw, (float) BOX / ih);
		int w = Math.max(1, Math.round(iw * scale));
		int h = Math.max(1, Math.round(ih * scale));
		int px = (BOX - w) / 2;
		int py = (BOX - h) / 2;
		g.drawImage(chathead, px, py, w, h, null);

		boolean isHead = item.getSlot() == EquipItemDef.Slot.HEAD;
		ChatheadAnchors.Anchor anchor = isHead ? a.getHead() : a.getFace();
		int cw = Math.max(1, Math.round(w * anchor.getWidth()));
		int ch = Math.max(1, Math.round(cw * (art.getHeight() / (float) art.getWidth())));
		int cx = px + Math.round(w * anchor.getX());
		int cy = py + Math.round(h * anchor.getY());
		g.drawImage(art, cx - cw / 2, isHead ? cy - ch : cy - ch / 2, cw, ch, null);

		// Anchor marks, so a bad result can be blamed on the measurement or on the art.
		g.setColor(isHead ? HEAD_MARK : FACE_MARK);
		g.drawLine(cx - cw / 2, cy, cx + cw / 2, cy);
		if (!isHead)
		{
			g.drawLine(cx, cy - 4, cx, cy + 4);
		}
		g.dispose();
		return tile;
	}

	private static String page(String body)
	{
		return "<!doctype html><meta charset=\"utf-8\"><title>Pet cosmetic placement</title>"
			+ "<style>"
			+ "body{background:#1b1815;color:#ddd6c8;font:13px/1.5 system-ui,sans-serif;margin:24px}"
			+ "h1{font-size:18px}h2{font-size:13px;font-weight:600;color:#c8bda4;margin:0 0 6px}"
			+ "section{margin:0 0 18px}figure{display:inline-block;margin:0 10px 0 0;text-align:center}"
			+ "img{image-rendering:pixelated;width:144px;height:144px;border:1px solid #3a342c}"
			+ "figcaption{font-size:11px;color:#9a927f;margin-top:2px}"
			+ "p{color:#9a927f;max-width:70ch}"
			+ "</style>"
			+ "<h1>Pet cosmetic placement</h1>"
			+ "<p>Derived from each chathead's alpha channel by ChatheadAnchors. The green bar marks "
			+ "where a hat's base sits; the blue cross marks the eye line. Both are drawn at the width "
			+ "the cosmetic is scaled to. Correct any misses in "
			+ "<code>chathead_anchors.json</code> and re-run.</p>"
			+ body;
	}
}

package com.petbattles.tools;

import com.google.gson.Gson;
import com.petbattles.data.ContentLoader;
import com.petbattles.data.PetDatabase;
import com.petbattles.engine.LearnsetEntry;
import com.petbattles.engine.MoveDef;
import com.petbattles.engine.MoveEffect;
import com.petbattles.engine.PetType;
import com.petbattles.engine.SpeciesDef;
import com.petbattles.engine.Stats;
import com.petbattles.engine.TypeChart;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

/**
 * Build-time tool (never on the plugin classpath): renders every species, its
 * learnset, and the type chart to a single HTML page for QA and reference.
 * Run via {@code ./gradlew generatePetReference}; writes into build/ only.
 */
public final class PetReferenceGenerator
{
	private PetReferenceGenerator()
	{
	}

	public static void main(String[] args) throws IOException
	{
		Path out = Paths.get(args.length > 0 ? args[0] : "build/pets.html");
		PetDatabase db = PetDatabase.load(new ContentLoader(new Gson()));
		Files.createDirectories(out.toAbsolutePath().getParent());
		Files.write(out, render(db).getBytes(StandardCharsets.UTF_8));
		System.out.println("Wrote " + out.toAbsolutePath() + " ("
			+ db.allSpecies().size() + " species, " + db.allMoves().size() + " moves)");
	}

	private static String render(PetDatabase db)
	{
		StringBuilder html = new StringBuilder();
		html.append("<!doctype html><html><head><meta charset=\"utf-8\">")
			.append("<title>Pet Battles — Reference</title><style>")
			.append("body{font-family:sans-serif;background:#16181c;color:#e6e1d2;margin:20px}")
			.append("h1,h2{color:#f0dc78}")
			.append(".cards{display:flex;flex-wrap:wrap;gap:12px}")
			.append(".card{background:#22262c;border:1px solid #5a4b28;border-radius:8px;padding:10px;width:330px}")
			.append(".card h3{margin:0 0 4px}")
			.append(".badge{display:inline-block;padding:1px 7px;border-radius:4px;color:#fff;font-size:11px;margin-right:4px}")
			.append(".meta{color:#9a948a;font-size:11px;margin:4px 0}")
			.append("table{border-collapse:collapse;font-size:12px;width:100%;margin-top:6px}")
			.append("td,th{border:1px solid #3a3f46;padding:2px 6px;text-align:left}")
			.append("th{background:#2b3038}")
			.append(".icon{width:32px;height:32px;vertical-align:middle;margin-right:6px}")
			.append(".s{color:#5cbf60}.w{color:#d16a5a}")
			.append("</style></head><body>");
		html.append("<h1>Pet Battles — Reference</h1>");
		html.append("<p class=\"meta\">Generated at build time from species.json / moves.json / typechart.json. ")
			.append(db.allSpecies().size()).append(" species, ")
			.append(db.allMoves().size()).append(" moves.</p>");

		// Species cards grouped by primary type
		for (PetType group : PetType.values())
		{
			StringBuilder cards = new StringBuilder();
			for (SpeciesDef species : db.allSpecies())
			{
				if (species.getTypes().isEmpty() || species.getTypes().get(0) != group)
				{
					continue;
				}
				cards.append(card(db, species));
			}
			if (cards.length() > 0)
			{
				html.append("<h2>").append(esc(group.getDisplayName())).append("</h2>")
					.append("<div class=\"cards\">").append(cards).append("</div>");
			}
		}

		html.append(typeChart(db.getTypeChart()));
		html.append("</body></html>");
		return html.toString();
	}

	private static String card(PetDatabase db, SpeciesDef species)
	{
		StringBuilder card = new StringBuilder();
		card.append("<div class=\"card\"><h3>")
			.append("<img class=\"icon\" alt=\"\" loading=\"lazy\" src=\"https://static.runelite.net/cache/item/icon/")
			.append(species.getItemId()).append(".png\">")
			.append(esc(species.getName())).append("</h3>");
		for (PetType type : species.getTypes())
		{
			card.append(badge(type));
		}
		card.append("<div class=\"meta\">id: ").append(esc(species.getId()))
			.append(" · item: ").append(species.getItemId());
		if (!species.getAltItemIds().isEmpty())
		{
			card.append(" (alt: ").append(esc(species.getAltItemIds().toString())).append(")");
		}
		card.append("</div>");
		Stats base = species.getBase();
		card.append("<div class=\"meta\">HP ").append(base.getHp())
			.append(" · Atk ").append(base.getAtk())
			.append(" · Def ").append(base.getDef())
			.append(" · Spd ").append(base.getSpd()).append("</div>");

		card.append("<table><tr><th>Lv</th><th>Move</th><th>Type</th><th>Pow</th><th>Acc</th><th>Effect</th></tr>");
		for (LearnsetEntry entry : species.getLearnset())
		{
			MoveDef move = db.move(entry.getMove());
			if (move == null)
			{
				card.append("<tr><td>").append(entry.getLevel())
					.append("</td><td colspan=\"5\" class=\"w\">UNKNOWN MOVE: ")
					.append(esc(entry.getMove())).append("</td></tr>");
				continue;
			}
			card.append("<tr><td>").append(entry.getLevel()).append("</td><td>")
				.append(esc(move.getName())).append("</td><td>").append(badge(move.getType()))
				.append("</td><td>").append(move.getPower() > 0 ? move.getPower() : "—")
				.append("</td><td>").append(move.getAccuracy()).append("%</td><td>")
				.append(effectText(move)).append("</td></tr>");
		}
		card.append("</table></div>");
		return card.toString();
	}

	private static String effectText(MoveDef move)
	{
		if (move.getEffect() == MoveEffect.NONE)
		{
			return "—";
		}
		return esc(move.getEffect().name()) + (move.getEffectChance() < 100
			? " (" + move.getEffectChance() + "%)" : "");
	}

	private static String typeChart(TypeChart chart)
	{
		StringBuilder html = new StringBuilder("<h2>Type chart</h2><table><tr><th>atk \\ def</th>");
		for (PetType def : PetType.values())
		{
			html.append("<th>").append(esc(def.getDisplayName())).append("</th>");
		}
		html.append("</tr>");
		for (PetType atk : PetType.values())
		{
			html.append("<tr><th>").append(esc(atk.getDisplayName())).append("</th>");
			for (PetType def : PetType.values())
			{
				double eff = chart.effectiveness(atk, def);
				String cls = eff > 1.0 ? "s" : eff < 1.0 ? "w" : "";
				html.append("<td class=\"").append(cls).append("\">").append(eff).append("</td>");
			}
			html.append("</tr>");
		}
		return html.append("</table>").toString();
	}

	private static String badge(PetType type)
	{
		return "<span class=\"badge\" style=\"background:#"
			+ String.format("%06x", type.getColorRgb() & 0xFFFFFF) + "\">"
			+ esc(type.getDisplayName()) + "</span>";
	}

	private static String esc(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.petbattles.ui;

import com.google.gson.Gson;
import com.petbattles.data.ContentLoader;
import com.petbattles.data.PetDatabase;
import com.petbattles.engine.SpeciesDef;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The alpha-scan placement in {@link ChatheadAnchors}. Cosmetic placement can only really be judged
 * in-game, so these tests pin the properties that must hold for any head — the anchors stay on the
 * art, the eye line sits below the crown, widths track the head's width at their own row — rather
 * than exact pixel values, which would be re-tuned constantly.
 */
public class ChatheadAnchorsTest
{
	/** A correction sheet shaped like the bundled one: a doc key, two entries, one deliberately bad. */
	private static final String OVERRIDES = "/com/petbattles/ui/test_anchors.json";

	private ChatheadAnchors anchors()
	{
		return new ChatheadAnchors(new Gson());
	}

	/** An opaque {@code w}x{@code h} block at (x, y) on a transparent {@code size}-square canvas. */
	private static BufferedImage block(int size, int x, int y, int w, int h)
	{
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setColor(Color.WHITE);
		g.fillRect(x, y, w, h);
		g.dispose();
		return img;
	}

	@Test
	public void anchorsCentreOnACentredHead()
	{
		// A 40x40 head centred in a 100px canvas: both anchors should sit on its centre line.
		ChatheadAnchors.Anchors a = anchors().anchors("k", "s", block(100, 30, 30, 40, 40));
		assertEquals(0.5f, a.getHead().getX(), 0.02f);
		assertEquals(0.5f, a.getFace().getX(), 0.02f);
		// Face sits below the crown, and both stay inside the head's vertical extent.
		assertTrue(a.getFace().getY() > a.getHead().getY());
		assertTrue(a.getHead().getY() >= 0.30f);
		assertTrue(a.getFace().getY() <= 0.70f);
	}

	@Test
	public void anchorsFollowAHeadOffToOneSide()
	{
		// Same head shifted right: the anchors must move with it, not stay at the canvas centre.
		ChatheadAnchors.Anchors a = anchors().anchors("k", "s", block(100, 55, 30, 40, 40));
		assertEquals(0.75f, a.getHead().getX(), 0.02f);
		assertEquals(0.75f, a.getFace().getX(), 0.02f);
	}

	@Test
	public void cosmeticWidthTracksTheHeadWidthNotTheCanvas()
	{
		// The whole point of measuring per-row: a narrow head gets a narrow cosmetic.
		ChatheadAnchors wide = anchors();
		ChatheadAnchors narrow = anchors();
		float wideFace = wide.anchors("k", "s", block(100, 20, 20, 60, 60)).getFace().getWidth();
		float narrowFace = narrow.anchors("k", "s", block(100, 40, 20, 20, 60)).getFace().getWidth();
		assertTrue("narrow head should get a narrower cosmetic", narrowFace < wideFace / 2);
	}

	@Test
	public void crownAnchorIgnoresALopsidedEarBelowTheCrownBand()
	{
		// A skull with a long ear hanging off its right side. The bounding-box centre drifts right;
		// the crown-band centroid should stay over the skull, which is where a hat belongs.
		BufferedImage img = new BufferedImage(100, 100, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setColor(Color.WHITE);
		g.fillRect(30, 20, 40, 60);  // skull, centred at x = 50
		g.fillRect(70, 55, 25, 10);  // ear jutting right, well below the crown band
		g.dispose();

		ChatheadAnchors.Anchors a = anchors().anchors("k", "s", img);
		// The full bounding box spans 30..95, whose centre is 0.625 — the hat must not go there.
		assertEquals(0.5f, a.getHead().getX(), 0.03f);
	}

	@Test
	public void blankOrDegenerateArtStillYieldsUsableAnchors()
	{
		ChatheadAnchors.Anchors blank = anchors()
			.anchors("k", "s", new BufferedImage(20, 20, BufferedImage.TYPE_INT_ARGB));
		assertNotNull(blank.getHead());
		assertNotNull(blank.getFace());
		assertTrue(blank.getHead().getWidth() > 0);

		ChatheadAnchors.Anchors none = anchors().anchors("k2", "s", null);
		assertNotNull(none.getHead());
		assertTrue(none.getFace().getWidth() > 0);
	}

	/**
	 * The correction sheet, which is the whole tuning loop: if overrides silently stopped applying,
	 * hand-tuning would appear to do nothing and the misses could never be fixed.
	 */
	@Test
	public void overridesReplaceOnlyTheFieldsTheyName()
	{
		ChatheadAnchors subject = new ChatheadAnchors(new Gson(), OVERRIDES);
		BufferedImage head = block(100, 30, 30, 40, 40);
		ChatheadAnchors.Anchors derived = anchors().anchors("some_species__blue", "some_species", head);
		ChatheadAnchors.Anchors tuned = subject.anchors("some_species__blue", "some_species", head);

		// The exact-key entry names all three head fields, so all three are replaced.
		assertEquals(0.11f, tuned.getHead().getX(), 0.0001f);
		assertEquals(0.22f, tuned.getHead().getY(), 0.0001f);
		assertEquals(0.33f, tuned.getHead().getWidth(), 0.0001f);
		// It says nothing about the face, and the more specific key wins outright, so the species
		// entry's face width does not leak in — the face stays fully derived.
		assertEquals(derived.getFace().getWidth(), tuned.getFace().getWidth(), 0.0001f);
	}

	@Test
	public void aSpeciesEntryCoversFormsWithNoEntryOfTheirOwn()
	{
		ChatheadAnchors subject = new ChatheadAnchors(new Gson(), OVERRIDES);
		BufferedImage head = block(100, 30, 30, 40, 40);
		ChatheadAnchors.Anchors derived = anchors().anchors("some_species__green", "some_species", head);
		ChatheadAnchors.Anchors tuned = subject.anchors("some_species__green", "some_species", head);

		// Falls back to the bare species entry, which names only the face width.
		assertEquals(0.44f, tuned.getFace().getWidth(), 0.0001f);
		assertEquals(derived.getFace().getY(), tuned.getFace().getY(), 0.0001f);
		assertEquals(derived.getHead().getY(), tuned.getHead().getY(), 0.0001f);
	}

	@Test
	public void oneMalformedEntryCostsOnlyItsOwnTuning()
	{
		ChatheadAnchors subject = new ChatheadAnchors(new Gson(), OVERRIDES);
		BufferedImage head = block(100, 30, 30, 40, 40);
		// The broken entry falls back to derived placement rather than throwing...
		ChatheadAnchors.Anchors broken = subject.anchors("broken_pet", "broken_pet", head);
		assertEquals(anchors().anchors("broken_pet", "broken_pet", head).getHead().getY(),
			broken.getHead().getY(), 0.0001f);
		// ...and the valid entries in the same file still apply.
		assertEquals(0.11f, subject.anchors("some_species__blue", "some_species", head).getHead().getX(),
			0.0001f);
	}

	/**
	 * The real bundled art, which is what actually ships. Every chathead must produce anchors that
	 * land on the image with a sensible size — a NaN or an off-image anchor would draw a hat into
	 * the middle of the battle scene.
	 */
	@Test
	public void everyBundledChatheadProducesAnchorsOnTheImage()
	{
		PetDatabase db = PetDatabase.load(new ContentLoader(new Gson()));
		PetChatheads chatheads = new PetChatheads();
		ChatheadAnchors subject = anchors();
		int checked = 0;
		for (SpeciesDef species : db.allSpecies())
		{
			// Base form plus every metamorphosis variant, since each can have its own art.
			List<String> forms = new ArrayList<>();
			forms.add(null);
			for (SpeciesDef.Variant variant : species.getVariants())
			{
				forms.add(variant.getId());
			}
			for (String variantId : forms)
			{
				PetChatheads.Chathead head = chatheads.resolve(species.getId(), variantId, null);
				if (head == null)
				{
					continue;
				}
				checked++;
				String what = head.getKey();
				ChatheadAnchors.Anchors a = subject.anchors(head.getKey(), species.getId(), head.getImage());
				assertOnImage(what + " head", a.getHead());
				assertOnImage(what + " face", a.getFace());
				assertTrue(what + ": face should sit below the crown",
					a.getFace().getY() > a.getHead().getY());
			}
		}
		assertTrue("expected the bundled chatheads to be found", checked > 0);
	}

	private static void assertOnImage(String what, ChatheadAnchors.Anchor a)
	{
		assertTrue(what + ": x off image (" + a.getX() + ")", a.getX() >= 0f && a.getX() <= 1f);
		assertTrue(what + ": y off image (" + a.getY() + ")", a.getY() >= 0f && a.getY() <= 1f);
		assertTrue(what + ": width unusable (" + a.getWidth() + ")",
			a.getWidth() > 0.02f && a.getWidth() <= 1.5f);
	}
}

package com.petbattles.ui;

import org.junit.Test;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;

/**
 * Variant-aware chathead resolution against the real bundled assets: a variant prefers its own
 * {@code <species>__<variant>.png} and falls back to the base {@code <species>.png}.
 */
public class PetChatheadsTest
{
	private final PetChatheads chatheads = new PetChatheads();

	@Test
	public void baseChatheadsLoad()
	{
		assertNotNull("beaver base chathead", chatheads.chathead("beaver"));
		assertNotNull("gull base chathead (newly added)", chatheads.chathead("gull"));
	}

	@Test
	public void variantChatheadsLoad()
	{
		assertNotNull("beaver fox variant", chatheads.chathead("beaver", "fox"));
		assertNotNull("cat hellcat variant", chatheads.chathead("cat", "hellcat"));
		assertNotNull("kalphite second_form variant", chatheads.chathead("kalphite_princess", "second_form"));
	}

	@Test
	public void unknownVariantFallsBackToBase()
	{
		// A variant with no bundled asset returns the base chathead (same cached instance).
		assertSame(chatheads.chathead("beaver"), chatheads.chathead("beaver", "does_not_exist"));
	}

	@Test
	public void stageChatheadsLoad()
	{
		// Base-form stages: cat__kitten.png / cat__overgrown.png distinct from the adult cat.png.
		assertNotNull("base kitten", chatheads.chathead("cat", null, "kitten"));
		assertNotNull("base overgrown", chatheads.chathead("cat", null, "overgrown"));
		assertNotSame("kitten differs from adult",
			chatheads.chathead("cat"), chatheads.chathead("cat", null, "kitten"));
		// Colour + stage: cat__black__kitten.png, and the hellcat's hell-kitten / overgrown art.
		assertNotNull("black kitten", chatheads.chathead("cat", "black", "kitten"));
		assertNotNull("hell-kitten", chatheads.chathead("cat", "hellcat", "kitten"));
		assertNotNull("overgrown hellcat", chatheads.chathead("cat", "hellcat", "overgrown"));
		// Split wily/lazy colour variants each have their own asset.
		assertNotNull("wily black", chatheads.chathead("cat", "wily_black"));
		assertNotNull("lazy grey_and_blue", chatheads.chathead("cat", "lazy_grey_and_blue"));
	}

	@Test
	public void missingStageFallsBackToVariantAdultNotWrongColour()
	{
		// A variant with no art for this stage falls back to its own adult chathead (same colour),
		// never to the base-form stage image of another colour.
		assertSame(chatheads.chathead("cat", "black"),
			chatheads.chathead("cat", "black", "no_such_stage"));
	}
}
